'''basic_trie.py
Simple Trie implementation with insert and search operations.
''' 

class TrieNode:
    """A node in the Trie structure."""
    __slots__ = ['children', 'is_end']
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    """Trie with insert and search methods for lowercase alphabetic strings."""
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        """Insert a word into the trie.
        Non‑alphabetic characters are ignored.
        """
        node = self.root
        for ch in word.lower():
            if not ch.isalpha():
                continue
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True

    def search(self, word: str) -> bool:
        """Return True if the exact word is stored in the trie."""
        node = self.root
        for ch in word.lower():
            if not ch.isalpha():
                continue
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.is_end

# Example usage (can be removed when importing)
if __name__ == "__main__":
    t = Trie()
    t.insert("hello")
    t.insert("world")
    print(t.search("hello"))  # True
    print(t.search("hell"))   # False
    print(t.search("world"))  # True

'''prefix_trie.py
Trie that supports bulk construction and prefix queries.
''' 

from typing import List

class Node:
    __slots__ = ['children', 'end']
    def __init__(self):
        self.children = {}
        self.end = False

class PrefixTrie:
    def __init__(self, words: List[str] = None):
        self.root = Node()
        if words:
            for w in words:
                self.insert(w)

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = Node()
            node = node.children[ch]
        node.end = True

    def _collect(self, node: Node, prefix: str, out: List[str]) -> None:
        if node.end:
            out.append(prefix)
        for ch, child in node.children.items():
            self._collect(child, prefix + ch, out)

    def words_with_prefix(self, prefix: str) -> List[str]:
        """Return a list of all words stored in the trie that start with *prefix*."""
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        result: List[str] = []
        self._collect(node, prefix, result)
        return result

# Demo
if __name__ == "__main__":
    sample = ["cat", "car", "cart", "dog", "dove", "door"]
    pt = PrefixTrie(sample)
    print(pt.words_with_prefix("ca"))   # ['cat', 'car', 'cart']
    print(pt.words_with_prefix("do"))   # ['dog', 'dove', 'door']
    print(pt.words_with_prefix("z"))    # []

'''trie_with_delete.py
Trie implementation that supports insertion, search, deletion, and a small test suite.
''' 

from __future__ import annotations
from typing import Dict
import unittest

class TrieNode:
    __slots__ = ['children', 'is_word']
    def __init__(self):
        self.children: Dict[str, TrieNode] = {}
        self.is_word: bool = False

class DeletableTrie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.is_word = True

    def search(self, word: str) -> bool:
        node = self._find_node(word)
        return bool(node) and node.is_word

    def delete(self, word: str) -> bool:
        """Delete *word* from the trie. Returns True if the word was present.
        The method recursively removes nodes that are no longer needed.
        """
        def _delete(node: TrieNode, idx: int) -> bool:
            if idx == len(word):
                if not node.is_word:
                    return False
                node.is_word = False
                return len(node.children) == 0
            ch = word[idx]
            child = node.children.get(ch)
            if not child:
                return False
            should_prune = _delete(child, idx + 1)
            if should_prune:
                del node.children[ch]
                return not node.is_word and len(node.children) == 0
            return False
        return _delete(self.root, 0)

    def _find_node(self, prefix: str) -> TrieNode | None:
        node = self.root
        for ch in prefix:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

# Unit tests
class TestDeletableTrie(unittest.TestCase):
    def setUp(self):
        self.trie = DeletableTrie()
        for w in ["test", "testing", "tester", "team"]:
            self.trie.insert(w)

    def test_search(self):
        self.assertTrue(self.trie.search("test"))
        self.assertTrue(self.trie.search("testing"))
        self.assertFalse(self.trie.search("tes"))

    def test_delete_leaf(self):
        self.assertTrue(self.trie.delete("team"))
        self.assertFalse(self.trie.search("team"))
        # other words unaffected
        self.assertTrue(self.trie.search("test"))

    def test_delete_prefix_word(self):
        self.assertTrue(self.trie.delete("test"))
        self.assertFalse(self.trie.search("test"))
        # longer words still exist
        self.assertTrue(self.trie.search("testing"))
        self.assertTrue(self.trie.search("tester"))

    def test_delete_nonexistent(self):
        self.assertFalse(self.trie.delete("unknown"))

if __name__ == "__main__":
    unittest.main()

'''cli_autocomplete.py
Command‑line autocomplete using a Trie.
Run the script and type a prefix when prompted.
''' 

import sys
from typing import List

class AutoNode:
    __slots__ = ['children', 'end']
    def __init__(self):
        self.children: dict[str, AutoNode] = {}
        self.end: bool = False

class AutocompleteTrie:
    def __init__(self, commands: List[str]):
        self.root = AutoNode()
        for cmd in commands:
            self.insert(cmd)

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, AutoNode())
        node.end = True

    def _gather(self, node: AutoNode, prefix: str, out: List[str]) -> None:
        if node.end:
            out.append(prefix)
        for ch, child in node.children.items():
            self._gather(child, prefix + ch, out)

    def suggestions(self, prefix: str) -> List[str]:
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        result: List[str] = []
        self._gather(node, prefix, result)
        return result

def main(argv: List[str] | None = None) -> None:
    commands = [
        'add', 'commit', 'checkout', 'clone', 'push', 'pull', 'status',
        'merge', 'rebase', 'reset', 'remote', 'branch', 'log', 'diff'
    ]
    trie = AutocompleteTrie(commands)
    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        prefix = input('Enter prefix: ').strip()
    else:
        prefix = argv[0]
    sug = trie.suggestions(prefix)
    if sug:
        print('Suggestions:', ', '.join(sug))
    else:
        print('No suggestions found.')

if __name__ == "__main__":
    main()

'''prefix_counter.py
Trie that can count words sharing a prefix and offers a simple CLI for testing.
''' 

import sys
from typing import Dict

class CounterNode:
    __slots__ = ['children', 'end', 'subtree_count']
    def __init__(self):
        self.children: Dict[str, CounterNode] = {}
        self.end: bool = False
        self.subtree_count: int = 0  # number of words in this subtree

class PrefixCounterTrie:
    def __init__(self):
        self.root = CounterNode()

    def insert(self, word: str) -> None:
        node = self.root
        node.subtree_count += 1
        for ch in word:
            if ch not in node.children:
                node.children[ch] = CounterNode()
            node = node.children[ch]
            node.subtree_count += 1
        node.end = True

    def count_with_prefix(self, prefix: str) -> int:
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return 0
            node = node.children[ch]
        return node.subtree_count

    def search(self, word: str) -> bool:
        node = self.root
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.end

def repl():
    trie = PrefixCounterTrie()
    print('Enter words to build the trie (blank line to finish)')
    while True:
        line = input('word: ').strip()
        if not line:
            break
        trie.insert(line)
    while True:
        cmd = input('prefix> ').strip()
        if cmd == '':
            continue
        if cmd == 'exit':
            break
        cnt = trie.count_with_prefix(cmd)
        print(f'Words with prefix "{cmd}": {cnt}')

if __name__ == "__main__":
    if len(sys.argv) > 1 and sys.argv[1] == '--repl':
        repl()
    else:
        # quick demo
        demo = PrefixCounterTrie()
        for w in ['apple', 'app', 'application', 'apt', 'banana']:
            demo.insert(w)
        print('Count for "app":', demo.count_with_prefix('app'))
        print('Count for "ap":', demo.count_with_prefix('ap'))
        print('Count for "b":', demo.count_with_prefix('b'))

'''check_or_create_venv.py
Ensures a virtual environment exists, creates it if missing, and reports the interpreter version inside.
Usage: python check_or_create_venv.py ./myenv
'''
import sys
import subprocess
from pathlib import Path

def venv_exists(venv_path: Path) -> bool:
    """Return True if *venv_path* looks like a virtual environment."""
    bin_dir = venv_path / ('Scripts' if sys.platform == 'win32' else 'bin')
    return bin_dir.is_dir() and any((bin_dir / exe).exists() for exe in ['python', 'python.exe'])

def create_venv(venv_path: Path) -> None:
    subprocess.run([sys.executable, '-m', 'venv', str(venv_path)], check=True)

def python_version_in_venv(venv_path: Path) -> str:
    py_exe = venv_path / ('Scripts' if sys.platform == 'win32' else 'bin') / ('python.exe' if sys.platform == 'win32' else 'python')
    result = subprocess.run([str(py_exe), '--version'], capture_output=True, text=True, check=True)
    return result.stdout.strip() or result.stderr.strip()

def main() -> None:
    if len(sys.argv) != 2:
        print('Usage: python check_or_create_venv.py <venv_dir>')
        sys.exit(1)
    venv_dir = Path(sys.argv[1]).resolve()
    if not venv_exists(venv_dir):
        print(f'Venv not found at {venv_dir}, creating...')
        create_venv(venv_dir)
    else:
        print(f'Venv already present at {venv_dir}')
    version = python_version_in_venv(venv_dir)
    print(f'Python version inside venv: {version}')

if __name__ == '__main__':
    main()

'''common_lines.py
Read two plain‑text files, interpret each line as a set element, and output the intersection.
Lines are stripped of trailing newlines and leading/trailing whitespace.
''' 

import sys
from pathlib import Path

def load_file_to_set(path):
    """Return a set containing the stripped lines of *path*.
    Empty lines are ignored.
    """
    p = Path(path)
    if not p.is_file():
        raise FileNotFoundError(f"File not found: {path}")
    return {line.strip() for line in p.read_text().splitlines() if line.strip()}

def main(file_a, file_b):
    set_a = load_file_to_set(file_a)
    set_b = load_file_to_set(file_b)
    common = set_a & set_b
    if common:
        print("Lines present in both files:")
        for line in sorted(common):
            print(line)
    else:
        print("No common lines found.")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <file1> <file2>")
        sys.exit(1)
    main(sys.argv[1], sys.argv[2])

answer:
A decorator is a callable that takes a function (or method) and returns a new function that usually adds some behavior before or after the original one. You apply it with the @ syntax placed above the function definition. For example:
```python
def shout(func):
    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        return result.upper()
    return wrapper

@shout
def greet(name):
    return f"Hello, {name}"

print(greet('Bob'))  # prints "HELLO, BOB"
```

When a decorator returns the inner wrapper function, that wrapper replaces the original function object, so attributes like __name__ and __doc__ are taken from the wrapper. To preserve them you can use `functools.wraps` on the wrapper:
```python
from functools import wraps

def log(func):
    @wraps(func)
    def wrapper(*a, **k):
        print('Calling', func.__name__)
        return func(*a, **k)
    return wrapper
```

A decorator with arguments is a three‑level function: the outermost receives the decorator arguments, returns the actual decorator, which then receives the function and returns the wrapper. Example:
```python
def repeat(times):
    def decorator(func):
        def wrapper(*a, **k):
            for _ in range(times):
                func(*a, **k)
        return wrapper
    return decorator

@repeat(3)
def hello():
    print('hi')

hello()  # prints 'hi' three times
```

Use a class‑based decorator when you need to maintain state across multiple calls or want to implement richer protocols like `__call__`, `__get__`, or descriptor behavior. The class’s `__init__` receives the function, and `__call__` is invoked each time the decorated function is called. Example:
```python
class Counter:
    def __init__(self, func):
        self.func = func
        self.calls = 0
    def __call__(self, *a, **k):
        self.calls += 1
        print(f'Call #{self.calls}')
        return self.func(*a, **k)

@Counter
def add(a, b):
    return a + b

add(1, 2)  # prints Call #1
add(3, 4)  # prints Call #2
```

If you don't preserve the original signature, the wrapper appears to have a generic `(*args, **kwargs)` signature, which confuses introspection tools. In Python 3.4+ you can use `functools.wraps` together with `inspect.signature` and `functools.update_wrapper` to copy `__signature__`. A simpler approach is to use the `wrapt` library, which handles signatures automatically.
```python
from wrapt import decorator

@decorator
def logged(wrapped, instance, args, kwargs):
    print('Calling', wrapped.__name__)
    return wrapped(*args, **kwargs)
```

When you decorate a function, the decorator receives that function object and must return a callable that replaces it. Decorating a class passes the class object to the decorator, allowing you to modify or replace the class itself (e.g., adding methods, changing inheritance). Example:
```python
def add_repr(cls):
    cls.__repr__ = lambda self: f'<{cls.__name__} {self.__dict__}>'
    return cls

@add_repr
class Point:
    def __init__(self, x, y):
        self.x, self.y = x, y
```

