#!/usr/bin/env python3
"""kv_to_json.py

Parse an arbitrary list of '--key value' arguments and emit a JSON object.
The script uses nargs='*' to collect the raw argument list and then builds
pairs in a loop, raising an error if an odd number of tokens is supplied.
"""
import argparse
import json
import sys

def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Convert key/value arguments to JSON")
    parser.add_argument(
        "pairs",
        nargs="*",
        help="Sequence of key value pairs, e.g. --name Alice --age 30",
    )
    return parser

def pairs_to_dict(tokens: list[str]) -> dict:
    if len(tokens) % 2:
        raise ValueError("Odd number of arguments; keys must have matching values")
    result = {}
    for i in range(0, len(tokens), 2):
        key = tokens[i].lstrip('-')
        value = tokens[i + 1]
        # Simple type inference: try int, then float, else keep string
        try:
            value = int(value)
        except ValueError:
            try:
                value = float(value)
            except ValueError:
                pass
        result[key] = value
    return result

def main() -> None:
    args = build_parser().parse_args()
    try:
        data = pairs_to_dict(args.pairs)
    except ValueError as e:
        sys.exit(str(e))
    print(json.dumps(data, indent=2, sort_keys=True))

if __name__ == "__main__":
    main()

