'''flask_mutable.py
A tiny Flask application that shows the mutable default argument problem in a view function
and provides a corrected version.
''' 
from __future__ import annotations
from flask import Flask, request, jsonify

app = Flask(__name__)

# Bad example – shared list across requests
@app.route('/bad', methods=['POST'])
def bad_collect(item: dict | None = None, collected: list = []):
    """Collects posted JSON objects into a shared list.
    The mutable default *collected* persists between HTTP requests.
    """
    if item is None:
        item = request.get_json(force=True)
    collected.append(item)
    return jsonify(collected)

# Good example – creates a new list per request
@app.route('/good', methods=['POST'])
def good_collect(item: dict | None = None, collected: list | None = None):
    """Collects posted JSON objects without sharing state.
    *collected* defaults to None, so a fresh list is made for each call.
    """
    if collected is None:
        collected = []
    if item is None:
        item = request.get_json(force=True)
    collected.append(item)
    return jsonify(collected)

if __name__ == '__main__':
    # Run on a non‑standard port to avoid clashes during testing
    app.run(port=5005, debug=True)

'''cache_util.py
Implements a simple memoization decorator that stores results in a mutable default dict.
Provides a function to clear the cache for a specific decorated function.
''' 
from __future__ import annotations
import functools
from typing import Callable, Any, Dict, Tuple

def memoize(func: Callable[..., Any]) -> Callable[..., Any]:
    """Decorator that caches results of *func* in a mutable default dict.
    The cache key is the tuple of positional arguments plus a frozenset of keyword items.
    """
    cache: Dict[Tuple[Any, ...], Any] = {}

    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = args + (frozenset(kwargs.items()),)
        if key not in cache:
            cache[key] = func(*args, **kwargs)
        return cache[key]
    wrapper._cache = cache  # expose for clearing
    return wrapper

def clear_cache(func: Callable[..., Any]) -> None:
    """Clears the memoization cache attached to *func* by the memoize decorator.
    If the function has no `_cache` attribute, the call is ignored.
    """
    if hasattr(func, '_cache'):
        func._cache.clear()

# Example usage
@memoize
def fib(n: int) -> int:
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

if __name__ == '__main__':
    print('fib(35) =', fib(35))  # fast after memoization
    print('Cache size before clear:', len(fib._cache))
    clear_cache(fib)
    print('Cache size after clear:', len(fib._cache))
    print('Recomputing fib(35) after clear:')
    print('fib(35) =', fib(35))

