'''average_price.py
Calculate and print the arithmetic mean of the "price" column in a CSV.
Usage: python average_price.py data.csv
'''import csv
import sys

def compute_average(path, column='price'):
    """Return the average of *column* values in *path*.
    Non‑numeric or missing entries are ignored.
    """
    total = 0.0
    count = 0
    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        if column not in reader.fieldnames:
            raise KeyError(f'Column "{column}" not found')
        for row in reader:
            try:
                total += float(row[column])
                count += 1
            except (ValueError, TypeError):
                continue
    if count == 0:
        raise ValueError('No valid numeric entries found')
    return total / count

def main():
    if len(sys.argv) != 2:
        print('Usage: python average_price.py data.csv')
        sys.exit(1)
    try:
        avg = compute_average(sys.argv[1])
        print(f'Average price: {avg:.2f}')
    except Exception as e:
        print(f'Error: {e}')
        sys.exit(1)

if __name__ == '__main__':
    main()

'''split_by_category.py
Read a CSV and write one output file per distinct value in the "category" column.
Each output file is named <category>.csv (sanitized).
Usage: python split_by_category.py input.csv
'''import csv
import os
import re
import sys

def sanitize(name):
    """Return a filename‑safe version of *name* by keeping alphanumerics and underscores."""
    return re.sub(r'[^A-Za-z0-9_]', '_', str(name))

def split_csv(path, key='category'):
    with open(path, newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        if key not in reader.fieldnames:
            raise KeyError(f'Column "{key}" not found')
        groups = {}
        for row in reader:
            groups.setdefault(row[key], []).append(row)
    for group, rows in groups.items():
        filename = f"{sanitize(group)}.csv"
        with open(filename, 'w', newline='', encoding='utf-8') as out_f:
            writer = csv.DictWriter(out_f, fieldnames=reader.fieldnames)
            writer.writeheader()
            writer.writerows(rows)
        print(f'Wrote {len(rows)} rows to {filename}')

def main():
    if len(sys.argv) != 2:
        print('Usage: python split_by_category.py input.csv')
        sys.exit(1)
    try:
        split_csv(sys.argv[1])
    except Exception as e:
        print(f'Error: {e}')
        sys.exit(1)

if __name__ == '__main__':
    main()

