'''fraction.py
A Fraction class that automatically reduces to lowest terms and
exposes readable representation, value‑based equality and a hash
compatible with sets and dicts.
'''

from __future__ import annotations
from math import gcd

class Fraction:
    """Rational number stored as numerator and denominator.

    The fraction is always kept in reduced form with a positive
    denominator.
    """

    __slots__ = ("_num", "_den")

    def __init__(self, numerator: int, denominator: int = 1) -> None:
        if denominator == 0:
            raise ZeroDivisionError("Denominator cannot be zero")
        # Normalise sign so denominator is positive
        if denominator < 0:
            numerator, denominator = -numerator, -denominator
        common = gcd(numerator, denominator)
        self._num = numerator // common
        self._den = denominator // common

    @property
    def numerator(self) -> int:
        return self._num

    @property
    def denominator(self) -> int:
        return self._den

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}({self.numerator}, {self.denominator})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Fraction):
            return NotImplemented
        return (self.numerator == other.numerator and
                self.denominator == other.denominator)

    def __hash__(self) -> int:
        # Hash the tuple (num, den) – safe because Fraction is immutable
        return hash((self.numerator, self.denominator))

    def __float__(self) -> float:
        return self.numerator / self.denominator

    # Optional arithmetic for demonstration
    def __add__(self, other: Fraction) -> Fraction:
        if not isinstance(other, Fraction):
            return NotImplemented
        num = self.numerator * other.denominator + other.numerator * self.denominator
        den = self.denominator * other.denominator
        return Fraction(num, den)

if __name__ == "__main__":
    f1 = Fraction(2, 4)      # reduces to 1/2
    f2 = Fraction(3, 6)      # also 1/2
    f3 = Fraction(-5, 10)    # reduces to -1/2
    print(f"f1: {f1!r}, f2: {f2!r}, f3: {f3!r}")
    print(f"f1 == f2: {f1 == f2}")
    print(f"set of fractions: {{f1, f2, f3}}")
    print(f"float of f3: {float(f3)}")
    print(f"f1 + f3: {f1 + f3}")

