'''matrix.py
A minimal immutable Matrix class supporting readable representation,
value based equality, hashability (via a tuple of rows) and a transpose
method. Rows are stored as tuples of numbers.
'''

from __future__ import annotations
from typing import Iterable, Tuple, List

class Matrix:
    """Immutable rectangular matrix.

    Parameters
    ----------
    rows : iterable of iterables
        Each inner iterable represents a row; all rows must have the same length.
    """

    __slots__ = ("_rows", "_nrows", "_ncols")

    def __init__(self, rows: Iterable[Iterable[float]]) -> None:
        # Convert to tuple of tuples for immutability and hashability
        converted: List[Tuple[float, ...]] = []
        for r in rows:
            tup = tuple(float(x) for x in r)
            converted.append(tup)
        if not converted:
            raise ValueError("Matrix cannot be empty")
        row_len = len(converted[0])
        if any(len(r) != row_len for r in converted):
            raise ValueError("All rows must have the same length")
        self._rows = tuple(converted)
        self._nrows = len(self._rows)
        self._ncols = row_len

    @property
    def rows(self) -> Tuple[Tuple[float, ...], ...]:
        return self._rows

    @property
    def shape(self) -> Tuple[int, int]:
        return (self._nrows, self._ncols)

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}({self._rows!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Matrix):
            return NotImplemented
        return self._rows == other._rows

    def __hash__(self) -> int:
        # The rows tuple is already hashable
        return hash(self._rows)

    def transpose(self) -> "Matrix":
        """Return a new Matrix that is the transpose of this one."""
        transposed = zip(*self._rows)
        return Matrix(transposed)

if __name__ == "__main__":
    m = Matrix([[1, 2, 3], [4, 5, 6]])
    print("Original:", m)
    print("Shape:", m.shape)
    t = m.transpose()
    print("Transposed:", t)
    print("Equality test:", m == Matrix([[1, 2, 3], [4, 5, 6]]))
    s = {m, t}
    print("Set contains", len(s), "matrices")

