Immutable two‑dimensional vector supporting readable representation,
value‑based equality, hashability, and a dot product operation.
'''

from __future__ import annotations

class Vector2D:
    """A lightweight immutable 2‑D vector.

    The class stores ``x`` and ``y`` as floats and can be used as a
    dictionary key because it defines ``__hash__`` consistent with ``__eq__``.
    """

    __slots__ = ("_x", "_y")

    def __init__(self, x: float, y: float) -> None:
        self._x = float(x)
        self._y = float(y)

    @property
    def x(self) -> float:
        return self._x

    @property
    def y(self) -> float:
        return self._y

    def __repr__(self) -> str:
        return f"{self.__class__.__name__}({self.x!r}, {self.y!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Vector2D):
            return NotImplemented
        return self.x == other.x and self.y == other.y

    def __hash__(self) -> int:
        return hash((self.x, self.y))

    def dot(self, other: Vector2D) -> float:
        """Return the dot product of this vector with ``other``."""
        if not isinstance(other, Vector2D):
            raise TypeError("dot product requires another Vector2D")
        return self.x * other.x + self.y * other.y

