'''memoize.py
A memoization decorator that caches function results in a dictionary.
''' 
import functools

def memoize(func):
    """Cache *func* results keyed by the arguments tuple.
    Works for hashable arguments only.
    """
    cache = {}
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        key = args + tuple(sorted(kwargs.items()))
        if key in cache:
            return cache[key]
        result = func(*args, **kwargs)
        cache[key] = result
        return result
    wrapper._cache = cache  # expose for inspection
    return wrapper

@memoize
def fib(n):
    """Recursive Fibonacci with memoization.
    Returns the *n*th Fibonacci number.
    """
    if n < 2:
        return n
    return fib(n-1) + fib(n-2)

if __name__ == '__main__':
    for i in range(10):
        print(f'fib({i}) = {fib(i)}')
    print('Cache size:', len(fib._cache))

'''typecheck.py
Decorator that validates argument types against annotations.
''' 
import functools
import inspect

def enforce_types(func):
    """Check that arguments match the function's type annotations.
    Raises TypeError if a mismatch is found.
    """
    sig = inspect.signature(func)
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        bound = sig.bind(*args, **kwargs)
        bound.apply_defaults()
        for name, value in bound.arguments.items():
            expected = func.__annotations__.get(name)
            if expected and not isinstance(value, expected):
                raise TypeError(f'Argument {name!r} must be {expected.__name__}, got {type(value).__name__}')
        return func(*args, **kwargs)
    return wrapper

@enforce_types
def concat(a: str, b: str) -> str:
    """Return the concatenation of two strings."""
    return a + b

@enforce_types
def divide(num: int, den: int) -> float:
    """Perform true division, both arguments must be int."""
    return num / den

if __name__ == '__main__':
    print(concat('hello', 'world'))
    try:
        concat('hi', 5)
    except TypeError as e:
        print('Error:', e)
    print(divide(10, 2))
    try:
        divide(10, '2')
    except TypeError as e:
        print('Error:', e)

'''retry_decorator.py
Implements a parametrized retry decorator.
''' 
import functools
import time
import random

def retry(max_attempts=3, delay=0.5, backoff=2):
    """Return a decorator that retries a function.
    *max_attempts* – how many times to call the function.
    *delay* – initial wait time between attempts.
    *backoff* – factor by which the delay grows after each failure.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            attempts = 0
            wait = delay
            while True:
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    attempts += 1
                    if attempts >= max_attempts:
                        print(f'All {max_attempts} attempts failed.')
                        raise
                    print(f'Attempt {attempts} failed ({exc}), retrying in {wait}s...')
                    time.sleep(wait)
                    wait *= backoff
        return wrapper
    return decorator

@retry(max_attempts=5, delay=0.2)
def flaky():
    """Simulate an unreliable operation that succeeds 30% of the time."""
    if random.random() < 0.7:
        raise RuntimeError('Random failure')
    return 'Success!'

if __name__ == '__main__':
    print(flaky())

'''call_counter.py
Class‑based decorator that tracks call count per function.
''' 
import functools

class CallCounter:
    """Callable class used as a decorator.
    It stores the number of times the wrapped function is invoked in ``self.calls``.
    """
    def __init__(self, func):
        functools.update_wrapper(self, func)
        self.func = func
        self.calls = 0

    def __call__(self, *args, **kwargs):
        self.calls += 1
        return self.func(*args, **kwargs)

@CallCounter
def square(x):
    """Return the square of *x*."""
    return x * x

@CallCounter
def hello(name='World'):
    """Return a greeting string."""
    return f'Hello, {name}!'

if __name__ == '__main__':
    for i in range(3):
        square(i)
    print(f'square was called {square.calls} times')
    hello()
    hello('Alice')
    print(f'hello was called {hello.calls} times')

'''timer.py
A simple timing decorator that prints execution time in ms.
''' 
import functools
import time

def timed(func):
    """Decorator that measures execution time and prints it.
    The duration is shown in milliseconds with three decimal places.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        end = time.perf_counter()
        elapsed_ms = (end - start) * 1000
        print(f'{func.__name__} executed in {elapsed_ms:.3f} ms')
        return result
    return wrapper

@timed
def busy_wait(seconds: float):
    """Sleep for *seconds* using time.sleep (simulates work)."""
    time.sleep(seconds)
    return 'done'

@timed
def sum_range(n: int) -> int:
    """Compute the sum of 0..n‑1 using a loop (CPU bound)."""
    total = 0
    for i in range(n):
        total += i
    return total

if __name__ == '__main__':
    busy_wait(0.123)
    print('Result:', sum_range(10_000))

