'''binary_search_iterative.py
Iterative binary search implementation.
The module provides a single function `binary_search` that returns the index of
the target value in a sorted list or -1 if the value is not present.
''' 

def binary_search(arr, target):
    """Return the index of *target* in sorted list *arr* using an iterative binary search.
    If *target* is not found, return -1.
    """
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        mid_val = arr[mid]
        if mid_val == target:
            return mid
        elif mid_val < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

if __name__ == "__main__":
    # Example usage
    data = [1, 3, 5, 7, 9, 11, 13, 15]
    for t in [7, 2, 15, 0]:
        idx = binary_search(data, t)
        if idx != -1:
            print(f"{t} found at index {idx}.")
        else:
            print(f"{t} not found in the list.")

'''binary_search_class.py
Recursive binary search encapsulated in a class.
The class records how many element comparisons are performed during a search.
''' 

class BinarySearcher:
    """Encapsulates a recursive binary search and counts comparisons."""

    def __init__(self, data):
        if not all(data[i] <= data[i + 1] for i in range(len(data) - 1)):
            raise ValueError("Data must be sorted in non‑decreasing order.")
        self.data = data
        self.comparisons = 0

    def _search(self, left, right, target):
        if left > right:
            return -1
        mid = (left + right) // 2
        self.comparisons += 1
        mid_val = self.data[mid]
        if mid_val == target:
            return mid
        elif mid_val < target:
            return self._search(mid + 1, right, target)
        else:
            return self._search(left, mid - 1, target)

    def search(self, target):
        """Public method that resets the comparison counter and starts recursion."""
        self.comparisons = 0
        return self._search(0, len(self.data) - 1, target)

if __name__ == "__main__":
    arr = [2, 4, 6, 8, 10, 12, 14]
    bs = BinarySearcher(arr)
    for val in [8, 5, 14]:
        idx = bs.search(val)
        print(f"Searching for {val}: index={idx}, comparisons={bs.comparisons}")

'''binary_search_file.py
Read integers from a text file (one per line) and perform a binary search.
The script validates input, catches I/O errors, and prints a helpful message.
''' 
import sys

def load_numbers(path):
    """Return a sorted list of integers from *path*.
    Blank lines are ignored; non‑numeric lines raise a ValueError.
    """
    numbers = []
    with open(path, 'r') as f:
        for line_num, line in enumerate(f, 1):
            stripped = line.strip()
            if not stripped:
                continue
            try:
                numbers.append(int(stripped))
            except ValueError as e:
                raise ValueError(f"Invalid integer on line {line_num}: '{stripped}'") from e
    numbers.sort()
    return numbers

def binary_search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def main():
    if len(sys.argv) != 3:
        print("Usage: python binary_search_file.py <path_to_file> <integer_to_find>")
        sys.exit(1)
    path, target_str = sys.argv[1], sys.argv[2]
    try:
        target = int(target_str)
    except ValueError:
        print(f"Error: target '{target_str}' is not a valid integer.")
        sys.exit(1)
    try:
        data = load_numbers(path)
    except (IOError, OSError) as e:
        print(f"I/O error while reading '{path}': {e}")
        sys.exit(1)
    except ValueError as ve:
        print(f"Data error: {ve}")
        sys.exit(1)
    index = binary_search(data, target)
    if index != -1:
        print(f"Found {target} at sorted index {index}.")
    else:
        print(f"{target} not present in the file.")

if __name__ == "__main__":
    main()

'''binary_search_objects.py
Binary search on a list of objects that have a numeric `value` attribute.
A `key` callable extracts the comparable field, allowing generic reuse.
''' 

from dataclasses import dataclass
from typing import Callable, List, Any

@dataclass(order=True)
class Item:
    value: int
    name: str

def binary_search(items: List[Any], target: int, key: Callable[[Any], int]) -> int:
    """Return the index of an element whose *key* equals *target*.
    If no such element exists, return -1.
    """
    left, right = 0, len(items) - 1
    while left <= right:
        mid = (left + right) // 2
        mid_key = key(items[mid])
        if mid_key == target:
            return mid
        elif mid_key < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

if __name__ == "__main__":
    catalogue = [
        Item(10, "alpha"),
        Item(20, "bravo"),
        Item(30, "charlie"),
        Item(40, "delta"),
    ]
    # The list is already sorted by `value` because of the dataclass ordering.
    for query in [20, 25, 40]:
        idx = binary_search(catalogue, query, key=lambda i: i.value)
        if idx != -1:
            print(f"Found {catalogue[idx].name} (value={catalogue[idx].value}) at index {idx}.")
        else:
