'''components_counter.py
Read an edge list from a text file and compute the number of connected
components using a Union‑Find data structure.
The file should contain one edge per line: ``u v`` (0‑based indices).
'''

from __future__ import annotations
import sys
from typing import List, Tuple

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a: int, b: int) -> None:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.rank[ra] < self.rank[rb]:
            self.parent[ra] = rb
        elif self.rank[ra] > self.rank[rb]:
            self.parent[rb] = ra
        else:
            self.parent[rb] = ra
            self.rank[ra] += 1

    def count_sets(self) -> int:
        # apply find to compress all paths before counting roots
        for i in range(len(self.parent)):
            self.find(i)
        return len({self.parent[i] for i in range(len(self.parent))})


def read_edges(path: str) -> Tuple[int, List[Tuple[int, int]]]:
    edges: List[Tuple[int, int]] = []
    max_node = -1
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if not line.strip():
                continue
            u_str, v_str = line.split()
            u, v = int(u_str), int(v_str)
            edges.append((u, v))
            max_node = max(max_node, u, v)
    # vertices are assumed to be 0..max_node
    return max_node + 1, edges


def count_components(file_path: str) -> int:
    n, edges = read_edges(file_path)
    uf = UnionFind(n)
    for u, v in edges:
        uf.union(u, v)
    return uf.count_sets()

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python components_counter.py <edge_file>")
        sys.exit(1)
    print("Components:", count_components(sys.argv[1]))

'''kruskal_mst.py
Implementation of Kruskal's algorithm for Minimum Spanning Tree (MST).
Edges are read from a file where each line contains ``u v w`` (0‑based
vertices and integer weight). The script prints the total weight of the
MST and the edges that belong to it.
'''

import sys
from typing import List, Tuple

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a: int, b: int) -> bool:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False
        if self.rank[ra] < self.rank[rb]:
            self.parent[ra] = rb
        elif self.rank[ra] > self.rank[rb]:
            self.parent[rb] = ra
        else:
            self.parent[rb] = ra
            self.rank[ra] += 1
        return True

def read_weighted_edges(path: str) -> Tuple[int, List[Tuple[int, int, int]]]:
    edges: List[Tuple[int, int, int]] = []
    max_v = -1
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if not line.strip():
                continue
            u_str, v_str, w_str = line.split()
            u, v, w = int(u_str), int(v_str), int(w_str)
            edges.append((u, v, w))
            max_v = max(max_v, u, v)
    return max_v + 1, edges

def kruskal_mst(vertex_count: int, edges: List[Tuple[int, int, int]]) -> Tuple[int, List[Tuple[int, int, int]]]:
    # Sort edges by weight (ascending)
    edges_sorted = sorted(edges, key=lambda e: e[2])
    uf = UnionFind(vertex_count)
    mst_weight = 0
    mst_edges: List[Tuple[int, int, int]] = []
    for u, v, w in edges_sorted:
        if uf.union(u, v):
            mst_weight += w
            mst_edges.append((u, v, w))
            if len(mst_edges) == vertex_count - 1:
                break
    return mst_weight, mst_edges

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python kruskal_mst.py <weighted_edge_file>")
        sys.exit(1)
    n, edges = read_weighted_edges(sys.argv[1])
    total, tree = kruskal_mst(n, edges)
    print("MST total weight:", total)
    print("Edges in MST:")
    for u, v, w in tree:
        print(f"{u} {v} {w}")

'''uf_visualizer.py
Utility that performs a sequence of union operations and then prints the
current partition of elements as a list of sets.  The script reads a file
where each line contains two integers ``a b`` representing ``union(a,b)``.
After processing, it builds a dictionary mapping each root to the list of
its members and displays them.
'''

import sys
from collections import defaultdict
from typing import List, Dict

class UnionFind:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x: int) -> int:
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, a: int, b: int) -> None:
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return
        if self.rank[ra] < self.rank[rb]:
            self.parent[ra] = rb
        elif self.rank[ra] > self.rank[rb]:
            self.parent[rb] = ra
        else:
            self.parent[rb] = ra
            self.rank[ra] += 1

def load_operations(path: str) -> List[Tuple[int, int]]:
    ops = []
    max_id = -1
    with open(path, "r", encoding="utf-8") as f:
        for line in f:
            if not line.strip():
                continue
            a_str, b_str = line.split()
            a, b = int(a_str), int(b_str)
            ops.append((a, b))
            max_id = max(max_id, a, b)
    return ops, max_id + 1  # number of distinct elements assuming 0‑based

def partition(uf: UnionFind) -> Dict[int, List[int]]:
    groups = defaultdict(list)
    for i in range(len(uf.parent)):
        root = uf.find(i)
        groups[root].append(i)
    return dict(groups)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python uf_visualizer.py <operations_file>")
        sys.exit(1)
    ops, size = load_operations(sys.argv[1])
    uf = UnionFind(size)
    for a, b in ops:
        uf.union(a, b)
    parts = partition(uf)
    print("Current partition of elements:")
    for root, members in sorted(parts.items()):
        print(f"Root {root}: {members}")

