'''file_bubble_sort.py
Reads integers from 'input.txt', sorts them with bubble sort, writes the sorted list
to 'output.txt' and prints a warning about bubble sort's inefficiency for large files.
'''

import sys

def bubble_sort(seq):
    """In‑place bubble sort returning the number of passes executed."""
    n = len(seq)
    passes = 0
    for i in range(n):
        made_swap = False
        for j in range(0, n - i - 1):
            if seq[j] > seq[j + 1]:
                seq[j], seq[j + 1] = seq[j + 1], seq[j]
                made_swap = True
        passes += 1
        if not made_swap:
            break
    return passes

def read_numbers(path):
    """Return a list of integers read line‑by‑line from *path*."""
    with open(path, 'r') as f:
        return [int(line.strip()) for line in f if line.strip()]

def write_numbers(path, numbers):
    """Write *numbers* to *path*, one per line."""
    with open(path, 'w') as f:
        for n in numbers:
            f.write(f"{n}
")

def main():
    input_file = 'input.txt'
    output_file = 'output.txt'
    try:
        data = read_numbers(input_file)
    except Exception as e:
        sys.exit(f"Failed to read {input_file}: {e}")

    if len(data) > 5000:
        print('Warning: Bubble sort on more than 5000 items may take a long time.')

    passes = bubble_sort(data)
    write_numbers(output_file, data)
    print(f'Sorted {len(data)} numbers in {passes} passes. Output written to {output_file}.')

if __name__ == '__main__':
    main()

'''basic_trie.py
Simple Trie implementation supporting insert and search operations.
''' 

class TrieNode:
    """Node of a Trie storing child links and an end‑of‑word flag."""
    __slots__ = ('children', 'is_word')

    def __init__(self):
        self.children = {}
        self.is_word = False

class Trie:
    """Trie data structure with insert and search methods."""
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        """Insert *word* into the trie.

        Complexity: O(len(word)).
        """
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_word = True

    def search(self, word: str) -> bool:
        """Return True if *word* was previously inserted, else False."""
        node = self.root
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.is_word

# Example usage when run as a script
if __name__ == '__main__':
    t = Trie()
    words = ['hello', 'world', 'help', 'helium']
    for w in words:
        t.insert(w)
    tests = ['hello', 'hell', 'world', 'wor', 'helium']
    for tword in tests:
        print(f"{tword!r} -> {t.search(tword)}")

'''prefix_trie.py
Trie supporting insertion, exact search and prefix enumeration.
''' 

from typing import List, Dict

class Node:
    __slots__ = ('children', 'end')
    def __init__(self):
        self.children: Dict[str, Node] = {}
        self.end: bool = False

class PrefixTrie:
    def __init__(self, words: List[str] = None):
        self.root = Node()
        if words:
            for w in words:
                self.insert(w)

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, Node())
        node.end = True

    def search(self, word: str) -> bool:
        node = self._walk(word)
        return bool(node) and node.end

    def starts_with(self, prefix: str) -> List[str]:
        """Return all stored words that begin with *prefix*.

        The function performs a DFS from the node representing the prefix.
        """
        node = self._walk(prefix)
        if not node:
            return []
        results: List[str] = []
        self._collect(node, prefix, results)
        return results

    def _walk(self, token: str) -> Node:
        node = self.root
        for ch in token:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

    def _collect(self, node: Node, prefix: str, out: List[str]) -> None:
        if node.end:
            out.append(prefix)
        for ch, child in node.children.items():
            self._collect(child, prefix + ch, out)

if __name__ == '__main__':
    sample = ['cat', 'car', 'cart', 'dog', 'dot', 'dove']
    trie = PrefixTrie(sample)
    print('Words starting with "ca":', trie.starts_with('ca'))
    print('Words starting with "do":', trie.starts_with('do'))
    print('Exact search for "cart":', trie.search('cart'))
    print('Exact search for "carp":', trie.search('carp'))

'''top_prefixes.py
Read a file, build a Trie of its words and report the ten most frequent 3‑letter prefixes.
''' 

import sys
import collections
from typing import Dict, List

class TrieNode:
    __slots__ = ('children', 'count')
    def __init__(self):
        self.children: Dict[str, TrieNode] = {}
        self.count: int = 0  # number of words that pass through this node

class PrefixCounterTrie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
            node.count += 1

    def top_n_prefixes(self, length: int, n: int) -> List[tuple]:
        """Return a list of (prefix, count) tuples for the *n* most common prefixes of given *length*."""
        results: List[tuple] = []
        def dfs(node: TrieNode, path: List[str]):
            if len(path) == length:
                results.append((''.join(path), node.count))
                return
            for ch, child in node.children.items():
                dfs(child, path + [ch])
        dfs(self.root, [])
        results.sort(key=lambda x: x[1], reverse=True)
        return results[:n]

def tokenize(text: str) -> List[str]:
    return [w.lower() for w in text.split() if w.isalpha()]

def main(filepath: str):
    trie = PrefixCounterTrie()
    with open(filepath, encoding='utf-8') as f:
        for line in f:
            for word in tokenize(line):
                trie.insert(word)
    top = trie.top_n_prefixes(3, 10)
    print('Top 10 three‑letter prefixes:')
    for pref, cnt in top:
        print(f"{pref}: {cnt}")

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python top_prefixes.py <path-to-text-file>')
        sys.exit(1)
    main(sys.argv[1])

'''deletable_trie.py
Trie supporting insert, search and delete operations.
''' 

from typing import Dict

class Node:
    __slots__ = ('children', 'is_word')
    def __init__(self):
        self.children: Dict[str, Node] = {}
        self.is_word: bool = False

class DeletableTrie:
    def __init__(self):
        self.root = Node()

    def insert(self, word: str) -> None:
        n = self.root
        for ch in word:
            n = n.children.setdefault(ch, Node())
        n.is_word = True

    def search(self, word: str) -> bool:
        n = self._walk(word)
        return bool(n) and n.is_word

    def delete(self, word: str) -> bool:
        """Remove *word* from the trie. Returns True if the word was present.
        The algorithm works recursively, deleting nodes that become unnecessary.
        """
        def _delete(node: Node, idx: int) -> bool:
            if idx == len(word):
                if not node.is_word:
                    return False  # word not present
                node.is_word = False
                return len(node.children) == 0  # prune if leaf
            ch = word[idx]
            child = node.children.get(ch)
            if not child:
                return False
            should_prune = _delete(child, idx + 1)
            if should_prune:
                del node.children[ch]
                return not node.is_word and len(node.children) == 0
            return False
        return _delete(self.root, 0)

    def _walk(self, token: str) -> Node:
        n = self.root
        for ch in token:
            n = n.children.get(ch)
            if n is None:
                return None
        return n

if __name__ == '__main__':
    t = DeletableTrie()
    for w in ['apple', 'app', 'application']:
        t.insert(w)
    print('search "app":', t.search('app'))
    t.delete('app')
    print('after delete, search "app":', t.search('app'))
    print('search "apple":', t.search('apple'))
    t.delete('apple')
    print('search "apple" after removal:', t.search('apple'))
    print('search "application":', t.search('application'))

'''autocomplete_trie.py
Trie based auto‑completion utility.
''' 

from typing import List, Dict

class TrieNode:
    __slots__ = ('children', 'end')
    def __init__(self):
        self.children: Dict[str, TrieNode] = {}
        self.end: bool = False

class AutoCompleteTrie:
    def __init__(self):
        self.root = TrieNode()

    def load_dictionary(self, path: str) -> None:
        """Read a plain‑text dictionary (one word per line) and insert each word."""
        with open(path, encoding='utf-8') as f:
            for line in f:
                word = line.strip()
                if word:
                    self.insert(word)

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.end = True

    def completions(self, prefix: str, limit: int = 10) -> List[str]:
        """Return up to *limit* words that start with *prefix*.
        Results are ordered alphabetically because children are traversed in sorted order.
        """
        node = self._walk(prefix)
        if not node:
            return []
        results: List[str] = []
        def dfs(cur: TrieNode, cur_prefix: List[str]):
            if len(results) >= limit:
                return
            if cur.end:
                results.append(''.join(cur_prefix))
            for ch in sorted(cur.children):
                dfs(cur.children[ch], cur_prefix + [ch])
        dfs(node, list(prefix))
        return results

    def _walk(self, token: str) -> TrieNode:
        n = self.root
        for ch in token:
            n = n.children.get(ch)
            if n is None:
                return None
        return n

if __name__ == '__main__':
    import sys
    if len(sys.argv) != 2:
        print('Usage: python autocomplete_trie.py <dictionary.txt>')
        sys.exit(1)
    trie = AutoCompleteTrie()
    trie.load_dictionary(sys.argv[1])
    while True:
        pref = input('Enter prefix (or empty to quit): ').strip()
        if not pref:
            break
        print('Suggestions:', trie.completions(pref))

'''url_trie.py
Trie for storing URLs and querying by domain prefix.
''' 

from urllib.parse import urlparse
from typing import List, Dict

class UrlNode:
    __slots__ = ('children', 'urls')
    def __init__(self):
        self.children: Dict[str, UrlNode] = {}
        self.urls: List[str] = []  # full URLs that end at this node

class UrlTrie:
    def __init__(self):
        self.root = UrlNode()

    def insert(self, url: str) -> None:
        """Insert *url* into the trie using its hostname as the key path."""
        hostname = urlparse(url).hostname or ''
        parts = hostname.split('.')[::-1]  # reverse for sub‑domain hierarchy
        node = self.root
        for part in parts:
            node = node.children.setdefault(part, UrlNode())
        node.urls.append(url)

    def query_domain(self, domain: str) -> List[str]:
        """Return all stored URLs whose hostname starts with *domain* (e.g., 'example.com')."""
        parts = domain.split('.')[::-1]
        node = self.root
        for part in parts:
            node = node.children.get(part)
            if node is None:
                return []
        return self._collect(node)

    def _collect(self, node: UrlNode) -> List[str]:
        result = list(node.urls)
        for child in node.children.values():
            result.extend(self._collect(child))
        return result

