# binary_maxheap.py
"""A minimal binary max‑heap implementation without using ``heapq``.

Features:
* ``insert`` – add a new key
* ``extract_max`` – remove and return the largest key
* ``heapify`` – turn an arbitrary list into a heap (called automatically
  on construction when a list is supplied)

A small self‑test runs when the module is executed directly.
"""
from __future__ import annotations
from typing import List, Any

class MaxHeap:
    def __init__(self, data: List[Any] | None = None):
        self._data: List[Any] = []
        if data:
            self._data = data[:]
            self.heapify()

    # ------------------------------------------------------------------
    def _parent(self, i: int) -> int:
        return (i - 1) // 2

    def _left(self, i: int) -> int:
        return 2 * i + 1

    def _right(self, i: int) -> int:
        return 2 * i + 2

    def _sift_up(self, i: int) -> None:
        while i > 0 and self._data[self._parent(i)] < self._data[i]:
            p = self._parent(i)
            self._data[i], self._data[p] = self._data[p], self._data[i]
            i = p

    def _sift_down(self, i: int) -> None:
        size = len(self._data)
        while True:
            l = self._left(i)
            r = self._right(i)
            largest = i
            if l < size and self._data[l] > self._data[largest]:
                largest = l
            if r < size and self._data[r] > self._data[largest]:
                largest = r
            if largest == i:
                break
            self._data[i], self._data[largest] = self._data[largest], self._data[i]
            i = largest

    # ------------------------------------------------------------------
    def insert(self, key: Any) -> None:
        """Add *key* to the heap and restore the heap property."""
        self._data.append(key)
        self._sift_up(len(self._data) - 1)

    def extract_max(self) -> Any:
        """Remove and return the maximum element.
        Raises ``IndexError`` if the heap is empty.
        """
        if not self._data:
            raise IndexError('extract_max from empty heap')
        max_item = self._data[0]
        last = self._data.pop()
        if self._data:
            self._data[0] = last
            self._sift_down(0)
        return max_item

    def heapify(self) -> None:
        """Convert the current list into a valid max‑heap in‑place."""
        for i in reversed(range(len(self._data) // 2)):
            self._sift_down(i)

    def __len__(self) -> int:
        return len(self._data)

    def __repr__(self) -> str:
        return f"MaxHeap({self._data})"

# ----------------------------------------------------------------------
def _run_tests() -> None:
    h = MaxHeap([3, 1, 4, 1, 5, 9, 2])
    assert len(h) == 7
    assert h.extract_max() == 9
    h.insert(6)
    assert h.extract_max() == 6
    remaining = sorted([h.extract_max() for _ in range(len(h))], reverse=True)
    assert remaining == [5, 4, 3, 2, 1, 1]
    print('All tests passed.')

if __name__ == '__main__':
    _run_tests()

# median_heap.py
"""MedianHeap maintains the median of a stream of numbers.

Two heaps are used:
* ``low`` – a max‑heap (implemented with negated values) containing the lower half
* ``high`` – a min‑heap containing the upper half

Insertion is O(log n).  The current median can be read in O(1) via the
``median`` property.
"""
import heapq
from typing import List

class MedianHeap:
    def __init__(self) -> None:
        self._low: List[int] = []   # max‑heap via negative numbers
        self._high: List[int] = []  # regular min‑heap

    def add(self, value: int) -> None:
        """Insert *value* into the structure and rebalance the two heaps."""
        if not self._low or value <= -self._low[0]:
            heapq.heappush(self._low, -value)
        else:
            heapq.heappush(self._high, value)
        # Rebalance so that sizes differ by at most one
        if len(self._low) > len(self._high) + 1:
            heapq.heappush(self._high, -heapq.heappop(self._low))
        elif len(self._high) > len(self._low):
            heapq.heappush(self._low, -heapq.heappop(self._high))

    @property
    def median(self) -> float:
        """Return the current median.
        If the total count is odd, the median is the top of ``_low``.
        If even, it is the average of the two heap tops.
        """
        if not self._low:
            raise ValueError('median requested from empty MedianHeap')
        if len(self._low) > len(self._high):
            return -self._low[0]
        return (-self._low[0] + self._high[0]) / 2.0

    def __len__(self) -> int:
        return len(self._low) + len(self._high)

if __name__ == '__main__':
    mh = MedianHeap()
    data = [5, 15, 1, 3, 8, 7, 9, 10, 6]
    for n in data:
        mh.add(n)
        print(f'Inserted {n}, current median: {mh.median}')

'''venv_web.py
A minimal Flask app exposing three endpoints:
  POST /create   – body: {"path": "myenv"}
  POST /install  – body: {"path": "myenv", "package": "requests"}
  GET  /list     – query: ?path=myenv
The app runs pip inside the requested virtual environment and returns JSON responses.
'''from flask import Flask, request, jsonify
import subprocess, sys, pathlib
app = Flask(__name__)

def venv_bin(venv_path: pathlib.Path) -> pathlib.Path:
    return venv_path / ('Scripts' if sys.platform == 'win32' else 'bin')

def exec_in_venv(venv_path: pathlib.Path, cmd: list) -> str:
    full_cmd = [str(venv_bin(venv_path) / cmd[0])] + cmd[1:]
    result = subprocess.run(full_cmd, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True)
    if result.returncode != 0:
        raise RuntimeError(result.stdout)
    return result.stdout.strip()

@app.route('/create', methods=['POST'])
def create():
    data = request.get_json(force=True)
    path = pathlib.Path(data['path']).resolve()
    subprocess.check_call([sys.executable, '-m', 'venv', str(path)])
    return jsonify({'status': 'created', 'path': str(path)})

@app.route('/install', methods=['POST'])
def install():
    data = request.get_json(force=True)
    path = pathlib.Path(data['path']).resolve()
    pkg = data['package']
    output = exec_in_venv(path, ['pip', 'install', pkg])
    return jsonify({'status': 'installed', 'package': pkg, 'output': output})

@app.route('/list', methods=['GET'])
def list_packages():
    path = pathlib.Path(request.args.get('path')).resolve()
    try:
        output = exec_in_venv(path, ['pip', 'freeze'])
        packages = [line for line in output.split('\n') if line]
    except RuntimeError as e:
        return jsonify({'error': str(e)}), 400
    return jsonify({'packages': packages})

if __name__ == '__main__':
    app.run(debug=True)

'''json_codec.py
Provides JsonEncoder and JsonDecoder classes that handle standard JSON plus
`datetime.datetime` objects by converting them to/from ISO‑8601 strings.
''' 

import json
from datetime import datetime
from typing import Any, Dict

ISO_FORMAT = '%Y-%m-%dT%H:%M:%S.%fZ'

class JsonEncoder(json.JSONEncoder):
    """Custom encoder that turns ``datetime`` objects into ISO‑8601 strings.

    Any other type is delegated to the default implementation.
    """
    def default(self, o: Any) -> Any:
        if isinstance(o, datetime):
            # Force UTC representation and strip microseconds if zero
            iso = o.strftime(ISO_FORMAT)
            return iso
        return super().default(o)

def json_decoder_hook(dct: Dict) -> Dict:
    """Object hook that attempts to parse ISO‑8601 strings back to ``datetime``.

    Only keys ending with '_at' are considered candidates for conversion.
    """
    for key, value in dct.items():
        if isinstance(value, str) and key.endswith('_at'):
            try:
                dct[key] = datetime.strptime(value, ISO_FORMAT)
            except ValueError:
                # Not a matching datetime string – leave as‑is
                pass
    return dct

def dumps(obj: Any, **kwargs: Any) -> str:
    """Serialize *obj* to a JSON string using ``JsonEncoder``.
    Additional ``json.dumps`` keyword arguments can be supplied.
    """
    return json.dumps(obj, cls=JsonEncoder, **kwargs)

def loads(s: str, **kwargs: Any) -> Any:
    """Deserialize *s* using ``json_decoder_hook`` to restore ``datetime`` objects.
    """
    return json.loads(s, object_hook=json_decoder_hook, **kwargs)

# Example usage when run as a script
if __name__ == '__main__':
    sample = {
        'event': 'test',
        'created_at': datetime.utcnow(),
        'payload': [1, 2, 3]
    }
    encoded = dumps(sample, indent=2)
    print('Serialized JSON:')
    print(encoded)
    decoded = loads(encoded)
    print('\nDeserialized object:')
    print(decoded)
    print('type of created_at:', type(decoded['created_at']))

