# average_by_key.sh – Compute average of the last column grouped by the first column.
# Usage: ./average_by_key.sh data.txt
# Output format: <key> <average>

set -euo pipefail

if [[ $# -ne 1 ]]; then
    echo "Usage: $0 <data-file>" >&2
    exit 1
fi

DATAFILE="$1"

awk '{
    key=$1
    val=$NF
    sum[key] += val
    cnt[key] += 1
