import sys
import json
from pathlib import Path
from typing import Dict, Any


def load_json(file_path: Path) -> Dict[str, Any]:
    """Load a JSON document from *file_path* and return it as a dictionary."""
    with file_path.open('r', encoding='utf-8') as f:
        return json.load(f)


def filter_path_keys(data: Dict[str, Any]) -> Dict[str, Any]:
    """Return a new dict containing only items whose keys include the substring 'path' (case‑insensitive)."""
    return {k: v for k, v in data.items() if 'path' in k.lower()}


def write_json(data: Dict[str, Any], dest: Path) -> None:
    """Write *data* to *dest* using pretty‑print formatting."""
    with dest.open('w', encoding='utf-8') as f:
        json.dump(data, f, indent=4, ensure_ascii=False)
    print(f"Wrote {len(data)} entries to {dest}")


def main(argv=None) -> None:
    argv = argv or sys.argv[1:]
    if len(argv) != 2:
        print("Usage: python extract_path_keys.py <input.json> <output.json>")
        sys.exit(1)
    input_path, output_path = map(Path, argv)
    if not input_path.is_file():
        print(f"Error: {input_path} does not exist or is not a file")
        sys.exit(2)
    raw = load_json(input_path)
    filtered = filter_path_keys(raw)
    write_json(filtered, output_path)


if __name__ == "__main__":
    main()

