'''file_mergesort.py
Utility that reads a newline‑separated list of integers, sorts them using mergesort,
and writes the sorted result to an output file.
Usage: python file_mergesort.py input.txt output.txt
'''

import sys
from typing import List

def _merge(a: List[int], b: List[int]) -> List[int]:
    i = j = 0
    result: List[int] = []
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            result.append(a[i])
            i += 1
        else:
            result.append(b[j])
            j += 1
    result.extend(a[i:])
    result.extend(b[j:])
    return result

def mergesort(arr: List[int]) -> List[int]:
    if len(arr) <= 1:
        return arr[:]
    mid = len(arr) // 2
    left = mergesort(arr[:mid])
    right = mergesort(arr[mid:])
    return _merge(left, right)

def read_numbers(path: str) -> List[int]:
    with open(path, 'r', encoding='utf-8') as f:
        return [int(line.strip()) for line in f if line.strip()]

def write_numbers(path: str, numbers: List[int]) -> None:
    with open(path, 'w', encoding='utf-8') as f:
        for n in numbers:
            f.write(f"{n}
")

def main(argv: List[str] = None) -> None:
    if argv is None:
        argv = sys.argv[1:]
    if len(argv) != 2:
        print('Usage: python file_mergesort.py <input> <output>')
        sys.exit(1)
    input_path, output_path = argv
    numbers = read_numbers(input_path)
    sorted_numbers = mergesort(numbers)
    write_numbers(output_path, sorted_numbers)
    print(f'Sorted {len(numbers)} numbers written to {output_path}')

if __name__ == '__main__':
    main()

'''linkedlist_mergesort.py
Mergesort implementation that works on a singly‑linked list.
Defines ``Node`` and ``LinkedList`` classes and a ``merge_sort`` method.
'''

from __future__ import annotations
from typing import Optional, Any

class Node:
    __slots__ = ('value', 'next')
    def __init__(self, value: Any, nxt: Optional['Node'] = None) -> None:
        self.value = value
        self.next = nxt

class LinkedList:
    def __init__(self, iterable: Optional[list[Any]] = None) -> None:
        self.head: Optional[Node] = None
        if iterable:
            for item in reversed(iterable):
                self.head = Node(item, self.head)

    def __iter__(self):
        cur = self.head
        while cur:
            yield cur.value
            cur = cur.next

    def to_list(self) -> list[Any]:
        return list(iter(self))

    @staticmethod
    def _split(head: Node) -> tuple[Optional[Node], Optional[Node]]:
        """Split the list starting at *head* into two halves using the fast/slow trick."""
        slow = head
        fast = head.next
        while fast and fast.next:
            slow = slow.next  # type: ignore[assignment]
            fast = fast.next.next
        middle = slow.next  # type: ignore[assignment]
        slow.next = None  # type: ignore[assignment]
        return head, middle

    @staticmethod
    def _merge(l1: Optional[Node], l2: Optional[Node]) -> Optional[Node]:
        dummy = Node(0)
        tail = dummy
        while l1 and l2:
            if l1.value <= l2.value:
                tail.next = l1
                l1 = l1.next
            else:
                tail.next = l2
                l2 = l2.next
            tail = tail.next
        tail.next = l1 if l1 else l2
        return dummy.next

    def _merge_sort(self, node: Optional[Node]) -> Optional[Node]:
        if node is None or node.next is None:
            return node
        left, right = self._split(node)
        left_sorted = self._merge_sort(left)
        right_sorted = self._merge_sort(right)
        return self._merge(left_sorted, right_sorted)

    def merge_sort(self) -> None:
        """Sort the linked list in place using mergesort."""
        self.head = self._merge_sort(self.head)

if __name__ == '__main__':
    ll = LinkedList([4, 2, 7, 3, 1, 5])
    print('Before:', ll.to_list())
    ll.merge_sort()
    print('After :', ll.to_list())

'''dict_values_enumerate.py

Given two dictionaries, extract the ``values()`` from each, pair the values
with ``zip`` and enumerate the pairs. The script demonstrates the ordering that
results from iterating over dictionary values (insertion order in Python 3.7+).
''' 

def print_enumerated_pairs(dict1, dict2):
    """Print each enumerated pair of values from *dict1* and *dict2*.

    The enumeration starts at 0. If the dictionaries differ in length, the
    shorter one determines the number of printed lines because ``zip`` stops
    at the shortest iterable.
    """
    for idx, (val1, val2) in enumerate(zip(dict1.values(), dict2.values())):
        print(f"{idx}: {val1} | {val2}")


def main():
    first = {'a': 10, 'b': 20, 'c': 30}
    second = {'x': 'apple', 'y': 'banana', 'z': 'cherry', 'w': 'date'}
    print_enumerated_pairs(first, second)


if __name__ == "__main__":
    main()

'''memoize.py
Simple memoization decorator that caches results of pure functions.
Works with functions that accept hashable arguments.
''' 
import functools

def memoize(func):
    """Cache the return value for each unique set of arguments.
    The cache is stored on the wrapper function as a dict named _cache.
    """
    cache = {}
    @functools.wraps(func)
    def wrapper(*args):
        if args in cache:
            return cache[args]
        result = func(*args)
        cache[args] = result
        return result
    wrapper._cache = cache  # expose for inspection or clearing
    return wrapper

# Demonstration with a recursive Fibonacci implementation
@memoize
def fib(n):
    """Return the nth Fibonacci number using a naive recursion.
    Thanks to @memoize the exponential blow‑up disappears.
    """
    if n < 2:
        return n
    return fib(n-1) + fib(n-2)

if __name__ == "__main__":
    for i in range(15):
        print(f"fib({i}) = {fib(i)}")
    print(f"Cache size after computation: {len(fib._cache)} entries")

'''type_check.py
Provides a @type_check decorator that validates arguments against type hints.
If a mismatch occurs a TypeError is raised.
''' 
import functools
import inspect

def type_check(func):
    """Validate arguments against the function's type annotations.
    Only positional and keyword arguments with explicit annotations are checked.
    """
    sig = inspect.signature(func)
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        bound = sig.bind(*args, **kwargs)
        bound.apply_defaults()
        for name, value in bound.arguments.items():
            expected = func.__annotations__.get(name)
            if expected and not isinstance(value, expected):
                raise TypeError(f"Argument '{name}' must be {expected.__name__}, got {type(value).__name__}")
        return func(*args, **kwargs)
    return wrapper

@type_check
def greet(name: str, times: int = 1) -> None:
    """Print *name* *times* times."""
    for _ in range(times):
        print(f"Hello, {name}!")

if __name__ == "__main__":
    greet("Alice", times=3)
    try:
        greet(123, times="two")
    except TypeError as e:
        print('Type error caught:', e)

'''command_registry.py
Implements a @command decorator that automatically adds the wrapped function
to a global COMMANDS dictionary keyed by a custom name.
The registry can be used to build simple command‑line interfaces.
''' 
import functools

COMMANDS = {}

def command(name=None):
    """Decorator that registers *func* in COMMANDS.
    If *name* is omitted the function's __name__ is used.
    """
    def decorator(func):
        reg_name = name or func.__name__
        COMMANDS[reg_name] = func
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapper
    return decorator

@command('greet')
def hello(who: str = 'world'):
    """Print a greeting message."""
    print(f"Hello, {who}!")

@command()
def add(a: int, b: int):
    """Add two integers and display the result."""
    print(f"{a} + {b} = {a + b}")

def run_command(name, *args):
    """Lookup *name* in COMMANDS and invoke the associated function.
    Raises KeyError if the command is not registered.
    """
    func = COMMANDS[name]
    func(*args)

if __name__ == "__main__":
    # Simple demonstration
    for cmd in COMMANDS:
        print(f"Available command: {cmd}")
    run_command('greet', 'Alice')
    run_command('add', 3, 5)

'''call_counter.py
Class based decorator that tracks call count per wrapped function.
The count is stored as an attribute ``calls`` on the wrapper instance.
''' 
import functools

class CallCounter:
    """Callable class used as a decorator.
    Each instance wraps a single function and increments ``calls``
    each time the function is invoked.
    """
    def __init__(self, func):
        functools.update_wrapper(self, func)
        self._func = func
        self.calls = 0

    def __call__(self, *args, **kwargs):
        self.calls += 1
        return self._func(*args, **kwargs)

# Example usage
@CallCounter
def multiply(a, b):
    """Return the product of *a* and *b*."""
    return a * b

if __name__ == "__main__":
    for i in range(1, 5):
        print(f"{i} * {i+1} = {multiply(i, i+1)} (call #{multiply.calls})")
    print(f"Total calls made to multiply: {multiply.calls}")

# int_descriptor.py
"""Descriptor example that ensures a managed attribute is always an integer.

`Integer` is a data descriptor implementing `__get__`, `__set__`, and
`__delete__`. The owning class `Person` uses it for the `age` field.
"""

class Integer:
    """Data descriptor that validates assignment to be an int.

    The value is stored in the instance's `__dict__` under a private name.
    """

    def __init__(self, name: str) -> None:
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name, None)

    def __set__(self, instance, value):
        if not isinstance(value, int):
            raise TypeError(f"Expected int for {self.private_name}, got {type(value).__name__}")
        setattr(instance, self.private_name, value)

    def __delete__(self, instance):
        raise AttributeError("Can't delete attribute")

class Person:
    """Simple class using the Integer descriptor for `age`."""

    age = Integer('age')

    def __init__(self, name: str, age: int) -> None:
        self.name = name
        self.age = age  # triggers descriptor validation

    def __repr__(self) -> str:
        return f"Person(name={self.name!r}, age={self.age})"

if __name__ == "__main__":
    p = Person('Alice', 30)
    print(p)
    try:
        p.age = 'thirty'  # should raise
    except TypeError as e:
        print('Error:', e)

# precedence_demo.py
"""Shows how Python resolves attribute access when both a descriptor
and a property exist with the same name.

`DataDesc` is a data descriptor (defines `__set__`). `Demo` also defines a
@property called `value`. The descriptor wins for all operations.
"""

class DataDesc:
    """Simple data descriptor that stores an integer and logs access."""

    def __init__(self, name: str):
        self.private_name = f"_{name}"
        self.name = name

    def __get__(self, instance, owner):
        if instance is None:
            return self
        print(f"[DataDesc] Getting {self.name}")
        return getattr(instance, self.private_name, 0)

    def __set__(self, instance, value):
        print(f"[DataDesc] Setting {self.name} to {value}")
        if not isinstance(value, int):
            raise TypeError('Only integers allowed')
        setattr(instance, self.private_name, value)

class Demo:
    """Class that defines both a descriptor and a property named `value`."""

    value = DataDesc('value')

    @property
    def value(self):  # this property is shadowed by DataDesc
        print('[Demo.property] Accessed')
        return 42

    @value.setter
    def value(self, val):  # also shadowed
        print('[Demo.property] Set called')
        self._value = val

    def __init__(self, start: int):
        self.value = start  # goes through DataDesc.__set__

if __name__ == "__main__":
    d = Demo(5)
    print('Current value:', d.value)  # triggers DataDesc.__get__
    d.value = 10  # triggers DataDesc.__set__
    print('After update:', d.value)

'''readonly_prop.py
A tiny example showing how to implement a read‑only attribute with @property.
'''

class Circle:
    """Simple circle class exposing a read‑only radius and a computed area."""

    def __init__(self, radius: float):
        if radius <= 0:
            raise ValueError('radius must be positive')
        self._radius = radius

    @property
    def radius(self) -> float:
        """Return the circle's radius.  No setter is provided – the attribute is read‑only."""
        return self._radius

    @property
    def area(self) -> float:
        """Calculate the area each time it is accessed.  This is a derived property."""
        import math
        return math.pi * self._radius ** 2

    def __repr__(self) -> str:
        return f'Circle(radius={self._radius})'


if __name__ == '__main__':
    c = Circle(3)
    print(c)               # Circle(radius=3)
    print('radius =', c.radius)
    print('area   =', c.area)
    # c.radius = 5  # <-- would raise AttributeError because no setter

'''type_checked.py
A reusable Typed descriptor that validates attribute assignments against a given type.
'''

from typing import Any


class Typed:
    """Descriptor that ensures a value matches the expected type."""

    def __init__(self, name: str, expected_type: type):
        self.name = '_' + name  # store under a private attribute name
        self.expected_type = expected_type

    def __get__(self, instance: Any, owner: type) -> Any:
        if instance is None:
            return self  # accessed through class, return descriptor itself
        return getattr(instance, self.name)

    def __set__(self, instance: Any, value: Any) -> None:
        if not isinstance(value, self.expected_type):
            raise TypeError(f'Expected {self.expected_type.__name__} for {self.name[1:]}, got {type(value).__name__}')
        setattr(instance, self.name, value)

    def __delete__(self, instance: Any) -> None:
        raise AttributeError('Cannot delete attribute')


class Person:
    """Example class that uses Typed descriptors for its fields."""

    name = Typed('name', str)
    age = Typed('age', int)
    height = Typed('height', float)

    def __init__(self, name: str, age: int, height: float):
        self.name = name
        self.age = age
        self.height = height

    def __repr__(self) -> str:
        return f'Person(name={self.name!r}, age={self.age}, height={self.height})'


if __name__ == '__main__':
    p = Person('Ada', 30, 1.68)
    print(p)
    try:
        p.age = 'thirty'  # triggers TypeError
    except TypeError as e:
        print('Error:', e)
    try:
        del p.name  # triggers AttributeError
    except AttributeError as e:
        print('Error:', e)

'''cached_property.py
A custom descriptor that computes a value once per instance and then caches it.
'''

from functools import wraps


class Cached:
    """Descriptor that lazily computes a value and caches it on first access."""

    def __init__(self, func):
        self.func = func
        self.attr_name = f'_{func.__name__}_cached'

    def __get__(self, instance, owner):
        if instance is None:
            return self  # accessed via class
        if not hasattr(instance, self.attr_name):
            # compute and store the result
            setattr(instance, self.attr_name, self.func(instance))
        return getattr(instance, self.attr_name)

    def __delete__(self, instance):
        if hasattr(instance, self.attr_name):
            delattr(instance, self.attr_name)


def cached_property(func):
    """Helper to create a Cached descriptor using decorator syntax."""
    return Cached(func)


class Fibonacci:
    """Simple Fibonacci sequence where the nth value is cached after first calculation."""

    def __init__(self, n):
        self.n = n

    @cached_property
    def value(self) -> int:
        """Recursively compute the nth Fibonacci number (inefficient on purpose)."""
        if self.n <= 0:
            return 0
        if self.n == 1:
            return 1
        # Use separate Fibonacci objects for sub‑problems
        return Fibonacci(self.n - 1).value + Fibonacci(self.n - 2).value

    def __repr__(self) -> str:
        return f'Fibonacci(n={self.n}, value={self.value})'


if __name__ == '__main__':
    f = Fibonacci(10)
    print('First access computes:', f.value)
    # Subsequent access retrieves cached result without recomputation
    print('Second access uses cache:', f.value)
    # Delete cached value and force recomputation
    del f.value
    print('After delete, recomputed:', f.value)

'''list_manager.py
Example mixing a simple @property with a custom descriptor to protect a list attribute.
'''

from collections.abc import Sequence
from typing import Any, List


class ListDescriptor:
    """Descriptor that stores a list and validates items on assignment."""

    def __init__(self, name: str, item_type: type):
        self.storage_name = '_' + name  # private attribute name
        self.item_type = item_type

    def __get__(self, instance: Any, owner: type) -> List[Any]:
        if instance is None:
            return self
        # Return a shallow copy so external code cannot mutate the original list directly
        return list(getattr(instance, self.storage_name))

    def __set__(self, instance: Any, value: Sequence) -> None:
        if not isinstance(value, Sequence):
            raise TypeError('Assigned value must be a sequence')
        # Validate each element
        for i, item in enumerate(value):
            if not isinstance(item, self.item_type):
                raise TypeError(f'Item {i} is not of type {self.item_type.__name__}')
        setattr(instance, self.storage_name, list(value))

    def __delete__(self, instance: Any) -> None:
        raise AttributeError('Cannot delete the list attribute')


class Inventory:
    """Manages a collection of product codes with type safety and a read‑only view."""

    # Use the descriptor for the mutable internal list
    _codes = ListDescriptor('codes', str)

    def __init__(self, initial: List[str] | None = None):
        self._codes = initial or []

    @property
    def codes(self) -> tuple:
        """Expose an immutable snapshot of the codes as a tuple."""
        return tuple(self._codes)

    def add_code(self, code: str) -> None:
        """Append a new product code after validation (descriptor already ensures type)."""
        if not isinstance(code, str):
            raise TypeError('code must be a string')
        # Directly modify the internal list via the descriptor's storage name
        self._codes.append(code)

    def __repr__(self) -> str:
        return f'Inventory(codes={self.codes})'


if __name__ == '__main__':
    inv = Inventory(['A001', 'B202'])
    print(inv)
    inv.add_code('C303')
    print('After add:', inv.codes)
    # Replace the whole list using the descriptor (will validate each element)
    inv._codes = ['X999', 'Y888']
    print('Replaced:', inv.codes)
    try:
        inv._codes = ['good', 123]  # triggers TypeError
    except TypeError as e:
        print('Error:', e)
    try:
        del inv._codes
    except AttributeError as e:
        print('Error:', e)

'''log_descriptor.py
A descriptor that prints a log message on every get, set, and delete operation.
'''

import datetime


class LoggedAttr:
    """Descriptor that logs access to an attribute for debugging purposes."""

    def __init__(self, name: str, default: Any = None):
        self.private_name = '_' + name
        self.default = default

    def _log(self, action: str, instance: Any, value: Any = None) -> None:
        ts = datetime.datetime.now().isoformat(timespec='seconds')
        if action == 'set':
            print(f'[{ts}] SET {self.private_name} = {value!r} on {instance}')
        elif action == 'get':
            print(f'[{ts}] GET {self.private_name} -> {value!r} from {instance}')
        elif action == 'del':
            print(f'[{ts}] DELETE {self.private_name} from {instance}')

    def __get__(self, instance: Any, owner: type) -> Any:
        if instance is None:
            return self
        value = getattr(instance, self.private_name, self.default)
        self._log('get', instance, value)
        return value

    def __set__(self, instance: Any, value: Any) -> None:
        self._log('set', instance, value)
        setattr(instance, self.private_name, value)

    def __delete__(self, instance: Any) -> None:
        self._log('del', instance)
        if hasattr(instance, self.private_name):
            delattr(instance, self.private_name)


class Config:
    """Sample class using LoggedAttr for its settings."""

    host = LoggedAttr('host', default='localhost')
    port = LoggedAttr('port', default=8080)

    def __repr__(self) -> str:
        return f'Config(host={self.host!r}, port={self.port!r})'


if __name__ == '__main__':
    cfg = Config()
    print(cfg)
    cfg.host = 'example.com'
    cfg.port = 443
    print('Current host:', cfg.host)
    del cfg.port
    print('After delete:', cfg)

'''range_validator.py
Descriptor that enforces a numeric value lies within a specified inclusive range.
'''

from typing import Any


class BoundedNumber:
    """Descriptor enforcing min <= value <= max for numeric attributes."""

    def __init__(self, name: str, *, min_val: float, max_val: float):
        self.private_name = '_' + name
        self.min_val = min_val
        self.max_val = max_val

    def __get__(self, instance: Any, owner: type) -> float:
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance: Any, value: float) -> None:
        if not isinstance(value, (int, float)):
            raise TypeError(f'{self.private_name[1:]} must be a number')
        if not (self.min_val <= value <= self.max_val):
            raise ValueError(f'{self.private_name[1:]} must be between {self.min_val} and {self.max_val}')
        setattr(instance, self.private_name, float(value))

    def __delete__(self, instance: Any) -> None:
        raise AttributeError('Cannot delete bounded attribute')


class TemperatureSensor:
    """Simulates a sensor that reports temperature in Celsius, bounded between -50 and 150."""

    celsius = BoundedNumber('celsius', min_val=-50.0, max_val=150.0)

    def __init__(self, initial: float = 20.0):
        self.celsius = initial

    @property
    def fahrenheit(self) -> float:
        """Convert the stored Celsius temperature to Fahrenheit (read‑only)."""
        return self.celsius * 9 / 5 + 32

    def __repr__(self) -> str:
        return f'TemperatureSensor(celsius={self.celsius:.1f}, fahrenheit={self.fahrenheit:.1f})'


if __name__ == '__main__':
    sensor = TemperatureSensor()
    print(sensor)
    sensor.celsius = 100
    print('Updated:', sensor)
    try:
        sensor.celsius = -100  # out of range
    except ValueError as e:
        print('Error:', e)
    try:
        sensor.celsius = 'hot'  # wrong type
    except TypeError as e:
        print('Error:', e)

