# pipeline_abort.sh – Executes a three‑stage pipeline with set -e; on failure prints stage and code to stderr.
# Usage: ./pipeline_abort.sh

set -euo pipefail

# Helper to run a stage and report failures.
run_stage() {
    local name="$1"
    shift
    echo "[stage] $name" >&2
    "$@"
}

# Stages of the pipeline.
stage1() { run_stage "stage1: list /" ls /; }
stage2() { run_stage "stage2: grep missing" ls / | grep missing; }
stage3() { run_stage "stage3: count lines" wc -l; }

# Trap to capture the failing stage's exit code.
trap 'rc=$?; echo "Error: stage failed with exit code $rc" >&2; exit $rc' ERR

# Execute pipeline.
stage1 | stage2 | stage3

