'''mixed_sort.py
Sort a heterogeneous list containing int/float and str values.
Numbers are placed before strings; numbers are ordered ascending, strings
alphabetically. The script demonstrates the key function and prints
the sorted result.
''' 
from typing import List, Any

def type_key(value: Any) -> tuple:
    """Return a tuple that groups numbers before strings.

    Numbers get a leading 0, strings a leading 1. The second element
    ensures natural ordering within each group.
    """
    if isinstance(value, (int, float)):
        return (0, value)
    if isinstance(value, str):
        return (1, value.lower())
    raise TypeError('Unsupported type in list')

def sort_mixed(items: List[Any]) -> List[Any]:
    """Return a new list sorted by type_key.
    """
    return sorted(items, key=type_key)

def main():
    data = [42, 'banana', 3.14, 'Apple', 7, 'orange', 1]
    print('Original:', data)
    print('Sorted  :', sort_mixed(data))

if __name__ == '__main__':
    main()

'''json_city_sort.py
