import json
from typing import List, Dict, Any

def load_data(path: str) -> List[Dict[str, Any]]:
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

def city_key(item: Dict[str, Any]) -> str:
    """Extract the city name from a nested address structure.
    If the key is missing, return an empty string so the item sorts first.
    """
    return item.get('address', {}).get('city', '')

def sort_by_city(data: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    return sorted(data, key=city_key)

def main():
