'''product_sort.py
Defines a simple Product class and sorts a collection of products.
Sorting priority: price ascending, then rating descending. The key
function builds a tuple that reflects these rules.
''' 
from dataclasses import dataclass
from typing import List

@dataclass
class Product:
    name: str
    price: float
    rating: int  # 1‑5 stars, higher is better

    def __repr__(self) -> str:
        return f"{self.name} – ${self.price:.2f}, rating {self.rating}"

def product_key(p: Product) -> tuple:
    """Return a tuple (price, -rating) for sorting.
    The negative rating flips the order so higher ratings come first.
    """
    return (p.price, -p.rating)

def sort_products(items: List[Product]) -> List[Product]:
    return sorted(items, key=product_key)

