'''binomial_memo.py
Defines a ``Combinatorics`` class with a memoized ``binomial`` method
that returns C(n, k) using the recursive relation C(n, k) = C(n-1, k-1) + C(n-1, k).
The memoization cache is stored on the instance to keep results
separate for each object.
''' 

from functools import lru_cache
from typing import Dict, Tuple

class Combinatorics:
    def __init__(self) -> None:
        # instance‑specific cache: (n, k) -> value
        self._cache: Dict[Tuple[int, int], int] = {}

    def binomial(self, n: int, k: int) -> int:
        """Return the binomial coefficient C(n, k).
        Values are cached per instance to avoid recomputation of overlapping subproblems.
        """
        if k < 0 or k > n:
            raise ValueError('k must satisfy 0 <= k <= n')
        if k == 0 or k == n:
            return 1
        key = (n, k)
        if key in self._cache:
            return self._cache[key]
        value = self.binomial(n - 1, k - 1) + self.binomial(n - 1, k)
        self._cache[key] = value
        return value

    def cache_size(self) -> int:
        """Return the number of cached entries."""
        return len(self._cache)

def main() -> None:
    combo = Combinatorics()
    for n in range(6):
        row = [combo.binomial(n, k) for k in range(n + 1)]
        print(row)
    print('Cache entries:', combo.cache_size())

if __name__ == "__main__":
    main()

'''ackermann_memo.py
Implements the classic Ackermann function with memoization.
Because Ackermann grows extremely fast, the wrapper also catches ``RecursionError``
and returns ``None`` for inputs that exceed the interpreter limit.
''' 

from functools import lru_cache
from typing import Optional

@lru_cache(maxsize=None)
def ackermann(m: int, n: int) -> Optional[int]:
    """Compute Ackermann(m, n) with memoization.
    Returns ``None`` if the recursion depth limit is hit.
    """
    try:
        if m == 0:
            return n + 1
        if n == 0:
            return ackermann(m - 1, 1)
        return ackermann(m - 1, ackermann(m, n - 1))
    except RecursionError:
        # Signal that the computation cannot be completed safely
        return None

def main() -> None:
    test_cases = [(2, 3), (3, 2), (3, 4)]
    for m, n in test_cases:
        result = ackermann(m, n)
        if result is None:
            print(f"Ackermann({m}, {n}) exceeded recursion limit.")
        else:
            print(f"Ackermann({m}, {n}) = {result}")

if __name__ == "__main__":
    main()

"""nqueens_one.py
Find a single solution for the N‑Queens puzzle using backtracking.
The board size is read from standard input or defaults to 8.
The solution is printed as a list of column positions.
"""
import sys
from typing import List, Optional

def safe(cols: List[int], row: int, col: int) -> bool:
    for r, c in enumerate(cols):
        if c == col or abs(c - col) == abs(r - row):
            return False
    return True

def backtrack(n: int, row: int, cols: List[int]) -> Optional[List[int]]:
    if row == n:
        return cols.copy()
    for col in range(n):
        if safe(cols, row, col):
            cols.append(col)
            result = backtrack(n, row + 1, cols)
            if result:
                return result
            cols.pop()
    return None

def main() -> None:
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 8
    solution = backtrack(n, 0, [])
    if solution:
        print(f"One solution for {n}-Queens: {solution}")
    else:
        print(f"No solution exists for {n} queens.")

if __name__ == "__main__":
    main()

