import sys
from typing import List

def print_board(cols: List[int], n: int) -> None:
    for r in range(n):
        row = ['.'] * n
        if r < len(cols):
            row[cols[r]] = 'Q'
        print(''.join(row))
    print('-' * n)

def safe(cols: List[int], row: int, col: int) -> bool:
    for r, c in enumerate(cols):
        if c == col or abs(c - col) == abs(r - row):
            return False
    return True

