'''fib_memoizer.py
Implements a memoizing closure for the Fibonacci sequence.
The inner function remembers previously computed values in a dictionary.
'''

def make_fib():
    """Return a memoized Fibonacci function.
    The cache lives in the enclosing scope, so repeated calls are O(1).
    """
    cache = {0: 0, 1: 1}
    def fib(n: int) -> int:
        if n < 0:
            raise ValueError('n must be non‑negative')
        if n not in cache:
            cache[n] = fib(n - 1) + fib(n - 2)
        return cache[n]
    return fib

