'''command_dispatcher.py
Implements a dispatcher that registers commands created via a closure.
Each command function remembers its own `name` and `action` description.
'''

def command_factory(name, action):
    """Return a command function that prints its name and performs `action`.
    The closure stores `name` and `action` so they are available when the command
    is invoked later.
    """
    def command(*args, **kwargs):
        print(f'Executing {name}!')
        return action(*args, **kwargs)
    return command

class Dispatcher:
    def __init__(self):
        self._registry = {}
    def register(self, name, action):
        self._registry[name] = command_factory(name, action)
    def run(self, name, *args, **kwargs):
        if name not in self._registry:
            raise KeyError(f'Command {name!r} not found')
        return self._registry[name](*args, **kwargs)

# Sample actions
def greet(person):
    return f'Hello, {person}!'

def add(x, y):
    return x + y

if __name__ == '__main__':
    d = Dispatcher()
    d.register('greet', greet)
    d.register('add', add)
    print(d.run('greet', 'Alice'))
    print('Sum:', d.run('add', 3, 7))

'''expensive_cache.py
Defines an artificially expensive function `slow_power(x, y)` that sleeps for 0.001 s per call.
Two wrappers are provided:
  - uncached_power: calls the function directly each time.
  - cached_power: the same function wrapped with @lru_cache(maxsize=None).
The script runs 2000 random calls for each wrapper, measures total time, and reports the cache size.
''' 
import random, time, functools, sys

@functools.lru_cache(maxsize=None)
def cached_power(x: int, y: int) -> int:
    return _slow_power(x, y)

def uncached_power(x: int, y: int) -> int:
    return _slow_power(x, y)

def _slow_power(base: int, exp: int) -> int:
    # Simulate work
    time.sleep(0.001)
    return pow(base, exp)

def benchmark(func, calls):
    start = time.perf_counter()
    for _ in range(calls):
        a = random.randint(1, 20)
        b = random.randint(1, 5)
        func(a, b)
    return time.perf_counter() - start

if __name__ == '__main__':
    CALLS = 2000
    t_uncached = benchmark(uncached_power, CALLS)
    t_cached = benchmark(cached_power, CALLS)
    cache_info = cached_power.cache_info()
    print(f'Uncached total time: {t_uncached:.3f}s')
    print(f'Cached total time:   {t_cached:.3f}s')
    print(f'Cache hits: {cache_info.hits}, misses: {cache_info.misses}, current size: {cache_info.currsize}')

"""config_class.py
A flexible Config class that reads values from the environment, applies type
conversions, and allows callers to override any setting via keyword arguments.

Example
-------
    cfg = Config(debug=True, timeout=60)
    print(cfg.database_url)
"""

import os
from typing import Any, Callable, Dict

class Config:
    """Container for application configuration.

    Attributes are populated from ``os.environ`` using the ``_spec`` mapping.
    Users may pass explicit values to the constructor to override defaults or
    environment‑derived values.
    """

    # Specification: env name → (attr name, conversion callable, default)
    _spec: Dict[str, tuple[str, Callable[[str], Any], Any]] = {
        "DATABASE_URL": ("database_url", str, "sqlite:///default.db"),
        "APP_PORT": ("port", int, 8080),
        "DEBUG": ("debug", lambda v: v.lower() in {"1", "true", "yes"}, False),
        "TIMEOUT": ("timeout", int, 30),
        "MAX_WORKERS": ("max_workers", int, 4),
    }

    def __init__(self, **overrides: Any):
        for env_key, (attr, cast, default) in self._spec.items():
            if attr in overrides:
                value = overrides[attr]
            else:
                raw = os.getenv(env_key)
                if raw is None:
                    value = default
                else:
                    try:
                        value = cast(raw)
                    except Exception as exc:
                        raise ValueError(f"Unable to cast env var {env_key}: {exc}") from exc
            setattr(self, attr, value)

    def as_dict(self) -> Dict[str, Any]:
        """Return a plain dictionary representation of the configuration."""
        return {attr: getattr(self, attr) for _, (attr, _, _) in self._spec.items()}

    def __repr__(self) -> str:
        attrs = ", ".join(f"{k}={v!r}" for k, v in self.as_dict().items())
        return f"Config({attrs})"

'''max_heap_demo.py
A small demonstration of a max‑heap built on top of Python's built‑in heapq module.
The heap stores tuples (negated_key, value) so that the smallest tuple corresponds to the
largest original key.  Functions are provided for push, pop, peek and a simple test.
'''import heapq
from typing import List, Tuple, Any

class MaxHeap:
    """A max‑heap wrapper around heapq.

    The internal list ``_data`` holds ``(neg_key, item)`` pairs.  Using a negative key
    turns the min‑heap behaviour of ``heapq`` into a max‑heap.
    """

    def __init__(self, items: List[Tuple[int, Any]] | None = None) -> None:
        self._data: List[Tuple[int, Any]] = []
        if items:
            for key, value in items:
                self.push(key, value)
        heapq.heapify(self._data)

    def push(self, key: int, value: Any) -> None:
        """Insert *value* with priority *key* (larger key == higher priority)."""
        heapq.heappush(self._data, (-key, value))

    def pop(self) -> Tuple[int, Any]:
        """Remove and return the element with the highest priority as ``(key, value)``."""
        neg_key, value = heapq.heappop(self._data)
        return -neg_key, value

    def peek(self) -> Tuple[int, Any] | None:
        """Return the highest‑priority element without removing it, or ``None`` if empty."""
        if not self._data:
            return None
        neg_key, value = self._data[0]
        return -neg_key, value

    def __len__(self) -> int:
        return len(self._data)

    def __repr__(self) -> str:
        return f"MaxHeap({[self.peek() for _ in range(len(self))]})"


def demo() -> None:
    """Run a simple sequence of operations and print the results."""
    h = MaxHeap([(5, 'apple'), (1, 'banana'), (3, 'cherry')])
    print('Initial heap peek:', h.peek())
    h.push(7, 'date')
    print('After pushing (7, "date"): peek =', h.peek())
    while len(h):
        key, val = h.pop()
        print(f'Popped ({key}, {val})')

if __name__ == '__main__':
