'''dijkstra_cli.py
Command‑line utility that runs Dijkstra's shortest‑path algorithm on a hard‑coded
sample graph.  The implementation uses the ``PriorityQueue`` class defined in
``priority_queue.py`` (included below) to select the next vertex with the smallest
tentative distance.
Usage: python dijkstra_cli.py <source> <target>
If omitted, it defaults to "A" -> "E" on the sample graph.
'''import sys
from typing import Dict, Tuple, List, Any
import heapq

# --- Simple priority queue (min‑heap) ---------------------------------------
class SimplePQ:
    def __init__(self) -> None:
        self._data: List[Tuple[float, Any]] = []

    def push(self, priority: float, item: Any) -> None:
        heapq.heappush(self._data, (priority, item))

    def pop(self) -> Tuple[float, Any]:
        return heapq.heappop(self._data)

    def __bool__(self) -> bool:
        return bool(self._data)

# --- Dijkstra --------------------------------------------------------------
def dijkstra(graph: Dict[str, List[Tuple[str, float]]], start: str) -> Tuple[Dict[str, float], Dict[str, str]]:
    """Return distance and predecessor maps for shortest paths from *start*.

    ``graph`` maps a vertex to a list of ``(neighbor, weight)`` tuples.
    """
    dist: Dict[str, float] = {v: float('inf') for v in graph}
    prev: Dict[str, str] = {}
    dist[start] = 0.0
    pq = SimplePQ()
    pq.push(0.0, start)
    while pq:
        cur_dist, u = pq.pop()
        if cur_dist != dist[u]:
            continue  # stale entry
        for v, w in graph[u]:
            alt = cur_dist + w
            if alt < dist[v]:
                dist[v] = alt
                prev[v] = u
                pq.push(alt, v)
    return dist, prev

def reconstruct_path(prev: Dict[str, str], start: str, goal: str) -> List[str]:
    """Build the path from *start* to *goal* using the predecessor map."""
    path: List[str] = []
    cur = goal
    while cur != start:
        path.append(cur)
        cur = prev.get(cur)
        if cur is None:
            return []  # no path
    path.append(start)
    path.reverse()
    return path

def main(argv: List[str] | None = None) -> None:
    if argv is None:
        argv = sys.argv[1:]
    # Sample undirected weighted graph
    graph = {
        'A': [('B', 2), ('C', 5)],
        'B': [('A', 2), ('C', 1), ('D', 4)],
        'C': [('A', 5), ('B', 1), ('D', 1), ('E', 3)],
        'D': [('B', 4), ('C', 1), ('E', 2)],
        'E': [('C', 3), ('D', 2)],
    }
    start = argv[0] if len(argv) > 0 else 'A'
    goal = argv[1] if len(argv) > 1 else 'E'
    if start not in graph or goal not in graph:
        print(f"Error: vertices must be one of {list(graph)}")
        sys.exit(1)
    dist, prev = dijkstra(graph, start)
    path = reconstruct_path(prev, start, goal)
    if not path:
        print(f'No path from {start} to {goal}.')
    else:
        print(f'Shortest path {start} → {goal}:', ' → '.join(path))
        print(f'Total distance: {dist[goal]:.2f}')

if __name__ == '__main__':
    main()

'''leftist_heap.py
Implementation of a leftist heap (min‑heap) with merge, insert, and delete_min.
A leftist heap maintains the "null‑path length" (npl) property so that the right
spine is always the shortest, enabling O(log n) merge.
The file ends with a small demo that builds a heap from random numbers.
'''import random
from typing import Optional, Tuple

class LeftistNode:
    __slots__ = ('key', 'left', 'right', 'npl')

    def __init__(self, key: int):
        self.key: int = key
        self.left: Optional['LeftistNode'] = None
        self.right: Optional['LeftistNode'] = None
        self.npl: int = 0  # null‑path length

    def __repr__(self) -> str:
        return f'Node({self.key}, npl={self.npl})'

def _merge(a: Optional[LeftistNode], b: Optional[LeftistNode]) -> Optional[LeftistNode]:
    if a is None:
        return b
    if b is None:
        return a
    if a.key > b.key:
        a, b = b, a
    # a.key <= b.key, merge b into a.right
    a.right = _merge(a.right, b)
    # Ensure leftist property: left.npl >= right.npl
    left_npl = a.left.npl if a.left else -1
    right_npl = a.right.npl if a.right else -1
    if left_npl < right_npl:
        a.left, a.right = a.right, a.left
    a.npl = (a.right.npl if a.right else -1) + 1
    return a

class LeftistHeap:
    """A min‑heap based on the leftist tree structure.
    Supports ``merge``, ``insert`` and ``delete_min`` in O(log n).
    """

    def __init__(self, iterable: Optional[Tuple[int, ...]] = None) -> None:
        self.root: Optional[LeftistNode] = None
        if iterable:
            for v in iterable:
                self.insert(v)

    def merge(self, other: 'LeftistHeap') -> None:
        """Merge *other* heap into this one; ``other`` becomes empty."""
        self.root = _merge(self.root, other.root)
        other.root = None

    def insert(self, key: int) -> None:
        """Insert *key* by merging a single‑node heap."""
        self.root = _merge(self.root, LeftistNode(key))

    def find_min(self) -> int:
        if self.root is None:
            raise IndexError('find_min from empty heap')
        return self.root.key

    def delete_min(self) -> int:
        """Remove and return the smallest key."""
        if self.root is None:
            raise IndexError('delete_min from empty heap')
        min_key = self.root.key
        left, right = self.root.left, self.root.right
        self.root = _merge(left, right)
        return min_key

    def is_empty(self) -> bool:
        return self.root is None

    def __len__(self) -> int:
        # simplistic O(n) count for demo purposes
        def count(node: Optional[LeftistNode]) -> int:
            if not node:
                return 0
            return 1 + count(node.left) + count(node.right)
        return count(self.root)

    def __repr__(self) -> str:
        return f'LeftistHeap(size={len(self)})'

# ----- demonstration -------------------------------------------------------
if __name__ == '__main__':
    random.seed(42)
    values = [random.randint(1, 100) for _ in range(15)]
    print('Inserting values:', values)
    heap = LeftistHeap()
    for v in values:
        heap.insert(v)
    print('Heap size after inserts:', len(heap))
    sorted_vals = []
    while not heap.is_empty():
        sorted_vals.append(heap.delete_min())
    print('Values extracted in order:', sorted_vals)

'''env_config.py
A lightweight configuration class that reads key=value pairs from a .env file,
combines them with the current process environment, and exposes values as
attributes. Missing keys raise AttributeError.
'''import os
from pathlib import Path

class Config:
    """Configuration holder that merges a .env file with os.environ.

    Example .env content::
        API_KEY=abc123
        TIMEOUT=30
    """
    def __init__(self, env_path: str | Path = ".env"):
        self._store: dict[str, str] = {}
        self._load_file(Path(env_path))
        # Overlay actual environment variables (they win over .env values)
        self._store.update({k: v for k, v in os.environ.items() if k in self._store})

    def _load_file(self, path: Path) -> None:
        if not path.is_file():
            return  # Silently ignore missing .env
        for line in path.read_text().splitlines():
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            if "=" not in line:
                continue
            key, val = line.split('=', 1)
            self._store[key.strip()] = val.strip()

    def __getattr__(self, name: str) -> str:
        try:
            return self._store[name]
        except KeyError:
            raise AttributeError(f"Configuration has no attribute '{name}'") from None

    def get(self, name: str, default: str | None = None) -> str | None:
        """Return *name* if present, otherwise *default* (or None)."""
        return self._store.get(name, default)

# Example usage when run directly
if __name__ == "__main__":
    cfg = Config()
    print("API_KEY:", cfg.get("API_KEY", "not set"))
    # Access via attribute (may raise AttributeError)
    try:
        print("TIMEOUT:", cfg.TIMEOUT)
    except AttributeError as e:
        print(e)

'''set_utils.py
Utility functions that wrap the built‑in set operators and expose them as explicit functions.
The module also contains a simple unittest.TestCase class to verify correct behaviour.
'''from typing import Iterable, Set
import unittest

def make_set(iterable: Iterable) -> Set:
    """Convert any iterable to a set, discarding duplicates.
    """
    return set(iterable)

def union(a: Iterable, b: Iterable) -> Set:
    """Return the union of two iterables as a set (a ∪ b)."""
    return make_set(a) | make_set(b)

def intersection(a: Iterable, b: Iterable) -> Set:
    """Return the intersection of two iterables as a set (a ∩ b)."""
    return make_set(a) & make_set(b)

def difference(a: Iterable, b: Iterable) -> Set:
    """Return the difference of two iterables as a set (a - b)."""
    return make_set(a) - make_set(b)

def is_subset(a: Iterable, b: Iterable) -> bool:
    """Return True if *a* is a subset of *b*.
    Equivalent to make_set(a) <= make_set(b).
    """
    return make_set(a) <= make_set(b)

class TestSetUtils(unittest.TestCase):
    def setUp(self):
        self.a = [1, 2, 3, 3]
        self.b = [3, 4, 5]

    def test_union(self):
        self.assertEqual(union(self.a, self.b), {1, 2, 3, 4, 5})

    def test_intersection(self):
        self.assertEqual(intersection(self.a, self.b), {3})

    def test_difference(self):
        self.assertEqual(difference(self.a, self.b), {1, 2})

    def test_is_subset_true(self):
        self.assertTrue(is_subset([1, 2], self.a))

    def test_is_subset_false(self):
        self.assertFalse(is_subset(self.b, self.a))

if __name__ == '__main__':
    unittest.main()

'''csv_set_intersect.py
Read two CSV files where each line represents a collection of integers separated by commas.
Each line is converted to a frozenset so it can be placed in a larger set representing all rows.
The script prints the rows that appear in both files (set intersection) in their original order.
'''import csv
import sys
from typing import List, Set, FrozenSet

def load_rows(path: str) -> List[FrozenSet[int]]:
    """Return a list of frozenset rows from a CSV file.
    Empty fields are ignored; values are converted to int.
    """
    rows: List[FrozenSet[int]] = []
    with open(path, newline='') as f:
        reader = csv.reader(f)
        for row in reader:
            # Convert non‑empty strings to ints
            nums = {int(val) for val in row if val.strip()}
            rows.append(frozenset(nums))
    return rows

def intersect_rows(file_a: str, file_b: str) -> Set[FrozenSet[int]]:
    """Return the set of rows that occur in both CSV files."""
    rows_a = set(load_rows(file_a))
    rows_b = set(load_rows(file_b))
    return rows_a & rows_b

def format_row(row: FrozenSet[int]) -> str:
    """Convert a frozen set back to a comma‑separated string, sorted numerically."""
    return ','.join(str(num) for num in sorted(row))

def main() -> None:
    if len(sys.argv) != 3:
        print('Usage: python csv_set_intersect.py <file1.csv> <file2.csv>')
        sys.exit(1)
    common = intersect_rows(sys.argv[1], sys.argv[2])
    if not common:
        print('No common rows found.')
    else:
        print('Rows common to both files:')
        for row in sorted(common, key=lambda r: (len(r), sorted(r))):
            print(format_row(row))

if __name__ == '__main__':
    main()

'''find_substring.py
Utility script that searches a text file for a user‑provided substring.
It prints each matching line together with its 1‑based line number.
Usage: python find_substring.py <path_to_file> <substring>
'''import sys

def load_file(path):
    """Return a list of lines from *path* without trailing newlines."""
    with open(path, 'r', encoding='utf-8') as f:
        return [line.rstrip('\n') for line in f]

def find_matches(lines, needle):
    """Yield (line_no, line) pairs where *needle* occurs in *line* (case‑sensitive)."""
    for idx, line in enumerate(lines, start=1):
        if needle in line:
            yield idx, line

def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if len(argv) != 2:
        sys.stderr.write('Usage: python find_substring.py <file> <substring>\n')
        sys.exit(1)
    path, needle = argv
    lines = load_file(path)
    matches = list(find_matches(lines, needle))
    if not matches:
        print(f'No occurrences of "{needle}" found.')
        return
    for lineno, text in matches:
        print(f'{lineno}: {text}')

if __name__ == '__main__':
    main()

'''jaro_winkler_matcher.py
Utility to compute Jaro‑Winkler similarity and pick the most similar string
from a candidate list.
Run as a script: python jaro_winkler_matcher.py <target> <candidate1> <candidate2> ...
'''import sys, math

def _jaro(s1, s2):
    if s1 == s2:
        return 1.0
    len1, len2 = len(s1), len(s2)
    if len1 == 0 or len2 == 0:
        return 0.0
    match_distance = (max(len1, len2) // 2) - 1
    s1_matches = [False] * len1
    s2_matches = [False] * len2
    matches = 0
    transpositions = 0
    # Count matches
    for i, c1 in enumerate(s1):
        start = max(0, i - match_distance)
        end = min(i + match_distance + 1, len2)
        for j in range(start, end):
            if not s2_matches[j] and c1 == s2[j]:
                s1_matches[i] = s2_matches[j] = True
                matches += 1
                break
    if matches == 0:
        return 0.0
    # Count transpositions
    k = 0
    for i, matched in enumerate(s1_matches):
        if matched:
            while not s2_matches[k]:
                k += 1
            if s1[i] != s2[k]:
                transpositions += 1
            k += 1
    transpositions //= 2
    return (matches / len1 + matches / len2 + (matches - transpositions) / matches) / 3.0

def jaro_winkler(s1, s2, scaling=0.1, prefix_limit=4):
    """Return Jaro‑Winkler similarity (0‑1) between *s1* and *s2*.
    ``scaling`` controls the weight of the common prefix (default 0.1).
    """
    j = _jaro(s1, s2)
    # Common prefix length
    prefix = 0
    for c1, c2 in zip(s1, s2):
        if c1 == c2:
            prefix += 1
            if prefix == prefix_limit:
                break
        else:
            break
    return j + (prefix * scaling * (1 - j))

def best_match(target, candidates):
    """Return the candidate with the highest Jaro‑Winkler score for *target*.
    If the list is empty, returns ``None``.
    """
    if not candidates:
        return None
    scores = [(cand, jaro_winkler(target, cand)) for cand in candidates]
    best = max(scores, key=lambda pair: pair[1])
    return best[0]

if __name__ == '__main__':
    if len(sys.argv) < 3:
        sys.stderr.write('Usage: python jaro_winkler_matcher.py <target> <cand1> [cand2 ...]\n')
        sys.exit(1)
    target = sys.argv[1]
    cand_list = sys.argv[2:]
    print('Best match:', best_match(target, cand_list))

