    sub = 'Scripts' if sys.platform.startswith('win') else 'bin'
    return str(venv / sub / 'pip')

def install_from_git(pip: str, repo: str) -> None:
    run([pip, 'install', f'git+{repo}'])
    print(f'Installed package from {repo}')

def show_version(python: str, pkg: str) -> None:
    result = subprocess.run([python, '-c', f'import {pkg}; print({pkg}.__version__)'],
                            capture_output=True, text=True, check=True)
    print(f'{pkg} version: {result.stdout.strip()}')

def main() -> None:
    create_venv(VENV_PATH)
    pip = pip_executable(VENV_PATH)
    python = pip.replace('pip', 'python')
    install_from_git(pip, GIT_URL)
    show_version(python, PACKAGE_NAME)

