import os
import shutil
import sys
from pathlib import Path

def find_venvs(parent: Path) -> list[Path]:
    """Return a list of sub‑directories that appear to be virtual environments.
    Heuristic: directory contains a 'bin/python' (POSIX) or 'Scripts/python.exe' (Windows).
    """
    venvs = []
    for child in parent.iterdir():
        if not child.is_dir():
            continue
        bin_dir = child / ('Scripts' if os.name == 'nt' else 'bin')
        py_exe = bin_dir / ('python.exe' if os.name == 'nt' else 'python')
        if py_exe.is_file():
            venvs.append(child)
    return venvs

def prompt_deletion(venvs: list[Path]) -> Path | None:
    """Ask the user which venv to delete.
    Returns the selected Path or None if the user aborts.
    """
    if not venvs:
        print('No virtual environments found.')
        return None
    print('Virtual environments found:')
    for idx, v in enumerate(venvs, 1):
        print(f'  {idx}) {v.name}')
    choice = input('Enter the number to delete (or press Enter to cancel): ').strip()
    if not choice:
        return None
    if not choice.isdigit() or not (1 <= int(choice) <= len(venvs)):
        print('Invalid selection.')
        return None
    return venvs[int(choice) - 1]

def delete_venv(path: Path) -> None:
    """Recursively delete the virtual environment directory after confirmation."""
    confirm = input(f'Are you sure you want to delete "{path}"? [y/N]: ').lower()
    if confirm == 'y':
        shutil.rmtree(path)
        print(f'Deleted {path}')
    else:
        print('Deletion cancelled.')

def main() -> None:
    parent_dir = Path(sys.argv[1]) if len(sys.argv) > 1 else Path('.')
    venvs = find_venvs(parent_dir)
    to_remove = prompt_deletion(venvs)
    if to_remove:
        delete_venv(to_remove)

if __name__ == '__main__':
    main()

# log_decorator.py
# A reusable decorator that logs when a function is entered and when it returns.

import functools
import datetime

def logger(prefix: str = "[LOG]") -> callable:
    """Factory that produces a decorator capturing *prefix* in a closure.

    The returned decorator adds timestamps and the given prefix to the output.
    """
    def decorator(func: callable) -> callable:
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            entry = datetime.datetime.now().isoformat()
            print(f"{prefix} {entry} - Entering {func.__name__} with args={args}, kwargs={kwargs}")
            result = func(*args, **kwargs)
            exit = datetime.datetime.now().isoformat()
            print(f"{prefix} {exit} - Exiting {func.__name__} returning {result}")
            return result
        return wrapper
    return decorator

# Example usage
@logger("[DEBUG]")
def multiply(a, b):
    return a * b

@logger()
def greet(name="World"):
    return f"Hello, {name}!"

if __name__ == "__main__":
    multiply(3, 7)
    greet(name="Alice")

'''binary_tree_dfs.py
Implements a simple binary tree class and a recursive depth‑first (pre‑order) search.
The recursion stops when a node is None (leaf base case).
'''

from __future__ import annotations
from typing import Optional, Any, List

class Node:
    def __init__(self, value: Any, left: Optional['Node'] = None, right: Optional['Node'] = None):
        self.value = value
        self.left = left
        self.right = right

    def __repr__(self) -> str:
        return f'Node({self.value})'

def dfs(root: Optional[Node], target: Any, path: Optional[List[Any]] = None) -> Optional[List[Any]]:
    """Return a list of node values forming the path to *target* using DFS.

    The base case is when *root* is None – the function returns None to signal
    that the current branch does not contain the target.
    """
    if path is None:
        path = []
    if root is None:
        return None  # Base case: reached beyond a leaf
    # Visit current node
    path.append(root.value)
    if root.value == target:
        return path
    # Search left subtree
    left_result = dfs(root.left, target, path.copy())
    if left_result is not None:
        return left_result
    # Search right subtree
    right_result = dfs(root.right, target, path.copy())
    if right_result is not None:
        return right_result
    return None  # Target not found in either subtree

def build_sample_tree() -> Node:
    # Construct a small binary tree for demonstration
    #        A
    #       / \n    #      B   C
    #     / \   \n    #    D   E   F
    return Node('A',
                Node('B', Node('D'), Node('E')),
                Node('C', None, Node('F')) )

def main() -> None:
    tree = build_sample_tree()
    for target in ['E', 'F', 'X']:
        result = dfs(tree, target)
        if result:
            print(f'Path to {target}: {result}')
        else:
            print(f'{target} not found in the tree.')

if __name__ == '__main__':
    main()

# rolling_buffer.py
#
# Implements a FixedSizeBuffer class based on collections.deque. When the
# buffer reaches its maximum capacity, older entries are automatically
# discarded.

from collections import deque
from typing import Any, Iterable, List


class FixedSizeBuffer:
    """A FIFO buffer with a maximum length.

    New items are appended on the right; when the buffer is full the left‑most
    item is removed automatically by the underlying deque.
    """

    def __init__(self, size: int, initial: Iterable[Any] = ()):
        if size <= 0:
            raise ValueError("size must be positive")
        self._size = size
        self._buf: deque[Any] = deque(maxlen=size)
        for item in initial:
            self.append(item)

    def append(self, item: Any) -> None:
        """Add *item* to the buffer, discarding the oldest if full."""
        self._buf.append(item)

    def get_all(self) -> List[Any]:
        """Return a list of the buffer contents from oldest to newest."""
        return list(self._buf)

    def __len__(self) -> int:
        return len(self._buf)

    def __repr__(self) -> str:
        return f"FixedSizeBuffer(size={self._size}, contents={list(self._buf)})"


def _demo() -> None:
    buf = FixedSizeBuffer(3)
    for i in range(5):
        buf.append(i)
        print(f"After appending {i}: {buf.get_all()}")


if __name__ == "__main__":
    _demo()

'''char_analysis.py

Uses collections.Counter to count characters in a string and then a
defaultdict to invert the mapping, producing groups of characters that share the
same frequency.
'''

from collections import Counter, defaultdict
from typing import Dict, List


def count_chars(text: str) -> Counter:
    """Return a Counter of character frequencies, ignoring whitespace."""
    return Counter(ch for ch in text if not ch.isspace())


def invert_mapping(cnt: Counter) -> Dict[int, List[str]]:
    """Return a dict mapping frequency -> list of characters with that frequency."""
    inv: defaultdict[int, List[str]] = defaultdict(list)
    for ch, frequency in cnt.items():
        inv[frequency].append(ch)
    # Sort characters within each frequency for deterministic output
    return {freq: sorted(chars) for freq, chars in inv.items()}


def _demo() -> None:
    sample = "Hello World!"
    frequencies = count_chars(sample)
    groups = invert_mapping(frequencies)
    print("Character counts:")
    for ch, cnt in frequencies.most_common():
        print(f"  {ch!r}: {cnt}")
    print("\nGrouped by frequency:")
    for freq in sorted(groups, reverse=True):
        print(f"{freq} -> {', '.join(groups[freq])}")


if __name__ == "__main__":
    _demo()

# moving_word_counter.py
#
# Demonstrates a sliding window word counter using a deque to store the most
# recent N words and a Counter to maintain frequencies.

from collections import Counter, deque
from typing import Iterable, List


class MovingWordCounter:
    """Maintain word frequencies for the last *window* tokens.

    New words are added with :meth:`push`. When the internal deque exceeds the
    window size, the oldest word is removed and its count decremented.
    """

    def __init__(self, window: int):
        if window <= 0:
            raise ValueError("window must be positive")
        self.window = window
        self._queue: deque[str] = deque()
        self._counter: Counter[str] = Counter()

    def push(self, word: str) -> None:
        """Add *word* to the sliding window and update counts."""
        self._queue.append(word)
        self._counter[word] += 1
        if len(self._queue) > self.window:
            old = self._queue.popleft()
            self._counter[old] -= 1
            if self._counter[old] == 0:
                del self._counter[old]

    def frequencies(self) -> Counter[str]:
        """Return a copy of the current Counter snapshot."""
        return self._counter.copy()

    def __repr__(self) -> str:
        return f"MovingWordCounter(window={self.window}, counts={dict(self._counter)})"


def _demo() -> None:
    stream = "the quick brown fox jumps over the lazy dog the quick".split()
    mwc = MovingWordCounter(window=5)
    for w in stream:
        mwc.push(w)
        print(f"After '{w}': {mwc.frequencies()}")


if __name__ == "__main__":
    _demo()

'''bfs_levels.py
Treats any graph as unweighted and prints vertices level‑by‑level.
Each line corresponds to one BFS depth from the start vertex.
''' 
import sys
from collections import deque, defaultdict

def build_adj(path):
    adj = defaultdict(list)
    with open(path) as f:
        for line in f:
            if not line.strip():
                continue
            u, v, *_ = line.split()
            adj[u].append(v)
            adj[v].append(u)  # ignore direction, ignore weight
    return adj

def bfs_levels(adj, start):
    visited = {start}
    q = deque([start])
    level = 0
    while q:
        size = len(q)
        current_level = []
        for _ in range(size):
            v = q.popleft()
            current_level.append(v)
            for nb in adj[v]:
                if nb not in visited:
                    visited.add(nb)
                    q.append(nb)
        yield level, current_level
        level += 1

if __name__ == '__main__':
    if len(sys.argv) != 3:
        print('Usage: python bfs_levels.py <edge_file> <start>')
        sys.exit(1)
    graph_file, start = sys.argv[1], sys.argv[2]
    adjacency = build_adj(graph_file)
    if start not in adjacency:
        print(f'Start node {start!r} missing.')
        sys.exit(1)
    for lvl, nodes in bfs_levels(adjacency, start):
        print(f'Level {lvl}:', ' '.join(nodes))

'''bipartite_check.py
Determines if an undirected graph is bipartite using BFS coloring.
The graph is supplied as a dict mapping vertices to iterables of neighbours.
The function returns a tuple (is_bipartite, color_dict).
''' 
from collections import deque

def is_bipartite(graph):
    """Return (True, colors) if *graph* is bipartite.
    *colors* maps each vertex to 0 or 1.  If the graph is not bipartite,
    the returned dict contains the partial coloring achieved before the conflict.
    """
    color = {}
    for start in graph:
        if start in color:
            continue
        color[start] = 0
        q = deque([start])
        while q:
            v = q.popleft()
            for nb in graph[v]:
                if nb not in color:
                    color[nb] = 1 - color[v]
                    q.append(nb)
                elif color[nb] == color[v]:
                    return False, color
    return True, color

if __name__ == '__main__':
    # Example graphs
    g1 = {'A': ['B','C'], 'B': ['A','D'], 'C': ['A','D'], 'D': ['B','C']}
    g2 = {'A': ['B','C'], 'B': ['A','C'], 'C': ['A','B']}
    for i, g in enumerate((g1, g2), 1):
        ok, col = is_bipartite(g)
        print(f'Graph {i} bipartite? {ok}')
        if ok:
            print('Colors:', col)

