'''json_utils.py
Utility functions for JSON serialization with custom handling for datetime objects.
Provides `dumps` and `loads` that mimic the standard json API but automatically convert
`datetime.datetime` instances to/from ISO‑8601 strings.
''' 
import json
from datetime import datetime
from typing import Any

ISO_FORMAT = "%Y-%m-%dT%H:%M:%S.%fZ"

def _default(obj: Any):
    """JSON encoder hook.
    If *obj* is a datetime, return its ISO string; otherwise raise TypeError.
    """
    if isinstance(obj, datetime):
        # Ensure UTC representation without timezone info
        return obj.strftime(ISO_FORMAT)
    raise TypeError(f'Object of type {type(obj).__name__} is not JSON serializable')

def _object_hook(dct: dict):
    """JSON decoder hook.
    Convert any string that matches ISO_FORMAT back to a datetime.
    """
    for key, value in dct.items():
        if isinstance(value, str):
            try:
                dct[key] = datetime.strptime(value, ISO_FORMAT)
            except ValueError:
                pass  # leave the value unchanged if it doesn't match
    return dct

def dumps(obj: Any, **kwargs) -> str:
    """Serialize *obj* to a JSON string, handling datetime objects.
    Additional keyword arguments are passed to :func:`json.dumps`.
    """
    return json.dumps(obj, default=_default, **kwargs)

def loads(s: str, **kwargs) -> Any:
    """Deserialize *s* (a JSON string) back to Python objects, converting ISO strings to datetime.
    Additional keyword arguments are passed to :func:`json.loads`.
    """
    return json.loads(s, object_hook=_object_hook, **kwargs)

# Example usage when the module is executed directly
if __name__ == '__main__':
    sample = {
        'event': 'test',
        'time': datetime.utcnow()
    }
    json_str = dumps(sample, indent=2)
    print('Serialized:', json_str)
    restored = loads(json_str)
    print('Restored:', restored)
    print('type of time:', type(restored['time']))

'''person_model.py
Dataclass definition for a Person with nested Address.
Includes `to_json` and `from_json` helpers that work for any dataclass using recursion.
''' 
from __future__ import annotations
import json
from dataclasses import dataclass, asdict, fields, is_dataclass
from typing import Any, Type, TypeVar

T = TypeVar('T')

def _serialize(obj: Any) -> Any:
    """Recursively convert dataclasses to plain dicts for JSON encoding.
    Lists, tuples and dicts are also traversed.
    """
    if is_dataclass(obj):
        return {f.name: _serialize(getattr(obj, f.name)) for f in fields(obj)}
    if isinstance(obj, (list, tuple)):
        return [_serialize(item) for item in obj]
    if isinstance(obj, dict):
        return {k: _serialize(v) for k, v in obj.items()}
    return obj

def _deserialize(cls: Type[T], data: Any) -> T:
    """Rebuild *cls* (a dataclass) from plain JSON data.
    Handles nested dataclasses by inspecting field types.
    """
    if not is_dataclass(cls):
        return data  # primitive value
    init_kwargs = {}
    for f in fields(cls):
        value = data.get(f.name)
        if value is None:
            init_kwargs[f.name] = None
            continue
        # If the field type is a dataclass, recurse
        if hasattr(f.type, '__dataclass_fields__'):
            init_kwargs[f.name] = _deserialize(f.type, value)
        elif getattr(f.type, '__origin__', None) in (list, List):
            # Assume homogenous list of dataclasses or primitives
            inner_type = f.type.__args__[0]
            init_kwargs[f.name] = [_deserialize(inner_type, v) for v in value]
        else:
            init_kwargs[f.name] = value
    return cls(**init_kwargs)

@dataclass
class Address:
    street: str
    city: str
    zip_code: str

@dataclass
class Person:
    name: str
    age: int
    email: str | None = None
    address: Address | None = None
    tags: list[str] | None = None

    def to_json(self, **kwargs) -> str:
        """Return a JSON string representing the Person instance."""
        return json.dumps(_serialize(self), **kwargs)

    @classmethod
    def from_json(cls: Type[T], s: str) -> T:
        """Create a Person (or subclass) from a JSON string."""
        data = json.loads(s)
        return _deserialize(cls, data)

# Simple demonstration when run as a script
if __name__ == '__main__':
    p = Person(
        name='Alice',
        age=30,
        email='alice@example.com',
        address=Address(street='123 Main St', city='Metropolis', zip_code='12345'),
        tags=['engineer', 'gamer']
    )
    j = p.to_json(indent=2)
    print('JSON representation:\n', j)
    p2 = Person.from_json(j)
    print('Round‑trip equal:', p == p2)

