import sys

def read_graph() -> list[list[int]]:
    """Read an adjacency list from stdin.
    First line: number of vertices N.
    Next N lines: space‑separated neighbours of vertex i (0‑based).
    Returns a list where graph[i] is a list of neighbours of i.
    """
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return []
    n = int(data[0])
    graph = []
    for line in data[1:n+1]:
        if line.strip():
            graph.append([int(x) for x in line.split()])
        else:
            graph.append([])
    return graph

def dfs_recursive(graph: list[list[int]], start: int, visited: set[int] | None = None) -> list[int]:
    """Return the order of nodes visited by a recursive DFS.
    visited is a set that persists across recursion calls.
    """
    if visited is None:
        visited = set()
    order = []
    def _dfs(v: int):
        visited.add(v)
        order.append(v)
        for nb in graph[v]:
            if nb not in visited:
                _dfs(nb)
    _dfs(start)
    return order

if __name__ == "__main__":
    g = read_graph()
    if not g:
        sys.exit("Empty graph")
    start_node = 0
    traversal = dfs_recursive(g, start_node)
    print("DFS order:", " ".join(map(str, traversal)))

'''DFS spanning‑tree generator.
Reads a file where each line contains two integers u v representing an
undirected edge. The Graph class stores adjacency sets. The DepthFirstTree
class performs DFS and records the parent of each visited vertex, producing
a spanning tree rooted at the first vertex encountered.
''' 
import sys
from collections import defaultdict
from typing import Dict, List, Set

class Graph:
    def __init__(self) -> None:
        self.adj: Dict[int, Set[int]] = defaultdict(set)

    def add_edge(self, u: int, v: int) -> None:
        self.adj[u].add(v)
        self.adj[v].add(u)

    def vertices(self) -> List[int]:
        return list(self.adj.keys())

class DepthFirstTree:
    def __init__(self, graph: Graph) -> None:
        self.graph = graph
        self.parent: Dict[int, int | None] = {}
        self.visited: Set[int] = set()

    def build(self, root: int) -> None:
        self.parent[root] = None
        self._dfs(root)

    def _dfs(self, v: int) -> None:
        self.visited.add(v)
        for nb in sorted(self.graph.adj[v]):  # deterministic order
            if nb not in self.visited:
                self.parent[nb] = v
                self._dfs(nb)

    def edges(self) -> List[tuple[int, int]]:
        return [(p, c) for c, p in self.parent.items() if p is not None]

def load_edge_list(path: str) -> Graph:
    g = Graph()
    with open(path, "r") as f:
        for line in f:
            if not line.strip():
                continue
            u, v = map(int, line.split())
            g.add_edge(u, v)
    return g

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit("Usage: python dfs_spanning_tree.py <edge_list.txt>")
    graph = load_edge_list(sys.argv[1])
    if not graph.vertices():
        sys.exit("Empty graph")
    root = min(graph.vertices())
    tree = DepthFirstTree(graph)
    tree.build(root)
    for u, v in tree.edges():
        print(f"{u} - {v}")

'''DFS generator module.
Provides dfs_generator(graph, start=0, method='recursive') which yields
vertices one by one. method can be 'recursive' or 'iterative'.
The graph is an adjacency list: List[List[int]].
''' 
from typing import List, Generator

def _recursive(graph: List[List[int]], v: int, visited: List[bool]):
    visited[v] = True
    yield v
    for nb in graph[v]:
        if not visited[nb]:
            yield from _recursive(graph, nb, visited)

def _iterative(graph: List[List[int]], start: int) -> Generator[int, None, None]:
    visited = [False] * len(graph)
    stack = [start]
    while stack:
        v = stack.pop()
        if visited[v]:
            continue
        visited[v] = True
        yield v
        # push neighbours in reverse order for natural left‑to‑right traversal
        for nb in reversed(graph[v]):
            if not visited[nb]:
                stack.append(nb)

def dfs_generator(graph: List[List[int]], start: int = 0, method: str = 'recursive') -> Generator[int, None, None]:
    """Yield vertices of graph in DFS order.
    method='recursive' uses a recursive helper; 'iterative' uses an explicit stack.
    """
    if method == 'recursive':
        visited = [False] * len(graph)
        yield from _recursive(graph, start, visited)
    elif method == 'iterative':
        yield from _iterative(graph, start)
    else:
        raise ValueError("method must be 'recursive' or 'iterative'")

if __name__ == "__main__":
    sample = [[1, 2], [3], [3, 4], [], []]
    print('Recursive: ', list(dfs_generator(sample, 0, 'recursive')))
    print('Iterative: ', list(dfs_generator(sample, 0, 'iterative')))

answer:
If the recursive function has a mutable default argument that you modify (e.g., appending to a list that tracks visited nodes), each recursive call reuses the same list, causing the base case to never be reached as the state keeps growing. For instance:
```python
def walk(node, visited=[]):
    if node in visited:
        return
    visited.append(node)
    for child in node.children:
        walk(child, visited)
```
Here `visited` never resets for a new top‑level call, leading to unintended deep recursion. Use `visited=None` and create a new list inside the function for each top‑level invocation.
```python
def walk(node, visited=None):
    if visited is None:
        visited = []
    ...
```

