'''dir_watcher.py
Watches a directory for created files and appends their absolute paths to log.txt.
Requires the watchdog package (pip install watchdog).
''' 
import sys
import time
from pathlib import Path
from watchdog.events import FileSystemEventHandler
from watchdog.observers import Observer

class NewFileLogger(FileSystemEventHandler):
    """Handler that records newly created files to a log file."""
    def __init__(self, log_path: Path):
        self.log_path = log_path
        super().__init__()

    def on_created(self, event):
        # Ignore directory creations; we only care about files.
        if not event.is_directory:
            p = Path(event.src_path).resolve()
            self.log_path.open('a').write(str(p) + '\n')
            print(f'Logged new file: {p}')

def watch(directory: Path, log_file: Path) -> None:
    if not directory.is_dir():
        raise NotADirectoryError(f"{directory} is not a directory")
    handler = NewFileLogger(log_file)
    observer = Observer()
    observer.schedule(handler, str(directory), recursive=True)
    observer.start()
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

def main() -> None:
    if len(sys.argv) != 3:
        print('Usage: python dir_watcher.py <directory> <log_file>')
        sys.exit(1)
    directory = Path(sys.argv[1])
    log_file = Path(sys.argv[2])
    try:
        watch(directory, log_file)
    except Exception as e:
        print('Error:', e)
        sys.exit(2)

if __name__ == '__main__':
    main()

'''uf_with_count.py
Union‑Find implementation that tracks the current number of disjoint sets.
Useful for algorithms like Kruskal's where you need to stop when all vertices are connected.
''' 

class UnionFind:
    """Disjoint‑set data structure with path compression, union by rank,
    and a live count of distinct sets.
    """
    def __init__(self, elements=None):
        self.parent = {}
        self.rank = {}
        self.set_count = 0
        if elements:
            for e in elements:
                self.make_set(e)

    def make_set(self, x):
        if x in self.parent:
            return
        self.parent[x] = x
        self.rank[x] = 0
        self.set_count += 1

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
            return False
        if self.rank[xr] < self.rank[yr]:
            self.parent[xr] = yr
        elif self.rank[xr] > self.rank[yr]:
            self.parent[yr] = xr
        else:
            self.parent[yr] = xr
            self.rank[xr] += 1
        self.set_count -= 1
        return True

    def count(self):
        """Return the current number of disjoint sets."""
        return self.set_count

if __name__ == "__main__":
    vertices = list('ABCDE')
    uf = UnionFind(vertices)
    edges = [('A','B'), ('B','C'), ('D','E')]
    for u, v in edges:
        uf.union(u, v)
        print(f"After union({u},{v}) sets={uf.count()}")
    # Expected: 3 sets remain (A‑B‑C, D‑E, and isolated vertex?)

'''components_from_file.py
Read a plain‑text edge list (one edge per line, format: u v)
and output the number of connected components using Union‑Find.
''' 
import sys

class UnionFind:
    def __init__(self):
        self.parent = {}
        self.rank = {}
        self.count = 0

    def make_set(self, x):
        if x not in self.parent:
            self.parent[x] = x
            self.rank[x] = 0
            self.count += 1

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
            return
        if self.rank[xr] < self.rank[yr]:
            self.parent[xr] = yr
        elif self.rank[xr] > self.rank[yr]:
            self.parent[yr] = xr
        else:
            self.parent[yr] = xr
            self.rank[xr] += 1
        self.count -= 1

def count_components(filename):
    uf = UnionFind()
    with open(filename, 'r') as f:
        for line in f:
            if not line.strip() or line.startswith('#'):
                continue
            u, v = line.split()
            uf.make_set(u)
            uf.make_set(v)
            uf.union(u, v)
    return uf.count

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print('Usage: python components_from_file.py <edge-list.txt>')
        sys.exit(1)
    file_path = sys.argv[1]
    comps = count_components(file_path)
    print(f'Number of connected components: {comps}')

'''uf_weighted_list.py
Weighted Union‑Find where the smaller tree is attached to the larger (union by size).
Provides `groups()` which returns a dict mapping root -> list of members.
''' 

class UnionFind:
    def __init__(self, items=None):
        self.parent = {}
        self.size = {}
        if items:
            for i in items:
                self.make_set(i)

    def make_set(self, x):
        if x in self.parent:
            return
        self.parent[x] = x
        self.size[x] = 1

    def find(self, x):
        while self.parent[x] != x:
            # path halving for compression
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
            return False
        # attach smaller tree to larger tree
        if self.size[xr] < self.size[yr]:
            xr, yr = yr, xr
        self.parent[yr] = xr
        self.size[xr] += self.size[yr]
        return True

    def groups(self):
        """Return a dictionary {root: [members,...]} for all current sets."""
        result = {}
        for item in self.parent:
            root = self.find(item)
            result.setdefault(root, []).append(item)
        return result

if __name__ == '__main__':
    uf = UnionFind(['a','b','c','d','e','f'])
    uf.union('a','b')
    uf.union('c','d')
    uf.union('b','c')
    uf.union('e','f')
    print('Groups:', uf.groups())

'''undoable_union_find.py
Union‑Find that supports undoing the most recent union operation.
Uses a stack of change records so `undo()` restores the previous state.
''' 

class UndoableUF:
    def __init__(self, elements=None):
        self.parent = {}
        self.rank = {}
        self.history = []  # stack of (changed_root, old_parent, old_rank, delta_count)
        self.set_count = 0
        if elements:
            for e in elements:
                self.make_set(e)

    def make_set(self, x):
        if x in self.parent:
            return
        self.parent[x] = x
        self.rank[x] = 0
        self.set_count += 1
        # no history entry because creation cannot be undone separately

    def find(self, x):
        while self.parent[x] != x:
            x = self.parent[x]
        return x

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
            self.history.append(None)  # marker for a no‑op union
            return False
        # ensure xr has higher rank
        if self.rank[xr] < self.rank[yr]:
            xr, yr = yr, xr
        # record state before change
        self.history.append((yr, self.parent[yr], self.rank[xr], 1))
        self.parent[yr] = xr
        if self.rank[xr] == self.rank[yr]:
            self.rank[xr] += 1
        self.set_count -= 1
        return True

    def undo(self):
        """Revert the most recent union. Does nothing if no operations recorded."""
        if not self.history:
            return
        record = self.history.pop()
        if record is None:
            # it was a no‑op union; nothing to rollback
            return
        yr, old_parent, old_rank, delta = record
        xr = self.parent[yr]
        self.parent[yr] = old_parent
        self.rank[xr] = old_rank
        self.set_count += delta

    def count(self):
        return self.set_count

if __name__ == '__main__':
    uf = UndoableUF(['1','2','3','4'])
    uf.union('1','2')
    uf.union('3','4')
    print('Components after unions:', uf.count())
    uf.undo()
    print('After one undo:', uf.count())
    uf.undo()
    print('After second undo:', uf.count())

'''kruskal_mst.py
Implementation of Kruskal's algorithm using Union‑Find.
The graph is supplied as a list of edges (u, v, weight).
The script prints the edges of the Minimum Spanning Tree and its total weight.
''' 

class UnionFind:
    def __init__(self, vertices):
        self.parent = {v: v for v in vertices}
        self.rank = {v: 0 for v in vertices}

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        xr, yr = self.find(x), self.find(y)
        if xr == yr:
            return False
        if self.rank[xr] < self.rank[yr]:
            self.parent[xr] = yr
        elif self.rank[xr] > self.rank[yr]:
            self.parent[yr] = xr
        else:
            self.parent[yr] = xr
            self.rank[xr] += 1
        return True

def kruskal(vertices, edges):
    """Return list of edges forming the MST and its total weight.
    `edges` must be an iterable of (u, v, w).
    """
    uf = UnionFind(vertices)
    mst = []
    total = 0
    # sort edges by weight
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        if uf.union(u, v):
            mst.append((u, v, w))
            total += w
    return mst, total

if __name__ == '__main__':
    V = ['A','B','C','D','E']
    E = [
        ('A','B', 1),
        ('A','C', 3),
        ('B','C', 1),
        ('B','D', 4),
        ('C','D', 1),
        ('C','E', 6),
        ('D','E', 5)
    ]
    mst_edges, mst_weight = kruskal(V, E)
    print('MST total weight:', mst_weight)
    print('MST edges:')
    for u, v, w in mst_edges:
        print(f'  {u}-{v} ({w})')

