# binary_search_file.py
"""Read a sorted list of integers from `data.txt` and answer interactive queries.

The file must contain one integer per line, already sorted in ascending order.
The script loads the list once, then repeatedly prompts the user for a number
and reports the index (or -1 if not present).  Enter an empty line to quit.
"""
import sys

def load_numbers(path):
    """Return a list of integers read from `path`.
    Each line should contain a single integer.
    """
    with open(path, "r", encoding="utf-8") as f:
        return [int(line.strip()) for line in f if line.strip()]

def binary_search(arr, target):
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def main():
    if len(sys.argv) != 2:
        print("Usage: python binary_search_file.py <data_file>")
        sys.exit(1)
    data = load_numbers(sys.argv[1])
    print(f"Loaded {len(data)} numbers.")
    while True:
        user = input("Enter number to search (blank to exit): ")
        if user == "":
            break
        try:
            val = int(user)
        except ValueError:
            print("Please enter a valid integer.")
            continue
        idx = binary_search(data, val)
        if idx != -1:
            print(f"Found at index {idx} (0‑based).")
        else:
            print("Not found.")

if __name__ == "__main__":
    main()

