"""Binary search for strings with accompanying unit tests.

The module defines `binary_search_strings` and a `unittest.TestCase`
that covers typical, edge‑case and failure scenarios.
"""
import unittest

def binary_search_strings(seq, target):
    """Return index of `target` in sorted list of strings `seq` or -1.
    Comparison uses the standard lexicographic order.
    """
    left, right = 0, len(seq) - 1
    while left <= right:
        mid = (left + right) // 2
        if seq[mid] == target:
            return mid
        elif seq[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

class TestBinarySearchStrings(unittest.TestCase):
    def setUp(self):
        self.words = ["apple", "banana", "cherry", "date", "fig", "grape"]

    def test_found_middle(self):
        self.assertEqual(binary_search_strings(self.words, "date"), 3)

    def test_found_first(self):
        self.assertEqual(binary_search_strings(self.words, "apple"), 0)

    def test_found_last(self):
        self.assertEqual(binary_search_strings(self.words, "grape"), 5)

    def test_not_found(self):
        self.assertEqual(binary_search_strings(self.words, "orange"), -1)

    def test_empty_list(self):
        self.assertEqual(binary_search_strings([], "anything"), -1)

if __name__ == "__main__":
    unittest.main()

