# detect_shell.sh – identify the executing interactive shell.
# Works on any system where bash is present; the script itself runs under bash,
# but it inspects the environment to guess the user's login shell.

# Determine the shell from $0, $SHELL, and the process hierarchy.
get_shell() {
    # $0 may be "bash", "-bash", or the script name.
    local prog="${0##*/}"
    case "$prog" in
        bash|*-bash) echo "Bash" && return;;
        zsh|*-zsh)   echo "Zsh" && return;;
    esac
    # Fallback to $SHELL environment variable.
    if [[ -n ${SHELL-} ]]; then
        case "${SHELL##*/}" in
            bash) echo "Bash" && return;;
            zsh)  echo "Zsh" && return;;
        esac
    fi
    # As a last resort, use ps to inspect the parent process.
    local parent=$(ps -p $$ -o ppid=)
    local parent_cmd=$(ps -p "$parent" -o comm= 2>/dev/null || echo "unknown")
    case "$parent_cmd" in
        bash) echo "Bash";;
        zsh)  echo "Zsh";;
        *)    echo "Other";;
    esac
}

shell_name=$(get_shell)
printf "You appear to be using: %s\n" "$shell_name"

