'''singly_linked_list.py
A minimal implementation of a singly linked list.
Provides Node and SinglyLinkedList classes with insert, delete, and search methods.
'''

class Node:
    """A node in a singly linked list."""
    __slots__ = ('value', 'next')

    def __init__(self, value, next=None):
        self.value = value
        self.next = next

    def __repr__(self):
        return f'Node({self.value!r})'


class SinglyLinkedList:
    """Singly linked list supporting basic operations."""
    def __init__(self):
        self.head = None

    def insert_head(self, value):
        """Insert a new node at the beginning of the list."""
        self.head = Node(value, self.head)

    def insert_tail(self, value):
        """Insert a new node at the end of the list.","""
        new_node = Node(value)
        if not self.head:
            self.head = new_node
            return
        cur = self.head
        while cur.next:
            cur = cur.next
        cur.next = new_node

    def delete(self, value):
        """Delete the first node whose value equals *value*.
        Returns True if a node was removed, False otherwise."""
        cur = self.head
        prev = None
        while cur:
            if cur.value == value:
                if prev is None:
                    self.head = cur.next
                else:
                    prev.next = cur.next
                return True
            prev, cur = cur, cur.next
        return False

    def search(self, value):
        """Return the first node containing *value*, or None if not found."""
        cur = self.head
        while cur:
            if cur.value == value:
                return cur
            cur = cur.next
        return None

    def __iter__(self):
        cur = self.head
        while cur:
            yield cur.value
            cur = cur.next

    def __repr__(self):
        values = list(self)
        return f'SinglyLinkedList({values})'


if __name__ == '__main__':
    lst = SinglyLinkedList()
    for i in range(5):
        lst.insert_tail(i)
    print('Initial list:', lst)
    lst.insert_head(99)
    print('After inserting 99 at head:', lst)
    lst.delete(2)
    print('After deleting value 2:', lst)
    node = lst.search(3)
    print('Search for 3 returns:', node)

'''doubly_linked_list.py
Implementation of a generic doubly linked list.
Includes prepend, append, remove, forward and reverse iteration.
'''

class DNode:
    """Node for a doubly linked list storing a value and two links."""
    __slots__ = ('value', 'prev', 'next')

    def __init__(self, value, prev=None, next=None):
        self.value = value
        self.prev = prev
        self.next = next

    def __repr__(self):
        return f'DNode({self.value!r})'


class DoublyLinkedList:
    """A mutable doubly linked list supporting O(1) insertions at both ends."""
    def __init__(self):
        self.head = None
        self.tail = None

    def append(self, value):
        """Add *value* to the end of the list."""
        new = DNode(value, prev=self.tail)
        if self.tail:
            self.tail.next = new
        else:
            self.head = new
        self.tail = new

    def prepend(self, value):
        """Add *value* to the front of the list."""
        new = DNode(value, next=self.head)
        if self.head:
            self.head.prev = new
        else:
            self.tail = new
        self.head = new

    def remove(self, node):
        """Remove *node* from the list. Raises ValueError if node not linked."""
        if node.prev:
            node.prev.next = node.next
        else:
            if self.head is not node:
                raise ValueError('Node not in list')
            self.head = node.next
        if node.next:
            node.next.prev = node.prev
        else:
            if self.tail is not node:
                raise ValueError('Node not in list')
            self.tail = node.prev
        node.prev = node.next = None

    def __iter__(self):
        cur = self.head
        while cur:
            yield cur.value
            cur = cur.next

    def __reversed__(self):
        cur = self.tail
        while cur:
            yield cur.value
            cur = cur.prev

    def __repr__(self):
        return f'DoublyLinkedList({list(self)})'


if __name__ == '__main__':
    dll = DoublyLinkedList()
    for ch in 'abc':
        dll.append(ch)
    dll.prepend('z')
    print('Forward:', list(dll))
    print('Backward:', list(reversed(dll)))
    # Remove the middle node (original 'b')
    node = dll.head.next.next  # points to 'b' after prepend
    dll.remove(node)
    print('After removal:', list(dll))

'''circular_singly.py
Circular singly linked list implementation.
Includes insert, delete, find, and rotate(k) which moves the head k steps forward.
'''

class CNode:
    """Node used in a circular singly linked list."""
    __slots__ = ('value', 'next')

    def __init__(self, value, next=None):
        self.value = value
        self.next = next

    def __repr__(self):
        return f'CNode({self.value!r})'


class CircularSinglyLinkedList:
    """Circular list where tail.next points to head."""
    def __init__(self):
        self.tail = None  # tail.next is the logical head

    def _head(self):
        return None if self.tail is None else self.tail.next

    def insert(self, value):
        """Insert *value* after the tail (i.e., at the end)."""
        new = CNode(value)
        if self.tail is None:
            new.next = new  # points to itself
            self.tail = new
        else:
            new.next = self.tail.next
            self.tail.next = new
            self.tail = new

    def delete(self, value):
        """Delete first node with *value*.
        Returns True if deletion succeeded, False otherwise."""
        if self.tail is None:
            return False
        cur = self.tail.next
        prev = self.tail
        while True:
            if cur.value == value:
                if cur is self.tail:
                    # deleting tail – need new tail
                    if cur is cur.next:  # only node
                        self.tail = None
                    else:
                        prev.next = cur.next
                        self.tail = prev
                else:
                    prev.next = cur.next
                return True
            prev, cur = cur, cur.next
            if cur is self.tail.next:
                break
        return False

    def rotate(self, k):
        """Rotate the list left by *k* nodes.
        After rotation, the former (k‑th) node becomes the new head.
        """
        if self.tail is None:
            return
        k = k % self.size()
        for _ in range(k):
            self.tail = self.tail.next  # moving tail forward shifts head backward

    def size(self):
        if self.tail is None:
            return 0
        cnt = 1
        cur = self.tail.next
        while cur is not self.tail:
            cnt += 1
            cur = cur.next
        return cnt

    def __iter__(self):
        if self.tail is None:
            return
        cur = self.tail.next
        while True:
            yield cur.value
            if cur is self.tail:
                break
            cur = cur.next

    def __repr__(self):
        return f'CircularSinglyLinkedList({list(self)})'


if __name__ == '__main__':
    cl = CircularSinglyLinkedList()
    for i in range(1, 6):
        cl.insert(i)
    print('Original:', cl)
    cl.rotate(2)
    print('After rotate(2):', cl)
    cl.delete(3)
    print('After deleting 3:', cl)

'''sorted_linked_list.py
A linked list that maintains its elements in ascending order.
Provides ordered insertion, deletion, and conversion to a plain list.
'''

class SNode:
    __slots__ = ('value', 'next')

    def __init__(self, value, nxt=None):
        self.value = value
        self.next = nxt

    def __repr__(self):
        return f'SNode({self.value!r})'


class SortedLinkedList:
    """Keeps elements sorted; duplicate values are allowed."""
    def __init__(self):
        self.head: Optional[SNode] = None

    def insert(self, value):
        """Insert *value* preserving ascending order."""
        new = SNode(value)
        if self.head is None or value < self.head.value:
            new.next = self.head
            self.head = new
            return
        cur = self.head
        while cur.next and cur.next.value <= value:
            cur = cur.next
        new.next = cur.next
        cur.next = new

    def delete(self, value):
        """Delete the first occurrence of *value*; returns True if removed."""
        cur = self.head
        prev = None
        while cur:
            if cur.value == value:
                if prev is None:
                    self.head = cur.next
                else:
                    prev.next = cur.next
                return True
            prev, cur = cur, cur.next
        return False

    def to_list(self):
        """Return a Python list containing all node values in order."""
        return [node.value for node in self]

    def __iter__(self):
        cur = self.head
        while cur:
            yield cur
            cur = cur.next

    def __repr__(self):
        return f'SortedLinkedList({self.to_list()})'


if __name__ == '__main__':
    sll = SortedLinkedList()
    for num in [5, 1, 3, 4, 2, 3]:
        sll.insert(num)
    print('After inserts:', sll)
    sll.delete(3)
    print('After deleting first 3:', sll)
    print('Plain Python list:', sll.to_list())

'''linked_stack.py
A Stack data structure built on top of a singly linked list.
Provides push, pop, peek, and size operations.
'''

class _StackNode:
    __slots__ = ('value', 'next')

    def __init__(self, value, nxt=None):
        self.value = value
        self.next = nxt

    def __repr__(self):
        return f'_StackNode({self.value!r})'


class LinkedStack:
    """LIFO stack where the top is the head of a singly linked list."""
    def __init__(self):
        self._top: Optional[_StackNode] = None
        self._size = 0

    def push(self, item):
        """Place *item* on top of the stack."""
        self._top = _StackNode(item, self._top)
        self._size += 1

    def pop(self):
        """Remove and return the top element.
        Raises IndexError if the stack is empty."""
        if self._top is None:
            raise IndexError('pop from empty stack')
        node = self._top
        self._top = node.next
        self._size -= 1
        return node.value

    def peek(self):
        """Return the top element without removing it; None if empty."""
        return None if self._top is None else self._top.value

    def size(self):
        return self._size

    def is_empty(self):
        return self._top is None

    def __len__(self):
        return self._size

    def __repr__(self):
        items = []
        cur = self._top
        while cur:
            items.append(cur.value)
            cur = cur.next
        return f'LinkedStack(top->bottom: {items})'


if __name__ == '__main__':
    s = LinkedStack()
    for i in range(3):
        s.push(i)
    print('Stack after pushes:', s)
    print('Peek:', s.peek())
    while not s.is_empty():
        print('Popped', s.pop())
    print('Final stack:', s)

