#!/usr/bin/env bash
# human2cron.sh – Translate simple human schedules to cron syntax.
# Supported patterns:
#   "every N minutes"
#   "every N hours"
#   "every N days at HH:MM"
#   "every N weeks on DOW at HH:MM" (DOW: Mon, Tue, ... Sun)
# Usage: ./human2cron.sh "every 2 hours"

usage() {
    echo "Usage: $0 \"schedule description\""
    echo "Examples:"
    echo "  \"every 15 minutes\""
    echo "  \"every 3 hours\""
    echo "  \"every 2 days at 03:30\""
    echo "  \"every 1 weeks on Sun at 04:00\""
    exit 2
}

weekday_to_num() {
    case "${1,,}" in
        mon) echo 1 ;;
        tue) echo 2 ;;
        wed) echo 3 ;;
        thu) echo 4 ;;
        fri) echo 5 ;;
        sat) echo 6 ;;
        sun) echo 0 ;;
        *) echo "?" ;;
    esac
}

parse() {
    local txt="$1"
    if [[ $txt =~ ^every[[:space:]]+([0-9]+)[[:space:]]+minutes?$ ]]; then
        echo "*/${BASH_REMATCH[1]} * * * *"
    elif [[ $txt =~ ^every[[:space:]]+([0-9]+)[[:space:]]+hours?$ ]]; then
        echo "0 */${BASH_REMATCH[1]} * * *"
    elif [[ $txt =~ ^every[[:space:]]+([0-9]+)[[:space:]]+days[[:space:]]+at[[:space:]]+([0-9]{2}):([0-9]{2})$ ]]; then
        echo "${BASH_REMATCH[3]} ${BASH_REMATCH[2]} */${BASH_REMATCH[1]} * *"
    elif [[ $txt =~ ^every[[:space:]]+([0-9]+)[[:space:]]+weeks[[:space:]]+on[[:space:]]+([A-Za-z]+)[[:space:]]+at[[:space:]]+([0-9]{2}):([0-9]{2})$ ]]; then
        local dow=$(weekday_to_num "${BASH_REMATCH[2]}")
        if [[ $dow == "?" ]]; then echo "Invalid weekday"; exit 1; fi
        echo "${BASH_REMATCH[4]} ${BASH_REMATCH[3]} * * $dow"
    else
        echo "Unrecognized pattern"
        usage
    fi
}

main() {
    [[ $# -ne 1 ]] && usage
    parse "$1"
}

if [[ "${BASH_SOURCE[0]}" == "${0}" ]]; then
    main "$@"
fi

"""list_venvs.py
Scans a directory for subfolders that look like Python virtual environments
(i.e., contain a bin/ or Scripts/ directory with a python executable).
For each found venv, the script prints the path and the interpreter version.
"""
import argparse
import os
import pathlib
import subprocess
import sys

def is_venv(path: pathlib.Path) -> bool:
    """Return True if *path* contains a virtual‑environment layout.
    Checks for bin/python (POSIX) or Scripts\python.exe (Windows).
    """
    if sys.platform.startswith('win'):
        return (path / 'Scripts' / 'python.exe').is_file()
    return (path / 'bin' / 'python').is_file()

def python_executable(path: pathlib.Path) -> pathlib.Path:
    return path / ('Scripts' if sys.platform.startswith('win') else 'bin') / ('python.exe' if sys.platform.startswith('win') else 'python')

def get_version(python_path: pathlib.Path) -> str:
    """Invoke *python_path* with '--version' and return the stdout string."""
    result = subprocess.run([str(python_path), '--version'], capture_output=True, text=True, check=True)
    return result.stdout.strip() or result.stderr.strip()

def main() -> None:
    parser = argparse.ArgumentParser(description='List virtual environments and their Python versions')
    parser.add_argument('parent', type=pathlib.Path, help='Directory containing possible venv subfolders')
    args = parser.parse_args()
    parent = args.parent.resolve()
    if not parent.is_dir():
        sys.exit(f'{parent} is not a directory')
    for child in parent.iterdir():
        if child.is_dir() and is_venv(child):
            py_exe = python_executable(child)
            version = get_version(py_exe)
            print(f'{child}: {version}')

if __name__ == '__main__':
    main()

