'''calc_unittest.py
A minimal example showing how to test a simple Calculator class using the built-in unittest framework.
Run the file directly: python calc_unittest.py
''' 

class Calculator:
    """A very small calculator supporting add, subtract, multiply and divide."""

    def add(self, a, b):
        return a + b

    def sub(self, a, b):
        return a - b

    def mul(self, a, b):
        return a * b

    def div(self, a, b):
        if b == 0:
            raise ZeroDivisionError("division by zero")
        return a / b

