'''doubly_linked_list.py
A minimal doubly‑linked list implementation.
Supports push (add to tail), pop (remove from tail) and in‑place reversal.
''' 

class DNode:
    """Node for a doubly‑linked list holding data, prev and next references."""
    def __init__(self, data, prev=None, nxt=None):
        self.data = data
        self.prev = prev
        self.next = nxt

    def __repr__(self):
        return f"DNode({self.data})"

class DoublyLinkedList:
    """Container for DNode objects with head and tail pointers."""
    def __init__(self):
        self.head = None
        self.tail = None

    def push(self, value):
        """Append *value* to the end of the list."""
        new_node = DNode(value, self.tail, None)
        if self.tail:
            self.tail.next = new_node
        else:
            self.head = new_node
        self.tail = new_node

    def pop(self):
        """Remove and return the last element. Returns None if list is empty."""
        if not self.tail:
            return None
        val = self.tail.data
        if self.tail.prev:
            self.tail = self.tail.prev
            self.tail.next = None
        else:
            self.head = self.tail = None
        return val

    def reverse(self):
        """Reverse the list in place by swapping next and prev of each node."""
        cur = self.head
        while cur:
            cur.prev, cur.next = cur.next, cur.prev
            cur = cur.prev  # after swap, prev is the original next
        self.head, self.tail = self.tail, self.head

    def to_list(self):
        """Return a Python list of node values from head to tail."""
        out = []
        cur = self.head
        while cur:
            out.append(cur.data)
            cur = cur.next
        return out

if __name__ == "__main__":
    dll = DoublyLinkedList()
    for ch in "abcde":
        dll.push(ch)
    print("Original:", dll.to_list())
    dll.reverse()
    print("Reversed:", dll.to_list())
    print("Popped:", dll.pop())
    print("After pop:", dll.to_list())

'''dataclass_linked_sum.py
Linked list node defined with @dataclass.
Provides a recursive sum_list function that adds up integer data values.
''' 

from __future__ import annotations
from dataclasses import dataclass
from typing import Optional

@dataclass
class ListNode:
    data: int
    next: Optional['ListNode'] = None

def sum_list(node: Optional[ListNode]) -> int:
    """Recursively compute the sum of *data* in the linked list starting at *node*.
    Returns 0 for an empty (None) node.
    """
    if node is None:
        return 0
    return node.data + sum_list(node.next)

def build_sample() -> ListNode:
    """Create a three‑node list 4 → 7 → 1 and return its head."""
    return ListNode(4, ListNode(7, ListNode(1)))

if __name__ == "__main__":
    head = build_sample()
    print("List values:", [head.data, head.next.data, head.next.next.data])
    print("Sum of list:", sum_list(head))

'''linked_stack.py
Stack implementation built on a singly‑linked list.
Supports push, pop, peek and an is_empty property.
''' 

class _StackNode:
    def __init__(self, value, nxt=None):
        self.value = value
        self.next = nxt

class LinkedStack:
    """LIFO stack where each element is a node in a singly‑linked list."""
    def __init__(self):
        self._top = None
        self._size = 0

    def push(self, item):
        """Place *item* on top of the stack."""
        self._top = _StackNode(item, self._top)
        self._size += 1

    def pop(self):
        """Remove and return the top item. Raises IndexError if the stack is empty."""
        if self.is_empty:
            raise IndexError("pop from empty stack")
        node = self._top
        self._top = node.next
        self._size -= 1
        return node.value

    def peek(self):
        """Return the top item without removing it. Returns None if empty."""
        return None if self.is_empty else self._top.value

    @property
    def is_empty(self):
        return self._top is None

    def __len__(self):
        return self._size

if __name__ == "__main__":
    s = LinkedStack()
    for ch in "abc":
        s.push(ch)
    print("Top after pushes:", s.peek())
    while not s.is_empty:
        print("pop ->", s.pop())
    print("Stack size after emptying:", len(s))

'''fib_cache.py
A simple demonstration of functools.lru_cache applied to a recursive Fibonacci
implementation. Includes a helper to clear the cache and a command‑line interface.
'''

from __future__ import annotations

import sys
from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n: int) -> int:
    """Return the nth Fibonacci number.

    The function is memoized with an unbounded LRU cache, so repeated calls are
    O(1) after the first computation.
    """
    if n < 0:
        raise ValueError('n must be non‑negative')
    if n in (0, 1):
        return n
    return fib(n - 1) + fib(n - 2)

def clear_cache() -> None:
    """Empty the internal cache of :func:`fib`."""
    fib.cache_clear()

def main(argv: list[str] | None = None) -> None:
    argv = argv or sys.argv[1:]
    if not argv:
        print('Usage: python fib_cache.py <non‑negative integer>')
        return
    if argv[0] == '--clear':
        clear_cache()
        print('Cache cleared.')
        return
    try:
        n = int(argv[0])
    except ValueError:
        print('Please provide a valid integer.')
        return
    try:
        result = fib(n)
        print(f'fib({n}) = {result}')
        print(f'Cache info: {fib.cache_info()}')
    except ValueError as e:
        print(e)

if __name__ == '__main__':
    main()

'''log_with_partial.py
A utility that builds a logging decorator with a user‑supplied prefix.
The decorator preserves the wrapped function's metadata via functools.wraps.
'''

import logging
from functools import wraps, partial

logging.basicConfig(format='%(levelname)s: %(message)s', level=logging.INFO)

def make_logger(prefix: str):
    """Return a decorator that logs *prefix* before the wrapped call.

    The returned decorator can be reused for many functions that share the same
    logging prefix.
    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            logging.info(f"{prefix} – calling {func.__name__}")
            return func(*args, **kwargs)
        return wrapper
    return decorator

# Use functools.partial to pre‑bind a common prefix.
info_logger = partial(make_logger, '[INFO]')
debug_logger = partial(make_logger, '[DEBUG]')

@info_logger()
def greet(name: str) -> str:
    """Return a greeting for *name*."""
    return f"Hello, {name}!"

@debug_logger()
def add(a: int, b: int) -> int:
    """Return the sum of *a* and *b*."""
    return a + b

if __name__ == '__main__':
    print(greet('Alice'))
    print('Sum =', add(4, 7))

'''set_relations_test.py
Utility functions for subset/superset checks together with a simple unittest suite.
Run with: python -m unittest set_relations_test.py
'''
import unittest
from typing import Iterable

def is_subset(candidate: Iterable, reference: Iterable) -> bool:
    """Return True if *candidate* is a subset of *reference*.
    Both arguments are converted to sets internally.
    """
    return set(candidate) <= set(reference)

def is_superset(candidate: Iterable, reference: Iterable) -> bool:
    """Return True if *candidate* is a superset of *reference*.
    Both arguments are converted to sets internally.
    """
    return set(candidate) >= set(reference)

class TestSetRelations(unittest.TestCase):
    def test_subset_true(self):
        self.assertTrue(is_subset({1, 2}, {1, 2, 3}))

    def test_subset_false(self):
        self.assertFalse(is_subset({1, 4}, {1, 2, 3}))

    def test_superset_true(self):
        self.assertTrue(is_superset({1, 2, 3}, {2, 3}))

    def test_superset_false(self):
        self.assertFalse(is_superset({1, 2}, {2, 3}))

    def test_empty_cases(self):
        self.assertTrue(is_subset(set(), {1, 2}))
        self.assertTrue(is_superset({1, 2}, set()))

if __name__ == '__main__':
    unittest.main()

import sys


def solve_n_queens(n: int):
    """Yield all valid board configurations for an n×n chessboard.

    Each configuration is represented as a list where the index is the row and
    the value is the column of the queen in that row.
    """
    def backtrack(row: int, cols: set[int], diag1: set[int], diag2: set[int], board: list[int]):
        if row == n:
            yield board.copy()
            return
        for col in range(n):
            d1 = row - col
            d2 = row + col
            if col in cols or d1 in diag1 or d2 in diag2:
                continue
            cols.add(col); diag1.add(d1); diag2.add(d2)
            board.append(col)
            yield from backtrack(row + 1, cols, diag1, diag2, board)
            board.pop()
            cols.remove(col); diag1.remove(d1); diag2.remove(d2)
    return backtrack(0, set(), set(), set(), [])


def format_solution(sol: list[int]) -> str:
    """Return a pretty multi‑line string visualising a single solution."""
    n = len(sol)
    lines = []
    for col in sol:
        line = ['.'] * n
        line[col] = 'Q'
        lines.append(''.join(line))
    return "\n".join(lines)


def main(argv: list[str] | None = None):
    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        print('usage: python nqueens_all.py <board-size>')
        return
    try:
        size = int(argv[0])
        if size < 1:
            raise ValueError
    except ValueError:
        print('board size must be a positive integer')
        return
    count = 0
    for solution in solve_n_queens(size):
        count += 1
        print(f"Solution {count}:")
        print(format_solution(solution))
        print()
    print(f"Total solutions for n={size}: {count}")

if __name__ == '__main__':
    main()

import sys
from pathlib import Path


def generate_solutions(n: int):
    """Yield each solution as a list of column positions for an n×n board."""
    def backtrack(row: int, cols: set[int], d1: set[int], d2: set[int], board: list[int]):
        if row == n:
            yield board.copy()
            return
        for col in range(n):
            if col in cols or (row - col) in d1 or (row + col) in d2:
                continue
            cols.add(col); d1.add(row - col); d2.add(row + col)
            board.append(col)
            yield from backtrack(row + 1, cols, d1, d2, board)
            board.pop(); cols.remove(col); d1.remove(row - col); d2.remove(row + col)
    return backtrack(0, set(), set(), set(), [])


def board_to_string(board: list[int]) -> str:
    n = len(board)
    lines = []
    for col in board:
        line = ['.'] * n
        line[col] = 'Q'
        lines.append(''.join(line))
