import sys


def print_board(state: list[int], n: int) -> None:
    for r in range(n):
        line = ['.'] * n
        if r < len(state):
            line[state[r]] = 'Q'
        print(''.join(line))
    print('-' * n)


def backtrack(row: int, n: int, cols: set[int], d1: set[int], d2: set[int], state: list[int]):
    if row == n:
        print('Solution found:')
        print_board(state, n)
        return True
    for col in range(n):
        if col in cols or (row - col) in d1 or (row + col) in d2:
            continue
        # place queen
        cols.add(col); d1.add(row - col); d2.add(row + col)
        state.append(col)
        print(f'Placing queen at ({row}, {col})')
        print_board(state, n)
        if backtrack(row + 1, n, cols, d1, d2, state):
            return True
        # backtrack: remove queen
        removed = state.pop()
        cols.remove(col); d1.remove(row - col); d2.remove(row + col)
        print(f'Removing queen from ({row}, {removed})')
        print_board(state, n)
    return False


def main(argv: list[str] | None = None):
    if argv is None:
        argv = sys.argv[1:]
    n = 4 if not argv else int(argv[0])
    backtrack(0, n, set(), set(), set(), [])

if __name__ == '__main__':
    main()

'''vector3d.py
3‑D vector implementation using a dataclass.
Supports arithmetic operators, magnitude, and a tiny unittest suite.
'''

from __future__ import annotations
import math
import unittest
from dataclasses import dataclass

@dataclass(frozen=True)
class Vector3D:
    """Immutable 3‑dimensional vector.

    Attributes are stored as ``x``, ``y`` and ``z`` floats.
    """

    x: float
    y: float
    z: float

    # Operator overloads -------------------------------------------------
    def __add__(self, other: Vector3D) -> Vector3D:
        return Vector3D(self.x + other.x, self.y + other.y, self.z + other.z)

    def __sub__(self, other: Vector3D) -> Vector3D:
        return Vector3D(self.x - other.x, self.y - other.y, self.z - other.z)

    def __mul__(self, scalar: float) -> Vector3D:
        """Scalar multiplication: ``v * k``.

        The reflected operation ``k * v`` is also supported via ``__rmul__``.
        """
        return Vector3D(self.x * scalar, self.y * scalar, self.z * scalar)

    __rmul__ = __mul__

    # Magnitude -----------------------------------------------------------
    def magnitude(self) -> float:
        """Return Euclidean length of the vector."""
        return math.sqrt(self.x ** 2 + self.y ** 2 + self.z ** 2)

    def __repr__(self) -> str:
        return f"Vector3D(x={self.x}, y={self.y}, z={self.z})"

# -----------------------------------------------------------------------
class TestVector3D(unittest.TestCase):
    def setUp(self) -> None:
        self.v1 = Vector3D(1, 2, 3)
        self.v2 = Vector3D(-1, 0, 4)

    def test_add(self) -> None:
        self.assertEqual(self.v1 + self.v2, Vector3D(0, 2, 7))

    def test_sub(self) -> None:
        self.assertEqual(self.v1 - self.v2, Vector3D(2, 2, -1))

    def test_scalar_mul(self) -> None:
        self.assertEqual(self.v1 * 3, Vector3D(3, 6, 9))
        self.assertEqual(2 * self.v2, Vector3D(-2, 0, 8))

    def test_magnitude(self) -> None:
        self.assertAlmostEqual(self.v1.magnitude(), math.sqrt(14))
        self.assertAlmostEqual(self.v2.magnitude(), math.sqrt(17))

if __name__ == "__main__":
    unittest.main()

'''basic_stack.py
A minimal Stack implementation using Python's built‑in list.
Provides push, pop, peek and is_empty methods.
''' 

class Stack:
    """LIFO stack backed by a Python list."""
    def __init__(self) -> None:
        self._items: list = []

    def push(self, item) -> None:
        """Add *item* to the top of the stack."""
        self._items.append(item)

    def pop(self):
        """Remove and return the top element.
        Raises IndexError if the stack is empty.
        """
        if self.is_empty():
            raise IndexError('pop from empty stack')
        return self._items.pop()

    def peek(self):
        """Return the top element without removing it.
        Raises IndexError if the stack is empty.
        """
        if self.is_empty():
            raise IndexError('peek from empty stack')
        return self._items[-1]

    def is_empty(self) -> bool:
        """Return True when the stack holds no items."""
        return not self._items

    def __len__(self) -> int:
        return len(self._items)

    def __repr__(self) -> str:
        return f"Stack({self._items!r})"

if __name__ == '__main__':
    s = Stack()
    for i in range(5):
        s.push(i)
        print(f'pushed {i}, stack now: {s}')
    print('peek ->', s.peek())
    while not s.is_empty():
        print('popped', s.pop())

'''deque_queue.py
Queue implementation based on collections.deque.
Supports enqueue (add to right), dequeue (remove from left), front and emptiness checks.
''' 

from collections import deque
from typing import Any

class Queue:
    """FIFO queue with O(1) operations using deque."""
    def __init__(self) -> None:
        self._data: deque = deque()

    def enqueue(self, item: Any) -> None:
        """Add *item* to the back of the queue."""
        self._data.append(item)

    def dequeue(self) -> Any:
        """Remove and return the front item.
        Raises IndexError if the queue is empty.
        """
        if self.is_empty():
            raise IndexError('dequeue from empty queue')
        return self._data.popleft()

    def front(self) -> Any:
        """Return the front item without removing it.
        Raises IndexError if empty.
        """
        if self.is_empty():
            raise IndexError('front from empty queue')
        return self._data[0]

    def is_empty(self) -> bool:
        return not self._data

    def __len__(self) -> int:
        return len(self._data)

    def __repr__(self) -> str:
        return f"Queue({list(self._data)!r})"

if __name__ == '__main__':
    q = Queue()
    for ch in 'abcde':
        q.enqueue(ch)
        print(f'enqueued {ch}, queue: {q}')
    print('front ->', q.front())
    while not q.is_empty():
        print('dequeued', q.dequeue())

'''stack_queue_reverse.py
Contains Stack and Queue classes (list‑based and deque‑based respectively)
and a utility function reverse_queue that uses a Stack to invert the order.
''' 

from collections import deque
from typing import Any, List

class Stack:
    def __init__(self) -> None:
        self._items: List[Any] = []
    def push(self, item: Any) -> None:
        self._items.append(item)
    def pop(self) -> Any:
        if not self._items:
            raise IndexError('pop from empty stack')
        return self._items.pop()
    def is_empty(self) -> bool:
        return not self._items
    def __len__(self) -> int:
        return len(self._items)
    def __repr__(self) -> str:
        return f"Stack({self._items!r})"

class Queue:
    def __init__(self) -> None:
        self._data: deque = deque()
    def enqueue(self, item: Any) -> None:
        self._data.append(item)
    def dequeue(self) -> Any:
        if not self._data:
            raise IndexError('dequeue from empty queue')
        return self._data.popleft()
    def is_empty(self) -> bool:
        return not self._data
    def __len__(self) -> int:
        return len(self._data)
    def __repr__(self) -> str:
        return f"Queue({list(self._data)!r})"

def reverse_queue(q: Queue) -> None:
    """Reverse *q* in‑place by moving its elements onto a Stack and back.
    After the call the order of elements is opposite of the original.
    """
    stack = Stack()
    while not q.is_empty():
        stack.push(q.dequeue())
    while not stack.is_empty():
        q.enqueue(stack.pop())

if __name__ == '__main__':
    q = Queue()
    for n in range(1, 6):
        q.enqueue(n)
    print('original queue:', q)
    reverse_queue(q)
    print('reversed queue:', q)

'''circular_queue.py
Fixed‑size circular queue implementation.
Uses a list of a preset capacity and head/tail indices.
Provides enqueue, dequeue, front, rear, is_full and is_empty.
''' 

from typing import Any, List

class CircularQueue:
    def __init__(self, capacity: int) -> None:
        if capacity <= 0:
            raise ValueError('capacity must be positive')
        self._buf: List[Any] = [None] * capacity
        self._capacity = capacity
        self._head = 0  # points to current front
        self._tail = 0  # points to next insertion slot
        self._size = 0

    def enqueue(self, item: Any) -> None:
        if self.is_full():
            raise OverflowError('enqueue on full circular queue')
        self._buf[self._tail] = item
        self._tail = (self._tail + 1) % self._capacity
        self._size += 1

    def dequeue(self) -> Any:
        if self.is_empty():
            raise IndexError('dequeue from empty circular queue')
        item = self._buf[self._head]
        self._buf[self._head] = None
        self._head = (self._head + 1) % self._capacity
        self._size -= 1
        return item

    def front(self) -> Any:
        if self.is_empty():
            raise IndexError('front from empty circular queue')
        return self._buf[self._head]

    def rear(self) -> Any:
        if self.is_empty():
            raise IndexError('rear from empty circular queue')
        return self._buf[(self._tail - 1) % self._capacity]

    def is_full(self) -> bool:
        return self._size == self._capacity

    def is_empty(self) -> bool:
        return self._size == 0

    def __len__(self) -> int:
        return self._size

    def __repr__(self) -> str:
        return f"CircularQueue(cap={self._capacity}, size={self._size}, buf={self._buf})"

if __name__ == '__main__':
    cq = CircularQueue(4)
    for i in range(4):
        cq.enqueue(i)
        print('enqueue', i, cq)
    try:
        cq.enqueue(99)
    except OverflowError as e:
        print('expected overflow:', e)
    while not cq.is_empty():
        print('dequeue ->', cq.dequeue(), cq)

'''paren_balance.py
Generic Stack implementation and a parenthesis‑balancing checker.
Supports (), [], {} pairs.
''' 

from typing import List

class Stack:
    def __init__(self) -> None:
        self._items: List[str] = []
    def push(self, item: str) -> None:
        self._items.append(item)
    def pop(self) -> str:
        if not self._items:
            raise IndexError('pop from empty stack')
        return self._items.pop()
    def peek(self) -> str:
        if not self._items:
            raise IndexError('peek from empty stack')
        return self._items[-1]
    def is_empty(self) -> bool:
        return not self._items
    def __len__(self) -> int:
        return len(self._items)

_PAIRS = {')': '(', ']': '[', '}': '{'}
_OPEN = set(_PAIRS.values())

def is_balanced(s: str) -> bool:
    """Return True if *s* contains properly nested and matched brackets.
    Any character not in the defined pairs is ignored.
    """
    stack = Stack()
    for ch in s:
        if ch in _OPEN:
            stack.push(ch)
        elif ch in _PAIRS:
            if stack.is_empty() or stack.pop() != _PAIRS[ch]:
                return False
    return stack.is_empty()

if __name__ == '__main__':
    tests = ["(a[{}])", "([)]", "{[()]}", "(((())))", ""]
    for t in tests:
        print(t, '=>', is_balanced(t))

'''fib_iterable.py
Provides a FibonacciIterable class whose __iter__ method returns a generator.
The generator yields Fibonacci numbers not exceeding a user‑specified limit.
