from typing import Generator, Iterable

def _fib_generator(limit: int) -> Generator[int, None, None]:
    """Yield Fibonacci numbers up to limit (inclusive)."""
    a, b = 0, 1
    while a <= limit:
        yield a
        a, b = b, a + b

class FibonacciIterable:
    """Iterable that produces Fibonacci numbers up to a given maximum.

    Parameters
    ----------
    limit : int
        Upper bound for the sequence; the generator stops when the next value would exceed this limit.
    """

    def __init__(self, limit: int = 100):
        if limit < 0:
            raise ValueError("limit must be non‑negative")
        self.limit = limit

    def __iter__(self) -> Generator[int, None, None]:
        """Return a fresh generator each time iteration starts."""
        return _fib_generator(self.limit)

