    for num in FibonacciIterable(50):
        print(num)

'''protect_mutable.py
Utility decorator that replaces mutable default arguments with fresh objects on each call.
'''

from functools import wraps
from inspect import signature, Parameter

def protect_mutable(func):
    """Wrap *func* so that any mutable default arguments are replaced with new instances.
    The decorator inspects the function signature, detects defaults that are mutable
    (list, dict, set), and recreates them for every call.
    """
    sig = signature(func)
    mutable_defaults = {
        name: default for name, param in sig.parameters.items()
        if param.default is not Parameter.empty and isinstance(param.default, (list, dict, set))
    }

    @wraps(func)
    def wrapper(*args, **kwargs):
        bound = sig.bind_partial(*args, **kwargs)
        for name, default in mutable_defaults.items():
            if name not in bound.arguments:
                # create a fresh copy of the mutable default
                if isinstance(default, list):
                    bound.arguments[name] = []
                elif isinstance(default, dict):
                    bound.arguments[name] = {}
                elif isinstance(default, set):
                    bound.arguments[name] = set()
        return func(*bound.args, **bound.kwargs)
    return wrapper

# Example usage
@protect_mutable
def add_item(item, collection: list = []):
    collection.append(item)
    return collection

def demo():
    print(add_item(1))  # [1]
    print(add_item(2))  # [2] – not shared

if __name__ == '__main__':
    demo()

'''class_mutable_default.py
Shows a class with a method that unintentionally shares a mutable default
argument and a corrected version using None.
'''

from typing import Dict

class Counter:
    def __init__(self):
        self.total = 0

    def add_bad(self, key: str, storage: Dict[str, int] = {}):
        """Increment *key* in *storage* using a mutable dict default.
        The dict is shared across all calls, leading to surprising accumulation.
        """
        storage[key] = storage.get(key, 0) + 1
        self.total += 1
        return storage

    def add_fixed(self, key: str, storage: Dict[str, int] = None):
        """Safe version – creates a new dict when *storage* is None.
        This prevents cross‑call leakage of counts.
        """
        if storage is None:
            storage = {}
        storage[key] = storage.get(key, 0) + 1
        self.total += 1
        return storage

def demo():
    c = Counter()
    print('Bad method calls:')
    print(c.add_bad('a'))  # {'a': 1}
    print(c.add_bad('b'))  # {'a': 1, 'b': 1} – shared dict
    print(c.add_bad('a'))  # {'a': 2, 'b': 1}

    print('
Fixed method calls:')
    print(c.add_fixed('a'))  # {'a': 1}
    print(c.add_fixed('b'))  # {'b': 1}
    print(c.add_fixed('a'))  # {'a': 1}

if __name__ == '__main__':
    demo()

