"""logging_descriptor.py
A demonstration of a non‑data descriptor that logs access to an attribute.
The LoggedAttribute descriptor prints a message on get and set.
"""

class LoggedAttribute:
    """Descriptor that logs gets and sets.
    It is a non‑data descriptor because it only implements __get__.
    The setter is handled by the owning class via a normal attribute.
    """

    def __init__(self, name: str):
        self.name = name
        self.storage_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        value = getattr(instance, self.storage_name, None)
        print(f"[LOG] Accessed '{self.name}' -> {value!r}")
        return value

