        setattr(self, self.age.storage_name, age)

    @property
    def age(self):
        # Provide a setter that also logs via the descriptor's __get__
        return type(self).age.__get__(self, type(self))

    @age.setter
    def age(self, value: int):
        print(f"[LOG] Setting '{self.__class__.age.name}' -> {value!r}")
        setattr(self, self.__class__.age.storage_name, value)

