"""typed_default_descriptor.py
A reusable descriptor that enforces a type, supplies a default value, and works for any attribute name.
"""

class TypedDefault:
    """Descriptor that checks type and provides a per‑instance default.
    Parameters
    ----------
    name: str
        Attribute name (used only for error messages).
    expected_type: type
        The type that assigned values must match.
    default: Any
        Value used when the attribute has never been set.
    """

    def __init__(self, name: str, expected_type: type, default):
        self.name = name
        self.expected_type = expected_type
        self.default = default
        self.storage_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.storage_name, self.default)

    def __set__(self, instance, value):
        if not isinstance(value, self.expected_type):
            raise TypeError(
                f"{self.name} must be of type {self.expected_type.__name__}, got {type(value).__name__}"
            )
        setattr(instance, self.storage_name, value)

    def __delete__(self, instance):
        if hasattr(instance, self.storage_name):
            delattr(instance, self.storage_name)
        else:
            raise AttributeError(f"{self.name} is not set and cannot be deleted")

class Settings:
    """Example class that uses TypedDefault for several configuration options.
    """
    timeout = TypedDefault('timeout', int, 30)
    host = TypedDefault('host', str, 'localhost')
    debug = TypedDefault('debug', bool, False)

    def __init__(self, **kwargs):
        for key, value in kwargs.items():
            if not hasattr(self.__class__, key):
                raise AttributeError(f"Unknown setting '{key}'")
            setattr(self, key, value)

if __name__ == "__main__":
