"""write_once_descriptor.py
Descriptor that allows a single assignment; further attempts raise an exception.
Used in the `Config` class for a `api_key` attribute.
"""

class WriteOnce:
    """Data descriptor permitting one-time assignment.
    Subsequent assignments raise a `AttributeError`.
    """

    def __init__(self, name: str):
        self.name = name
        self.storage_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        if not hasattr(instance, self.storage_name):
            raise AttributeError(f"{self.name} has not been set yet")
        return getattr(instance, self.storage_name)

    def __set__(self, instance, value):
        if hasattr(instance, self.storage_name):
            raise AttributeError(f"{self.name} is write‑once and already set")
        setattr(instance, self.storage_name, value)

    def __delete__(self, instance):
        raise AttributeError(f"{self.name} cannot be deleted")

class Config:
    """Configuration holder where `api_key` may be set only once.
    """
    api_key = WriteOnce('api_key')

    def __init__(self, api_key: str = None):
        if api_key is not None:
            self.api_key = api_key

if __name__ == "__main__":
    cfg = Config('initial-key')
    print('API key set to:', cfg.api_key)
    try:
        cfg.api_key = 'new-key'
    except Exception as e:
        print('Error on second assignment:', e)
    try:
        del cfg.api_key
    except Exception as e:
        print('Error on delete attempt:', e)
    # Demonstrate lazy creation
    cfg2 = Config()
    try:
        print(cfg2.api_key)
    except Exception as e:
        print('Access before set error:', e)
    cfg2.api_key = 'second-key'
    print('Second config key:', cfg2.api_key)

'''batch_executor.py
Read a list of shell commands (one per line) from INPUT_FILE, execute them one after another,
and write a log entry for each command to LOG_FILE indicating success or failure.
Empty lines and lines starting with # are ignored.
''' 
import pathlib
import subprocess
from typing import List

INPUT_FILE = pathlib.Path("commands.txt")
LOG_FILE = pathlib.Path("execution.log")

def load_commands(path: pathlib.Path) -> List[str]:
    """Return a list of non‑empty, non‑comment lines from *path*."""
    return [
        line.strip()
        for line in path.read_text().splitlines()
        if line.strip() and not line.lstrip().startswith("#")
    ]

def execute(command: str) -> bool:
    """Run *command* via subprocess.run and return True on exit code 0."""
    result = subprocess.run(command, shell=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    return result.returncode == 0

def log(message: str) -> None:
    """Append *message* with a newline to LOG_FILE."""
    LOG_FILE.write_text(LOG_FILE.read_text() + message + "\n")

def run_batch():
    commands = load_commands(INPUT_FILE)
    for cmd in commands:
        success = execute(cmd)
        status = "SUCCESS" if success else "FAIL"
        log(f"{cmd} :: {status}")
        print(f"{cmd} -> {status}")

if __name__ == "__main__":
    if not INPUT_FILE.exists():
        print(f"Input file {INPUT_FILE} not found.")
    else:
        run_batch()

"""shapes.py – defines a simple shape hierarchy and a factory.

The package's ``__init__`` re‑exports ``Shape``, ``Circle``, ``Square`` and the
``create_shape`` factory so users can simply write ``import shapes`` and then
use ``shapes.Circle`` etc.
"""

from abc import ABC, abstractmethod
import math
from typing import Dict, Type

class Shape(ABC):
    """Abstract base class for all shapes."""

    @abstractmethod
    def area(self) -> float:
        """Return the area of the shape."""
        pass

    @abstractmethod
    def perimeter(self) -> float:
        """Return the perimeter of the shape."""
        pass

class Circle(Shape):
    """A circle defined by its radius."""

    def __init__(self, radius: float):
        if radius <= 0:
            raise ValueError("radius must be positive")
        self.radius = radius

    def area(self) -> float:
        return math.pi * self.radius ** 2

    def perimeter(self) -> float:
        return 2 * math.pi * self.radius

class Square(Shape):
    """A square defined by the length of its side."""

    def __init__(self, side: float):
        if side <= 0:
            raise ValueError("side must be positive")
        self.side = side

    def area(self) -> float:
        return self.side ** 2

    def perimeter(self) -> float:
        return 4 * self.side

# Registry used by the factory – maps a string key to the concrete class.
_SHAPE_REGISTRY: Dict[str, Type[Shape]] = {
    "circle": Circle,
    "square": Square,
}

def create_shape(shape_type: str, *args, **kwargs) -> Shape:
    """Factory that creates a ``Shape`` subclass instance.

    ``shape_type`` is case‑insensitive.  Additional positional and keyword
    arguments are forwarded to the concrete class constructor.
    """
    cls = _SHAPE_REGISTRY.get(shape_type.lower())
    if cls is None:
        raise ValueError(f"Unknown shape type: {shape_type}")
    return cls(*args, **kwargs)

# The package's public interface – ``__all__`` mirrors what ``__init__.py``
# will export.
__all__ = ["Shape", "Circle", "Square", "create_shape"]

