'''find_dupes.py
Searches a directory tree for files with identical SHA‑256 hashes.
Usage: python find_dupes.py <root_dir>
'''import sys
import hashlib
from collections import defaultdict
from pathlib import Path

def file_hash(p: Path, block_size: int = 65536) -> str:
    """Compute SHA‑256 hash of *p* reading in chunks to avoid high memory usage."""
    hasher = hashlib.sha256()
    with p.open('rb') as f:
        for chunk in iter(lambda: f.read(block_size), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

def collect_hashes(root: Path) -> defaultdict:
    """Walk *root* and map each hash to a list of file paths having that hash."""
    hash_map = defaultdict(list)
    for path in root.rglob('*'):
        if path.is_file():
            try:
                h = file_hash(path)
                hash_map[h].append(path)
            except PermissionError:
                print(f"Skipping {path} (no permission)")
    return hash_map

def print_duplicates(hash_map: defaultdict) -> None:
    """Print groups of files that share the same hash (i.e., duplicates)."""
    dup_groups = [paths for paths in hash_map.values() if len(paths) > 1]
    if not dup_groups:
        print("No duplicate files found.")
        return
    for i, group in enumerate(dup_groups, 1):
        print(f"Duplicate group {i} (hash {file_hash(group[0])}):")
        for p in group:
            print(f"  {p}")
        print()

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python find_dupes.py <root_dir>")
        sys.exit(1)
    root_path = Path(sys.argv[1])
    if not root_path.is_dir():
        print(f"{root_path} is not a directory.")
        sys.exit(1)
    hashes = collect_hashes(root_path)
    print_duplicates(hashes)

'''validate_phone.py
Utility to check whether a supplied string matches common US phone number formats.
Run: python validate_phone.py "(555) 123-4567"
''' 
import re
import sys

# Accepts optional parentheses, spaces, dashes, or a plain 10‑digit string
PHONE_REGEX = re.compile(
    r"^(?:\+1\s*)?"               # optional country code
    r"(?:\(?(\d{3})\)?[\s-]?)"   # area code with optional parentheses
    r"(\d{3})[\s-]?(\d{4})$"      # central office and line number
)

def is_valid_phone(number: str) -> bool:
    """Return True if *number* matches one of the accepted US formats."""
    return bool(PHONE_REGEX.match(number.strip()))

def main() -> None:
    if len(sys.argv) != 2:
        sys.stderr.write("Usage: python validate_phone.py <phone_number>\n")
        sys.exit(1)
    phone = sys.argv[1]
    if is_valid_phone(phone):
        print(f"'{phone}' is a valid US phone number.")
    else:
        print(f"'{phone}' is NOT a valid US phone number.")

if __name__ == "__main__":
    main()

'''mask_ips.py
Replaces every IPv4 address in the supplied input with the token <IP>.
Can be used as a filter: cat file.txt | python mask_ips.py
''' 
import re
import sys

IP_PATTERN = re.compile(r'''\b(
    (?:25[0-5]|2[0-4]\d|1\d{2}|[1-9]?\d)\.){3}
    (?:25[0-5]|2[0-4]\d|1\d{2}|[1-9]?\d)
)\b''', re.VERBOSE)

def mask_line(line: str) -> str:
    """Return *line* with every IPv4 address replaced by '<IP>'."""
    return IP_PATTERN.sub('<IP>', line)

def main() -> None:
    # Read from stdin if no file argument, else from file
    if len(sys.argv) == 1:
        for raw in sys.stdin:
            sys.stdout.write(mask_line(raw))
    else:
        path = sys.argv[1]
        try:
            with open(path, 'r', encoding='utf-8') as f:
                for raw in f:
                    sys.stdout.write(mask_line(raw))
        except OSError as e:
            sys.stderr.write(f'Error opening {path}: {e}\n')
            sys.exit(1)

if __name__ == '__main__':
    main()

