"""Fraction type with automatic reduction and correct magic methods.
The implementation uses Euclid's algorithm for GCD and ensures the
fraction is always stored in lowest terms with a non‑negative denominator.
"""
from __future__ import annotations
from math import gcd

class Fraction:
    """Immutable rational number.

    Parameters
    ----------
    numerator : int
    denominator : int, optional (default 1)
    """

    __slots__ = ("_num", "_den")

    def __init__(self, numerator: int, denominator: int = 1) -> None:
        if denominator == 0:
            raise ZeroDivisionError("Denominator cannot be zero")
        # Normalise sign so denominator is always positive
        if denominator < 0:
            numerator, denominator = -numerator, -denominator
        common = gcd(numerator, denominator)
        self._num = numerator // common
        self._den = denominator // common

    @property
    def numerator(self) -> int:
        return self._num

    @property
    def denominator(self) -> int:
        return self._den

    def __repr__(self) -> str:
        return f"Fraction({self.numerator}, {self.denominator})"

    def __eq__(self, other: object) -> bool:
        if isinstance(other, Fraction):
            return (self.numerator == other.numerator and
                    self.denominator == other.denominator)
        return NotImplemented

    def __hash__(self) -> int:
        # The pair (num, den) uniquely identifies the value because it is reduced.
        return hash((self.numerator, self.denominator))

    # Additional arithmetic for demonstration (not required for the task)
    def __add__(self, other: Fraction) -> Fraction:
        num = self.numerator * other.denominator + other.numerator * self.denominator
        den = self.denominator * other.denominator
        return Fraction(num, den)

    def __sub__(self, other: Fraction) -> Fraction:
        num = self.numerator * other.denominator - other.numerator * self.denominator
        den = self.denominator * other.denominator
        return Fraction(num, den)

if __name__ == "__main__":
    f1 = Fraction(2, 4)
    f2 = Fraction(-6, 9)
    f3 = Fraction(5, 3)
    print(f"f1: {f1}")          # Fraction(1, 2)
    print(f"f2: {f2}")          # Fraction(-2, 3)
    print(f"f1 == Fraction(1,2): {f1 == Fraction(1,2)}")
    s = {f1, f2, f3}
    print("Set contents:", s)

