"""Simple n‑dimensional immutable Vector with magic methods.
The class stores components in a tuple, making it hashable.
"""
from __future__ import annotations
from typing import Iterable, Tuple

class Vector:
    """Immutable mathematical vector.

    Parameters
    ----------
    components : iterable of numbers
        The coordinates of the vector.
    """

    __slots__ = ("_components",)

    def __init__(self, components: Iterable[float]) -> None:
        self._components = tuple(float(c) for c in components)
        if not self._components:
            raise ValueError("Vector must have at least one component")

    @property
    def components(self) -> Tuple[float, ...]:
        return self._components

    def __len__(self) -> int:
        return len(self._components)

    def __getitem__(self, index: int) -> float:
        return self._components[index]

    def __repr__(self) -> str:
        comps = ", ".join(repr(c) for c in self._components)
        return f"Vector({comps})"

    def __eq__(self, other: object) -> bool:
        if isinstance(other, Vector):
            return self._components == other._components
        return NotImplemented

    def __hash__(self) -> int:
        return hash(self._components)

    # Optional: vector addition for illustration
    def __add__(self, other: Vector) -> Vector:
        if len(self) != len(other):
            raise ValueError("Vectors must have the same dimension to add")
        summed = (a + b for a, b in zip(self, other))
        return Vector(summed)

if __name__ == "__main__":
    v1 = Vector([1, 2, 3])
    v2 = Vector((1.0, 2.0, 3.0))
    v3 = Vector([0, 0, 0])
    print(v1)                     # Vector(1, 2, 3)
    print(v1 == v2)               # True
    print({v1, v3})               # {Vector(1, 2, 3), Vector(0, 0, 0)}
    print(v1 + v3)                # Vector(1, 2, 3)

