"""CaseInsensitiveString wraps a regular string but compares and hashes case‑insensitively.
The original string is preserved for representation, while internal storage uses the lower‑cased form.
"""

class CaseInsensitiveString:
    """Immutable string that ignores case for equality and hashing.

    Parameters
    ----------
    value : str
        The underlying text.
    """

    __slots__ = ("_original", "_lower")

    def __init__(self, value: str) -> None:
        self._original = value
        self._lower = value.lower()

    @property
    def original(self) -> str:
        """Return the string exactly as it was provided."""
        return self._original

    def __repr__(self) -> str:
        return f"CaseInsensitiveString({self._original!r})"

    def __eq__(self, other: object) -> bool:
        if isinstance(other, CaseInsensitiveString):
            return self._lower == other._lower
        if isinstance(other, str):
            return self._lower == other.lower()
        return NotImplemented

    def __hash__(self) -> int:
        # Hash the normalized lower‑case version so that different casings map to the same bucket.
        return hash(self._lower)

# Simple demo
if __name__ == "__main__":
    a = CaseInsensitiveString("Hello")
    b = CaseInsensitiveString("hello")
    c = "HeLLo"
    print(a)                     # CaseInsensitiveString('Hello')
    print(a == b)                # True
    print(a == c)                # True
    d = {a: 1, b: 2}
    print(d)                     # Only one key because a and b are equal

