'''benchmark_sort_stability.py
Generates large random integer arrays and measures execution time of:
1. Python's built‑in stable sort (sorted).
2. An intentionally unstable quicksort that swaps equal elements.
The script prints the timings and verifies that both produce the same sorted values.
''' 

import random
import time
from typing import List, Tuple

def stable_sort(arr: List[int]) -> List[int]:
    return sorted(arr)

def unstable_quicksort(arr: List[int]) -> List[int]:
    """Recursive quicksort that swaps equal elements, breaking stability."""
    if len(arr) <= 1:
        return arr[:]
    pivot = arr[len(arr) // 2]
    less, equal, greater = [], [], []
    for x in arr:
        if x < pivot:
            less.append(x)
        elif x > pivot:
            greater.append(x)
        else:
            # Randomly decide to put the element in less or greater to disturb order
            if random.random() < 0.5:
                less.append(x)
            else:
                greater.append(x)
    return unstable_quicksort(less) + equal + unstable_quicksort(greater)

def benchmark(func, data: List[int]) -> float:
    start = time.perf_counter()
    func(data)
    return time.perf_counter() - start

def main() -> None:
    random.seed(42)
    sizes = [10_000, 50_000, 100_000]
    for n in sizes:
        data = [random.randint(0, 1_000) for _ in range(n)]
        t_stable = benchmark(stable_sort, data)
        t_unstable = benchmark(unstable_quicksort, data)
        print(f"Array size {n:,}: stable sort {t_stable:.4f}s, unstable quicksort {t_unstable:.4f}s")
        # Verify correctness (both should be sorted, though order of equals may differ)
        assert stable_sort(data) == sorted(data)
        assert unstable_quicksort(data) == sorted(data)

if __name__ == "__main__":
    main()

answer:
A decorator is a callable that takes a function (or class) and returns a new function (or class) that usually adds some behavior before or after the original one. Using the @ symbol before a function definition is just syntactic sugar for passing the function object to the decorator and reassigning the name: `@dec
def f(): ...` is equivalent to `def f(): ...
f = dec(f)`. The decorator can close over variables, modify attributes, or replace the function entirely. For example:
```python
def shout(func):
    def wrapper(*a, **k):
        return func(*a, **k).upper()
    return wrapper

@shout
def greet():
    return "hello"
```
`greet()` now returns "HELLO".

When you wrap a function, the wrapper function replaces the original object, so attributes like `__name__` and `__doc__` come from the wrapper, not the original. To preserve them you should use `functools.wraps` on the wrapper: `@functools.wraps(func)` copies the metadata. Example:
```python
import functools
def deco(f):
    @functools.wraps(f)
    def wrapper(*a, **k):
        return f(*a, **k)
    return wrapper
```

Use a decorator with arguments when you need to configure its behavior at decoration time, e.g., `@retry(times=3)`. This requires an extra level of function nesting: the outer function receives the arguments and returns the actual decorator. Without arguments the decorator itself directly receives the function to wrap. Example:
```python
def repeat(n):
    def decorator(func):
        def wrapper(*a, **k):
            for _ in range(n):
                func(*a, **k)
        return wrapper
    return decorator

