"""Dynamic graph class with Dijkstra shortest‑path method.

The Graph object stores a mutable adjacency list.  Vertices can be added
implicitly when edges are inserted.  The method ``dijkstra(source)`` returns a
dictionary of distances and a predecessor mapping, useful for path retrieval.
"""
import heapq
from typing import Dict, List, Tuple, Any

Node = Any
Weight = float
Edge = Tuple[Node, Node, Weight]

class Graph:
    def __init__(self) -> None:
        self.adj: Dict[Node, List[Tuple[Node, Weight]]] = {}

    def add_edge(self, u: Node, v: Node, w: Weight, *, bidirectional: bool = False) -> None:
        """Insert edge *u → v* with weight *w*.
        If *bidirectional* is True, also add *v → u*.
        """
        if w < 0:
            raise ValueError("Dijkstra requires non‑negative weights")
        self.adj.setdefault(u, []).append((v, w))
        if bidirectional:
            self.adj.setdefault(v, []).append((u, w))

    def remove_edge(self, u: Node, v: Node, *, bidirectional: bool = False) -> None:
        """Remove edge *u → v*; optionally also *v → u*.
        Raises KeyError if the edge does not exist.
        """
        self._remove_one(u, v)
        if bidirectional:
            self._remove_one(v, u)

    def _remove_one(self, src: Node, dst: Node) -> None:
        edges = self.adj.get(src)
        if not edges:
            raise KeyError(f"No outgoing edges from {src}")
        for i, (nbr, _) in enumerate(edges):
            if nbr == dst:
                edges.pop(i)
                if not edges:
                    self.adj.pop(src)
                return
        raise KeyError(f"Edge {src}->{dst} not found")

    def dijkstra(self, source: Node) -> Tuple[Dict[Node, Weight], Dict[Node, Node]]:
        """Return distances and predecessor map from *source*.
        Nodes unreachable from *source* are absent from the results.
        """
        dist: Dict[Node, Weight] = {source: 0.0}
        pred: Dict[Node, Node] = {}
        heap: List[Tuple[Weight, Node]] = [(0.0, source)]
        while heap:
            d, u = heapq.heappop(heap)
            if d != dist[u]:
                continue
            for v, w in self.adj.get(u, []):
                nd = d + w
                if v not in dist or nd < dist[v]:
                    dist[v] = nd
                    pred[v] = u
                    heapq.heappush(heap, (nd, v))
        return dist, pred

    def __str__(self) -> str:
        lines = []
        for u, outs in self.adj.items():
            outs_str = ", ".join([f"{v}({w})" for v, w in outs])
            lines.append(f"{u} -> [{outs_str}]")
        return "\n".join(lines)

# Demo when run directly
if __name__ == "__main__":
    g = Graph()
    g.add_edge('A', 'B', 3, bidirectional=True)
    g.add_edge('A', 'C', 1)
    g.add_edge('C', 'B', 1)
    g.add_edge('B', 'D', 2)
    print("Graph adjacency list:\n", g)
    d, p = g.dijkstra('A')
    print("Distances:", d)
    print("Predecessors:", p)

#!/usr/bin/env python3
"""Generate a random weighted directed graph and find the shortest path.

The graph has *n* vertices numbered 0 … n‑1.  For each ordered pair (i, j)
with i != j there is a probability *p* of an edge; its weight is a float in
[1, 10).  Dijkstra is run from 0 to n‑1 and the resulting path (or a message
if unreachable) is printed.
"""
import random
import heapq
import sys

def generate_graph(n: int, p: float = 0.3) -> dict:
    adj = {i: [] for i in range(n)}
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if random.random() < p:
                w = random.uniform(1, 10)
                adj[i].append((j, w))
    return adj

def dijkstra(adj: dict, source: int, target: int):
    dist = {source: 0.0}
    pred = {}
    heap = [(0.0, source)]
    while heap:
        d, u = heapq.heappop(heap)
        if u == target:
            break
        if d != dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if v not in dist or nd < dist[v]:
                dist[v] = nd
                pred[v] = u
                heapq.heappush(heap, (nd, v))
    if target not in dist:
        return None, None
    # reconstruct path
    path = []
    cur = target
    while cur != source:
        path.append(cur)
        cur = pred[cur]
    path.append(source)
    path.reverse()
    return dist[target], path

def main():
    if len(sys.argv) != 2:
        print('Usage: python random_dijkstra.py <num_vertices>')
        sys.exit(1)
    n = int(sys.argv[1])
    random.seed(0)
    graph = generate_graph(n)
    distance, path = dijkstra(graph, 0, n-1)
    if path is None:
        print('No path from 0 to', n-1)
    else:
        print('Shortest distance:', distance)
        print('Path:', path)

if __name__ == '__main__':
    main()

