"""double_hash.py
Hash table using double hashing for collision resolution.
The primary hash function is ``hash(key) % capacity`` and the secondary
hash is ``1 + (hash(key) % (capacity - 1))`` which guarantees a step size
that is co‑prime to the table size when capacity is a power of two.
The script also contains a small demo that inserts several words and
looks them up.
"""

class DoubleHashTable:
    """Open‑addressing hash table with double hashing.

    Attributes
    ----------
    capacity : int
        Size of the internal array; kept as a power of two for simplicity.
    size : int
        Number of stored key‑value pairs.
    """

    _TOMBSTONE = object()

    def __init__(self, capacity: int = 8):
        # Ensure capacity is a power of two for the secondary hash to work well
        if capacity & (capacity - 1) != 0:
            raise ValueError('capacity must be a power of two')
        self.capacity = capacity
        self.size = 0
        self.keys = [None] * capacity
        self.values = [None] * capacity

    # ------------------------------------------------------------------
    def _hash1(self, key):
        return hash(key) % self.capacity

    def _hash2(self, key):
        # Must be non‑zero and less than capacity
        return 1 + (hash(key) % (self.capacity - 1))

    def _probe(self, key):
        h1 = self._hash1(key)
        h2 = self._hash2(key)
        for i in range(self.capacity):
            idx = (h1 + i * h2) % self.capacity
            yield idx

    def insert(self, key, value):
        if self.size / self.capacity > 0.5:
            self._resize(self.capacity * 2)
        for idx in self._probe(key):
            cur_key = self.keys[idx]
            if cur_key is None or cur_key is self._TOMBSTONE:
                self.keys[idx] = key
                self.values[idx] = value
                self.size += 1
                return
            if cur_key == key:
                self.values[idx] = value
                return
        raise RuntimeError('HashTable is full')

    def get(self, key, default=None):
        for idx in self._probe(key):
            cur_key = self.keys[idx]
            if cur_key is None:
                return default
            if cur_key is self._TOMBSTONE:
                continue
            if cur_key == key:
                return self.values[idx]
        return default

    def delete(self, key):
        for idx in self._probe(key):
            cur_key = self.keys[idx]
            if cur_key is None:
                break
            if cur_key == key:
                self.keys[idx] = self._TOMBSTONE
                self.values[idx] = None
                self.size -= 1
                return
        raise KeyError(key)

    # ------------------------------------------------------------------
    def _resize(self, new_capacity):
        old_keys, old_values = self.keys, self.values
        self.capacity = new_capacity
        self.keys = [None] * new_capacity
        self.values = [None] * new_capacity
        self.size = 0
        for k, v in zip(old_keys, old_values):
            if k is not None and k is not self._TOMBSTONE:
                self.insert(k, v)

    def __repr__(self):
        pairs = []
        for k, v in zip(self.keys, self.values):
            if k is not None and k is not self._TOMBSTONE:
                pairs.append(f"{k!r}: {v!r}")
        return '{' + ', '.join(pairs) + '}'

# Demo when run as script
if __name__ == "__main__":
    words = ["apple", "banana", "cherry", "date", "elderberry", "fig", "grape"]
    table = DoubleHashTable()
    for w in words:
