'''call_counter.py

Implements a decorator `count_calls` that stores a mutable dictionary
as a default argument to keep track of invocation counts. The
dictionary lives on the decorator function object, so all wrapped
functions share the same counter unless a separate default is supplied.
The script also shows a safer version that uses `functools.wraps`
and a per‑function counter.
''' 

from functools import wraps

def count_calls(counter={}):
    """Decorator that increments *counter['calls']* each time the wrapped function runs.

    Because `counter` is a mutable default, the same dict is reused for
    every function decorated with `@count_calls` that does not provide its
    own dictionary.
    """
    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            counter['calls'] = counter.get('calls', 0) + 1
            return func(*args, **kwargs)
        wrapper._counter = counter
        return wrapper
    return decorator

def safe_count_calls():
    """Returns a decorator that creates an isolated counter for each function."""
    def decorator(func):
        local_counter = {'calls': 0}
        @wraps(func)
        def wrapper(*args, **kwargs):
            local_counter['calls'] += 1
            return func(*args, **kwargs)
        wrapper._counter = local_counter
        return wrapper
    return decorator

@count_calls()
def foo():
    return 'foo'

@count_calls()
def bar():
    return 'bar'

@safe_count_calls()
def baz():
    return 'baz'

if __name__ == "__main__":
    for _ in range(3):
        foo()
    for _ in range(2):
        bar()
    for _ in range(5):
        baz()
    print('Shared counter after foo/bar:', foo._counter['calls'])
    print('Baz own counter:', baz._counter['calls'])

