'''fib_memo.py
Simple Fibonacci calculator that uses memoization (top‑down dynamic programming).
Run the script with an integer argument to get the nth Fibonacci number.
''' 
import sys
from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n: int) -> int:
    """Return the nth Fibonacci number (0‑indexed).
    The function is memoized so each value is computed only once.
    """
    if n < 0:
        raise ValueError('n must be non‑negative')
    if n in (0, 1):
        return n
    return fib(n - 1) + fib(n - 2)

def main() -> None:
    if len(sys.argv) != 2:
        print('Usage: python fib_memo.py <non‑negative integer>')
        sys.exit(1)
    try:
        n = int(sys.argv[1])
    except ValueError:
        print('Argument must be an integer.')
        sys.exit(1)
    print(f'Fibonacci({n}) = {fib(n)}')

if __name__ == '__main__':
    main()

'''fib_bottomup.py
Provides a FibonacciCache class that computes values with a bottom‑up DP table.
The table is stored as a class attribute, so all instances share the same cache.
''' 
from typing import List

class FibonacciCache:
    """Compute Fibonacci numbers using an iterative DP table.
    The class attribute _table holds all previously computed values.
    """
    _table: List[int] = [0, 1]  # base cases for n=0 and n=1

    @classmethod
    def _extend_table(cls, n: int) -> None:
        """Extend the DP table up to index n (inclusive)."""
        while len(cls._table) <= n:
            cls._table.append(cls._table[-1] + cls._table[-2])

    @classmethod
    def get(cls, n: int) -> int:
        """Return the nth Fibonacci number, extending the cache if needed.
        Raises ValueError for negative n.
        """
        if n < 0:
            raise ValueError('n must be non‑negative')
        cls._extend_table(n)
        return cls._table[n]

    @classmethod
    def sequence(cls, up_to: int) -> List[int]:
        """Return a list of Fibonacci numbers from 0 up to up_to (inclusive)."""
        if up_to < 0:
            raise ValueError('up_to must be non‑negative')
        cls._extend_table(up_to)
        return cls._table[: up_to + 1]

