'''fib_timed.py
Memoized Fibonacci implementation plus a generic timing decorator.
Running the file prints the time taken to compute fib(35) twice – the second call is instantaneous thanks to caching.
''' 
import time
from functools import lru_cache, wraps

def timed(func):
    """Decorator that prints the execution time of *func* each time it is called."""
    @wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        end = time.perf_counter()
        print(f'[{func.__name__}] executed in {end - start:.6f}s')
        return result
    return wrapper

@lru_cache(maxsize=None)
@timed
def fib(n: int) -> int:
    """Return the nth Fibonacci number using recursion with memoization.
    The @timed decorator reports how long each call takes.
    """
    if n < 0:
        raise ValueError('n must be non‑negative')
    if n in (0, 1):
        return n
    return fib(n - 1) + fib(n - 2)

if __name__ == '__main__':
    for n in (35, 35):
        print(f'fib({n}) = {fib(n)}')

import sys, os, time

def load_as_string(path):
    """Read the whole file into one string and return it."""
    with open(path, 'r', encoding='utf-8') as f:
        return f.read()

def load_as_list(path):
    """Read the file and return a list where each element is a line."""
    with open(path, 'r', encoding='utf-8') as f:
        return f.readlines()

def size_in_mb(obj):
    """Approximate memory size of *obj* in megabytes using sys.getsizeof.
    For containers, it adds the size of contained items recursively.
    """
    seen = set()
    def inner(o):
        if id(o) in seen:
            return 0
        seen.add(id(o))
        size = sys.getsizeof(o)
        if isinstance(o, (list, tuple, set, frozenset)):
            size += sum(inner(i) for i in o)
        elif isinstance(o, dict):
            size += sum(inner(k) + inner(v) for k, v in o.items())
        return size
    return inner(obj) / (1024 * 1024)

