import time
from functools import lru_cache

# Recursive function that counts how many times it's called
call_counter = {'total': 0}

def reset_counter():
    call_counter['total'] = 0

def counted_fib(n):
    """Naïve Fibonacci that increments a global counter on each call."""
    call_counter['total'] += 1
    if n < 2:
        return n
    return counted_fib(n - 1) + counted_fib(n - 2)

# Helper to wrap counted_fib with a given cache size
def make_cached_fib(maxsize):
    @lru_cache(maxsize=maxsize)
    def cached(n):
        return counted_fib(n)
    return cached

def benchmark(maxsize, n):
    reset_counter()
    cached_fib = make_cached_fib(maxsize)
    start = time.perf_counter()
    result = cached_fib(n)
    elapsed = time.perf_counter() - start
    hits = cached_fib.cache_info().hits
    misses = cached_fib.cache_info().misses
    return result, elapsed, hits, misses, call_counter['total']

if __name__ == "__main__":
    N = 35
    for size in (0, 10, 50, 200, None):  # None means an unbounded cache
        result, t, hits, misses, calls = benchmark(size, N)
        cache_desc = 'unbounded' if size is None else str(size)
        print(f"Cache size={cache_desc:9} | result={result:2} | time={t:.4f}s | hits={hits:4} | misses={misses:4} | raw_calls={calls}")

