    pass

class DivisionByZeroError(CalcError):
    """Raised when the divisor is zero in a division operation."""
    def __init__(self, dividend):
        self.dividend = dividend
        super().__init__(f"Cannot divide {dividend} by zero")

class InvalidOperatorError(CalcError):
    """Raised when an unknown operator is supplied to `calculate`."""
    def __init__(self, operator):
        self.operator = operator
        super().__init__(f"Invalid operator: '{operator}'")


def calculate(a: float, b: float, op: str) -> float:
    """Perform a basic arithmetic operation.

    Supported operators: '+', '-', '*', '/'.
    Raises the appropriate custom exception on error.
    """
    if op == '+':
        return a + b
    if op == '-':
        return a - b
    if op == '*':
        return a * b
    if op == '/':
        if b == 0:
            raise DivisionByZeroError(a)
        return a / b
    raise InvalidOperatorError(op)

