import os
import sys

def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description='List or delete files.')
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument(
        '--list',
        action='store_true',
        help='List files in the target directory.'
    )
    group.add_argument(
        '--delete',
        metavar='FILE',
        help='Delete the specified file.'
    )
    parser.add_argument(
        '-d', '--directory',
        default='.',
        help='Directory to operate on (default: current directory).'
    )
    return parser

def list_files(dir_path: str) -> None:
    try:
        entries = os.listdir(dir_path)
        for entry in entries:
            print(entry)
    except OSError as e:
        sys.exit(f'Error listing directory: {e}')

def delete_file(dir_path: str, filename: str) -> None:
    target = os.path.join(dir_path, filename)
    if not os.path.isfile(target):
        sys.exit(f'File not found: {target}')
    try:
        os.remove(target)
        print(f'Deleted: {target}')
    except OSError as e:
        sys.exit(f'Failed to delete {target}: {e}')

