#!/usr/bin/env bash
# temp_convert.sh – Simple temperature conversion utilities.
# Usage: ./temp_convert.sh c2f <celsius>   or   ./temp_convert.sh f2c <fahrenheit>

c2f() {
  local c=$1
  # Fahrenheit = (Celsius * 9/5) + 32
  printf "%.2f" "$(echo "($c * 9 / 5) + 32" | bc -l)"
}

f2c() {
  local f=$1
  # Celsius = (Fahrenheit - 32) * 5/9
  printf "%.2f" "$(echo "($f - 32) * 5 / 9" | bc -l)"
}

if [[ $# -ne 2 ]]; then
  echo "Usage: $0 {c2f|f2c} <value>"
  exit 1
fi

mode=$1
value=$2

case $mode in
  c2f) echo "${value}°C = $(c2f "$value")°F" ;;
  f2c) echo "${value}°F = $(f2c "$value")°C" ;;
  *) echo "Invalid mode: $mode"; exit 2 ;;
esac

