set -euo pipefail

if [[ $# -ne 1 ]]; then
  echo "Usage: $0 <file>" >&2
  exit 1
fi

file="$1"

awk '\
  {
    key = $1;
    cnt[key]++;
    sum[key] += $3;
  }
  END {
    printf "%s\tCount\tAvg\n", "Group";
    for (k in cnt) {
      avg = sum[k] / cnt[k];
