    }
  }' "${file}" | sort -k1,1

'''iterative_binary_search.py
A tiny utility that performs an iterative binary search on a sorted list.
It returns the index of the target value or -1 if the value is absent.
'''

from typing import List

def binary_search(arr: List[int], target: int) -> int:
    """Return the index of *target* in *arr* using an iterative binary search.

    *arr* must be sorted in non‑decreasing order. If *target* is not found,
    the function returns -1.
    """
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        mid_val = arr[mid]
        if mid_val == target:
            return mid
        elif mid_val < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def main() -> None:
    sample = [3, 8, 12, 15, 19, 22, 27, 31, 42, 58]
    for value in [15, 7, 58, 0, 31]:
        idx = binary_search(sample, value)
        if idx != -1:
            print(f"{value} found at index {idx}")
        else:
            print(f"{value} not present in the list")

if __name__ == "__main__":
    main()

'''recursive_binary_search.py
Provides a recursive binary search implementation together with a small test suite.
The tests can be run directly via ``python -m unittest recursive_binary_search``.
'''

from typing import List
import unittest

def recursive_binary_search(arr: List[int], target: int, low: int = 0, high: int = None) -> int:
    """Recursively search *arr* for *target*.

    Returns the index of *target* or -1 if not present. ``low`` and ``high`` are
    optional bounds for internal recursion; callers should omit them.
    """
    if high is None:
        high = len(arr) - 1
    if low > high:
        return -1
    mid = (low + high) // 2
    if arr[mid] == target:
        return mid
    elif arr[mid] < target:
        return recursive_binary_search(arr, target, mid + 1, high)
    else:
        return recursive_binary_search(arr, target, low, mid - 1)

class TestRecursiveBinarySearch(unittest.TestCase):
    def setUp(self):
        self.data = [1, 4, 6, 9, 13, 17, 21, 34, 55, 89]

    def test_found(self):
        for idx, val in enumerate(self.data):
            self.assertEqual(recursive_binary_search(self.data, val), idx)

    def test_not_found(self):
        for val in [-5, 0, 2, 20, 100]:
            self.assertEqual(recursive_binary_search(self.data, val), -1)

if __name__ == "__main__":
    unittest.main()

