from contextlib import contextmanager

class DataCorruptionError(Exception):
    """Raised when data read from a source is found to be malformed."""
    pass

@contextmanager
def ignore_data_corruption():
    """Context manager that catches DataCorruptionError and does nothing.

    Example:
        with ignore_data_corruption():
            process()
    """
    try:
        yield
    except DataCorruptionError as exc:
        # Suppress the error – optionally log it.
        print(f"Suppressed: {exc}")
        # No re‑raise, so execution continues.


