        super().__init__(f"Payment of {amount:.2f} exceeds daily limit of {limit:.2f}.")
        self.amount = amount
        self.limit = limit


def validate_payment(amount, balance, account_currency='USD', payment_currency='USD', daily_limit=1000.0):
    """Validate a payment request.

    Checks:
        * amount must be positive.
        * amount must not exceed *daily_limit*.
        * account and payment currencies must match.
        * balance must cover the amount.
    """
    if amount <= 0:
        raise ValueError('Payment amount must be positive')
    if payment_currency != account_currency:
        raise CurrencyMismatchError(account_currency, payment_currency)
    if amount > daily_limit:
        raise PaymentLimitExceededError(amount, daily_limit)
    if balance < amount:
        raise InsufficientFundsError(balance, amount)
    return True


def demo():
    scenarios = [
        (500, 600, 'USD', 'USD'),   # valid
        (1500, 2000, 'USD', 'USD'), # limit exceeded
        (200, 100, 'USD', 'USD'),   # insufficient funds
        (100, 500, 'USD', 'EUR'),   # currency mismatch
    ]
    for amt, bal, acc_cur, pay_cur in scenarios:
        try:
            validate_payment(amt, bal, acc_cur, pay_cur)
        except PaymentError as pe:
            print(f"PaymentError: {pe}")
        else:
            print(f"Payment of {amt} approved.")

if __name__ == '__main__':
    demo()

'''multi_catch_logger.py
Shows catching several custom exceptions together and writing a log entry.
''' 

import logging

logging.basicConfig(
    filename='multi_errors.log',
    level=logging.WARNING,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

class DataLoadError(RuntimeError):
    pass

class DataParseError(RuntimeError):
    pass

class DataSaveError(RuntimeError):
    pass

def load_data(source):
    if source == 'missing':
        raise DataLoadError('Source file not found')
    return "raw data"

def parse_data(raw):
    if raw == 'bad':
        raise DataParseError('Unable to parse data')
    return {"parsed": True}

def save_data(parsed, destination):
    if destination == 'readonly':
        raise DataSaveError('Cannot write to read‑only location')
    return True

def process(source, destination):
    try:
        raw = load_data(source)
        parsed = parse_data(raw)
        save_data(parsed, destination)
    except (DataLoadError, DataParseError, DataSaveError) as exc:
        logging.warning(str(exc))
        print(f"Handled error: {exc}")
    else:
        print('Processing completed successfully')


def demo():
    cases = [
        ('missing', 'out.txt'),
        ('good', 'readonly'),
        ('good', 'out.txt')
    ]
    for src, dst in cases:
        print(f"\nRunning case: source={src}, dest={dst}")
        # For the second case we simulate a bad parse by feeding 'bad' raw data.
        if src == 'good' and dst == 'readonly':
            # Monkey‑patch load_data to return 'bad'
            global load_data
            def load_data(_):
                return 'bad'
        process(src, dst)

if __name__ == '__main__':
    demo()

'''rich_exception.py
Custom exception carrying extra context data and a helper that shows how to read it.
''' 

class QueryExecutionError(RuntimeError):
    """Exception raised when a database query fails.

    Attributes
    ----------
    query : str
        The SQL statement that was executed.
    params : tuple
        Parameters supplied to the query.
    original : Exception | None
        The low‑level exception that triggered the failure.
    """
    def __init__(self, query, params=None, original=None):
        self.query = query
        self.params = params or ()
        self.original = original
        msg = f"Query failed: {query}"
        if params:
            msg += f" with params {params}"
        if original:
            msg += f" (caused by {original.__class__.__name__})"
        super().__init__(msg)


def execute(query, params=None):
    """Pretend to run *query*; raise QueryExecutionError on simulated failure.

    For demonstration, any query containing the word 'FAIL' triggers an error.
    """
    try:
        if 'FAIL' in query.upper():
            raise ValueError('simulated low‑level failure')
        # Simulated successful result
        return {'status': 'ok', 'rows': []}
    except Exception as exc:
        raise QueryExecutionError(query, params, exc) from exc


def demo():
    test_queries = [
        ('SELECT * FROM users', None),
        ('UPDATE accounts SET balance=balance-100 WHERE id=? FAIL', (42,)),
    ]
    for q, p in test_queries:
        try:
            result = execute(q, p)
        except QueryExecutionError as qe:
            print('Caught QueryExecutionError')
            print('Message:', qe)
            print('Query attribute:', qe.query)
            print('Params attribute:', qe.params)
            print('Original exception type:', type(qe.original).__name__)
        else:
            print('Success:', result)

if __name__ == '__main__':
    demo()

'''powerset_generator.py
Generate and display the power set of a user‑provided collection of integers.
The user enters numbers separated by commas; the script prints each subset.
''' 

import itertools


def parse_input(text: str) -> list[int]:
    """Convert a comma‑separated string into a list of unique integers.
    Duplicates are removed while preserving the first occurrence order.
    """
    seen = set()
    result = []
    for part in text.split(','):
        part = part.strip()
        if not part:
            continue
        try:
            num = int(part)
        except ValueError:
            raise ValueError(f"'{part}' is not a valid integer")
        if num not in seen:
            seen.add(num)
            result.append(num)
    return result


def power_set(elements: list[int]):
    """Yield each subset of `elements` as a list.
    The subsets are produced in increasing size order.
    """
    for r in range(len(elements) + 1):
        for combo in itertools.combinations(elements, r):
            yield list(combo)


def main():
    raw = input('Enter integers separated by commas: ')
    try:
        elems = parse_input(raw)
    except ValueError as e:
        print('Error:', e)
        return
    print('\nPower set:')
    for subset in power_set(elems):
        print(subset)


if __name__ == '__main__':
    main()

'''set_utils.py
Utility functions for common set‑related calculations.
All functions operate on Python's built‑in set type and are pure (no I/O).
''' 

from collections import Counter
from itertools import product
from typing import Iterable, Any, Set, Tuple, List


def are_disjoint(a: Set[Any], b: Set[Any]) -> bool:
    """Return True if sets ``a`` and ``b`` share no elements.
    Equivalent to ``a.isdisjoint(b)`` but kept for illustration.
    """
    return a.isdisjoint(b)


def cartesian_product(*sets: Iterable[Any]) -> Set[Tuple[Any, ...]]:
    """Compute the Cartesian product of any number of input iterables.

    Returns a set of tuples, each tuple containing one element from each input.
    """
    if not sets:
        return set()
    # Convert each iterable to a tuple to guarantee hashability of resulting tuples
    converted = [tuple(s) for s in sets]
    return {tuple(p) for p in product(*converted)}


def most_common_across_sets(*sets: Iterable[Any]) -> List[Any]:
    """Find element(s) that appear in the greatest number of the provided sets.

    Returns a list because there can be a tie. Elements are not required to be hashable
    beyond what a normal set needs.
    """
    counter = Counter()
    for s in sets:
        counter.update(set(s))  # update counts per unique element in each set
    if not counter:
        return []
    max_occurrence = max(counter.values())
    return [elem for elem, cnt in counter.items() if cnt == max_occurrence]

# Example usage when run as a script
if __name__ == '__main__':
    A = {1, 2, 3}
    B = {3, 4, 5}
    C = {5, 6}
    print('Disjoint A & C?', are_disjoint(A, C))
    print('Cartesian product of A, B:', cartesian_product(A, B))
    print('Most common element(s) among A, B, C:', most_common_across_sets(A, B, C))

'''defprotect.py
Provides @protect_mutable_defaults decorator.
It replaces any mutable default (list, dict, set) with a fresh object on each call.
Usage::
    @protect_mutable_defaults
    def f(x, cache=[]):
        ...
'''\n\nimport functools\nimport collections.abc\n\n_MUTABLE_TYPES = (list, dict, set)\n\ndef _is_mutable(obj):
    return isinstance(obj, _MUTABLE_TYPES)\n\ndef protect_mutable_defaults(func):
    """Wrap *func* so that mutable defaults are recreated for every invocation.
    The wrapper inspects func.__defaults__ and substitutes a copy when needed.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        defaults = func.__defaults__ or ()
        fresh = []
        for d in defaults:
            if _is_mutable(d):
                fresh.append(d.__class__(d))  # shallow copy of same type
            else:
                fresh.append(d)
        # Build a new positional argument tuple replacing missing defaults
        needed = len(defaults) - len(args)
        if needed > 0:
            args = args + tuple(fresh[-needed:])
        return func(*args, **kwargs)
    return wrapper\n\n@protect_mutable_defaults\ndef collect(value, bag=[]):
    """Append *value* to *bag* and return the list."""
    bag.append(value)
    return bag\n\nif __name__ == '__main__':\n    print(collect(1))  # [1]\n    print(collect(2))  # [2] – no sharing due to decorator\n

'''flask_mutable.py
A minimal Flask application that intentionally uses a mutable default argument
in a view function. Visiting /add/3 repeatedly shows the list growing.
Run with: FLASK_APP=flask_mutable.py flask run
'''

from flask import Flask, jsonify

app = Flask(__name__)

def collector(value, store=[]):
    """Add *value* to the mutable default *store* and return it.
    This mirrors the common pitfall when defaults are evaluated only once.
    """
    store.append(value)
    return store

@app.route('/add/<int:num>')
def add(num):
    current = collector(num)
    return jsonify({'added': num, 'store': current})

@app.route('/reset')
def reset():
    # Demonstrate how to clear the shared list manually
    collector.__defaults__[0].clear()
    return jsonify({'status': 'store cleared'})

if __name__ == '__main__':
    app.run(debug=True)

