'''stable_check_decorator.py
Provides @require_stable which wraps a sorting function.
After the function runs, the wrapper checks that equal keys appear in the
same relative order as the input.  If not, it raises ValueError.
''' 
from typing import Callable, List, Tuple, Any
import functools

def _is_stable(original: List[Any], sorted_seq: List[Any], key: Callable[[Any], Any]) -> bool:
    """Internal helper that returns True if *sorted_seq* preserves order of equal keys.
    It works for any objects as long as *key* extracts a comparable value.
    """
    buckets: dict = {}
    for item in original:
        k = key(item)
        buckets.setdefault(k, []).append(item)
    for item in sorted_seq:
        k = key(item)
        if not buckets[k] or buckets[k][0] is not item:
            return False
        buckets[k].pop(0)
    return True

def require_stable(key: Callable[[Any], Any] = lambda x: x):
    """Decorator that asserts the wrapped sorting function is stable.
    The wrapped function must accept a list and return a new sorted list.
    """
    def decorator(func: Callable[[List[Any]], List[Any]]):
        @functools.wraps(func)
        def wrapper(seq: List[Any]):
            original = list(seq)  # copy for safety
            result = func(seq)
            if not _is_stable(original, result, key):
                raise ValueError(f"Function {func.__name__} produced an unstable ordering")
            return result
        return wrapper
    return decorator

# ------------------------------------------------------------
# Example usage with a deliberately unstable sort
@require_stable(key=lambda x: x[0])
def unstable_sort(pairs: List[Tuple[int, int]]) -> List[Tuple[int, int]]:
    """Sort using a comparator that randomises equal keys (unstable)."""
    from functools import cmp_to_key
    import random
    def cmp(a, b):
        if a[0] < b[0]:
            return -1
        if a[0] > b[0]:
            return 1
        return random.choice([-1, 1])
    return sorted(pairs, key=cmp_to_key(cmp))

if __name__ == '__main__':
    sample = [(2, i) for i in range(5)] + [(1, i) for i in range(5, 10)]
    try:
        unstable_sort(sample)
    except ValueError as e:
        print('Caught expected instability:', e)

'''basic_stack.py
A minimal stack implementation using Python's built‑in list.
Provides push, pop, peek and is_empty methods.
'''

class Stack:
    """A LIFO stack using a Python list internally."""

    def __init__(self):
        self._items = []

    def push(self, item):
        """Add *item* to the top of the stack."""
        self._items.append(item)

    def pop(self):
        """Remove and return the top item. Raises IndexError if empty."""
        if self.is_empty():
            raise IndexError('pop from empty stack')
        return self._items.pop()

    def peek(self):
        """Return the top item without removing it. Returns None if empty."""
        if self.is_empty():
            return None
        return self._items[-1]

    def is_empty(self):
        """True if the stack contains no items."""
        return len(self._items) == 0

    def __len__(self):
        return len(self._items)

    def __repr__(self):
        return f'Stack({self._items})'

# Simple demo when run as a script
if __name__ == '__main__':
    s = Stack()
    for i in range(3):
        s.push(i)
        print(f'Pushed {i}, stack now: {s}')
    print('Peek:', s.peek())
    while not s.is_empty():
        print('Popped', s.pop(), 'stack now:', s)

'''deque_queue.py
Queue implementation based on collections.deque for O(1) enqueue and dequeue.
Includes enqueue, dequeue, front, is_empty, and size methods.
'''

from collections import deque

class Queue:
    """FIFO queue using a deque under the hood."""

    def __init__(self, iterable=None):
        self._data = deque(iterable) if iterable is not None else deque()

    def enqueue(self, item):
        """Add *item* to the back of the queue."""
        self._data.append(item)

    def dequeue(self):
        """Remove and return the front item. Raises IndexError if empty."""
        if self.is_empty():
            raise IndexError('dequeue from empty queue')
        return self._data.popleft()

    def front(self):
        """Return the front item without removing it. Returns None if empty."""
        return self._data[0] if not self.is_empty() else None

    def is_empty(self):
        return not self._data

    def size(self):
        return len(self._data)

    def __repr__(self):
        return f'Queue({list(self._data)})'

if __name__ == '__main__':
    q = Queue([1, 2])
    q.enqueue(3)
    print('After enqueue 3:', q)
    print('Front element:', q.front())
    while not q.is_empty():
        print('Dequeued', q.dequeue(), 'queue now:', q)

'''tree_bfs.py
Combines a simple Stack and Queue implementation with a binary‑tree node class.
The bfs function uses the Queue to traverse the tree level by level.
'''

class Stack:
    def __init__(self):
        self._items = []
    def push(self, x):
        self._items.append(x)
    def pop(self):
        if not self._items:
            raise IndexError('pop from empty stack')
        return self._items.pop()
    def __len__(self):
        return len(self._items)

class Queue:
    def __init__(self):
        self._data = []
    def enqueue(self, x):
        self._data.append(x)
    def dequeue(self):
        if not self._data:
            raise IndexError('dequeue from empty queue')
        return self._data.pop(0)
    def is_empty(self):
        return not self._data

class Node:
    def __init__(self, value, left=None, right=None):
        self.value = value
        self.left = left
        self.right = right

def bfs(root):
    """Return a list of node values visited in breadth‑first order."""
    if root is None:
        return []
    q = Queue()
    order = []
    q.enqueue(root)
    while not q.is_empty():
        node = q.dequeue()
        order.append(node.value)
        if node.left:
            q.enqueue(node.left)
        if node.right:
            q.enqueue(node.right)
    return order

if __name__ == '__main__':
    # Build a small tree:      1
    #                        / \n    #                       2   3
    #                      /   / \n    #                     4   5   6
    tree = Node(1, Node(2, Node(4)), Node(3, Node(5), Node(6)))
    print('BFS traversal:', bfs(tree))

'''printer_priority_queue.py
Simulates a printer job queue where each job has a numeric priority.
Higher numeric value means higher priority; the heapq module provides a min‑heap, so priorities are stored as negative numbers.
'''

import heapq
import itertools

class PrintJob:
    def __init__(self, document, priority):
        self.document = document
        self.priority = priority  # higher number = higher priority
    def __repr__(self):
        return f'PrintJob({self.document!r}, p={self.priority})'

class PrinterQueue:
    def __init__(self):
        self._heap = []
        self._counter = itertools.count()  # tie‑breaker for equal priority

    def add_job(self, job):
        """Insert *job* into the queue respecting its priority."""
        # heapq is a min‑heap; use -priority so larger numbers float to the top
        entry = (-job.priority, next(self._counter), job)
        heapq.heappush(self._heap, entry)

    def next_job(self):
        """Remove and return the highest‑priority job; raises IndexError if empty."""
        if not self._heap:
            raise IndexError('no jobs in queue')
        _, _, job = heapq.heappop(self._heap)
        return job

    def __len__(self):
        return len(self._heap)

    def __repr__(self):
        jobs = [e[2] for e in sorted(self._heap, reverse=True)]
        return f'PrinterQueue({jobs})'

if __name__ == '__main__':
    pq = PrinterQueue()
    pq.add_job(PrintJob('report.pdf', 2))
