'''generic_ds.py
Generic Stack and Queue implementations with type hints.
Includes a small unittest.TestCase at the bottom that can be run via python -m unittest generic_ds.py.
'''

from __future__ import annotations
from typing import Generic, TypeVar, List, Deque
from collections import deque
import unittest

T = TypeVar('T')

class Stack(Generic[T]):
    """A LIFO collection storing items of type *T*."""
    def __init__(self) -> None:
        self._items: List[T] = []

    def push(self, item: T) -> None:
        self._items.append(item)

    def pop(self) -> T:
        if not self._items:
            raise IndexError('pop from empty stack')
        return self._items.pop()

    def peek(self) -> T | None:
        return self._items[-1] if self._items else None

    def __len__(self) -> int:
        return len(self._items)

class Queue(Generic[T]):
    """A FIFO collection storing items of type *T*."""
    def __init__(self) -> None:
        self._data: Deque[T] = deque()

    def enqueue(self, item: T) -> None:
        self._data.append(item)

    def dequeue(self) -> T:
        if not self._data:
            raise IndexError('dequeue from empty queue')
        return self._data.popleft()

    def front(self) -> T | None:
        return self._data[0] if self._data else None

    def __len__(self) -> int:
        return len(self._data)

# ------------------- Unit tests -------------------
class TestGenericDS(unittest.TestCase):
    def test_stack(self) -> None:
        s = Stack[int]()
        s.push(1)
        s.push(2)
        self.assertEqual(s.peek(), 2)
        self.assertEqual(s.pop(), 2)
        self.assertEqual(len(s), 1)
        self.assertEqual(s.pop(), 1)
        with self.assertRaises(IndexError):
            s.pop()

    def test_queue(self) -> None:
        q = Queue[str]()
        q.enqueue('a')
        q.enqueue('b')
        self.assertEqual(q.front(), 'a')
        self.assertEqual(q.dequeue(), 'a')
        self.assertEqual(len(q), 1)
        self.assertEqual(q.dequeue(), 'b')
        with self.assertRaises(IndexError):
            q.dequeue()

if __name__ == '__main__':
    unittest.main()

'''two_stack_queue.py
Implements a queue by using two Stack instances.
enqueue pushes onto the input stack; dequeue moves elements to the output stack when needed.
'''

class Stack:
    def __init__(self):
        self._items = []
    def push(self, x):
        self._items.append(x)
    def pop(self):
        if not self._items:
            raise IndexError('pop from empty stack')
        return self._items.pop()
    def is_empty(self):
        return not self._items

class TwoStackQueue:
    def __init__(self):
        self._in = Stack()
        self._out = Stack()

    def enqueue(self, item):
        self._in.push(item)

    def _transfer(self):
        while not self._in.is_empty():
            self._out.push(self._in.pop())

    def dequeue(self):
        if self._out.is_empty():
            if self._in.is_empty():
                raise IndexError('dequeue from empty queue')
            self._transfer()
        return self._out.pop()

    def __len__(self):
        return len(self._in._items) + len(self._out._items)

if __name__ == '__main__':
    q = TwoStackQueue()
    for i in range(5):
        q.enqueue(i)
        print(f'Enqueued {i}, size={len(q)}')
    while len(q):
        print('Dequeued', q.dequeue(), 'size now', len(q))

