"""date_delta.py – Compute the number of days between today and a given date.

Usage:
  python date_delta.py <date>
  python date_delta.py <date> --past

The date must be in ISO format YYYY‑MM‑DD.
"""
import argparse
import sys
from datetime import datetime, date

def build_parser():
    parser = argparse.ArgumentParser(description="Days until (or since) a date.")
    parser.add_argument("target", help="Target date in YYYY-MM-DD format.")
    parser.add_argument("--past", action="store_true",
                        help="Allow dates in the past; report days since.")
    return parser

def parse_date(s: str) -> date:
    try:
        return datetime.strptime(s, "%Y-%m-%d").date()
    except ValueError:
        sys.exit(f"Error: '{s}' is not a valid YYYY-MM-DD date.")

def main():
    parser = build_parser()
    args = parser.parse_args()
    target = parse_date(args.target)
    today = date.today()
    delta = (target - today).days
    if delta < 0 and not args.past:
        sys.exit("Error: target date is in the past. Use --past to allow this.")
    if delta >= 0:
        print(f"{delta} day(s) until {target}.")
    else:
        print(f"{-delta} day(s) since {target}.")

if __name__ == "__main__":
    main()

'''bfs_graph.py
A lightweight Graph class that supports dynamic edge insertion and BFS‑based queries.
Methods:
    add_edge(u, v)           – insert an undirected edge.
    bfs(start)               – list of nodes in BFS order.
    shortest_path(src, dst) – list of nodes representing the shortest path (fewest edges).
'''
from collections import defaultdict, deque
from typing import List, Dict, Optional

class Graph:
    def __init__(self) -> None:
        self.adj: Dict[str, List[str]] = defaultdict(list)

    def add_edge(self, u: str, v: str) -> None:
        """Add an undirected edge between *u* and *v*.
        Duplicate edges are ignored.
        """
        if v not in self.adj[u]:
            self.adj[u].append(v)
        if u not in self.adj[v]:
            self.adj[v].append(u)

    def bfs(self, start: str) -> List[str]:
        """Return nodes in the order they are visited from *start*.
        Nodes with no adjacency list are treated as isolated.
        """
        visited = {start}
        order = []
        q = deque([start])
        while q:
            node = q.popleft()
            order.append(node)
            for nb in sorted(self.adj[node]):
                if nb not in visited:
                    visited.add(nb)
                    q.append(nb)
        return order

    def shortest_path(self, src: str, dst: str) -> Optional[List[str]]:
        """Return the shortest path (fewest edges) from *src* to *dst*.
        If no path exists, return None.
        """
        if src == dst:
            return [src]
        parent: Dict[str, Optional[str]] = {src: None}
        q = deque([src])
        while q:
            node = q.popleft()
            for nb in self.adj[node]:
                if nb not in parent:
                    parent[nb] = node
                    if nb == dst:
                        # reconstruct path
                        path = [dst]
                        while parent[path[-1]] is not None:
                            path.append(parent[path[-1]])
                        path.reverse()
                        return path
                    q.append(nb)
        return None

# Demonstration when executed directly
if __name__ == "__main__":
    g = Graph()
    edges = [("A", "B"), ("A", "C"), ("B", "D"), ("C", "D"), ("D", "E")]
    for u, v in edges:
        g.add_edge(u, v)
    print("BFS from A:", g.bfs("A"))
    print("Shortest path A→E:", g.shortest_path("A", "E"))

'''bfs_maze_solver.py
Solve a rectangular maze given as a text file of 0s and 1s.
0 – open cell, 1 – wall. The algorithm uses BFS to compute the minimum
number of steps from (0,0) to (rows‑1, cols‑1). Diagonal moves are not allowed.
The program prints the length of the shortest path or reports that no path exists.
'''
import sys
from collections import deque
from typing import List, Tuple

def read_maze(path: str) -> List[List[int]]:
    maze = []
    with open(path) as f:
        for line in f:
            row = [int(ch) for ch in line.strip().split() if ch in '01']
            if row:
                maze.append(row)
    return maze

def bfs_shortest(maze: List[List[int]]) -> int:
    rows, cols = len(maze), len(maze[0])
    if maze[0][0] == 1 or maze[rows-1][cols-1] == 1:
        return -1
    q = deque([((0, 0), 0)])  # ((r,c), distance)
    visited = {(0, 0)}
    directions = [(1,0), (-1,0), (0,1), (0,-1)]
    while q:
        (r, c), d = q.popleft()
        if (r, c) == (rows-1, cols-1):
            return d
        for dr, dc in directions:
            nr, nc = r+dr, c+dc
            if 0 <= nr < rows and 0 <= nc < cols and maze[nr][nc] == 0 and (nr, nc) not in visited:
                visited.add((nr, nc))
                q.append(((nr, nc), d+1))
    return -1

def main():
    if len(sys.argv) != 2:
        print('Usage: python bfs_maze_solver.py <maze_file>')
        sys.exit(1)
    maze = read_maze(sys.argv[1])
    if not maze:
        print('Empty or invalid maze file.')
        sys.exit(1)
    length = bfs_shortest(maze)
    if length == -1:
        print('No path exists from start to goal.')
    else:
        print(f'Shortest path length: {length}')

if __name__ == '__main__':
    main()

