'''prime_pool_demo.py
Calculates prime numbers up to a limit using a thread pool and a process pool.
Shows that CPU‑bound prime testing is limited by the GIL for threads but not for processes.
''' 
import time
import concurrent.futures as cf

LIMIT = 100_000
CHUNK = 10_000

def is_prime(n: int) -> bool:
    if n < 2:
        return False
    if n % 2 == 0:
        return n == 2
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def count_primes(start: int, end: int) -> int:
    """Count primes in the half‑open interval [start, end)."""
    return sum(1 for x in range(start, end) if is_prime(x))

def run_thread_pool():
    ranges = [(i, min(i + CHUNK, LIMIT)) for i in range(2, LIMIT, CHUNK)]
    start = time.perf_counter()
    with cf.ThreadPoolExecutor() as executor:
        results = list(executor.map(lambda r: count_primes(*r), ranges))
    elapsed = time.perf_counter() - start
    return elapsed, sum(results)

def run_process_pool():
    ranges = [(i, min(i + CHUNK, LIMIT)) for i in range(2, LIMIT, CHUNK)]
    start = time.perf_counter()
    with cf.ProcessPoolExecutor() as executor:
        results = list(executor.map(lambda r: count_primes(*r), ranges))
    elapsed = time.perf_counter() - start
    return elapsed, sum(results)

if __name__ == '__main__':
    t_thread, cnt_t = run_thread_pool()
    print(f'Thread pool: {cnt_t} primes found in {t_thread:.2f}s')
    t_proc, cnt_p = run_process_pool()
    print(f'Process pool: {cnt_p} primes found in {t_proc:.2f}s')
    if t_thread > t_proc:
        print('Processes are faster because the GIL blocks parallel CPU execution in threads.')
    else:
        print('Threads performed similarly – the task may have released the GIL unexpectedly.')

