'''linear_probing_hash.py
Open addressing hash table using linear probing.
Supports put, get and remove, and automatically resizes when load > 0.7.
''' 

class LinearProbingHash:
    _DELETED = object()

    def __init__(self, capacity=8):
        self.capacity = capacity
        self.size = 0
        self.slots = [None] * self.capacity

    def _hash(self, key, i):
        return (hash(key) + i) % self.capacity

    def _need_resize(self):
        return self.size / self.capacity > 0.7

    def _resize(self):
        old_slots = self.slots
        self.capacity *= 2
        self.slots = [None] * self.capacity
        self.size = 0
        for entry in old_slots:
            if entry and entry is not self._DELETED:
                self.put(*entry)

    def put(self, key, value):
        if self._need_resize():
            self._resize()
        i = 0
        first_deleted = None
        while True:
            idx = self._hash(key, i)
            slot = self.slots[idx]
            if slot is None:
                target = first_deleted if first_deleted is not None else idx
                self.slots[target] = (key, value)
                self.size += 1
                return
            if slot is self._DELETED:
                if first_deleted is None:
                    first_deleted = idx
            elif slot[0] == key:
                self.slots[idx] = (key, value)
                return
            i += 1

    def get(self, key, default=None):
        i = 0
        while True:
            idx = self._hash(key, i)
            slot = self.slots[idx]
            if slot is None:
                return default
            if slot is not self._DELETED and slot[0] == key:
                return slot[1]
            i += 1

    def remove(self, key):
        i = 0
        while True:
            idx = self._hash(key, i)
            slot = self.slots[idx]
            if slot is None:
                raise KeyError(key)
            if slot is not self._DELETED and slot[0] == key:
                self.slots[idx] = self._DELETED
                self.size -= 1
                return
            i += 1

    def __repr__(self):
        pairs = [f"{k}: {v}" for slot in self.slots if slot and slot is not self._DELETED for k, v in [slot]]
        return "{ " + ", ".join(pairs) + " }"

if __name__ == "__main__":
    h = LinearProbingHash()
    for i in range(20):
        h.put(f'key{i}', i)
    print(h.get('key5'))
    h.remove('key5')
    print('after removal:', h)

'''custom_string_hash.py
A thin wrapper around dict that uses a user‑supplied hash function for string keys.
The custom hash is used only for bucket selection; collisions are still resolved by dict.
''' 

def _default_string_hash(s):
    """Simple hash: sum of Unicode code points modulo a large prime."""
    return sum(ord(ch) for ch in s) % 10000019

class CustomStringHashTable:
    def __init__(self, hash_func=_default_string_hash, bucket_count=256):
        self._hash_func = hash_func
        self._buckets = [{} for _ in range(bucket_count)]
        self._bucket_count = bucket_count

    def _bucket_index(self, key):
        if not isinstance(key, str):
            raise TypeError('CustomStringHashTable only accepts string keys')
        return self._hash_func(key) % self._bucket_count

    def set(self, key, value):
        idx = self._bucket_index(key)
        self._buckets[idx][key] = value

    def get(self, key, default=None):
        idx = self._bucket_index(key)
        return self._buckets[idx].get(key, default)

    def delete(self, key):
        idx = self._bucket_index(key)
        try:
            del self._buckets[idx][key]
        except KeyError:
            raise KeyError(key)

    def __repr__(self):
        items = []
        for bucket in self._buckets:
            for k, v in bucket.items():
                items.append(f"{k}: {v}")
        return "{ " + ", ".join(items) + " }"

# Demo when run directly
if __name__ == "__main__":
    table = CustomStringHashTable()
    table.set('hello', 1)
    table.set('world', 2)
    print('hello ->', table.get('hello'))
    table.delete('hello')
    print('after delete:', table)

'''word_counter.py
Counts occurrences of each word in a given text file using a custom hash table.
Run as: python word_counter.py path/to/file.txt
''' 

import sys
import re

class WordHashTable:
    def __init__(self, size=101):
        self.size = size
        self.buckets = [[] for _ in range(self.size)]

    def _hash(self, word):
        # simple polynomial rolling hash, case‑insensitive
        h = 0
        for ch in word.lower():
            h = (h * 31 + ord(ch)) % self.size
        return h

    def inc(self, word):
        idx = self._hash(word)
        bucket = self.buckets[idx]
        for i, (w, cnt) in enumerate(bucket):
            if w == word:
                bucket[i] = (w, cnt + 1)
                return
        bucket.append((word, 1))

    def items(self):
        for bucket in self.buckets:
            for w, cnt in bucket:
                yield w, cnt

def main(path):
    table = WordHashTable()
    pattern = re.compile(r"\b\w+\b")
    with open(path, encoding='utf-8') as f:
        for line in f:
            for word in pattern.findall(line):
                table.inc(word)
    # sort by frequency descending
    for word, count in sorted(table.items(), key=lambda x: x[1], reverse=True)[:20]:
        print(f"{word}: {count}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print('Usage: python word_counter.py <file>')
        sys.exit(1)
    main(sys.argv[1])

'''generic_hash_table.py
A generic hash table supporting any hashable object as a key.
Includes a small unittest suite runnable via python -m unittest generic_hash_table.
''' 

import unittest

class GenericHashTable:
    def __init__(self, capacity=17):
        self.capacity = capacity
        self.buckets = [[] for _ in range(self.capacity)]
        self.size = 0

    def _index(self, key):
        return hash(key) % self.capacity

    def set(self, key, value):
        idx = self._index(key)
        bucket = self.buckets[idx]
        for i, (k, _) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return
        bucket.append((key, value))
        self.size += 1

    def get(self, key, default=None):
        idx = self._index(key)
        for k, v in self.buckets[idx]:
            if k == key:
                return v
        return default

    def delete(self, key):
        idx = self._index(key)
        bucket = self.buckets[idx]
        for i, (k, _) in enumerate(bucket):
            if k == key:
                del bucket[i]
                self.size -= 1
                return
        raise KeyError(key)

    def __len__(self):
        return self.size

# ------------------- Unit tests -------------------
class TestGenericHashTable(unittest.TestCase):
    def test_basic_operations(self):
        ht = GenericHashTable()
        ht.set('a', 1)
        ht.set('b', 2)
        self.assertEqual(ht.get('a'), 1)
        self.assertEqual(ht.get('b'), 2)
        ht.set('a', 3)
        self.assertEqual(ht.get('a'), 3)
        ht.delete('b')
        self.assertIsNone(ht.get('b'))
        self.assertEqual(len(ht), 1)

    def test_custom_key_object(self):
        class Point:
            def __init__(self, x, y):
                self.x, self.y = x, y
            def __hash__(self):
                return hash((self.x, self.y))
            def __eq__(self, other):
                return isinstance(other, Point) and self.x == other.x and self.y == other.y
        p1 = Point(1, 2)
        p2 = Point(1, 2)
        ht = GenericHashTable()
        ht.set(p1, 'origin')
        self.assertEqual(ht.get(p2), 'origin')
        self.assertEqual(len(ht), 1)

if __name__ == '__main__':
    unittest.main()

'''calc_unittest.py
Simple demonstration of unittest for a Calculator class.
''' 

class Calculator:
    """A very small calculator supporting add, subtract, multiply and divide."""
    def add(self, a, b):
        return a + b

    def subtract(self, a, b):
        return a - b

    def multiply(self, a, b):
        return a * b

    def divide(self, a, b):
        if b == 0:
            raise ZeroDivisionError('division by zero')
        return a / b

