'''memoize_closure.py
A memoization decorator implemented with a closure.
The decorator keeps a private cache dictionary that is shared across all
calls to the wrapped function.
''' 

def memoize(func):
    """Return a wrapped version of *func* that caches results.
    The cache lives in the closure, so each decorated function gets its own
    storage without polluting the global namespace.
    """
    cache = {}

    def wrapper(*args):
        if args in cache:
            return cache[args]
        result = func(*args)
        cache[args] = result
        return result

    return wrapper

@memoize
def fibonacci(n: int) -> int:
    """Return the nth Fibonacci number using a naive recursive algorithm.
    The memoization provided by the decorator makes repeated calls fast.
    """
    if n < 2:
        return n
    return fibonacci(n - 1) + fibonacci(n - 2)

if __name__ == "__main__":
    for i in range(10):
        print(f"fib({i}) = {fibonacci(i)}")

'''rate_limiter.py
A decorator that limits how often a function can be called.
The decorator keeps the timestamp of the last successful call in a
closure and blocks calls that occur before the specified interval.
''' 
import time
from functools import wraps

def rate_limit(seconds: float):
    """Return a decorator that allows a function to be called at most
    once every *seconds*.
    The `last_called` variable lives in the closure of the wrapper.
    """
    def decorator(func):
        last_called = 0.0

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal last_called
            now = time.time()
            if now - last_called < seconds:
                raise RuntimeError(f"Function called too soon; wait {seconds - (now - last_called):.2f}s")
            last_called = now
            return func(*args, **kwargs)
        return wrapper
    return decorator

@rate_limit(2.0)
def greet(name: str):
    """Print a greeting; can only be called every two seconds."""
    print(f"Hello, {name}!")

if __name__ == "__main__":
    try:
        greet('Alice')
        greet('Bob')   # likely too fast
    except RuntimeError as e:
        print('Rate limit:', e)
    time.sleep(2.1)
    greet('Charlie')

'''param_logger.py
Creates a decorator factory ``log_if_name`` that logs a call only if the
wrapped function's name matches a supplied target name. The factory is
built with functools.partial and the inner wrapper uses functools.wraps.
''' 
import functools
import logging

logging.basicConfig(level=logging.INFO, format='%(message)s')

def _log_if_name(target_name: str, func):
    """Actual decorator that logs when func.__name__ equals target_name."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        if func.__name__ == target_name:
            logging.info(f'[LOG] Calling {func.__name__} with {args}, {kwargs}')
        return func(*args, **kwargs)
    return wrapper

# Partial creates a factory that only needs the target name later
log_if_name = functools.partial(_log_if_name)

@log_if_name('process')
def process(x: int) -> int:
    """Simple function that doubles its argument."""
    return x * 2

@log_if_name('ignore')
def add(a: int, b: int) -> int:
    """Adds two numbers; will not be logged because its name differs."""
    return a + b

def main() -> None:
    print('process(5) =', process(5))
    print('add(3,4) =', add(3, 4))

if __name__ == '__main__':
    main()

'''tk_partial_wrap.py
Creates a partially configured tkinter.Button factory using
functools.partial and defines a validator decorator built with
functools.wraps. Running the script opens a small window with two
styled buttons.
''' 
import functools
import tkinter as tk
from tkinter import messagebox

# ---- Partial button creator -------------------------------------------------
def make_button(master, text, command, **kw):
    """Return a tkinter.Button with a common style.
    The style includes a blue background and white foreground.
    """
    return tk.Button(master, text=text, command=command,
                     bg='royalblue', fg='white', activebackground='dodgerblue', **kw)

# Partially bind the master window later; keep style fixed
styled_button = functools.partial(make_button, bg='royalblue', fg='white',
                                 activebackground='dodgerblue')

# ---- Argument‑validation decorator ----------------------------------------
def validate_positive(func):
    """Decorator that ensures all positional arguments are positive numbers.
    Raises ValueError otherwise.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        for i, a in enumerate(args):
            if isinstance(a, (int, float)) and a <= 0:
                raise ValueError(f'Argument {i} must be positive, got {a}')
        return func(*args, **kwargs)
    return wrapper

@validate_positive
def divide(a: float, b: float) -> float:
    """Return a / b, assuming both are positive."""
    return a / b

def main() -> None:
    root = tk.Tk()
    root.title('Partial + Wrap Demo')
    root.geometry('250x120')

    def on_click():
        try:
            result = divide(10, 2)
            messagebox.showinfo('Result', f'10 / 2 = {result}')
        except ValueError as e:
            messagebox.showerror('Error', str(e))

    btn = styled_button(root, text='Compute 10/2', command=on_click)
    btn.pack(pady=20)
    root.mainloop()

if __name__ == '__main__':
