'''factorial_recursive.py
A simple command‑line utility that computes the factorial of a non‑negative integer
using a recursive function with an explicit base case. It validates input and
demonstrates error handling for negative numbers.
'''
import sys

def factorial(n: int) -> int:
    """Return n! recursively.
    The base case is n <= 1, which returns 1. For all other positive integers the
    function returns n * factorial(n‑1).
    """
    if n < 0:
        raise ValueError('factorial is undefined for negative integers')
    if n <= 1:
        return 1
    return n * factorial(n - 1)

def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        print('Usage: python factorial_recursive.py <non‑negative integer>')
        return 1
    try:
        number = int(argv[0])
        result = factorial(number)
    except ValueError as e:
        print(f'Error: {e}')
        return 1
    print(f'{number}! = {result}')
    return 0

if __name__ == '__main__':
    sys.exit(main())

'''fib_memo.py
Recursive Fibonacci calculator that uses a dictionary for memoization.
It includes a base case for n in (0, 1) and provides a simple CLI.
'''
import sys
from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n: int) -> int:
    """Return the nth Fibonacci number.
    Base cases: fib(0) == 0, fib(1) == 1. For n > 1 the function returns
    fib(n‑1) + fib(n‑2). The @lru_cache decorator memoizes results to avoid
    exponential blow‑up.
    """
    if n < 0:
        raise ValueError('n must be non‑negative')
    if n <= 1:
        return n
    return fib(n - 1) + fib(n - 2)

def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if not argv:
        print('Usage: python fib_memo.py <non‑negative integer>')
        return 1
    try:
        n = int(argv[0])
        print(f'Fibonacci({n}) = {fib(n)}')
    except ValueError as e:
        print(f'Error: {e}')
        return 1
    return 0

if __name__ == '__main__':
    sys.exit(main())

'''gcd_recursive.py
Implementation of Euclid's algorithm using recursion.
The base case occurs when the second argument becomes zero; at that point the
first argument is the greatest common divisor.
'''
import sys

def gcd(a: int, b: int) -> int:
    """Return the greatest common divisor of a and b.
    Base case: if b == 0, return abs(a) (the divisor). Otherwise recur with
    (b, a % b).
    """
    if b == 0:
        return abs(a)
    return gcd(b, a % b)

def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if len(argv) != 2:
        print('Usage: python gcd_recursive.py <int1> <int2>')
        return 1
    try:
        x = int(argv[0])
        y = int(argv[1])
        print(f'GCD({x}, {y}) = {gcd(x, y)}')
    except ValueError:
        print('Both arguments must be integers.')
        return 1
    return 0

if __name__ == '__main__':
    sys.exit(main())

'''basic_trie.py
A minimal implementation of a Trie (prefix tree) that supports insertion of words
and exact‑match look‑ups.  The TrieNode class stores child links in a dict and
marks the end of a word with the `is_word` flag.
'''

class TrieNode:
    def __init__(self):
        self.children = {}  # char -> TrieNode
        self.is_word = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        """Insert *word* into the trie.  Non‑alphabetic characters are stored as‑is."""
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_word = True

    def search(self, word: str) -> bool:
        """Return True if *word* was previously inserted, otherwise False."""
        node = self._find_node(word)
        return node.is_word if node else False

    def starts_with(self, prefix: str) -> bool:
        """Return True if any stored word begins with *prefix*."""
        return self._find_node(prefix) is not None

    def _find_node(self, prefix: str):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

if __name__ == "__main__":
    trie = Trie()
    words = ["cat", "car", "dog", "dot"]
    for w in words:
        trie.insert(w)
    print(trie.search("cat"))   # True
    print(trie.search("cab"))   # False
    print(trie.starts_with("do"))  # True

'''prefix_trie.py
Implements a Trie with a method to collect all stored words that start with a
specified prefix.  The `collect` helper performs a depth‑first traversal.
'''

from typing import List

class Node:
    def __init__(self):
        self.children: dict[str, Node] = {}
        self.end: bool = False

class PrefixTrie:
    def __init__(self, words: List[str] = None):
        self.root = Node()
        if words:
            for w in words:
                self.insert(w)

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, Node())
        node.end = True

    def _find(self, prefix: str):
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return None
            node = node.children[ch]
        return node

    def words_with_prefix(self, prefix: str) -> List[str]:
        """Return a list of all words stored that begin with *prefix*."""
        start = self._find(prefix)
        if not start:
            return []
        results: List[str] = []
        self._collect(start, prefix, results)
        return results

    def _collect(self, node: Node, path: str, out: List[str]) -> None:
        if node.end:
            out.append(path)
        for ch, child in node.children.items():
            self._collect(child, path + ch, out)

if __name__ == "__main__":
    sample = ["apple", "app", "application", "apt", "bat", "batch"]
    trie = PrefixTrie(sample)
    print(trie.words_with_prefix("app"))  # ['app', 'apple', 'application']
    print(trie.words_with_prefix("ba"))   # ['bat', 'batch']
    print(trie.words_with_prefix("cat"))  # []

'''radix_trie.py
A compact radix (compressed) trie implementation.  Each edge stores a string
segment instead of a single character, reducing the number of nodes.  The
`autocomplete` function returns up to `limit` completions for a given prefix.
'''

from typing import List, Tuple

class RadixNode:
    def __init__(self, label: str = ""):
        self.label: str = label                # edge label from parent
        self.children: dict[str, 'RadixNode'] = {}
        self.is_word: bool = False

class RadixTrie:
    def __init__(self):
        self.root = RadixNode()

    def insert(self, word: str) -> None:
        node = self.root
        i = 0
        while i < len(word):
            # Find a child whose label shares a prefix with the remaining word
            for child_label, child in node.children.items():
                common = self._common_prefix(word[i:], child_label)
                if common:
                    # split edge if necessary
                    if common != child_label:
                        # create intermediate node
                        remainder = child_label[len(common):]
                        intermediate = RadixNode(common)
                        intermediate.children[remainder] = child
                        intermediate.is_word = child.is_word if remainder == "" else False
                        # adjust parent link
                        node.children[common] = intermediate
                        del node.children[child_label]
                        child = intermediate
                    node = child
                    i += len(common)
                    break
            else:  # no matching child
                # add a new leaf
                leaf = RadixNode(word[i:])
                leaf.is_word = True
                node.children[word[i:]] = leaf
                return
        node.is_word = True

    def _common_prefix(self, a: str, b: str) -> str:
        i = 0
        while i < min(len(a), len(b)) and a[i] == b[i]:
            i += 1
        return a[:i]

    def _search_node(self, prefix: str) -> Tuple[RadixNode, int]:
        node = self.root
        i = 0
        while i < len(prefix):
            for label, child in node.children.items():
                if prefix.startswith(label, i):
                    i += len(label)
                    node = child
                    break
                elif label.startswith(prefix[i:]):
                    # prefix ends in the middle of an edge
                    return child, i + len(prefix[i:])
            else:
                return None, i
        return node, i

    def autocomplete(self, prefix: str, limit: int = 10) -> List[str]:
        """Return up to *limit* words that begin with *prefix* sorted alphabetically."""
        node, consumed = self._search_node(prefix)
        if not node:
            return []
        results: List[str] = []
        self._collect(node, prefix[:consumed], results, limit)
        return sorted(results)[:limit]

    def _collect(self, node: RadixNode, path: str, out: List[str], limit: int) -> None:
        if node.is_word:
            out.append(path)
            if len(out) >= limit:
                return
        for label, child in sorted(node.children.items()):
            if len(out) >= limit:
                break
            self._collect(child, path + label, out, limit)

if __name__ == "__main__":
    words = ["car", "card", "cards", "care", "cat", "cater", "dog", "dot"]
    trie = RadixTrie()
    for w in words:
        trie.insert(w)
    print(trie.autocomplete("car"))   # ['car', 'card', 'cards', 'care']
    print(trie.autocomplete("ca", 3))  # first three suggestions

'''concurrent_trie.py
Thread‑safe Trie implementation using a re‑entrant lock.  The class provides
`insert`, `search`, and `delete` operations that can be called safely from
multiple threads.  Deleting a word only clears the end‑of‑word flag; unused
nodes are pruned lazily.
'''

import threading
from typing import Optional

class _Node:
    __slots__ = ("children", "is_word")
    def __init__(self):
        self.children: dict[str, _Node] = {}
        self.is_word: bool = False

class ConcurrentTrie:
    def __init__(self):
        self._root = _Node()
        self._lock = threading.RLock()  # re‑entrant for nested calls

    def insert(self, word: str) -> None:
        with self._lock:
            node = self._root
            for ch in word:
                node = node.children.setdefault(ch, _Node())
            node.is_word = True

    def search(self, word: str) -> bool:
        with self._lock:
            node = self._find_node(word)
            return bool(node and node.is_word)

    def delete(self, word: str) -> bool:
        """Remove *word* from the trie.  Returns True if the word existed."""
        with self._lock:
            path: list[tuple[_Node, str]] = []
            node = self._root
            for ch in word:
                if ch not in node.children:
                    return False
                path.append((node, ch))
                node = node.children[ch]
            if not node.is_word:
                return False
            node.is_word = False
            # prune unnecessary nodes from bottom up
            for parent, char in reversed(path):
                child = parent.children[char]
                if child.is_word or child.children:
                    break
                del parent.children[char]
            return True

    def _find_node(self, prefix: str) -> Optional[_Node]:
        node = self._root
        for ch in prefix:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

if __name__ == "__main__":
    trie = ConcurrentTrie()
    trie.insert("hello")
    trie.insert("world")
    print(trie.search("hello"))  # True
    print(trie.search("hell"))   # False
    print(trie.delete("hello"))  # True
    print(trie.search("hello"))  # False

'''file_prefix_counter.py
Reads a word list from a file (one word per line) into a Trie and offers
`count_prefix(prefix)` which returns the number of stored words that start
with the given prefix.  The script can be used as a module or run directly.
'''

import sys
from typing import List

class Node:
    __slots__ = ("children", "is_word", "subtree_count")
    def __init__(self):
        self.children: dict[str, Node] = {}
        self.is_word: bool = False
        self.subtree_count: int = 0  # number of words in this subtree

class PrefixCounterTrie:
    def __init__(self):
        self.root = Node()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, Node())
            node.subtree_count += 1
        node.is_word = True

    def count_prefix(self, prefix: str) -> int:
        node = self.root
        for ch in prefix:
            node = node.children.get(ch)
            if node is None:
                return 0
        return node.subtree_count + (1 if node.is_word else 0)

def build_trie_from_file(path: str) -> PrefixCounterTrie:
    trie = PrefixCounterTrie()
    with open(path, encoding="utf-8") as f:
        for line in f:
            word = line.strip()
            if word:
                trie.insert(word)
    return trie

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <wordfile>")
        sys.exit(1)
    trie = build_trie_from_file(sys.argv[1])
    while True:
        pref = input("Enter prefix (or blank to quit): ").strip()
        if not pref:
            break
        print(f"Words with prefix '{pref}': {trie.count_prefix(pref)}")

'''trie_visualizer.py
Builds a simple character Trie and generates a Graphviz DOT description that
can be rendered with `dot -Tpng trie.dot -o trie.png`.  Nodes are labelled with
the character they represent; the root is shown as "ROOT" and final words are
highlighted in bold.
'''

from __future__ import annotations

import itertools
from typing import Dict

class VizNode:
    def __init__(self, char: str = ""):
        self.char: str = char
        self.children: Dict[str, VizNode] = {}
        self.is_word: bool = False

class TrieViz:
    def __init__(self):
        self.root = VizNode()
        self._id_counter = itertools.count()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, VizNode(ch))
        node.is_word = True

    def _dot(self) -> str:
        lines = ["digraph Trie {", "  node [shape=circle];"]
        def recurse(n: VizNode, parent_id: int | None):
            nid = next(self._id_counter)
            label = n.char if n.char else "ROOT"
            style = "[style=filled, fillcolor=lightgray]" if n.is_word else ""
            lines.append(f"  {nid} [label="{label}" {style}];")
            if parent_id is not None:
                lines.append(f"  {parent_id} -> {nid};")
            for child in n.children.values():
                recurse(child, nid)
        recurse(self.root, None)
        lines.append("}")
        return "
".join(lines)

    def get_dot_source(self) -> str:
        """Return the DOT source representing the current trie."""
        return self._dot()

if __name__ == "__main__":
    viz = TrieViz()
    for w in ["cat", "car", "dog", "dot"]:
        viz.insert(w)
    print(viz.get_dot_source())

'''prime_islice.py

Provides a simple infinite prime generator and then uses itertools.islice
to fetch the first *n* primes (default 100). The script prints each prime on
its own line.
''' 

import itertools
from typing import Generator

def _candidate_generator() -> Generator[int, None, None]:
    """Yield an infinite sequence of odd numbers starting at 3.
    The even prime 2 is handled separately.
    """
    n = 3
    while True:
        yield n
        n += 2

def is_prime(num: int) -> bool:
    """Return True if *num* is prime using trial division up to sqrt(num)."""
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    i = 3
    while i * i <= num:
        if num % i == 0:
            return False
        i += 2
    return True

def prime_generator() -> Generator[int, None, None]:
    """Yield an endless stream of prime numbers.
    Starts with 2, then checks each odd candidate.
    """
    yield 2
    for cand in _candidate_generator():
        if is_prime(cand):
            yield cand

def main(limit: int = 100) -> None:
    for p in itertools.islice(prime_generator(), limit):
        print(p)

if __name__ == "__main__":
    main()

"""minheap_demo.py
A tiny interactive demonstration of a min‑heap built on Python's built‑in ``heapq`` module.
It supports insertion, peeking at the smallest element, popping the minimum, and printing the
current heap state.  Run the script and follow the on‑screen menu.
"""

import heapq
import sys


def print_menu() -> None:
    print("\n--- Min‑Heap Demo ---")
    print("1. Insert a number")
    print("2. Peek smallest")
    print("3. Pop smallest")
    print("4. Show heap contents")
    print("5. Exit")


def insert(heap: list[int], value: int) -> None:
    """Push *value* onto *heap* while preserving the heap invariant."""
    heapq.heappush(heap, value)
    print(f"Inserted {value}.")


def peek(heap: list[int]) -> None:
    """Show the smallest element without removing it.  If empty, warn the user."""
    if heap:
        print(f"Smallest element: {heap[0]}")
    else:
        print("Heap is empty.")


def pop_min(heap: list[int]) -> None:
    """Remove and return the smallest element, informing the user of the result."""
    if heap:
        smallest = heapq.heappop(heap)
        print(f"Popped {smallest}.")
    else:
        print("Heap is empty – nothing to pop.")


def show(heap: list[int]) -> None:
    """Display the internal list representation of the heap."""
    print(f"Current heap: {heap}")


def main() -> None:
    heap: list[int] = []
    actions = {
        "1": lambda: insert(heap, int(input("Enter integer to insert: "))),
        "2": lambda: peek(heap),
        "3": lambda: pop_min(heap),
        "4": lambda: show(heap),
    }
    while True:
