'''basic_trie.py
A minimal implementation of a prefix tree (trie) that supports insertion of words and prefix search.
''' 

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end = False

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        """Insert *word* into the trie.

        The method creates new nodes as needed and marks the last node as a word end.
        """
        node = self.root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end = True

    def search(self, word: str) -> bool:
        """Return ``True`` if *word* exists in the trie, ``False`` otherwise."""
        node = self._find_node(word)
        return bool(node) and node.is_end

    def starts_with(self, prefix: str) -> bool:
        """Return ``True`` if there is any word in the trie that starts with *prefix*."""
        return self._find_node(prefix) is not None

    def _find_node(self, key: str):
        node = self.root
        for char in key:
            if char not in node.children:
                return None
            node = node.children[char]
        return node

if __name__ == "__main__":
    trie = Trie()
    for w in ["cat", "car", "dog", "dove"]:
        trie.insert(w)
    print(trie.search("cat"))          # True
    print(trie.search("cow"))          # False
    print(trie.starts_with("do"))      # True
    print(trie.starts_with("ca"))      # True
    print(trie.starts_with("z"))       # False

'''trie_prefix_listing.py
Builds a Trie from a collection of words and provides a method to retrieve all stored words
that share a given prefix.
''' 

from typing import List

class Node:
    __slots__ = ('children', 'is_word')
    def __init__(self):
        self.children = {}
        self.is_word = False

class PrefixTrie:
    def __init__(self, words: List[str] = None):
        self.root = Node()
        if words:
            for w in words:
                self.add(w)

    def add(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, Node())
        node.is_word = True

    def _collect(self, node: Node, prefix: str, out: List[str]) -> None:
        if node.is_word:
            out.append(prefix)
        for ch, child in node.children.items():
            self._collect(child, prefix + ch, out)

    def words_with_prefix(self, prefix: str) -> List[str]:
        """Return a list of all words stored in the trie that start with *prefix*.
        """
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return []
            node = node.children[ch]
        results: List[str] = []
        self._collect(node, prefix, results)
        return results

if __name__ == "__main__":
    sample = ["apple", "app", "application", "apt", "banana", "band", "bandana"]
    trie = PrefixTrie(sample)
    print(trie.words_with_prefix('app'))   # ['app', 'apple', 'application']
    print(trie.words_with_prefix('ban'))   # ['banana', 'band', 'bandana']
    print(trie.words_with_prefix('cat'))   # []

'''trie_with_delete.py
A Trie implementation that supports insertion, search, prefix search, deletion and a small unittest suite.
''' 

from __future__ import annotations
from typing import Dict, List
import unittest

class TrieNode:
    def __init__(self):
        self.children: Dict[str, TrieNode] = {}
        self.is_end: bool = False

class DeletableTrie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, TrieNode())
        node.is_end = True

    def search(self, word: str) -> bool:
        node = self._find(word)
        return bool(node) and node.is_end

    def starts_with(self, prefix: str) -> bool:
        return self._find(prefix) is not None

    def delete(self, word: str) -> bool:
        """Delete *word* from the trie.
        Returns ``True`` if the word existed and was removed, ``False`` otherwise.
        """
        def _delete(node: TrieNode, i: int) -> bool:
            if i == len(word):
                if not node.is_end:
                    return False
                node.is_end = False
                # If leaf, tell caller to prune
                return len(node.children) == 0
            ch = word[i]
            child = node.children.get(ch)
            if not child:
                return False
            should_prune = _delete(child, i + 1)
            if should_prune:
                del node.children[ch]
                return not node.is_end and len(node.children) == 0
            return False
        return _delete(self.root, 0)

    def _find(self, key: str) -> TrieNode | None:
        node = self.root
        for ch in key:
            node = node.children.get(ch)
            if node is None:
                return None
        return node

# ------------------- Unit Tests -------------------
class TestDeletableTrie(unittest.TestCase):
    def setUp(self):
        self.trie = DeletableTrie()
        for w in ["test", "testing", "team", "toast"]:
            self.trie.insert(w)

    def test_search(self):
        self.assertTrue(self.trie.search("test"))
        self.assertFalse(self.trie.search("tes"))

    def test_prefix(self):
        self.assertTrue(self.trie.starts_with("tes"))
        self.assertFalse(self.trie.starts_with("toasx"))

    def test_delete_word(self):
        self.assertTrue(self.trie.delete("testing"))
        self.assertFalse(self.trie.search("testing"))
        # "test" should still exist
        self.assertTrue(self.trie.search("test"))

    def test_delete_nonexistent(self):
        self.assertFalse(self.trie.delete("nonexistent"))

    def test_prune_nodes(self):
        self.trie.delete("toast")
        self.assertIsNone(self.trie._find("toast"))
        # The prefix "to" should no longer exist
        self.assertFalse(self.trie.starts_with("to"))

if __name__ == "__main__":
    unittest.main()

'''trie_visualiser.py
Implements a simple trie and exports its structure to a Graphviz dot file,
then renders it as a PNG if Graphviz is installed.
''' 

from typing import Dict
import subprocess
import os

class Vertex:
    def __init__(self):
        self.children: Dict[str, Vertex] = {}
        self.is_word: bool = False

class VisualTrie:
    def __init__(self):
        self.root = Vertex()
        self._node_id = 0

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.children.setdefault(ch, Vertex())
        node.is_word = True

    def _dot(self) -> str:
        lines = ["digraph Trie {", "node [shape=circle];"]
        def dfs(node: Vertex, name: str):
            for ch, child in node.children.items():
                child_name = f"node{self._node_id}"; self._node_id += 1
                label = f"{ch}" + ("*" if child.is_word else "")
                lines.append(f"{name} -> {child_name} [label=\"{label}\"];")
                dfs(child, child_name)
        dfs(self.root, "root")
        lines.append("}")
        return "\n".join(lines)

    def render(self, out_png: str = "trie.png") -> None:
        dot_src = self._dot()
        dot_path = out_png + ".dot"
        with open(dot_path, "w", encoding="utf-8") as f:
            f.write(dot_src)
        # Use the `dot` command; ignore errors if not installed
        try:
            subprocess.run(["dot", "-Tpng", dot_path, "-o", out_png], check=True)
            print(f"Rendered trie to {out_png}")
        except Exception as e:
            print("Graphviz not available or rendering failed:", e)

if __name__ == "__main__":
    words = ["cat", "car", "cart", "dog", "dot"]
    vt = VisualTrie()
    for w in words:
        vt.insert(w)
    vt.render()
    # Clean up intermediate dot file if desired
    try:
        os.remove("trie.png.dot")
    except OSError:
        pass

'''radix_trie.py
A compact (radix) trie where edges may store strings instead of single characters.
It supports insertion, prefix completion, and exact lookup.
''' 

from typing import Dict, List, Tuple

class RadixNode:
    __slots__ = ('children', 'is_word')
    def __init__(self):
        self.children: Dict[str, RadixNode] = {}
        self.is_word: bool = False

class RadixTrie:
    def __init__(self):
        self.root = RadixNode()

    def insert(self, word: str) -> None:
        node = self.root
        i = 0
        while i < len(word):
            # Find a child whose label shares a prefix with the remaining suffix
            for label, child in list(node.children.items()):
                common = self._common_prefix(label, word[i:])
                if not common:
                    continue
                if common == label:
                    # Full edge match, move deeper
                    i += len(label)
                    node = child
                    break
                # Partial match – need to split edge
                suffix_label = label[len(common):]
                suffix_word = word[i+len(common):]
                # Create intermediate node for common part
                inter = RadixNode()
                node.children[common] = inter
                # Re‑attach existing child
                inter.children[suffix_label] = child
                del node.children[label]
                if suffix_word:
                    inter.children[suffix_word] = RadixNode()
                    inter.children[suffix_word].is_word = True
                else:
                    inter.is_word = True
                return
            else:
                # No matching edge – create new leaf
                node.children[word[i:]] = RadixNode()
                node.children[word[i:]].is_word = True
                return
        node.is_word = True

    def _common_prefix(self, a: str, b: str) -> str:
        i = 0
        while i < min(len(a), len(b)) and a[i] == b[i]:
            i += 1
        return a[:i]

    def search(self, word: str) -> bool:
        node, offset = self._traverse(word)
        return node is not None and offset == len(word) and node.is_word

    def completions(self, prefix: str) -> List[str]:
        node, offset = self._traverse(prefix)
        if node is None:
            return []
        results: List[str] = []
        base = prefix[:offset]
        self._collect(node, base, results)
        return results

    def _traverse(self, key: str) -> Tuple[RadixNode | None, int]:
        node = self.root
        i = 0
        while i < len(key):
            for label, child in node.children.items():
                if key.startswith(label, i):
                    i += len(label)
                    node = child
                    break
                # key may be inside a label
                if label.startswith(key[i:]):
                    i = len(key)
                    return child, i
            else:
                return None, i
        return node, i

    def _collect(self, node: RadixNode, prefix: str, out: List[str]):
        if node.is_word:
            out.append(prefix)
        for label, child in node.children.items():
            self._collect(child, prefix + label, out)

if __name__ == "__main__":
    rt = RadixTrie()
    for w in ["bear", "bell", "bid", "bull", "buy", "sell", "stock", "stop"]:
        rt.insert(w)
    print(rt.completions('b'))   # ['bear', 'bell', 'bid', 'bull', 'buy']
    print(rt.completions('bu'))  # ['bull', 'buy']
    print(rt.search('sell'))    # True
    print(rt.search('sel'))      # False

'''cli_autocomplete.py
Defines a small command‑line interface that offers tab‑completion for sub‑commands
using a Trie. The script demonstrates integration with ``argparse`` and the
``readline`` module (Unix‑like systems).
''' 

import argparse
import sys
import readline
from typing import List

class AutoTrie:
    def __init__(self, words: List[str]):
        self.root = {}
        for w in words:
            self._add(w)

    def _add(self, word: str) -> None:
        node = self.root
        for ch in word:
            node = node.setdefault(ch, {})
        node['_end_'] = True

    def suggestions(self, prefix: str) -> List[str]:
        node = self.root
        for ch in prefix:
            if ch not in node:
                return []
            node = node[ch]
        results: List[str] = []
        self._collect(node, prefix, results)
        return results

    def _collect(self, node, cur: str, out: List[str]):
        if '_end_' in node:
            out.append(cur)
        for ch, child in node.items():
            if ch != '_end_':
                self._collect(child, cur + ch, out)

# ---------- Completion hook for readline ----------

def completer_factory(trie: AutoTrie):
    def completer(text, state):
        # Only complete the first argument (the command)
        if readline.get_begidx() == 0:
            opts = trie.suggestions(text)
            if state < len(opts):
                return opts[state]
        return None
    return completer

# ---------- Main CLI ----------

def main(argv=None):
    commands = ['init', 'install', 'update', 'upgrade', 'uninstall', 'list', 'search']
    trie = AutoTrie(commands)
    readline.set_completer(completer_factory(trie))
    readline.parse_and_bind('tab: complete')

    parser = argparse.ArgumentParser(prog='pkgtool')
    parser.add_argument('command', choices=commands, help='sub‑command to run')
    args = parser.parse_args(argv)
    print(f"Executing {args.command}…")

if __name__ == '__main__':
    main()

'''binary_search_demo.py
Simple demonstration of binary search on a sorted list of integers.
The script defines a recursive binary_search function and runs a few test cases.
''' 

def binary_search(arr, target, low=0, high=None):
    """Return the index of *target* in *arr* using binary search.

    *arr* must be sorted in ascending order. If the target is not present,
    the function returns -1.
    The implementation is recursive for clarity.
    """
    if high is None:
        high = len(arr) - 1
    if low > high:
        return -1
    mid = (low + high) // 2
    if arr[mid] == target:
        return mid
    elif arr[mid] < target:
        return binary_search(arr, target, mid + 1, high)
    else:
        return binary_search(arr, target, low, mid - 1)

if __name__ == "__main__":
    sample = [3, 8, 12, 15, 23, 42, 56, 71, 89]
    tests = [15, 42, 1, 89, 100]
    for t in tests:
        idx = binary_search(sample, t)
        if idx != -1:
            print(f"{t} found at index {idx}.")
        else:
            print(f"{t} not present in the list.")

'''iterative_binary_search.py
Provides an iterative binary search function for reuse.
The function works on any sequence that supports indexing and length.
''' 

def binary_search_iter(arr, target):
    """Iteratively search *target* in a sorted sequence *arr*.

    Returns the index of *target* or -1 if absent. The algorithm runs in O(log n).
    """
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

