    data = list(range(0, 101, 5))  # [0,5,10,...,100]
    for x in [0, 55, 100, 101]:
        print(f"Searching for {x}: index {binary_search_iter(data, x)}")

'''file_binary_search.py
Reads a sorted list of integers from 'numbers.txt' and lets the user query
whether a value exists using binary search. The file must contain one integer per line.
''' 
import sys

def load_numbers(path):
    """Load integers from *path*, sort them, and return the list.
    Empty lines and comments starting with '#' are ignored.
    """
    nums = []
    with open(path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith('#'):
                continue
            try:
                nums.append(int(line))
            except ValueError:
                print(f"Skipping non‑integer line: {line}", file=sys.stderr)
    nums.sort()
    return nums

def binary_search(arr, target):
    low, high = 0, len(arr) - 1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return True
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return False

def interactive_loop(data):
    print("Enter integers to search (blank line to quit).")
    while True:
        try:
            line = input('> ').strip()
        except EOFError:
            break
        if line == '':
            break
        try:
            val = int(line)
        except ValueError:
            print('Please enter a valid integer.')
            continue
        found = binary_search(data, val)
        print(f"{val} {'is' if found else 'is NOT'} present in the file.")

if __name__ == '__main__':
    numbers = load_numbers('numbers.txt')
    if not numbers:
        print('No valid numbers loaded. Exiting.', file=sys.stderr)
        sys.exit(1)
    interactive_loop(numbers)

'''first_occurrence_binary_search.py
Binary search variant that returns the left‑most index of *target* when duplicates exist.
The function is iterative and runs in O(log n).
''' 

def first_occurrence(arr, target):
    """Return the index of the first occurrence of *target* in a sorted list.
    If the target is absent, return -1.
    """
    low, high = 0, len(arr) - 1
    result = -1
    while low <= high:
        mid = (low + high) // 2
        if arr[mid] == target:
            result = mid            # record match and keep searching left side
            high = mid - 1
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return result

if __name__ == '__main__':
