'''tokenise_stopstem.py
Tokenise a list of sentences, drop English stop words, apply Porter stemming and output a JSON array where each element corresponds to the processed tokens of the original sentence.
No external libraries besides the standard library are used – stemming is implemented via nltk's PorterStemmer which is bundled with the script for simplicity.
''' 

import json
import sys
from typing import List

# Minimal stop‑word list – in practice you might load a larger set
_STOP_WORDS = {
    'the', 'and', 'is', 'in', 'it', 'of', 'to', 'a', 'that', 'for', 'on', 'with', 'as', 'by', 'this', 'an', 'be',
}

# Simple whitespace tokenizer that also strips punctuation
_PUNCT = set('.,;:!?"\'()[]{}')

def tokenize(sentence: str) -> List[str]:
    """Return a list of lower‑cased tokens without surrounding punctuation."""
    tokens = []
    for raw in sentence.split():
        token = raw.strip(''.join(_PUNCT)).lower()
        if token:
            tokens.append(token)
    return tokens

# Porter stemmer implementation – lightweight version taken from the nltk source
class PorterStemmer:
    def __init__(self):
        self.vowels = set('aeiou')
    def _cons(self, word, i):
        return word[i] not in self.vowels if i == 0 else word[i] not in self.vowels and not (word[i] == 'y' and self._cons(word, i-1))
    def _measure(self, word):
        m = 0
        i = 0
        length = len(word)
        while i < length:
            while i < length and not self._cons(word, i):
                i += 1
            if i >= length:
                break
            while i < length and self._cons(word, i):
                i += 1
            m += 1
        return m
    def stem(self, word):
        if len(word) <= 2:
            return word
        # Step 1a – simplified
        if word.endswith('sses'):
            word = word[:-2]
        elif word.endswith('ies'):
            word = word[:-2]
        elif word.endswith('ss'):
            pass
        elif word.endswith('s'):
            word = word[:-1]
        # Step 1b – only "ed" and "ing" removal if a vowel is present
        if word.endswith('eed') and self._measure(word[:-3]) > 0:
            word = word[:-1]
        elif any(v in word[:-3] for v in self.vowels) and word.endswith('ed'):
            word = word[:-2]
        elif any(v in word[:-3] for v in self.vowels) and word.endswith('ing'):
            word = word[:-3]
        # Step 1c – replace trailing 'y' with 'i' if there is a vowel before it
        if word.endswith('y') and any(v in word[:-1] for v in self.vowels):
            word = word[:-1] + 'i'
        return word

stemmer = PorterStemmer()

def process_sentences(sentences: List[str]) -> List[List[str]]:
    """Tokenise each sentence, drop stop words and apply stemming.
    Returns a list where each element is the list of processed tokens for the corresponding input sentence.
    """
    result = []
    for sent in sentences:
        tokens = tokenize(sent)
        filtered = [stemmer.stem(tok) for tok in tokens if tok not in _STOP_WORDS]
        result.append(filtered)
    return result

if __name__ == '__main__':
    # Expect a JSON array of sentences on stdin or as a file argument
    if len(sys.argv) == 2:
        with open(sys.argv[1], 'r', encoding='utf-8') as f:
            data = json.load(f)
    else:
        data = json.load(sys.stdin)
    processed = process_sentences(data)
    json.dump(processed, sys.stdout, ensure_ascii=False, indent=2)
    sys.stdout.write('\n')

# fib_cache.py
"""Compute Fibonacci numbers with LRU caching.

Run the module from the command line:
    python fib_cache.py 10
will print the 10th Fibonacci number.
"""
import sys
from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n: int) -> int:
    """Return the nth Fibonacci number (0‑based).
    The function is cached indefinitely, so repeated calls are O(1).
    """
    if n < 0:
        raise ValueError("n must be non‑negative")
    if n in (0, 1):
        return n
    return fib(n - 1) + fib(n - 2)

def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python fib_cache.py <non‑negative integer>")
        sys.exit(1)
    try:
        n = int(sys.argv[1])
    except ValueError:
        print("Argument must be an integer.")
        sys.exit(1)
    print(f"fib({n}) = {fib(n)}")

if __name__ == "__main__":
    main()

# unique_ints.py
"""Read integers from a text file and ensure all values are unique.

Custom exceptions:
* :class:`NonIntegerError` – raised when a line cannot be parsed as an int.
* :class:`DuplicateIntegerError` – raised when a duplicate integer is found.
"""

class NonIntegerError(RuntimeError):
    """Raised when a line in the input file does not contain a valid integer."""
    def __init__(self, line_no, content):
        super().__init__(f"Line {line_no}: '{content.strip()}' is not an integer.")
        self.line_no = line_no
        self.content = content

class DuplicateIntegerError(RuntimeError):
    """Raised when the same integer appears more than once in the file."""
    def __init__(self, value, first_occurrence, second_occurrence):
        super().__init__(
            f"Integer {value} first seen on line {first_occurrence}, "
            f"duplicate on line {second_occurrence}."
        )
        self.value = value
        self.first_occurrence = first_occurrence
        self.second_occurrence = second_occurrence

def load_unique_integers(path):
    """Return a list of unique integers from *path*.

    The function validates each line, raising the custom exceptions defined above.
    """
    seen = {}
    result = []
    with open(path, "r", encoding="utf-8") as f:
        for line_no, raw in enumerate(f, start=1):
            stripped = raw.strip()
            if not stripped:
                continue  # skip empty lines
            try:
                value = int(stripped)
            except ValueError:
                raise NonIntegerError(line_no, raw)
            if value in seen:
                raise DuplicateIntegerError(value, seen[value], line_no)
            seen[value] = line_no
            result.append(value)
    return result

if __name__ == "__main__":
    import sys
    if len(sys.argv) != 2:
        print("Usage: python unique_ints.py <path-to-file>")
        sys.exit(1)
    try:
        ints = load_unique_integers(sys.argv[1])
    except (NonIntegerError, DuplicateIntegerError) as e:
        print(f"Error: {e}")
        sys.exit(2)
    print("All integers loaded successfully:", ints)

