"""Exception hierarchy for a minimal banking simulation.

The module defines:
* :class:`BankError` – base class for all banking‑related errors.
* :class:`AccountNotFoundError` – raised when an account identifier cannot be resolved.
* :class:`InsufficientFundsError` – raised when a withdrawal exceeds the balance.

A demonstration function ``demo_operations`` shows how the exceptions are used.
"""

class BankError(Exception):
    """Base class for all custom banking exceptions."""
    pass

class AccountNotFoundError(BankError):
    """Raised when a requested account does not exist in the system."""
    def __init__(self, account_id):
