"""

import argparse

class ConfigError(RuntimeError):
    """Raised when supplied command‑line options are invalid or contradictory."""
    def __init__(self, message):
        super().__init__(message)
        self.message = message

def build_parser():
    parser = argparse.ArgumentParser(description="Demo config parser.")
    mode_group = parser.add_mutually_exclusive_group(required=True)
    mode_group.add_argument("--fast", action="store_true", help="Run in fast mode.")
    mode_group.add_argument("--slow", action="store_true", help="Run in slow mode.")
    parser.add_argument("--threads", type=int, required=True, help="Number of worker threads (must be >0).")
    return parser

def validate_args(args):
    if args.threads <= 0:
        raise ConfigError(f"--threads must be positive, got {args.threads}.")
    # No further contradictions because argparse already enforced mutual exclusivity
    return {
        "mode": "fast" if args.fast else "slow",
        "threads": args.threads,
    }

if __name__ == "__main__":
    parser = build_parser()
    try:
        parsed = parser.parse_args()
        config = validate_args(parsed)
    except ConfigError as ce:
        parser.error(str(ce))
    else:
        print("Configuration accepted:", config)

