"""Simple mock API client demonstrating a hierarchy of custom exceptions.

* ``APIException`` – common base class.
* ``AuthenticationError`` – raised when credentials are invalid.
* ``RateLimitError`` – raised when the simulated request quota is exceeded.
* ``ServerError`` – generic server‑side failure.

The function ``mock_api_call`` randomly picks a scenario and raises the appropriate
exception, otherwise it returns a success dictionary.
"""

import random

class APIException(Exception):
    """Base class for all mock API errors."""
    pass

class AuthenticationError(APIException):
    """Raised when the provided token is rejected."""
    def __init__(self, token):
        super().__init__(f"Invalid token '{token}'.")
        self.token = token

class RateLimitError(APIException):
    """Raised when the client has exceeded the allowed number of calls."""
    def __init__(self, limit, retry_after):
        super().__init__(f"Rate limit of {limit} requests exceeded. Retry after {retry_after}s.")
        self.limit = limit
        self.retry_after = retry_after

class ServerError(APIException):
    """Raised for generic 5xx‑style failures."""
    def __init__(self, code):
        super().__init__(f"Server responded with error code {code}.")
        self.code = code

def mock_api_call(token: str, endpoint: str):
    """Simulate an API request.

    * If ``token`` is not ``'valid-token'`` an ``AuthenticationError`` is raised.
    * A random choice decides whether a ``RateLimitError`` or ``ServerError`` occurs.
    * On success a dict with ``endpoint`` and ``data`` is returned.
    """
    if token != "valid-token":
        raise AuthenticationError(token)
    # Simulate other failures with weighted probabilities
    outcome = random.choices(
        population=["success", "rate_limit", "server_error"],
        weights=[0.7, 0.2, 0.1],
        k=1,
    )[0]
    if outcome == "rate_limit":
        raise RateLimitError(limit=100, retry_after=30)
    if outcome == "server_error":
        raise ServerError(code=502)
    return {"endpoint": endpoint, "data": "sample payload"}

if __name__ == "__main__":
    try:
        resp = mock_api_call("valid-token", "/status")
    except APIException as exc:
        print(f"API call failed: {exc}")
    else:
