"""wildcard_match.py

A minimal recursive matcher supporting two wildcards:
    *  – matches any (including empty) sequence of characters
    ?  – matches exactly one character
The public function `wildcard_match(text, pattern)` returns a boolean.
"""

def wildcard_match(text: str, pattern: str) -> bool:
    """Return True if *text* matches *pattern* using `*` and `?` wildcards.

    The algorithm processes the pattern from left to right. When a `*` is
    encountered, the function tries all possible consumptions of characters
    (including zero) via recursion. `?` consumes exactly one character. All other
    characters must match literally.
    """
    def helper(t_i: int, p_i: int) -> bool:
        # End of pattern
        if p_i == len(pattern):
            return t_i == len(text)
        # End of text but pattern may still match if remaining chars are all '*'
        if t_i == len(text):
            return all(ch == '*' for ch in pattern[p_i:])
        pat_char = pattern[p_i]
        if pat_char == '*':
            # Try to match zero chars or consume one and stay on '*'
            return helper(t_i, p_i + 1) or helper(t_i + 1, p_i)
        if pat_char == '?':
            return helper(t_i + 1, p_i + 1)
        # Literal character
        if pat_char == text[t_i]:
            return helper(t_i + 1, p_i + 1)
        return False
    return helper(0, 0)

if __name__ == '__main__':
    import argparse
    parser = argparse.ArgumentParser(description='Test wildcard pattern against a string.')
    parser.add_argument('pattern', help='Pattern containing * and ?')
    parser.add_argument('string', help='String to test')
    args = parser.parse_args()
    result = wildcard_match(args.string, args.pattern)
    print('Match' if result else 'No match')

