import os

def stripped_lines(path: str, encoding: str = 'utf-8'):
    """Yield each line from *path* without trailing newline or surrounding whitespace.

    The file is opened lazily and closed automatically when iteration ends.
    """
    if not os.path.isfile(path):
        raise FileNotFoundError(f'File not found: {path}')
    with open(path, 'r', encoding=encoding) as f:
        for raw in f:
            yield raw.strip()


