from functools import lru_cache

@lru_cache(maxsize=None)
def fib(n: int) -> int:
    """Return the n‑th Fibonacci number.
    The recursion stops at n == 0 or n == 1, both of which return 1.
    ````
    >>> [fib(i) for i in range(5)]
    [1, 1, 2, 3, 5]
    ````
