'''copy_visualizer.py

Creates two copies (shallow and deep) of a nested dictionary and draws them as
graphs using ``graphviz``. Nodes represent dictionary keys; edges show nesting.
If a shallow copy shares a sub‑dictionary, the graph re‑uses the same node
identifier, while the deep copy creates distinct nodes. Running the script
produces ``shallow.gv`` and ``deep.gv`` files that can be rendered with Graphviz.
''' 

import copy
from graphviz import Digraph

def build_data():
    """Return a nested dictionary for copying.

    Example structure:
    {
        'root': {
            'level1': {'a': 1, 'b': 2},
            'shared': {'x': 10}
        }
    }
    """
    return {'root': {'level1': {'a': 1, 'b': 2}, 'shared': {'x': 10}}}

def dict_to_graph(d, graph, parent=None, seen=None, prefix=''):
    """Recursively add nodes/edges for dictionary ``d``.

    ``seen`` keeps track of object ids already visualized so that shallow copies
    can point to the same node.
    """
    if seen is None:
        seen = {}
    node_id = f'{prefix}{id(d)}'
    if node_id in seen:
        # Already drawn this dict; just add an edge to the existing node
        if parent:
            graph.edge(parent, node_id)
        return
    seen[node_id] = True
    label = '{' + ', '.join(d.keys()) + '}'
    graph.node(node_id, label)
    if parent:
        graph.edge(parent, node_id)
    for k, v in d.items():
        if isinstance(v, dict):
            dict_to_graph(v, graph, node_id, seen, prefix=prefix)
        else:
            leaf_id = f'{node_id}_{k}'
            graph.node(leaf_id, f'{k}: {v}')
            graph.edge(node_id, leaf_id)

def generate_visualizations():
    original = build_data()
    shallow = copy.copy(original)      # outer dict shallow, inner dicts shared
    deep = copy.deepcopy(original)      # all dicts duplicated

    for name, data in [('shallow', shallow), ('deep', deep)]:
        g = Digraph(comment=f'{name} copy')
        dict_to_graph(data, g)
        g.render(filename=name, format='gv', cleanup=True)
        print(f'Generated {name}.gv')

if __name__ == '__main__':
    generate_visualizations()

