'''singly_linked_list.py
Implementation of a basic singly linked list.
Provides Node, SinglyLinkedList classes with insert, delete, search, and iteration.
'''

class Node:
    """A node in a singly linked list."""
    __slots__ = ("value", "next")

    def __init__(self, value, next=None):
        self.value = value
        self.next = next

    def __repr__(self):
        return f"Node({self.value!r})"

class SinglyLinkedList:
    """Simple singly linked list supporting common operations."""

    def __init__(self):
        self.head = None
        self._size = 0

    def __len__(self):
        return self._size

    def __iter__(self):
        current = self.head
        while current:
            yield current.value
            current = current.next

    def __repr__(self):
        return "SinglyLinkedList([" + ", ".join(repr(v) for v in self) + "] )"

    def insert_front(self, value):
        """Insert a new value at the beginning of the list."""
        self.head = Node(value, self.head)
        self._size += 1

    def insert_back(self, value):
        """Insert a new value at the end of the list."""
        new_node = Node(value)
        if not self.head:
            self.head = new_node
        else:
            cur = self.head
            while cur.next:
                cur = cur.next
            cur.next = new_node
        self._size += 1

    def delete(self, value):
        """Delete the first node containing *value*.
        Returns True if a node was removed, otherwise False.
        """
        prev = None
        cur = self.head
        while cur:
            if cur.value == value:
                if prev is None:
                    self.head = cur.next
                else:
                    prev.next = cur.next
                self._size -= 1
                return True
            prev, cur = cur, cur.next
        return False

    def search(self, value):
        """Return True if *value* exists in the list, else False."""
        for item in self:
            if item == value:
                return True
        return False

