'''generic_linkedlist.py
A generic singly linked list using @dataclass.
Includes recursive list reversal and a utility to build a list from an iterable.
'''

from __future__ import annotations
from dataclasses import dataclass, field
from typing import Any, Iterable, Optional

@dataclass
class ListNode:
    """A node that can hold any value and a reference to the next node."""
    value: Any
    next: Optional[ListNode] = field(default=None, repr=False)

    def __repr__(self) -> str:
        return f"ListNode({self.value!r})"

class GenericLinkedList:
    """Container for a singly linked list of ListNode objects."""

    def __init__(self, iterable: Optional[Iterable[Any]] = None):
        self.head: Optional[ListNode] = None
        if iterable:
            for item in iterable:
                self.append(item)

    def append(self, value: Any) -> None:
        """Append *value* at the end of the list."""
        new_node = ListNode(value)
        if not self.head:
            self.head = new_node
            return
        cur = self.head
        while cur.next:
            cur = cur.next
        cur.next = new_node

    def to_list(self) -> list[Any]:
        """Return a Python list of the stored values."""
        out = []
        cur = self.head
        while cur:
            out.append(cur.value)
            cur = cur.next
        return out

    def reverse_recursive(self) -> None:
        """Reverse the linked list in‑place using recursion.
        After execution, self.head points to the former tail.
        """
        def _rev(node: Optional[ListNode], prev: Optional[ListNode]) -> Optional[ListNode]:
            if not node:
                return prev
            nxt = node.next
            node.next = prev
            return _rev(nxt, node)

        self.head = _rev(self.head, None)

    def __iter__(self):
        cur = self.head
        while cur:
            yield cur.value
            cur = cur.next

    def __repr__(self):
        return f"GenericLinkedList({self.to_list()})"

