'''binary_search_recursive.py
Recursive binary search that works with any list of comparable items.
The `binary_search` function returns the index of `target` or -1 if absent.
A simple test runs when the module is executed.
'''

def binary_search(arr, target, left=0, right=None):
    """Recursively search `target` in `arr` between `left` and `right`.
    If `right` is omitted, the whole list is considered.
    Returns the index of `target` or -1.
    """
    if right is None:
        right = len(arr) - 1
    if left > right:
        return -1
    mid = (left + right) // 2
    mid_val = arr[mid]
    if mid_val == target:
        return mid
    elif mid_val < target:
        return binary_search(arr, target, mid + 1, right)
    else:
        return binary_search(arr, target, left, mid - 1)

if __name__ == "__main__":
    words = ['apple', 'banana', 'cherry', 'date', 'fig', 'grape', 'kiwi']
    for key in ['date', 'orange', 'apple']:
        print(f"{key!r} -> {binary_search(words, key)}")

'''binary_search_file.py
Read a sorted integer list from `data.txt` and allow interactive binary searches.
The file `data.txt` must contain one integer per line, already sorted in ascending order.
Running the script launches a REPL where the user types a number to look up.
'''
import sys

def load_numbers(path):
    """Load integers from a file, one per line, returning a sorted list.
    The function strips whitespace and ignores empty lines.
    """
    with open(path, 'r') as f:
        return [int(line.strip()) for line in f if line.strip()]

def binary_search(arr, target):
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def main():
    if len(sys.argv) != 2:
        print('Usage: python binary_search_file.py data.txt')
        return
    numbers = load_numbers(sys.argv[1])
    print(f'Loaded {len(numbers)} numbers. Type a value to search, or "quit" to exit.')
    while True:
        user = input('search> ').strip()
        if user.lower() in ('quit', 'exit'):
            break
        if not user.isdigit() and not (user.startswith('-') and user[1:].isdigit()):
            print('Please enter a valid integer.')
            continue
        target = int(user)
        idx = binary_search(numbers, target)
        if idx != -1:
            print(f'Found {target} at index {idx}.')
        else:
            print(f'{target} not found.')

if __name__ == '__main__':
    main()

'''point.py
A tiny geometry helper that defines a 2‑D Point class.
The class implements __repr__ for debugging, __eq__ for value comparison,
and __hash__ so Point instances can be used in sets or as dictionary keys.
''' 

from __future__ import annotations
from typing import Any

class Point:
    """Immutable 2‑D point.

    Attributes
    ----------
    x: float
        Horizontal coordinate.
    y: float
        Vertical coordinate.
    """

    __slots__ = ("_x", "_y")

    def __init__(self, x: float, y: float) -> None:
        self._x = float(x)
        self._y = float(y)

    @property
    def x(self) -> float:
        return self._x

    @property
    def y(self) -> float:
        return self._y

    def __repr__(self) -> str:
        return f"Point(x={self.x!r}, y={self.y!r})"

    def __eq__(self, other: Any) -> bool:
        if isinstance(other, Point):
            return (self.x, self.y) == (other.x, other.y)
        return NotImplemented

    def __hash__(self) -> int:
        # Use a tuple of the coordinates; tuples are already hashable.
        return hash((self.x, self.y))

