'''fraction.py
Defines an immutable Fraction type that always stores the fraction in reduced form.
It implements __repr__ for debugging, __eq__ for value comparison, and __hash__ so
fractions can be used as keys in dictionaries or members of sets.
''' 

from __future__ import annotations
from math import gcd
from typing import Any

class Fraction:
    """Immutable rational number stored in lowest terms.

    Parameters
    ----------
    numerator : int
        The top part of the fraction.
    denominator : int, optional
        The bottom part; must be non‑zero. Defaults to 1.
    """

    __slots__ = ("_num", "_den")

    def __init__(self, numerator: int, denominator: int = 1) -> None:
        if denominator == 0:
            raise ZeroDivisionError("Denominator cannot be zero")
        # Normalise sign: denominator always positive
        if denominator < 0:
            numerator, denominator = -numerator, -denominator
        common = gcd(numerator, denominator)
        self._num = numerator // common
        self._den = denominator // common

    @property
    def numerator(self) -> int:
        return self._num

    @property
    def denominator(self) -> int:
        return self._den

    def __repr__(self) -> str:
        return f"Fraction({self.numerator}, {self.denominator})"

    def __eq__(self, other: Any) -> bool:
        if isinstance(other, Fraction):
            return (self.numerator, self.denominator) == (other.numerator, other.denominator)
        return NotImplemented

