from __future__ import annotations
from typing import Any, Tuple

class Matrix:
    """Immutable 2×2 matrix.

    The matrix is represented as:
        [a b]
        [c d]
    """

    __slots__ = ("_a", "_b", "_c", "_d")

    def __init__(self, a: float, b: float, c: float, d: float) -> None:
        self._a = float(a)
        self._b = float(b)
        self._c = float(c)
        self._d = float(d)

