import argparse
import sys

def lines_containing(file_path: str, needle: str) -> list[str]:
    """Return a list of lines from *file_path* that contain *needle*.

    The search is case‑insensitive and the newline character is stripped
    from each returned line.
    """
    matches: list[str] = []
    try:
        with open(file_path, "r", encoding="utf-8") as f:
            for raw in f:
                line = raw.rstrip("\n")
                if needle.lower() in line.lower():
                    matches.append(line)
    except FileNotFoundError:
        sys.stderr.write(f"Error: file '{file_path}' not found.\n")
    return matches

def main() -> None:
    parser = argparse.ArgumentParser(description="Print lines containing a substring.")
    parser.add_argument("file", help="Path to the text file to search.")
    parser.add_argument("substring", help="Substring to look for.")
    args = parser.parse_args()

    for line in lines_containing(args.file, args.substring):
        print(line)

