'''vector2d.py

A minimal 2‑dimensional vector supporting representation, equality with a
tolerance, and hashing. The module also provides deduplicate_vectors which
returns a list with duplicates removed while preserving order.
'''

from __future__ import annotations
import math
from typing import List, Iterable

class Vector2D:
    """Immutable 2‑D vector.

    Equality is based on a small tolerance to avoid floating‑point noise.
    """

    __slots__ = ("_x", "_y")
    _tol = 1e-9

    def __init__(self, x: float, y: float) -> None:
        self._x = float(x)
        self._y = float(y)

    @property
    def x(self) -> float:
        return self._x

    @property
    def y(self) -> float:
        return self._y

    def __repr__(self) -> str:
        return f"Vector2D({self.x!r}, {self.y!r})"

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Vector2D):
            return NotImplemented
        return (abs(self.x - other.x) < self._tol) and (abs(self.y - other.y) < self._tol)

    def __hash__(self) -> int:
        # Round to the tolerance level before hashing.
        return hash((round(self.x, 9), round(self.y, 9)))

    def magnitude(self) -> float:
        return math.hypot(self.x, self.y)

def deduplicate_vectors(seq: Iterable[Vector2D]) -> List[Vector2D]:
    """Return a list of vectors with duplicates removed, preserving first occurrence.

    The function uses a set of seen vectors (leveraging __hash__) to filter.
    """
    seen = set()
    result: List[Vector2D] = []
    for v in seq:
        if v not in seen:
            seen.add(v)
            result.append(v)
    return result

# Simple demo ----------------------------------------------------------
if __name__ == "__main__":
    vectors = [Vector2D(1, 2), Vector2D(1.0, 2.0), Vector2D(0, 0), Vector2D(1e-10, -1e-10)]
    print("Original:", vectors)
    print("Deduped:", deduplicate_vectors(vectors))

'''money_cli.py

Money represents a monetary amount stored as integer cents to avoid
floating‑point rounding issues. The script can be run from the command line
with a decimal string (e.g., 12.34) and prints the Money representation.
'''

from __future__ import annotations
import argparse
from typing import Any

class Money:
    """Immutable monetary value stored in cents.

    The class supports equality, hashing and a helpful __repr__ that shows the
    amount in dollars.cents format.
    """

    __slots__ = ("_cents",)

    def __init__(self, cents: int) -> None:
        if not isinstance(cents, int):
            raise TypeError("cents must be an integer")
        self._cents = cents

    @classmethod
    def from_float(cls, amount: float) -> "Money":
        """Create Money from a float representing dollars.

        The float is multiplied by 100 and rounded to the nearest cent.
        """
        cents = int(round(amount * 100))
        return cls(cents)

    @property
    def cents(self) -> int:
        return self._cents

    def __repr__(self) -> str:
        dollars = self.cents // 100
        cents = abs(self.cents % 100)
        return f"Money(${dollars}.{cents:02d})"

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, Money):
            return NotImplemented
        return self.cents == other.cents

    def __hash__(self) -> int:
        return hash(self.cents)

    def __add__(self, other: "Money") -> "Money":
        if not isinstance(other, Money):
            return NotImplemented
        return Money(self.cents + other.cents)

def _parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description="Convert a decimal amount to Money.")
    parser.add_argument("amount", type=float, help="Amount in dollars, e.g., 12.34")
    return parser.parse_args()

def main() -> None:
    args = _parse_args()
    money = Money.from_float(args.amount)
    print(f"Created: {money}")

if __name__ == "__main__":
    main()

'''vowel_window_counter.py
Count length‑5 substrings that contain exactly two vowels using a sliding window.
''' 

def is_vowel(ch):
    return ch.lower() in {'a', 'e', 'i', 'o', 'u'}


def count_exact_two_vowel_substrings(s, window_len=5):
    """Return how many substrings of length *window_len* contain exactly two vowels.

    The function works for any printable string; non‑alphabetic characters are treated as consonants.
    """
    if window_len <= 0:
        raise ValueError('window_len must be positive')
    if len(s) < window_len:
        return 0
    # Initial vowel count in the first window
    vowel_cnt = sum(is_vowel(ch) for ch in s[:window_len])
    total = 1 if vowel_cnt == 2 else 0
    # Slide the window
    for i in range(window_len, len(s)):
        left_char = s[i - window_len]
        right_char = s[i]
        vowel_cnt += is_vowel(right_char) - is_vowel(left_char)
        if vowel_cnt == 2:
            total += 1
    return total


def _demo():
    test_str = "beautifully crafted code"
    print(f"String: {test_str}")
    print(f"Substrings of length 5 with exactly two vowels: {count_exact_two_vowel_substrings(test_str)}")

if __name__ == "__main__":
    _demo()

'''rate_limiter.py
A decorator that limits a wrapped function to *max_calls* within a *period* (seconds).
It uses a sliding‑window queue of timestamps.
''' 
import time
import collections
import functools

def rate_limit(max_calls, period):
    """Return a decorator that enforces *max_calls* per *period* seconds.

    The implementation stores timestamps of recent calls in a deque. Before each call it
    discards timestamps older than ``time.time() - period`` and raises ``RuntimeError``
    if the limit would be exceeded.
    """
    def decorator(func):
        timestamps = collections.deque()
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            now = time.time()
            # Remove stale entries
            while timestamps and timestamps[0] <= now - period:
                timestamps.popleft()
            if len(timestamps) >= max_calls:
                raise RuntimeError(f"Rate limit exceeded: {max_calls} calls per {period}s")
            timestamps.append(now)
            return func(*args, **kwargs)
        return wrapper
    return decorator

# Example usage
@rate_limit(max_calls=5, period=10)
def my_api_call(x):
    """Dummy function representing an API request."""
    return f"Result for {x}"

