import heapq
from collections import defaultdict
from typing import List, Tuple, Any


def shortest_path_length(edges: List[Tuple[Any, Any, float]], start: Any, goal: Any) -> float:
    """Return the numeric length of the shortest path from *start* to *goal*.

    *edges* is a list of ``(u, v, w)`` tuples representing a directed weighted
    graph.  If *goal* is unreachable, ``float('inf')`` is returned.
    """
    # Build adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))
        # ensure the destination appears as a key
        graph.setdefault(v, [])
    if start not in graph or goal not in graph:
        return float('inf')
    dist = {node: float('inf') for node in graph}
    dist[start] = 0.0
    heap = [(0.0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if u == goal:
            return d
        if d != dist[u]:
            continue
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(heap, (nd, v))
    return float('inf')

# Example usage
