    edge_list = [
        ('A', 'B', 3), ('A', 'C', 1),
        ('C', 'B', 1), ('B', 'D', 2),
        ('C', 'D', 4)
    ]
    print(shortest_path_length(edge_list, 'A', 'D'))  # prints 4.0

import json
import heapq
import sys
from typing import Dict, List, Tuple, Any


def load_json_graph(path: str) -> Dict[Any, List[Tuple[Any, float]]]:
    """Load a graph stored as JSON.
    Expected format: {"nodes": ["A", "B"], "edges": [{"src": "A", "dst": "B", "w": 2.5}, ...]}
    Returns an adjacency list mapping each node to a list of (neighbor, weight).
    """
    with open(path, 'r') as f:
        data = json.load(f)
    graph: Dict[Any, List[Tuple[Any, float]]] = {n: [] for n in data.get('nodes', [])}
    for e in data.get('edges', []):
        src, dst, w = e['src'], e['dst'], float(e['w'])
        graph.setdefault(src, []).append((dst, w))
        graph.setdefault(dst, [])  # ensure destination exists
    return graph


def dijkstra_tree(graph: Dict[Any, List[Tuple[Any, float]]], root: Any) -> Tuple[Dict[Any, float], Dict[Any, Any]]:
    """Return distance and predecessor maps representing the shortest‑path tree from *root*."""
    if root not in graph:
        raise KeyError(f'Root node {root!r} not in graph')
    dist = {n: float('inf') for n in graph}
    prev = {n: None for n in graph}
    dist[root] = 0.0
    heap = [(0.0, root)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        for v, w in graph[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))
    return dist, prev


def print_tree(dist: Dict[Any, float], prev: Dict[Any, Any], root: Any):
    print(f'Shortest‑path tree rooted at {root}:')
    for node in sorted(dist):
        if node == root:
            print(f'  {node}: distance 0 (root)')
        elif dist[node] == float('inf'):
            print(f'  {node}: unreachable')
        else:
            # build path by walking predecessors
            path = []
            cur = node
            while cur is not None:
                path.append(cur)
                cur = prev[cur]
            path.reverse()
            print(f'  {node}: distance {dist[node]:.2f}, path: {' -> '.join(map(str, path))}')


def main(argv=None):
    if argv is None:
        argv = sys.argv[1:]
    if len(argv) != 2:
        print('Usage: python json_dijkstra.py <graph.json> <root>')
        sys.exit(1)
    graph_path, root = argv
    graph = load_json_graph(graph_path)
    dist, prev = dijkstra_tree(graph, root)
    print_tree(dist, prev, root)

if __name__ == '__main__':
    main()

