# Implements a memoized Fibonacci calculator using a closure.
# The outer function builds a cache dictionary that the inner
# recursive function closes over.  This approach avoids global state
# and keeps the cache private to each generated Fibonacci function.

def make_fib():
    """Return a Fibonacci function with its own memoization cache.

    The returned `fib` function computes `fib(n)` using recursion while
    storing previously computed results in the `cache` dictionary.
    """
    cache = {0: 0, 1: 1}

    def fib(n: int) -> int:
        if n < 0:
            raise ValueError('n must be non‑negative')
        if n not in cache:
            cache[n] = fib(n - 1) + fib(n - 2)
        return cache[n]

    return fib

