# A lightweight logger built with a closure. The outer factory function
# creates a `log` callable that captures the current log level and a
# prefix. The level can be changed at runtime via the `set_level`
# method attached to the callable.

LEVELS = {'debug': 10, 'info': 20, 'warning': 30, 'error': 40}

def make_logger(name: str, level: str = 'info'):
    """Return a logger function that respects a mutable log level.

    The returned object behaves like a function: `logger(msg, lvl='info')`.
    It also has an attribute `set_level(new_level)` to adjust the threshold.
    """
    if level not in LEVELS:
        raise ValueError('Invalid initial level')
    current_level = LEVELS[level]

    def logger(msg: str, lvl: str = 'info'):
        nonlocal current_level
        if lvl not in LEVELS:
            raise ValueError('Invalid message level')
        if LEVELS[lvl] >= current_level:
            print(f'[{lvl.upper()}] {name}: {msg}')
    # attach a helper to modify the level
    def set_level(new_level: str):
        nonlocal current_level
        if new_level not in LEVELS:
            raise ValueError('Invalid level')
        current_level = LEVELS[new_level]
    logger.set_level = set_level
    return logger

if __name__ == '__main__':
