import unittest
from typing import List, TypeVar

T = TypeVar('T')

def binary_search_recursive(seq: List[T], target: T, left: int = 0, right: int = None) -> int:
    """Recursively search for *target* in *seq*.
    Returns the index if found, otherwise -1.
    The initial call can omit *left* and *right*.
    """
    if right is None:
        right = len(seq) - 1
    if left > right:
        return -1
    mid = (left + right) // 2
    if seq[mid] == target:
        return mid
    elif seq[mid] < target:
        return binary_search_recursive(seq, target, mid + 1, right)
    else:
        return binary_search_recursive(seq, target, left, mid - 1)

class TestBinarySearchRecursive(unittest.TestCase):
    def setUp(self):
        self.data = [1, 4, 5, 8, 12, 20, 33]

    def test_found(self):
        for idx, val in enumerate(self.data):
            self.assertEqual(binary_search_recursive(self.data, val), idx)

    def test_not_found(self):
        self.assertEqual(binary_search_recursive(self.data, 0), -1)
        self.assertEqual(binary_search_recursive(self.data, 13), -1)
        self.assertEqual(binary_search_recursive(self.data, 100), -1)

    def test_empty(self):
        self.assertEqual(binary_search_recursive([], 5), -1)

