    unittest.main()

"""binary_search_class.py
A small library that encapsulates binary search in a class.
It tracks how many element comparisons are performed for each search.
"""
from typing import Generic, List, TypeVar

T = TypeVar('T')

class BinarySearchArray(Generic[T]):
    """Wrap a sorted list and expose iterative & recursive binary search.
    The *comparisons* attribute records the number of element comparisons
    performed during the most recent search.
    """

    def __init__(self, data: List[T]):
        if not all(data[i] <= data[i+1] for i in range(len(data)-1)):
            raise ValueError("Data must be sorted in non‑decreasing order.")
        self.data = data
        self.comparisons = 0

    def _reset_counter(self):
        self.comparisons = 0

    def iterative_search(self, target: T) -> int:
        """Iterative binary search returning index or -1.
        After the call, *self.comparisons* holds the comparison count.
        """
        self._reset_counter()
        left, right = 0, len(self.data) - 1
        while left <= right:
            mid = (left + right) // 2
            self.comparisons += 1
            if self.data[mid] == target:
                return mid
            elif self.data[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return -1

    def recursive_search(self, target: T) -> int:
        """Recursive binary search (wrapper)."""
        self._reset_counter()
        return self._recursive_helper(target, 0, len(self.data) - 1)

    def _recursive_helper(self, target: T, left: int, right: int) -> int:
        if left > right:
            return -1
        mid = (left + right) // 2
        self.comparisons += 1
        if self.data[mid] == target:
            return mid
        elif self.data[mid] < target:
            return self._recursive_helper(target, mid + 1, right)
        else:
            return self._recursive_helper(target, left, mid - 1)

if __name__ == "__main__":
    arr = BinarySearchArray([1, 4, 7, 9, 15, 20, 31])
    print("Iterative search for 15 ->", arr.iterative_search(15), "comparisons:", arr.comparisons)
    print("Recursive search for 2  ->", arr.recursive_search(2),  "comparisons:", arr.comparisons)

