import os

def file_line_count(path: str) -> int:
    """Return the number of lines in *path* by iterating once.
    This is needed to establish the search bounds.
    """
    with open(path, "rb") as f:
        return sum(1 for _ in f)

def read_id_at(path: str, line_no: int) -> int:
    """Seek to *line_no* (0‑based) and return the integer ID on that line.
    Assumes each line ends with a newline character.
    """
    with open(path, "rb") as f:
        # Move forward line_no times
        for _ in range(line_no):
            f.readline()
        line = f.readline()
        return int(line.strip())

def binary_search_csv(path: str, target: int) -> int:
    """Binary search for *target* in a sorted CSV file.
    Returns the 0‑based line number if found, otherwise -1.
    """
    total = file_line_count(path)
    left, right = 0, total - 1
    while left <= right:
        mid = (left + right) // 2
        mid_val = read_id_at(path, mid)
        if mid_val == target:
            return mid
        elif mid_val < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1

