"""Generate a random directed graph and list reachable vertices via DFS.

The script uses the `random` module to create *n* vertices (named 0..n‑1) and
adds a directed edge from each vertex to a random subset of other vertices with
probability *p*.  The user supplies *n*, *p*, and the source vertex on the
command line.  The reachable set is printed one vertex per line.
"""

import sys
import random
from typing import Dict, List, Set


def generate_random_digraph(n: int, p: float) -> Dict[int, List[int]]:
    """Return an adjacency list for a random digraph with *n* vertices.

    For every ordered pair (i, j) where i != j, an edge i→j is added with
    probability *p*.
    """
    adj: Dict[int, List[int]] = {i: [] for i in range(n)}
    for i in range(n):
        for j in range(n):
            if i == j:
                continue
            if random.random() < p:
                adj[i].append(j)
    return adj


def dfs_reachable(source: int, adj: Dict[int, List[int]]) -> Set[int]:
    """Return the set of vertices reachable from *source* using depth‑first search."""
    visited: Set[int] = set()

    def _dfs(v: int) -> None:
        visited.add(v)
        for w in adj.get(v, []):
            if w not in visited:
                _dfs(w)

    if source not in adj:
        raise KeyError(f"Source vertex {source} not present in graph")
    _dfs(source)
    return visited


def main() -> None:
    if len(sys.argv) != 4:
        sys.stderr.write("Usage: python random_dfs_reachable.py <n> <p> <source>\n")
        sys.exit(1)
    n = int(sys.argv[1])
    p = float(sys.argv[2])
    source = int(sys.argv[3])
    if not (0 <= source < n):
        sys.stderr.write("Source must be between 0 and n-1\n")
        sys.exit(1)
    random.seed(0)  # deterministic for example runs
    graph = generate_random_digraph(n, p)
    reachable = dfs_reachable(source, graph)
    for v in sorted(reachable):
        print(v)


if __name__ == "__main__":
    main()

