import datetime as _dt
import sys as _sys
from typing import Callable

class Logger:
    """Simple console logger supporting custom f‑string templates.

    Example template: "{time} - {level:<8} - {msg}".
    """
    def __init__(self, template: str = "{time} | {level:<8} | {msg}") -> None:
        self.template = template
        self._level_funcs = {
            'DEBUG': self.debug,
            'INFO': self.info,
            'WARNING': self.warning,
            'ERROR': self.error,
        }

    def _now(self) -> str:
        return _dt.datetime.now().strftime('%Y-%m-%d %H:%M:%S')

    def _log(self, level: str, message: str) -> None:
        formatted = self.template.format(time=self._now(), level=level, msg=message)
        print(formatted, file=_sys.stderr if level == 'ERROR' else _sys.stdout)

    def debug(self, msg: str) -> None: self._log('DEBUG', msg)
    def info(self, msg: str) -> None: self._log('INFO', msg)
    def warning(self, msg: str) -> None: self._log('WARNING', msg)
    def error(self, msg: str) -> None: self._log('ERROR', msg)

    def log(self, level: str, msg: str) -> None:
        """Log *msg* using *level* if the level exists; otherwise fall back to INFO."""
        func: Callable[[str], None] = self._level_funcs.get(level.upper(), self.info)
        func(msg)

def _demo() -> None:
    logger = Logger(template="{time} - {level:<7} -> {msg}")
    logger.debug('Debugging start')
    logger.info('Application initialized')
    logger.warning('Low disk space')
    logger.error('Unable to open config file')
    # Using generic log method
    logger.log('info', 'Generic log call')
    logger.log('unknown', 'Falls back to INFO')

if __name__ == '__main__':
