'''call_counter.py
Implements a class‑based decorator CallCounter.
Each wrapped function gets an attribute .calls that tracks the number of
executions across the lifetime of the program.
''' 
import functools

class CallCounter:
    """Class‑based decorator that increments a counter each time the function runs.
    The counter is stored on the wrapper as the attribute ``calls``.
    """
    def __init__(self, func):
        functools.update_wrapper(self, func)
        self.func = func
        self.calls = 0

    def __call__(self, *args, **kwargs):
        self.calls += 1
        return self.func(*args, **kwargs)

# Example usage
@CallCounter
def greet(name):
    """Return a friendly greeting."""
    return f"Hello, {name}!"

if __name__ == "__main__":
    for person in ["Alice", "Bob", "Charlie"]:
        print(greet(person))
        print(f"Called {greet.calls} time(s) so far")

'''memo_fib.py
A minimal memoization decorator and a recursive Fibonacci implementation.
The decorator caches results in a dictionary keyed by the function arguments.
''' 
import functools

def memoize(func):
    """Simple memoization decorator using a dict as a cache.
    It works for functions with hashable positional arguments only.
    """
    cache = {}
    @functools.wraps(func)
    def wrapper(*args):
        if args in cache:
            return cache[args]
        result = func(*args)
        cache[args] = result
        return result
    return wrapper

@memoize
def fib(n):
    """Return the n‑th Fibonacci number using recursion.
    The memoize decorator makes this O(n) instead of exponential.
    """
    if n < 2:
        return n
    return fib(n-1) + fib(n-2)

if __name__ == "__main__":
    for i in range(15):
        print(f"fib({i}) = {fib(i)}")

'''validate_positive.py
A decorator that checks all positional arguments are positive integers.
If a check fails, a ValueError is raised with a helpful message.
''' 
import functools

def require_positive_ints(func):
    """Validate that every positional argument passed to *func* is a positive integer.
    Keyword arguments are ignored for simplicity.
    """
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        for idx, arg in enumerate(args, start=1):
            if not isinstance(arg, int) or arg <= 0:
                raise ValueError(
                    f"Argument {idx} to {func.__name__} must be a positive integer, got {arg!r}"
                )
        return func(*args, **kwargs)
    return wrapper

@require_positive_ints
def multiply(a, b):
    """Return the product of two positive integers."""
    return a * b

