'''stacked_decorators.py
Demonstrates three composable decorators:
- @log_calls  – prints function entry and exit.
- @timed      – reports execution time in ms.
- @retry      – re‑executes the function up to *tries* times on exception.
The decorators are applied in a stack to a sample flaky function.
''' 
import functools
import time
import datetime
import random

def log_calls(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f"CALL: {func.__name__}{args}{kwargs}")
        result = func(*args, **kwargs)
        print(f"RETURN: {func.__name__} -> {result!r}")
        return result
    return wrapper

def timed(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = (time.perf_counter() - start) * 1000
        ts = datetime.datetime.now().strftime('%H:%M:%S')
        print(f"[{ts}] {func.__name__} took {elapsed:.2f} ms")
        return result
    return wrapper

def retry(tries=3, delay=0.1):
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            last_exc = None
            for attempt in range(1, tries + 1):
                try:
                    return func(*args, **kwargs)
                except Exception as exc:
                    last_exc = exc
                    print(f"Attempt {attempt} failed: {exc}")
                    time.sleep(delay)
            raise last_exc
        return wrapper
    return decorator

@retry(tries=5, delay=0.2)
@timed
@log_calls
def flaky_divide(a, b):
    """Divide *a* by *b* but randomly raise ZeroDivisionError to simulate flakiness."""
    if random.random() < 0.4:
        raise ZeroDivisionError("Simulated random failure")
    return a / b

if __name__ == "__main__":
    print('Result:', flaky_divide(10, 2))

"""circular_buffer.py
Implements a fixed‑size circular buffer with O(1) appends and a method
`tail(k)` that returns the last *k* items using slice syntax with a negative start.
"""

from collections import deque
from typing import List, Any

class CircularBuffer:
    """A circular buffer of a predetermined capacity.

    The internal storage is a `deque` with `maxlen` set to *capacity*.
    ``tail(k)`` returns a list of the last *k* elements by slicing the
    underlying tuple representation using a negative start index.
    """

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._data: deque = deque(maxlen=capacity)

    def append(self, item: Any) -> None:
        """Add *item* to the buffer, overwriting the oldest value if full."""
        self._data.append(item)

    def tail(self, k: int) -> List[Any]:
        """Return the last *k* elements as a list.

        If *k* exceeds the current number of stored items, all items are returned.
        The slice uses a negative start index (`-k`) to illustrate negative indexing.
        """
        if k <= 0:
            return []
        # Convert deque to a tuple for slicing; this is O(n) but fine for demo.
        as_tuple = tuple(self._data)
        start = -k if k <= len(as_tuple) else None
        return list(as_tuple[start:])

    def __len__(self) -> int:
        return len(self._data)

    def __repr__(self) -> str:
        return f"CircularBuffer(capacity={self._capacity}, data={list(self._data)})"

if __name__ == "__main__":
    buf = CircularBuffer(5)
    for i in range(8):
        buf.append(i)
        print(buf, "tail(3)=", buf.tail(3))

'''temperature.py
A tiny example illustrating the use of a property and a custom descriptor.
The Temperature class stores a value internally in Celsius and exposes both
Celsius and Fahrenheit attributes.  The Fahrenheit attribute is implemented
with a descriptor that performs the conversion on the fly.
''' 

class FahrenheitDescriptor:
    """Descriptor that maps Fahrenheit access to the underlying Celsius value.

    The descriptor expects the owning instance to have a ``_celsius`` attribute.
    Reading ``instance.fahrenheit`` returns the value converted to Fahrenheit.
    Setting ``instance.fahrenheit`` updates ``_celsius`` accordingly.
    """
    def __get__(self, instance, owner):
        if instance is None:
            return self
        return instance._celsius * 9 / 5 + 32

    def __set__(self, instance, value):
        instance._celsius = (value - 32) * 5 / 9

    def __delete__(self, instance):
        raise AttributeError("cannot delete Fahrenheit attribute")


class Temperature:
    """Container for a temperature value stored in Celsius.

    ``celsius`` is a regular property that validates the input, while
    ``fahrenheit`` is a descriptor defined above.
    """
    fahrenheit = FahrenheitDescriptor()

    def __init__(self, celsius=0.0):
        self._celsius = float(celsius)

    @property
    def celsius(self):
        """Return the temperature in Celsius."""
        return self._celsius

    @celsius.setter
    def celsius(self, value):
        if not isinstance(value, (int, float)):
            raise TypeError("Celsius must be a number")
        self._celsius = float(value)

    @celsius.deleter
    def celsius(self):
        raise AttributeError("cannot delete celsius attribute")

    def __repr__(self):
        return f"Temperature(celsius={self._celsius!r})"

# Simple demo when run as a script
if __name__ == "__main__":
    t = Temperature(25)
    print(t)                     # Temperature(celsius=25.0)
    print("Fahrenheit:", t.fahrenheit)  # 77.0
    t.fahrenheit = 212
    print("Now Celsius:", t.celsius)     # 100.0

'''uppercase.py
A concise example of a data descriptor that forces a string attribute to be
uppercase. The descriptor is reusable: any class attribute assigned to it will
behave the same way.
''' 

class UpperCase:
    """Descriptor that stores the value in the instance's __dict__ as uppercase.

    The attribute name is captured on first access via __set_name__.
    """
    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name, None)

    def __set__(self, instance, value):
        if not isinstance(value, str):
            raise TypeError("UpperCase attribute requires a string")
        setattr(instance, self.private_name, value.upper())

    def __delete__(self, instance):
        raise AttributeError("cannot delete attribute managed by UpperCase")


class Person:
