'''lazy_fib.py
Implements a class with a lazily‑evaluated, cached Fibonacci property.
The first access computes the value; subsequent accesses return the stored
result without recomputation.
''' 

class Fibonacci:
    """Calculate the n‑th Fibonacci number on demand.

    The result is cached after the first computation via the ``value``
    property.
    """
    def __init__(self, n: int):
        if n < 0:
            raise ValueError("n must be non‑negative")
        self.n = n
        self._value = None

    @property
    def value(self) -> int:
        """Return the n‑th Fibonacci number, computing it once.
        """
        if self._value is None:
            self._value = self._compute()
        return self._value

    def _compute(self) -> int:
        a, b = 0, 1
        for _ in range(self.n):
            a, b = b, a + b
        return a

    def __repr__(self):
        return f"Fibonacci(n={self.n}, value={self._value})"

if __name__ == "__main__":
    f = Fibonacci(35)
    print('First access computes:', f.value)
    print('Second access uses cache:', f.value)

'''positivelist.py
