class PositiveListDescriptor:
    """Descriptor that ensures the underlying attribute is always a list of numbers.
    """
    def __set_name__(self, owner, name):
        self.storage_name = f"_{name}"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.storage_name, [])

    def __set__(self, instance, value):
        if not isinstance(value, list):
            raise TypeError("must assign a list")
        if not all(isinstance(x, (int, float)) for x in value):
            raise ValueError("list items must be numbers")
        setattr(instance, self.storage_name, value)

    def __delete__(self, instance):
        raise AttributeError("cannot delete the list attribute")


class NumberBag:
