'''readonly.py
A tiny example of a descriptor that provides a read‑only attribute.
The descriptor stores the value on first assignment and then forbids any
subsequent changes or deletions.
''' 

class ReadOnly:
    """Descriptor that allows a single assignment and then becomes immutable."""
    def __set_name__(self, owner, name):
        self.private_name = f"_{name}"
        self.assigned = False

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        if self.assigned:
            raise AttributeError("attribute is read‑only")
        setattr(instance, self.private_name, value)
        self.assigned = True

    def __delete__(self, instance):
        raise AttributeError("cannot delete read‑only attribute")


class Config:
