'''loggedattr.py
A small utility demonstrating a descriptor that logs each assignment.
The descriptor records the old and new values to ``instance._log``.
The ``value`` property simply returns the current stored value.
''' 

import datetime

class LoggedAttribute:
    """Descriptor that logs assignments to an internal list on the instance.

    The log entry includes a timestamp, attribute name, old value, and new value.
    """
    def __set_name__(self, owner, name):
        self.name = name
        self.storage = f"_{name}_value"
        self.log_name = "_log"

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.storage, None)

    def __set__(self, instance, value):
        old = getattr(instance, self.storage, None)
        setattr(instance, self.storage, value)
        log_entry = {
            "time": datetime.datetime.now().isoformat(),
            "attr": self.name,
            "old": old,
            "new": value,
        }
        if not hasattr(instance, self.log_name):
            setattr(instance, self.log_name, [])
        getattr(instance, self.log_name).append(log_entry)

    def __delete__(self, instance):
        raise AttributeError("cannot delete logged attribute")

class Counter:
    value = LoggedAttribute()

    def __init__(self, start=0):
        self.value = start

    @property
    def log(self):
        """Return the list of change‑log entries."""
        return getattr(self, "_log", [])

    def __repr__(self):
        return f"Counter(value={self.value})"

if __name__ == "__main__":
    c = Counter(5)
    c.value = 10
    c.value = 15
    print(c)
    for entry in c.log:
        print(entry)

