'''set_stats.py
Utility class that computes simple statistics about a set of comparable items.
The class is immutable – the original set is stored internally and never modified.
'''

from __future__ import annotations
from typing import Iterable, Generic, TypeVar

T = TypeVar('T', bound='Comparable')

class Comparable:
    """A minimal protocol for objects that support < and > comparisons."""
    def __lt__(self, other: object) -> bool: ...  # pragma: no cover
    def __gt__(self, other: object) -> bool: ...  # pragma: no cover

class SetStats(Generic[T]):
    """Encapsulate basic statistics for a set of comparable elements."""

    def __init__(self, data: Iterable[T]):
        self._data: set[T] = set(data)
        if not self._data:
            raise ValueError("SetStats requires a non‑empty collection")

    @property
    def size(self) -> int:
        """Return the number of unique elements."""
        return len(self._data)

    @property
    def minimum(self) -> T:
        """Return the smallest element according to the natural ordering."""
        return min(self._data)

    @property
    def maximum(self) -> T:
        """Return the largest element according to the natural ordering."""
        return max(self._data)

    def is_subset_of(self, other: Iterable[T]) -> bool:
        """Return ``True`` if the stored set is a subset of *other*.

        The *other* argument may be any iterable; it is converted to a set for the test.
        """
        return self._data.issubset(set(other))

    def __repr__(self) -> str:
        return (f"SetStats(size={self.size}, min={self.minimum}, "
                f"max={self.maximum})")

# Simple demonstration when run as a script
if __name__ == "__main__":
    numbers = SetStats([3, 1, 4, 1, 5, 9])
    print(numbers)
    print("Is subset of 0‑10 range?", numbers.is_subset_of(range(11)))

'''bst_inorder.py
Simple binary search tree implementation that builds a tree from a list of integers
and prints the inorder (sorted) traversal.
'''

class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BinarySearchTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert a key into the BST."""
        if self.root is None:
            self.root = Node(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        if key < node.key:
            if node.left is None:
                node.left = Node(key)
            else:
                self._insert(node.left, key)
        elif key > node.key:
            if node.right is None:
                node.right = Node(key)
            else:
                self._insert(node.right, key)
        # duplicate keys are ignored

    def inorder(self) -> list:
        """Return a list of keys in inorder (sorted) order."""
        result = []
        self._inorder(self.root, result)
        return result

    def _inorder(self, node, acc):
        if node is None:
            return
        self._inorder(node.left, acc)
        acc.append(node.key)
        self._inorder(node.right, acc)

if __name__ == "__main__":
    data = [7, 3, 9, 1, 5, 8, 10]
    bst = BinarySearchTree()
    for value in data:
        bst.insert(value)
    print("Inorder traversal:", bst.inorder())

'''bst_delete.py
Binary Search Tree implementation that supports insertion, searching and deletion.
A short demo at the bottom shows deleting a node with two children.
'''

class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        if self.root is None:
            self.root = Node(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node, key):
        if key < node.key:
            if node.left is None:
                node.left = Node(key)
            else:
                self._insert(node.left, key)
        elif key > node.key:
            if node.right is None:
                node.right = Node(key)
            else:
                self._insert(node.right, key)

    def search(self, key):
        return self._search(self.root, key)

    def _search(self, node, key):
        if node is None or node.key == key:
            return node
        if key < node.key:
            return self._search(node.left, key)
        else:
            return self._search(node.right, key)

    def delete(self, key):
        self.root = self._delete(self.root, key)

    def _delete(self, node, key):
        if node is None:
            return None
        if key < node.key:
            node.left = self._delete(node.left, key)
        elif key > node.key:
            node.right = self._delete(node.right, key)
        else:
            # Node with only one child or no child
            if node.left is None:
                return node.right
            if node.right is None:
                return node.left
            # Node with two children: get inorder successor (smallest in right subtree)
            succ = self._min_value_node(node.right)
            node.key = succ.key
            node.right = self._delete(node.right, succ.key)
        return node

    def _min_value_node(self, node):
        current = node
        while current.left is not None:
            current = current.left
        return current

    def inorder(self):
        res = []
        self._inorder(self.root, res)
        return res

    def _inorder(self, node, acc):
        if node is None:
            return
        self._inorder(node.left, acc)
        acc.append(node.key)
        self._inorder(node.right, acc)

if __name__ == "__main__":
    bst = BST()
    for v in [50, 30, 70, 20, 40, 60, 80]:
        bst.insert(v)
    print("Before delete:", bst.inorder())
    bst.delete(70)  # node with two children
    print("After delete 70:", bst.inorder())

'''bst_visualize.py
Binary Search Tree with a method to export the structure to a Graphviz DOT file
and optionally render it as PNG. Requires the `graphviz` package.
'''

from __future__ import annotations
import os
from typing import Optional

try:
    from graphviz import Digraph
except ImportError:
    raise ImportError('graphviz package is required: pip install graphviz')

class Node:
    def __init__(self, key: int):
        self.key = key
        self.left: Optional[Node] = None
        self.right: Optional[Node] = None

class BST:
    def __init__(self):
        self.root: Optional[Node] = None

    def insert(self, key: int) -> None:
        if self.root is None:
            self.root = Node(key)
        else:
            self._insert(self.root, key)

    def _insert(self, node: Node, key: int) -> None:
        if key < node.key:
            if node.left is None:
                node.left = Node(key)
            else:
                self._insert(node.left, key)
        elif key > node.key:
            if node.right is None:
                node.right = Node(key)
            else:
                self._insert(node.right, key)
        # duplicates ignored

    def to_graphviz(self, filename: str = 'bst') -> Digraph:
        dot = Digraph(comment='Binary Search Tree')
        def add_nodes(node: Optional[Node]):
            if node is None:
                return
            dot.node(str(id(node)), str(node.key))
            if node.left:
                dot.edge(str(id(node)), str(id(node.left)), label='L')
                add_nodes(node.left)
            if node.right:
