'''bst_iterator.py
Provides a BinarySearchTree class with an inner InorderIterator that yields keys in
inorder using an explicit stack (no recursion).
'''

from __future__ import annotations
from typing import Optional, Iterator, List

class Node:
    def __init__(self, key: int):
        self.key = key
        self.left: Optional[Node] = None
        self.right: Optional[Node] = None

class BinarySearchTree:
    def __init__(self):
        self.root: Optional[Node] = None

    def insert(self, key: int) -> None:
        if self.root is None:
            self.root = Node(key)
            return
        cur = self.root
        while True:
            if key < cur.key:
                if cur.left is None:
                    cur.left = Node(key)
                    break
                cur = cur.left
            elif key > cur.key:
                if cur.right is None:
                    cur.right = Node(key)
                    break
                cur = cur.right
            else:
                break  # duplicate ignored

    class InorderIterator(Iterator[int]):
        def __init__(self, root: Optional[Node]):
            self.stack: List[Node] = []
            self._push_left(root)

        def _push_left(self, node: Optional[Node]) -> None:
            while node is not None:
                self.stack.append(node)
                node = node.left

        def __next__(self) -> int:
            if not self.stack:
                raise StopIteration
            node = self.stack.pop()
            key = node.key
            if node.right is not None:
                self._push_left(node.right)
            return key

    def __iter__(self) -> Iterator[int]:
        return self.InorderIterator(self.root)

if __name__ == '__main__':
    bst = BinarySearchTree()
    for v in [50, 30, 70, 20, 40, 60, 80]:
        bst.insert(v)
    print('Inorder via iterator:', list(bst))

'''bst_benchmark.py
Compares the time to insert N random integers into a naive BST implementation and into
a sorted Python list that is kept in binary‑search‑tree order (using bisect).
Results are printed in milliseconds.
'''

import random, time, bisect

class Node:
    __slots__ = ('key', 'left', 'right')
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        if self.root is None:
            self.root = Node(key)
            return
        cur = self.root
        while True:
            if key < cur.key:
                if cur.left is None:
                    cur.left = Node(key)
                    return
                cur = cur.left
            elif key > cur.key:
                if cur.right is None:
                    cur.right = Node(key)
                    return
                cur = cur.right
            else:
                return  # duplicate ignored

def benchmark(num: int = 10000) -> None:
    data = [random.randint(0, num*10) for _ in range(num)]
    # BST timing
    bst = BST()
    start = time.perf_counter()
    for v in data:
        bst.insert(v)
    bst_time = (time.perf_counter() - start) * 1000
    # Sorted list timing (bisect insertion)
    slist = []
    start = time.perf_counter()
    for v in data:
        bisect.insort(slist, v)
    list_time = (time.perf_counter() - start) * 1000
    print(f'Inserted {num} elements:')
    print(f'  BST insert time   : {bst_time:.2f} ms')
    print(f'  Sorted list time  : {list_time:.2f} ms')

if __name__ == '__main__':
    benchmark(20000)

'''Linear probing hash table implementation.

Provides a HashTable class that stores key/value pairs using open addressing
with linear probing for collision resolution. Supports insert, get, delete and
iteration over keys.
''' 

class HashTable:
    """Hash table with linear probing.

    The table size is always a prime number to reduce clustering. When the
    load factor exceeds 0.7 the table is resized to the next prime.
    """
    _PRIMES = [53, 101, 211, 431, 863, 1733, 3469, 6949, 13901]

    def __init__(self, initial_capacity=53):
        self._capacity = self._next_prime(initial_capacity)
        self._size = 0
        self._keys = [None] * self._capacity
        self._values = [None] * self._capacity
        self._DELETED = object()

    # ---------------------------------------------------------------------
    # Public API
    # ---------------------------------------------------------------------
    def __len__(self):
        return self._size

    def __contains__(self, key):
        return self._find_slot(key) is not None

    def __getitem__(self, key):
        slot = self._find_slot(key)
        if slot is None:
            raise KeyError(key)
        return self._values[slot]

    def __setitem__(self, key, value):
        self._insert(key, value)

    def __delitem__(self, key):
        slot = self._find_slot(key)
        if slot is None:
            raise KeyError(key)
        self._keys[slot] = self._DELETED
        self._values[slot] = None
        self._size -= 1

    def keys(self):
        return [k for k in self._keys if k not in (None, self._DELETED)]

    # ---------------------------------------------------------------------
    # Internal helpers
    # ---------------------------------------------------------------------
    def _hash(self, key):
        return hash(key) % self._capacity

    def _probe(self, start):
        i = start
        while True:
            yield i
            i = (i + 1) % self._capacity
            if i == start:
                break

    def _find_slot(self, key):
        start = self._hash(key)
        for idx in self._probe(start):
            k = self._keys[idx]
            if k is None:
                return None
            if k is not self._DELETED and k == key:
                return idx
        return None

    def _insert(self, key, value):
        if self._size + 1 > 0.7 * self._capacity:
            self._resize()
        start = self._hash(key)
        first_deleted = None
        for idx in self._probe(start):
            k = self._keys[idx]
            if k is None:
                target = first_deleted if first_deleted is not None else idx
                self._keys[target] = key
                self._values[target] = value
                self._size += 1
                return
            if k is self._DELETED:
                if first_deleted is None:
                    first_deleted = idx
            elif k == key:
                self._values[idx] = value
                return

    def _resize(self):
        old_keys, old_values = self._keys, self._values
        new_cap = self._next_prime(self._capacity * 2)
        self._capacity = new_cap
        self._keys = [None] * new_cap
        self._values = [None] * new_cap
        self._size = 0
        for k, v in zip(old_keys, old_values):
            if k not in (None, self._DELETED):
                self._insert(k, v)

    @classmethod
    def _next_prime(cls, n):
        for p in cls._PRIMES:
            if p > n:
                return p
        # fallback simple search
        cand = n + 1 if n % 2 == 0 else n + 2
        while True:
            if all(cand % d for d in range(3, int(cand ** 0.5) + 1, 2)):
                return cand
            cand += 2

if __name__ == '__main__':
