    for i in range(30):
        ht[f'key{i}'] = i * i
    print('size:', len(ht))
    print('key10 ->', ht['key10'])
    del ht['key10']
    print('key10 in ht?', 'key10' in ht)
    print('All keys:', ht.keys())

'''Separate‑chaining hash table demo using Python's dict.

The script defines a SimpleChainHash class that mimics a hash table where each
bucket holds a Python list of (key, value) pairs. The implementation is kept
minimal to illustrate the concept rather than performance.
''' 

class SimpleChainHash:
    """Hash table with separate chaining.

    Internally it uses a list of buckets; each bucket is a list of (key, value)
    tuples. Collisions are resolved by appending to the bucket's list.
    """
    def __init__(self, bucket_count=8):
        self._buckets = [[] for _ in range(bucket_count)]
        self._size = 0

    def _index(self, key):
        return hash(key) % len(self._buckets)

    def insert(self, key, value):
        idx = self._index(key)
        bucket = self._buckets[idx]
        for i, (k, _) in enumerate(bucket):
            if k == key:
                bucket[i] = (key, value)
                return
        bucket.append((key, value))
        self._size += 1
        if self._size > 2 * len(self._buckets):
            self._rehash()

    def get(self, key, default=None):
        idx = self._index(key)
        for k, v in self._buckets[idx]:
            if k == key:
                return v
        return default

    def delete(self, key):
        idx = self._index(key)
        bucket = self._buckets[idx]
        for i, (k, _) in enumerate(bucket):
            if k == key:
                del bucket[i]
                self._size -= 1
                return True
        return False

    def _rehash(self):
        old = self._buckets
        new_capacity = len(old) * 2
        self._buckets = [[] for _ in range(new_capacity)]
        self._size = 0
        for bucket in old:
            for k, v in bucket:
                self.insert(k, v)

    def __len__(self):
        return self._size

    def __iter__(self):
        for bucket in self._buckets:
            for k, _ in bucket:
                yield k

if __name__ == '__main__':
