    for i in range(15):
        h.insert(f'item{i}', i * 10)
    print('size after inserts:', len(h))
    print('value of item7:', h.get('item7'))
    h.delete('item7')
    print('exists after delete?', h.get('item7'))
    print('all keys:', list(h))

'''Quadratic probing insertion visualizer.

The script defines QuadraticHashTable with insert, get and delete methods. After each
operation it prints a compact representation of the internal array, showing
empty slots (.), deleted slots (X) and occupied slots as the stored key.
''' 

class QuadraticHashTable:
    def __init__(self, capacity=13):
        self._capacity = capacity
        self._keys = [None] * capacity
        self._values = [None] * capacity
        self._DELETED = object()
        self._size = 0

    def _hash(self, key):
        return hash(key) % self._capacity

    def _probe(self, start, key):
        for i in range(self._capacity):
            idx = (start + i * i) % self._capacity
            yield idx
            if i > self._capacity:  # safety, never happens
                break

    def insert(self, key, value):
        start = self._hash(key)
        first_del = None
        for idx in self._probe(start, key):
            k = self._keys[idx]
            if k is None:
                target = first_del if first_del is not None else idx
                self._keys[target] = key
                self._values[target] = value
                self._size += 1
                self._display('insert', key, idx)
                return
            if k is self._DELETED:
                if first_del is None:
                    first_del = idx
            elif k == key:
                self._values[idx] = value
                self._display('update', key, idx)
                return
        raise RuntimeError('HashTable is full')

    def get(self, key, default=None):
        start = self._hash(key)
        for idx in self._probe(start, key):
            k = self._keys[idx]
            if k is None:
                return default
            if k is not self._DELETED and k == key:
                return self._values[idx]
        return default

    def delete(self, key):
        start = self._hash(key)
        for idx in self._probe(start, key):
            k = self._keys[idx]
            if k is None:
                return False
            if k is not self._DELETED and k == key:
                self._keys[idx] = self._DELETED
                self._values[idx] = None
                self._size -= 1
                self._display('delete', key, idx)
                return True
        return False

    def _display(self, action, key, idx):
        # compact visual: . empty, X deleted, otherwise key
        line = []
        for k in self._keys:
            if k is None:
                line.append('.')
            elif k is self._DELETED:
                line.append('X')
            else:
                line.append(str(k))
        print(f'{action.upper():6} key={key!r} at {idx:2d}  |', ' '.join(line))

if __name__ == '__main__':
    ht = QuadraticHashTable()
    for item in ['a', 'b', 'c', 'd', 'e']:
        ht.insert(item, ord(item))
    ht.delete('c')
    ht.insert('f', 102)
    print('final size =', ht._size)

'''Double‑hashing hash map for string keys.

The map uses two hash functions: h1 for the initial bucket and h2 for the step
size. The second hash is guaranteed to be odd and non‑zero so that all slots
are eventually probed. Supports insert, lookup, delete and iteration.
''' 

class DoubleHashMap:
    def __init__(self, capacity=17):
        self._capacity = self._next_prime(capacity)
        self._keys = [None] * self._capacity
        self._values = [None] * self._capacity
        self._DELETED = object()
        self._size = 0

    # -----------------------------------------------------------------
    # Public API
    # -----------------------------------------------------------------
    def __len__(self):
        return self._size

    def __setitem__(self, key, value):
        self._insert(key, value)

    def __getitem__(self, key):
        idx = self._find(key)
        if idx is None:
            raise KeyError(key)
        return self._values[idx]

    def __delitem__(self, key):
        idx = self._find(key)
        if idx is None:
            raise KeyError(key)
        self._keys[idx] = self._DELETED
        self._values[idx] = None
        self._size -= 1

    def __contains__(self, key):
        return self._find(key) is not None

    def items(self):
        for k, v in zip(self._keys, self._values):
            if k not in (None, self._DELETED):
                yield (k, v)

    # -----------------------------------------------------------------
    # Internal helpers
    # -----------------------------------------------------------------
    def _hash1(self, key):
        # simple polynomial rolling hash
        h = 0
        for ch in key:
            h = (31 * h + ord(ch)) % self._capacity
        return h

    def _hash2(self, key):
        # second hash must be odd and not zero; use a different base
        h = 0
        for ch in key:
            h = (17 * h + ord(ch)) % self._capacity
        step = h * 2 + 1  # ensures odd
        return step

    def _probe(self, start, step):
        idx = start
        for _ in range(self._capacity):
            yield idx
            idx = (idx + step) % self._capacity

    def _find(self, key):
        start = self._hash1(key)
        step = self._hash2(key)
        for idx in self._probe(start, step):
            k = self._keys[idx]
            if k is None:
                return None
            if k is not self._DELETED and k == key:
                return idx
        return None

    def _insert(self, key, value):
        if self._size + 1 > 0.6 * self._capacity:
            self._resize()
        start = self._hash1(key)
        step = self._hash2(key)
        first_del = None
        for idx in self._probe(start, step):
            k = self._keys[idx]
            if k is None:
                target = first_del if first_del is not None else idx
                self._keys[target] = key
                self._values[target] = value
                self._size += 1
                return
            if k is self._DELETED:
                if first_del is None:
                    first_del = idx
            elif k == key:
                self._values[idx] = value
                return
        raise RuntimeError('Table full')

    def _resize(self):
        old_keys, old_vals = self._keys, self._values
        new_cap = self._next_prime(self._capacity * 2)
        self._capacity = new_cap
        self._keys = [None] * new_cap
        self._values = [None] * new_cap
        self._size = 0
        for k, v in zip(old_keys, old_vals):
            if k not in (None, self._DELETED):
                self._insert(k, v)

    @staticmethod
    def _next_prime(n):
        # simple incremental prime finder
        def is_prime(x):
            if x < 2:
                return False
            if x % 2 == 0:
                return x == 2
            for i in range(3, int(x ** 0.5) + 1, 2):
                if x % i == 0:
                    return False
            return True
        cand = n if n % 2 else n + 1
        while not is_prime(cand):
            cand += 2
        return cand

