'''bst_inorder.py
Builds a binary search tree (BST) from a list of integers and prints the values
using an in‑order traversal (which yields the keys in sorted order).
''' 

class Node:
    """A node in the binary search tree."""
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BinarySearchTree:
    """Simple unbalanced BST with insert and in‑order traversal methods."""
    def __init__(self):
        self.root = None

    def insert(self, key):
        """Insert *key* into the tree. Duplicates are ignored."""
        if self.root is None:
            self.root = Node(key)
            return
        self._insert(self.root, key)

    def _insert(self, node, key):
        if key == node.key:
            return  # ignore duplicates
        if key < node.key:
            if node.left is None:
                node.left = Node(key)
            else:
                self._insert(node.left, key)
        else:
            if node.right is None:
                node.right = Node(key)
            else:
                self._insert(node.right, key)

    def inorder(self):
        """Yield the keys of the tree using in‑order traversal."""
        yield from self._inorder(self.root)

    def _inorder(self, node):
        if node is None:
            return
        yield from self._inorder(node.left)
        yield node.key
        yield from self._inorder(node.right)

if __name__ == '__main__':
    data = [7, 3, 9, 1, 5, 8, 10]
    bst = BinarySearchTree()
    for n in data:
        bst.insert(n)
    print('In‑order traversal (sorted):')
    print(list(bst.inorder()))

'''bst_module.py
A minimal binary search tree implementation with insert, search, and delete
operations, plus a small unittest suite that can be run directly.
''' 

import unittest

class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    # ------------------------------------------------------------
    def insert(self, key):
        """Insert *key* into the tree (duplicates ignored)."""
        if self.root is None:
            self.root = Node(key)
            return
        cur = self.root
        while True:
            if key == cur.key:
                return
            if key < cur.key:
                if cur.left is None:
                    cur.left = Node(key)
                    return
                cur = cur.left
            else:
                if cur.right is None:
                    cur.right = Node(key)
                    return
                cur = cur.right

    # ------------------------------------------------------------
    def search(self, key):
        """Return the node containing *key*, or ``None`` if not found."""
        cur = self.root
        while cur:
            if key == cur.key:
                return cur
            cur = cur.left if key < cur.key else cur.right
        return None

    # ------------------------------------------------------------
    def delete(self, key):
        """Remove *key* from the tree if present."""
        self.root = self._delete_rec(self.root, key)

    def _delete_rec(self, node, key):
        if node is None:
            return None
        if key < node.key:
            node.left = self._delete_rec(node.left, key)
        elif key > node.key:
            node.right = self._delete_rec(node.right, key)
        else:  # found node
            if node.left is None:
                return node.right
            if node.right is None:
                return node.left
            # node with two children: replace with inorder successor
            succ = node.right
            while succ.left:
                succ = succ.left
            node.key = succ.key
            node.right = self._delete_rec(node.right, succ.key)
        return node

    # ------------------------------------------------------------
    def inorder(self):
        """Return a list of keys in sorted order."""
        res = []
        self._inorder(self.root, res)
        return res

    def _inorder(self, node, out):
        if not node:
            return
        self._inorder(node.left, out)
        out.append(node.key)
        self._inorder(node.right, out)

# ---------------------------------------------------------------------
class TestBST(unittest.TestCase):
    def setUp(self):
        self.bst = BST()
        for v in [5, 3, 7, 2, 4, 6, 8]:
            self.bst.insert(v)

    def test_search(self):
        self.assertIsNotNone(self.bst.search(4))
        self.assertIsNone(self.bst.search(10))

    def test_delete_leaf(self):
        self.bst.delete(2)
        self.assertNotIn(2, self.bst.inorder())

    def test_delete_one_child(self):
        self.bst.delete(7)  # 7 has left child 6 and right child 8
        self.assertNotIn(7, self.bst.inorder())
        self.assertIn(6, self.bst.inorder())
        self.assertIn(8, self.bst.inorder())

    def test_delete_two_children(self):
        self.bst.delete(5)
        self.assertNotIn(5, self.bst.inorder())
        self.assertEqual(self.bst.inorder(), [2, 3, 4, 6, 7, 8])

if __name__ == '__main__':
    unittest.main()

'''bst_ascii.py
Prints a binary search tree as a sideways ASCII diagram.
The root appears on the left, children are indented to the right.
''' 

class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        if self.root is None:
            self.root = Node(key)
            return
        cur = self.root
        while True:
            if key < cur.key:
                if cur.left is None:
                    cur.left = Node(key)
                    return
                cur = cur.left
            elif key > cur.key:
                if cur.right is None:
                    cur.right = Node(key)
                    return
                cur = cur.right
            else:
                return  # ignore duplicates

    def _display(self, node, prefix, is_left):
        if node is None:
            return []
        lines = []
        # Process right child first so it appears on top
        lines += self._display(node.right, prefix + ('│   ' if is_left else '    '), False)
        lines.append(prefix + ('└── ' if is_left else '┌── ') + str(node.key))
        lines += self._display(node.left, prefix + ('    ' if is_left else '│   '), True)
        return lines

    def ascii(self):
        """Return a string with the ASCII representation of the tree."""
        return '\n'.join(self._display(self.root, '', True))

if __name__ == '__main__':
    import random
    bst = BST()
    for v in random.sample(range(1, 30), 10):
        bst.insert(v)
    print('ASCII representation of the BST:')
    print(bst.ascii())

'''balanced_bst.py
Reads integers from a text file (one per line), builds a height‑balanced BST
using the classic “sorted‑array‑to‑BST” method, and lets the user query the
depth (distance from the root) of any key.
''' 

class Node:
    def __init__(self, key, left=None, right=None):
        self.key = key
        self.left = left
        self.right = right

def build_balanced(sorted_vals):
    """Recursively build a balanced BST from a sorted list of values."""
    if not sorted_vals:
        return None
    mid = len(sorted_vals) // 2
    return Node(
        sorted_vals[mid],
        left=build_balanced(sorted_vals[:mid]),
        right=build_balanced(sorted_vals[mid + 1:])
    )

def depth(node, key, current=0):
    """Return the depth of *key* in the tree rooted at *node* or ``-1`` if absent."""
    if node is None:
        return -1
    if key == node.key:
        return current
    if key < node.key:
        return depth(node.left, key, current + 1)
    else:
        return depth(node.right, key, current + 1)

if __name__ == '__main__':
    import sys
    if len(sys.argv) != 2:
        print('Usage: python balanced_bst.py <file-with-ints>')
        sys.exit(1)
    filename = sys.argv[1]
    try:
        values = [int(line.strip()) for line in open(filename) if line.strip()]
    except Exception as e:
        print('Error reading file:', e)
        sys.exit(1)
    # Remove duplicates and sort
    uniq = sorted(set(values))
    root = build_balanced(uniq)
    print('Balanced BST built with', len(uniq), 'unique keys.')
    while True:
        try:
            txt = input('Enter integer to find depth (or blank to quit): ').strip()
            if txt == '':
                break
            key = int(txt)
            d = depth(root, key)
            if d >= 0:
                print(f'Key {key} found at depth {d}.')
            else:
                print(f'Key {key} is not present in the tree.')
        except KeyboardInterrupt:
            print('\nExiting.')
            break
        except ValueError:
            print('Please enter a valid integer.')

'''bst_preorder_iter.py
Implements a binary search tree with an iterator that yields nodes in
pre‑order (root, left, right) without recursion, using an explicit stack.
''' 

class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None

class BST:
    def __init__(self):
        self.root = None

    def insert(self, key):
        if self.root is None:
            self.root = Node(key)
            return
        cur = self.root
        while True:
            if key == cur.key:
                return
            if key < cur.key:
                if cur.left is None:
                    cur.left = Node(key)
                    return
                cur = cur.left
            else:
                if cur.right is None:
                    cur.right = Node(key)
                    return
                cur = cur.right

    def __iter__(self):
        return PreOrderIterator(self.root)

class PreOrderIterator:
    """Iterates a BST in pre‑order using a stack (no recursion)."""
    def __init__(self, root):
        self.stack = []
        if root:
            self.stack.append(root)

    def __iter__(self):
        return self

    def __next__(self):
        if not self.stack:
            raise StopIteration
        node = self.stack.pop()
        # Push right first so left is processed next
        if node.right:
            self.stack.append(node.right)
        if node.left:
            self.stack.append(node.left)
        return node.key

if __name__ == '__main__':
    bst = BST()
    for v in [15, 10, 20, 8, 12, 17, 25]:
        bst.insert(v)
    print('Pre‑order traversal using iterator:')
    print(list(bst))

'''bst_json.py
Serializes a binary search tree to a JSON-compatible dict and rebuilds
it. The format is {"key": <int>, "left": <subtree>, "right": <subtree>},
where a missing child is represented by ``null``.
''' 

import json

class Node:
    def __init__(self, key, left=None, right=None):
        self.key = key
        self.left = left
        self.right = right

def insert(root, key):
    if root is None:
        return Node(key)
    if key < root.key:
        root.left = insert(root.left, key)
    elif key > root.key:
        root.right = insert(root.right, key)
    return root

def to_dict(node):
    if node is None:
        return None
    return {
        'key': node.key,
        'left': to_dict(node.left),
        'right': to_dict(node.right)
    }

def from_dict(d):
    if d is None:
        return None
    return Node(d['key'], from_dict(d['left']), from_dict(d['right']))

if __name__ == '__main__':
    values = [50, 30, 70, 20, 40, 60, 80]
    root = None
    for v in values:
        root = insert(root, v)
    data = to_dict(root)
    json_str = json.dumps(data, indent=2)
    print('Serialized BST as JSON:')
    print(json_str)
    # Reconstruct
    rebuilt_root = from_dict(json.loads(json_str))
    print('Re‑built tree in‑order traversal:')
    def inorder(node):
        return [] if node is None else inorder(node.left) + [node.key] + inorder(node.right)
    print(inorder(rebuilt_root))

