'''common_chars.py
Read a file whose each line represents a collection of characters.
The script computes the intersection of all line‑sets and prints the
characters that appear in every line, sorted alphabetically.
Usage: python common_chars.py <filename>
'''
import sys

def line_to_set(line: str) -> set:
    """Return a set of the stripped characters in *line* (excluding whitespace)."""
    return {ch for ch in line.rstrip('\n') if not ch.isspace()}

def intersect_file_sets(filepath: str) -> set:
    """Open *filepath* and return the intersection of character sets from each line.
    Empty files yield an empty set.
    """
    with open(filepath, 'r', encoding='utf-8') as f:
        lines = f.readlines()
    if not lines:
        return set()
    common = line_to_set(lines[0])
    for ln in lines[1:]:
        common &= line_to_set(ln)
    return common

def main() -> None:
    if len(sys.argv) != 2:
        print('Usage: python common_chars.py <filename>')
        sys.exit(1)
    result = intersect_file_sets(sys.argv[1])
    print('Common characters:', ''.join(sorted(result)))

if __name__ == '__main__':
    main()

import heapq
import sys

def load_graph(path):
    """Load an undirected weighted graph from *path*.
    Expected format per line: ``node1 node2 weight`` (space separated)."""
    graph = {}
    with open(path, "r") as f:
        for line in f:
            parts = line.strip().split()
            if len(parts) != 3:
                continue
            u, v, w = parts[0], parts[1], float(parts[2])
            graph.setdefault(u, []).append((v, w))
            graph.setdefault(v, []).append((u, w))
    return graph

def dijkstra(graph, source):
    """Return a dict mapping each node to its shortest distance from *source*.
    Uses a min‑heap (priority queue) for O((E+V) log V) performance."""
    dist = {node: float('inf') for node in graph}
    dist[source] = 0.0
    pq = [(0.0, source)]
    while pq:
        cur_dist, u = heapq.heappop(pq)
        if cur_dist != dist[u]:
            continue
        for v, w in graph[u]:
            nd = cur_dist + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <graph_file> <source_node>")
        sys.exit(1)
    graph_path, source = sys.argv[1], sys.argv[2]
    graph = load_graph(graph_path)
    if source not in graph:
        print(f"Source node '{source}' not found in graph.")
        sys.exit(1)
    distances = dijkstra(graph, source)
    for node, d in sorted(distances.items()):
        print(f"{node}: {d:.4f}")

if __name__ == "__main__":
    main()

import csv
import sys
import heapq
from collections import defaultdict

def load_csv(path):
    """Return a directed adjacency map built from a CSV file.
    Expected columns: source,destination,weight (weight can be float).
    """
    graph = defaultdict(dict)
    with open(path, newline='') as f:
        reader = csv.reader(f)
        for row in reader:
            if len(row) != 3:
                continue
            u, v, w = row[0], row[1], float(row[2])
            graph[u][v] = w
    return graph

def dijkstra(graph, source, target):
    dist = {node: float('inf') for node in graph}
    prev = {node: None for node in graph}
    dist[source] = 0.0
    heap = [(0.0, source)]
    while heap:
        d, u = heapq.heappop(heap)
        if u == target:
            break
        if d != dist[u]:
            continue
        for v, w in graph[u].items():
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))
    if dist[target] == float('inf'):
        return None, None
    # rebuild path
    path = []
    cur = target
    while cur is not None:
        path.append(cur)
        cur = prev[cur]
    path.reverse()
    return dist[target], path

def main():
    if len(sys.argv) != 4:
        print(f"Usage: {sys.argv[0]} <edges.csv> <source> <target>")
        sys.exit(1)
    csv_path, src, tgt = sys.argv[1], sys.argv[2], sys.argv[3]
    g = load_csv(csv_path)
    if src not in g or tgt not in g:
        print("Source or target not present in graph.")
        sys.exit(1)
    distance, path = dijkstra(g, src, tgt)
    if path is None:
        print(f"No path from {src} to {tgt}.")
    else:
        print(f"Shortest distance: {distance:.4f}")
        print(" -> ".join(path))

if __name__ == "__main__":
    main()

"""Dijkstra's algorithm with a hand‑rolled binary min‑heap.

The ``PriorityQueue`` class provides ``push``, ``pop`` and ``decrease_key``
operations without relying on the standard library ``heapq`` module.
The script demonstrates the algorithm on a tiny graph defined in
``GRAPH``.
"""
from typing import Any, List, Tuple

class PriorityQueue:
    """Simple binary min‑heap supporting decrease‑key.
    Elements are stored as (key, value) tuples.
    ``position`` maps a value to its index in ``_data`` for O(log n) updates.
    """
    def __init__(self) -> None:
        self._data: List[Tuple[float, Any]] = []
        self.position: dict[Any, int] = {}

    def _swap(self, i: int, j: int) -> None:
        self._data[i], self._data[j] = self._data[j], self._data[i]
        self.position[self._data[i][1]] = i
        self.position[self._data[j][1]] = j

    def _sift_up(self, idx: int) -> None:
        while idx > 0:
            parent = (idx - 1) // 2
            if self._data[parent][0] <= self._data[idx][0]:
                break
            self._swap(parent, idx)
            idx = parent

    def _sift_down(self, idx: int) -> None:
        size = len(self._data)
        while True:
            left = 2 * idx + 1
            right = left + 1
            smallest = idx
            if left < size and self._data[left][0] < self._data[smallest][0]:
                smallest = left
            if right < size and self._data[right][0] < self._data[smallest][0]:
                smallest = right
            if smallest == idx:
                break
            self._swap(idx, smallest)
            idx = smallest

    def push(self, key: float, value: Any) -> None:
        if value in self.position:
            self.decrease_key(value, key)
            return
        self._data.append((key, value))
        idx = len(self._data) - 1
        self.position[value] = idx
        self._sift_up(idx)

    def pop(self) -> Tuple[float, Any]:
        if not self._data:
            raise IndexError('pop from empty priority queue')
        min_item = self._data[0]
        last = self._data.pop()
        del self.position[min_item[1]]
        if self._data:
            self._data[0] = last
            self.position[last[1]] = 0
            self._sift_down(0)
        return min_item

    def decrease_key(self, value: Any, new_key: float) -> None:
        idx = self.position.get(value)
        if idx is None:
            self.push(new_key, value)
            return
        old_key, _ = self._data[idx]
        if new_key >= old_key:
            return
        self._data[idx] = (new_key, value)
        self._sift_up(idx)

    def __len__(self) -> int:
        return len(self._data)

# Example graph as adjacency map
GRAPH = {
    'A': {'B': 1, 'C': 4},
    'B': {'C': 2, 'D': 5},
    'C': {'D': 1},
    'D': {}
}

def dijkstra(graph, source):
    dist = {node: float('inf') for node in graph}
    dist[source] = 0.0
    pq = PriorityQueue()
    for node, d in dist.items():
        pq.push(d, node)
    while len(pq):
        d, u = pq.pop()
        if d != dist[u]:
            continue
        for v, w in graph[u].items():
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                pq.decrease_key(v, nd)
    return dist

if __name__ == "__main__":
    print('Distances from A:', dijkstra(GRAPH, 'A'))

'''regex_repl.py
Simple interactive REPL for testing regular expressions.
Type a pattern, then a test string, and the program prints:
  - full match
  - named groups (if any)
  - positional groups
Enter an empty pattern to quit.
''' 
import re
import sys

def evaluate(pattern: str, test_str: str) -> None:
    """Compile *pattern* and apply it to *test_str*, printing results."""
    try:
        compiled = re.compile(pattern)
    except re.error as err:
        print(f'Invalid pattern: {err}')
        return
    match = compiled.search(test_str)
    if not match:
        print('No match')
        return
    print('Full match :', match.group(0))
    if match.lastgroup:
        print('Named groups:')
        for name, val in match.groupdict().items():
            print(f'  {name} = {val}')
    else:
        print('Named groups: None')
    if match.lastindex:
        print('Positional groups:')
        for i in range(1, match.lastindex + 1):
            print(f'  {i} = {match.group(i)}')
    else:
        print('Positional groups: None')

def repl() -> None:
    print('Regex REPL – enter an empty pattern to exit')
    while True:
        pattern = input('Pattern> ').strip()
        if not pattern:
            break
        test_str = input('Test string> ')
        evaluate(pattern, test_str)
        print('-' * 40)

if __name__ == '__main__':
    try:
        repl()
    except KeyboardInterrupt:
        sys.exit(0)

'''wildcard_filter.py
Convert glob‑style patterns to regular expressions and filter a list of filenames.
Usage:
    python wildcard_filter.py "*.py" file1.txt script.py notes.md
The matching filenames are printed one per line.
''' 
import re
import sys
from typing import List

_SPECIAL_CHARS = {'.', '^', '$', '+', '{', '}', '[', ']', '|', '(', ')'}

def glob_to_regex(pattern: str) -> str:
    """Translate a shell wildcard *pattern* to a regex string.
    Supports '*', '?', and character ranges like [a-z].
    """
    regex = ['^']
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '*':
            regex.append('.*')
        elif c == '?':
            regex.append('.')
        elif c == '[':
            j = i + 1
            while j < len(pattern) and pattern[j] != ']':
                j += 1
            if j >= len(pattern):
                regex.append('\\[')  # unmatched '[' treated literally
            else:
                content = pattern[i:j+1]
                regex.append(content)
                i = j
        elif c in _SPECIAL_CHARS:
            regex.append('\\' + c)
        else:
            regex.append(c)
        i += 1
    regex.append('$')
    return ''.join(regex)

def filter_filenames(pattern: str, names: List[str]) -> List[str]:
    """Return a list of filenames from *names* that match the wildcard *pattern*."""
    regex = re.compile(glob_to_regex(pattern))
    return [n for n in names if regex.fullmatch(n)]

def main(argv=None) -> None:
    argv = argv or sys.argv[1:]
    if len(argv) < 2:
        print('Usage: python wildcard_filter.py <pattern> <file1> [file2 ...]')
        sys.exit(1)
    pattern, *files = argv
    matches = filter_filenames(pattern, files)
    for m in matches:
        print(m)

if __name__ == '__main__':
    main()

'''Infinite prime number generator using itertools.

The module defines ``primes`` – an iterator that yields prime numbers forever.
It combines ``itertools.count`` with a simple trial‑division test that checks
potential divisors up to the square root of the candidate. The generator is
lazy and can be stopped with ``break`` or ``itertools.islice``.
''' 

import itertools
import math
from typing import Iterator


def _is_prime(n: int) -> bool:
    """Return ``True`` if *n* is a prime number.

    Small numbers are handled explicitly; for larger numbers we test divisibility
    by all odd integers up to ``sqrt(n)``.
    """
    if n < 2:
        return False
    if n in (2, 3):
        return True
    if n % 2 == 0:
        return False
    limit = int(math.isqrt(n))
    for d in range(3, limit + 1, 2):
        if n % d == 0:
            return False
    return True


def primes() -> Iterator[int]:
    """Yield an infinite sequence of prime numbers.

    The implementation starts at 2 and checks each subsequent integer using
    ``_is_prime``. ``itertools.count`` provides the unbounded counter.
    """
    for candidate in itertools.count(2):
        if _is_prime(candidate):
            yield candidate


def _demo() -> None:
    print("First 15 primes:")
    for p in itertools.islice(primes(), 15):
        print(p, end=" ")
    print()


if __name__ == "__main__":
    _demo()

'''module_dependency_sort.py
Analyze import statements in *.py files inside a given directory, construct a dependency
graph where each node is a module (filename without .py) and edges point from a module
to the modules it imports, then output a topological order suitable for installation
or packaging.

Only intra‑directory imports (i.e., imports of files that exist in the same folder)
are considered; external libraries are ignored.
''' 
import ast
import os
import sys
from collections import defaultdict, deque
from typing import Dict, List, Set

def find_python_files(root: str) -> List[str]:
    return [f for f in os.listdir(root) if f.endswith('.py')]

def parse_imports(file_path: str) -> Set[str]:
    with open(file_path, 'r', encoding='utf-8') as f:
        tree = ast.parse(f.read(), filename=file_path)
    imports = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                imports.add(alias.name.split('.')[0])
        elif isinstance(node, ast.ImportFrom):
            if node.level == 0 and node.module:
                imports.add(node.module.split('.')[0])
    return imports

def build_graph(dir_path: str) -> Dict[str, Set[str]]:
    modules = {os.path.splitext(f)[0]: f for f in find_python_files(dir_path)}
    graph: Dict[str, Set[str]] = defaultdict(set)
    for mod, filename in modules.items():
        full_path = os.path.join(dir_path, filename)
        imported = parse_imports(full_path)
        # Keep only imports that refer to modules in the same directory
        intra = {imp for imp in imported if imp in modules}
        graph[mod] = intra
    return graph

def kahn_sort(graph: Dict[str, Set[str]]) -> List[str]:
    indegree = defaultdict(int)
    for u in graph:
        indegree[u] = indegree[u]  # ensure presence
    for u, neigh in graph.items():
        for v in neigh:
            indegree[v] += 1
    zero = deque([n for n, d in indegree.items() if d == 0])
    order: List[str] = []
    while zero:
        n = zero.popleft()
        order.append(n)
        for m in graph[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                zero.append(m)
    if len(order) != len(graph):
        raise RuntimeError('Circular import detected among modules')
    return order

def main():
    if len(sys.argv) != 2:
        print('Usage: python module_dependency_sort.py <directory>')
        sys.exit(1)
    dir_path = sys.argv[1]
    if not os.path.isdir(dir_path):
        print('Error: given path is not a directory')
        sys.exit(1)
    graph = build_graph(dir_path)
    try:
        order = kahn_sort(graph)
        print('Installation order:')
        for mod in order:
            print(mod)
    except RuntimeError as e:
        print('Error:', e)

if __name__ == '__main__':
    main()

'''schedule_tasks.py
Command‑line utility that reads a JSON description of tasks and their prerequisites
and prints a topological schedule. The JSON format is a list of objects:
[{"task": "A", "requires": ["B", "C"]}, ...]
If a cycle exists, the tool reports it and exits with status 1.
''' 
import json
import sys
from collections import defaultdict, deque
from typing import Dict, List, Set

def load_json(path: str) -> List[Dict[str, List[str]]]:
    with open(path, 'r', encoding='utf-8') as f:
        return json.load(f)

def build_graph(entries: List[Dict[str, List[str]]]) -> Dict[str, Set[str]]:
    graph: Dict[str, Set[str]] = defaultdict(set)
    all_tasks: Set[str] = set()
    for entry in entries:
        task = entry['task']
        reqs = entry.get('requires', [])
        all_tasks.add(task)
        all_tasks.update(reqs)
        graph[task].update(reqs)
    # Ensure every task appears as a key
    for t in all_tasks:
        graph[t] = graph[t]
    return graph

def kahn_schedule(graph: Dict[str, Set[str]]) -> List[str]:
    indegree = defaultdict(int)
    for node in graph:
        indegree[node] = indegree[node]
    for node, deps in graph.items():
        for d in deps:
            indegree[d] += 1
    zero = deque([n for n, d in indegree.items() if d == 0])
    order: List[str] = []
    while zero:
        n = zero.popleft()
        order.append(n)
        for m in graph[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                zero.append(m)
    if len(order) != len(graph):
        raise ValueError('Cycle detected in task dependencies')
    return order

def main():
    if len(sys.argv) not in (2, 3):
        print('Usage: python schedule_tasks.py <json-file> [--detect-cycle]')
        sys.exit(1)
    path = sys.argv[1]
    entries = load_json(path)
    graph = build_graph(entries)
    try:
        schedule = kahn_schedule(graph)
        print('Task schedule:')
        for t in schedule:
            print(t)
    except ValueError as e:
        print('Error:', e)
        sys.exit(1)

if __name__ == '__main__':
    main()

'''toposorter.py
Defines a reusable TopoSorter class.
The class accepts a directed graph (adjacency list) at construction time.
Calling the instance returns a topological ordering using Kahn's algorithm.
If Kahn's algorithm fails because of a cycle, the class automatically
switches to a depth‑first search implementation that raises a CycleError
with a more detailed path.
''' 
from collections import defaultdict, deque
from typing import Dict, Iterable, List, Set, TypeVar

T = TypeVar('T')

class CycleError(Exception):
    """Exception raised when a directed cycle is detected.
    The attribute `cycle_path` contains the nodes involved in the cycle.
    """
    def __init__(self, message: str, cycle_path: List[T] = None):
        super().__init__(message)
        self.cycle_path = cycle_path or []

class TopoSorter:
    def __init__(self, graph: Dict[T, Iterable[T]]):
        # Store a copy with sets for fast membership tests
        self.graph: Dict[T, Set[T]] = {k: set(v) for k, v in graph.items()}
        # Ensure every node appears as a key
        all_nodes = set(self.graph)
        for targets in self.graph.values():
            all_nodes.update(targets)
        for n in all_nodes:
            self.graph.setdefault(n, set())

    def __call__(self) -> List[T]:
        try:
            return self._kahn()
        except CycleError:
            # fallback to DFS which can provide a concrete cycle path
            return self._dfs()

    def _kahn(self) -> List[T]:
        indegree = defaultdict(int)
        for u in self.graph:
            indegree[u] = indegree[u]
        for u, nbrs in self.graph.items():
            for v in nbrs:
                indegree[v] += 1
        zero = deque([n for n, d in indegree.items() if d == 0])
        order: List[T] = []
        while zero:
            n = zero.popleft()
            order.append(n)
            for m in self.graph[n]:
                indegree[m] -= 1
                if indegree[m] == 0:
                    zero.append(m)
        if len(order) != len(self.graph):
            raise CycleError('Cycle detected (Kahn)')
        return order

    def _dfs(self) -> List[T]:
        visited: Set[T] = set()
        temp_mark: Set[T] = set()
        order: List[T] = []
        cycle_path: List[T] = []

        def visit(node: T):
            if node in temp_mark:
                # cycle discovered – build path
                idx = list(temp_mark).index(node)
                cycle_path.extend(list(temp_mark)[idx:] + [node])
                raise CycleError('Cycle detected (DFS)', cycle_path)
            if node not in visited:
                temp_mark.add(node)
                for nbr in self.graph[node]:
                    visit(nbr)
                temp_mark.remove(node)
                visited.add(node)
                order.append(node)
        for n in self.graph:
            if n not in visited:
                visit(n)
        order.reverse()
        return order

if __name__ == '__main__':
    example = {
        'a': ['b', 'c'],
        'b': ['d'],
        'c': ['d'],
        'd': []
    }
    sorter = TopoSorter(example)
    print('Topological order:', sorter())

