'''quicksort_generic.py
A generic quicksort implementation that works with any objects supporting
comparison operators.  The module also contains a simple unittest class.
'''

from typing import List, TypeVar, Callable
import unittest

T = TypeVar('T')

def quicksort(arr: List[T], key: Callable[[T], T] = lambda x: x) -> List[T]:
    """Return a new list with *arr* sorted according to *key*.

    The algorithm is the same as the classic quicksort but uses the *key*
    function to obtain the value that determines ordering.  This makes the
    function usable with custom classes or when sorting by a specific attribute.
    """
    if len(arr) <= 1:
        return arr[:]
    pivot = arr[-1]
    pivot_key = key(pivot)
    less = [x for x in arr[:-1] if key(x) <= pivot_key]
    greater = [x for x in arr[:-1] if key(x) > pivot_key]
    return quicksort(less, key) + [pivot] + quicksort(greater, key)

class TestQuickSort(unittest.TestCase):
    def test_numbers(self):
        self.assertEqual(quicksort([5, 1, 4, 2, 3]), [1, 2, 3, 4, 5])

    def test_strings(self):
        self.assertEqual(quicksort(["pear", "apple", "orange"]), ["apple", "orange", "pear"])

    def test_custom_objects(self):
        class Point:
            def __init__(self, x, y):
                self.x, self.y = x, y
            def __repr__(self):
                return f"Point({self.x},{self.y})"
        pts = [Point(2, 3), Point(1, 5), Point(3, 1)]
        sorted_pts = quicksort(pts, key=lambda p: p.x)
        self.assertEqual([p.x for p in sorted_pts], [1, 2, 3])

if __name__ == "__main__":
    unittest.main()

'''quicksort_counter.py
QuickSort implementation that tracks how many element comparisons are performed.
The counter is stored in a mutable object so that recursive calls share it.
'''

from typing import List, Tuple

class Counter:
    def __init__(self):
        self.comparisons = 0

    def inc(self, n: int = 1) -> None:
        self.comparisons += n

def quicksort(arr: List[int], counter: Counter) -> List[int]:
    if len(arr) <= 1:
        return arr[:]
    pivot = arr[-1]
    less = []
    greater = []
    for x in arr[:-1]:
        counter.inc()  # one comparison per element
        if x <= pivot:
            less.append(x)
        else:
            greater.append(x)
    return quicksort(less, counter) + [pivot] + quicksort(greater, counter)

def sort_and_count(values: List[int]) -> Tuple[List[int], int]:
    counter = Counter()
    sorted_vals = quicksort(values, counter)
    return sorted_vals, counter.comparisons

if __name__ == "__main__":
    numbers = [12, 4, 5, 23, 1, 9, 8]
    sorted_numbers, comps = sort_and_count(numbers)
    print(f"Sorted: {sorted_numbers}")
    print(f"Comparisons performed: {comps}")

'''table_formatter.py
Render a list of dictionaries as a nicely aligned text table.
Column widths are computed from the longest item in each column, then each row
is printed with f‑strings that use those widths.
'''

from typing import List, Dict

def compute_widths(rows: List[Dict[str, str]]) -> Dict[str, int]:
    """Return a mapping of column name to maximum width (including header)."""
    widths: Dict[str, int] = {}
    for row in rows:
        for key, value in row.items():
            widths[key] = max(widths.get(key, len(key)), len(str(value)))
    return widths

def format_table(rows: List[Dict[str, str]]) -> str:
    """Build the table string using f‑strings with the calculated widths."""
    if not rows:
        return "<empty table>"
    widths = compute_widths(rows)
    header = " | ".join(f"{col:<{widths[col]}}" for col in widths)
    separator = "-+-".join('-' * widths[col] for col in widths)
    body_lines = []
    for row in rows:
        line = " | ".join(f"{str(row.get(col, '')):<{widths[col]}}" for col in widths)
        body_lines.append(line)
    return "\n".join([header, separator] + body_lines)

if __name__ == "__main__":
    data = [
        {"Name": "Alice",   "Score": "92", "Grade": "A"},
        {"Name": "Bob",     "Score": "85", "Grade": "B"},
        {"Name": "Charlie", "Score": "78", "Grade": "C"},
    ]
    print(format_table(data))

