'''stack_basic.py
Simple Stack implementation using a Python list.
Provides push, pop, peek, and size methods.
'''

class Stack:
    """LIFO stack data structure."""

    def __init__(self):
        self._items = []

    def push(self, item):
        """Add *item* to the top of the stack."""
        self._items.append(item)

    def pop(self):
        """Remove and return the top item. Raises IndexError if empty."""
        if not self._items:
            raise IndexError('pop from empty stack')
        return self._items.pop()

    def peek(self):
        """Return the top item without removing it. Returns None if empty."""
        return self._items[-1] if self._items else None

    def size(self):
        """Return the number of items currently stored."""
        return len(self._items)

    def is_empty(self):
        """True if the stack has no elements."""
        return not self._items

    def __repr__(self):
        return f"Stack({self._items})"

# Example usage when run as a script
if __name__ == '__main__':
    s = Stack()
    for i in range(5):
        s.push(i)
        print(f'pushed {i}, size={s.size()}')
    print('peek ->', s.peek())
    while not s.is_empty():
        print('pop ->', s.pop())

'''queue_deque.py
Queue implementation based on collections.deque for O(1) enqueue and dequeue.
Includes basic methods and a simple command‑line test.
'''

from collections import deque

class Queue:
    """FIFO queue built on top of deque."""

    def __init__(self, iterable=None):
        self._data = deque(iterable) if iterable is not None else deque()

    def enqueue(self, item):
        """Add *item* to the rear of the queue."""
        self._data.append(item)

    def dequeue(self):
        """Remove and return the front item. Raises IndexError if empty."""
        if not self._data:
            raise IndexError('dequeue from empty queue')
        return self._data.popleft()

    def front(self):
        """Return the front item without removing it, or None if empty."""
        return self._data[0] if self._data else None

    def __len__(self):
        return len(self._data)

    def is_empty(self):
        return not self._data

    def __repr__(self):
        return f"Queue({list(self._data)})"

# Demo when executed directly
if __name__ == '__main__':
    q = Queue([1, 2, 3])
    print('initial', q)
    q.enqueue(4)
    print('after enqueue 4', q)
    print('front ->', q.front())
    while not q.is_empty():
