from collections import deque

# ----- Stack using a plain Python list -----
class ListStack:
    def __init__(self):
        self._data = []

    def push(self, item):
        self._data.append(item)

    def pop(self):
        if not self._data:
            raise IndexError('pop from empty stack')
        return self._data.pop()

    def is_empty(self):
        return not self._data

# ----- Queue using deque -----
class DequeQueue:
    def __init__(self, items=None):
        self._q = deque(items) if items else deque()

    def enqueue(self, item):
        self._q.append(item)

    def dequeue(self):
        if not self._q:
            raise IndexError('dequeue from empty queue')
        return self._q.popleft()

    def __len__(self):
        return len(self._q)

# ----- Helper functions -----
def reverse_string_via_stack(s: str) -> str:
    """Reverse *s* by pushing characters onto a ListStack and popping them back."""
    stack = ListStack()
    for ch in s:
        stack.push(ch)
    reversed_chars = []
    while not stack.is_empty():
        reversed_chars.append(stack.pop())
    return ''.join(reversed_chars)

def process_tasks(tasks):
    """Enqueue each task and then dequeue printing them in FIFO order."""
    q = DequeQueue()
    for t in tasks:
        q.enqueue(t)
    while len(q):
        print('Processing:', q.dequeue())

