'''circular_queue.py
Fixed‑size circular queue implementation using a list.
Supports constant‑time enqueue and dequeue without resizing.
'''

class CircularQueue:
    """Ring buffer queue with a pre‑allocated capacity."""

    def __init__(self, capacity: int):
        if capacity <= 0:
            raise ValueError('capacity must be positive')
        self._buf = [None] * capacity
        self._capacity = capacity
        self._head = 0  # index of next element to dequeue
        self._tail = 0  # index where next element will be enqueued
        self._size = 0

    def enqueue(self, item):
        """Add *item* to the queue; raises OverflowError if full."""
        if self.is_full():
            raise OverflowError('enqueue on full circular queue')
        self._buf[self._tail] = item
        self._tail = (self._tail + 1) % self._capacity
        self._size += 1

    def dequeue(self):
        """Remove and return the front item; raises IndexError if empty."""
        if self.is_empty():
            raise IndexError('dequeue from empty circular queue')
        item = self._buf[self._head]
        self._buf[self._head] = None  # optional: help GC
        self._head = (self._head + 1) % self._capacity
        self._size -= 1
        return item

    def peek(self):
        """Return the front element without removing it, or None if empty."""
        return self._buf[self._head] if not self.is_empty() else None

    def is_full(self) -> bool:
        return self._size == self._capacity

    def is_empty(self) -> bool:
        return self._size == 0

    def __len__(self):
        return self._size

    def __repr__(self):
        items = []
        idx = self._head
        for _ in range(self._size):
            items.append(repr(self._buf[idx]))
            idx = (idx + 1) % self._capacity
        return f"CircularQueue([{', '.join(items)}], capacity={self._capacity})"

# Simple test harness
if __name__ == '__main__':
    cq = CircularQueue(3)
    for i in range(3):
        cq.enqueue(i)
        print('enqueued', i, cq)
    try:
        cq.enqueue(99)
    except OverflowError as e:
        print('expected overflow:', e)
    while not cq.is_empty():
        print('dequeued', cq.dequeue(), cq)

'''stack_benchmark.py
Benchmark push/pop speed of a custom Stack class versus a raw list.
Uses time.perf_counter for high‑resolution timing and prints results.
'''

import time

class Stack:
    """Thin wrapper around a list providing explicit stack methods."""
    def __init__(self):
        self._data = []
    def push(self, item):
        self._data.append(item)
    def pop(self):
        return self._data.pop()

def benchmark_push_pop(container_factory, n):
    """Push *n* integers then pop them all, measuring elapsed seconds.
    *container_factory* returns a fresh container supporting push/pop.
    """
    start = time.perf_counter()
    c = container_factory()
    for i in range(n):
        c.push(i) if hasattr(c, 'push') else c.append(i)
    for _ in range(n):
        c.pop() if hasattr(c, 'pop') else c.pop()
    return time.perf_counter() - start

def list_factory():
    return []  # plain list, will use append/pop directly in benchmark

def stack_factory():
    return Stack()

if __name__ == '__main__':
    N = 5_000_00  # 500,000 operations each direction
    t_list = benchmark_push_pop(list_factory, N)
    t_stack = benchmark_push_pop(stack_factory, N)
    print(f'Plain list push/pop time: {t_list:.6f} seconds')
    print(f'Stack class push/pop time: {t_stack:.6f} seconds')
    diff = t_stack - t_list
    print(f'Difference (stack - list): {diff:+.6f} seconds')

