"""Demonstrates a memory‑efficient bit‑set using a plain Python int.

* `BitSet` class provides `add`, `remove`, `contains`, and `to_list`.
* Internally it stores bits in a single integer, giving O(1) operations
  and using roughly N/8 bytes instead of N booleans.
"""
from __future__ import annotations

class BitSet:
    """A mutable set of non‑negative integers implemented with bits.
    The maximum element is limited only by Python's unlimited integer size.
    """
    def __init__(self, iterable=None):
        self._bits: int = 0
        if iterable:
            for i in iterable:
                self.add(i)

    def add(self, n: int) -> None:
        if n < 0:
            raise ValueError("BitSet only supports non‑negative integers")
        self._bits |= (1 << n)

    def remove(self, n: int) -> None:
        if not self.contains(n):
            raise KeyError(n)
        self._bits &= ~(1 << n)

    def contains(self, n: int) -> bool:
        if n < 0:
            return False
        return (self._bits >> n) & 1 == 1

    def __contains__(self, n: int) -> bool:
        return self.contains(n)

    def to_list(self) -> list[int]:
        """Return a sorted list of all elements in the set."""
        bits = self._bits
        result = []
        idx = 0
        while bits:
            if bits & 1:
                result.append(idx)
            bits >>= 1
            idx += 1
        return result

    def __len__(self) -> int:
        # population count (Hamming weight)
        return self._bits.bit_count()

    def __repr__(self) -> str:
        return f"BitSet({self.to_list()})"

def demo():
    # Build a set with 0‑999 using a list of booleans (baseline).
    bool_list = [False] * 1000
    for i in range(0, 1000, 2):  # add evens
        bool_list[i] = True
    # Same set with BitSet.
    bs = BitSet(i for i in range(0, 1000, 2))
    # Verify membership and size.
    assert all((i in bs) == bool_list[i] for i in range(1000))
    print("BitSet contains", len(bs), "elements; first few:", bs.to_list()[:5])

if __name__ == "__main__":
    demo()

"""singly_linked_list.py
A minimal implementation of a singly linked list.
Provides Node and SinglyLinkedList classes with methods to append,
prepend, delete by value, and iterate over the list.
"""

class Node:
    """A node of a singly linked list holding a value and a reference to the next node."""
    __slots__ = ('value', 'next')

    def __init__(self, value, next=None):
        self.value = value
        self.next = next

    def __repr__(self):
        return f"Node({self.value!r})"


class SinglyLinkedList:
    """Container for Node objects supporting common list operations."""
    def __init__(self):
        self.head = None
        self._size = 0

    def __len__(self):
        return self._size

    def __iter__(self):
        current = self.head
        while current:
            yield current.value
            current = current.next

    def __repr__(self):
        values = list(self)
        return f"SinglyLinkedList({values})"

    def append(self, value):
        """Add *value* to the end of the list."""
        new_node = Node(value)
        if not self.head:
            self.head = new_node
        else:
            tail = self.head
            while tail.next:
                tail = tail.next
            tail.next = new_node
        self._size += 1

    def prepend(self, value):
        """Insert *value* at the beginning of the list."""
        self.head = Node(value, self.head)
        self._size += 1

    def delete(self, value):
        """Remove the first node whose data equals *value*.
        Returns ``True`` if a node was removed, ``False`` otherwise.
        """
        current = self.head
        prev = None
        while current:
            if current.value == value:
                if prev:
                    prev.next = current.next
                else:
                    self.head = current.next
                self._size -= 1
                return True
            prev, current = current, current.next
        return False

    def to_list(self):
        """Return a Python list with the same order of elements."""
        return list(self)

# Simple demo when the file is executed directly
if __name__ == "__main__":
    ll = SinglyLinkedList()
    for i in range(5):
        ll.append(i)
    ll.prepend(-1)
    print("List after inserts:", ll)
    ll.delete(2)
    print("List after deleting 2:", ll)
    print("Length:", len(ll))
    print("Elements:", ll.to_list())

'''doubly_linked_list.py
Implementation of a generic doubly linked list.
Features:
* append, prepend
* insert after a given node index
* remove by index
* reverse (in‑place) method
* iterator that yields values from head to tail
'''

class DNode:
    """Node used by DoublyLinkedList, storing a value and links to neighbours."""
    __slots__ = ('value', 'prev', 'next')

    def __init__(self, value, prev=None, next=None):
        self.value = value
        self.prev = prev
        self.next = next

    def __repr__(self):
        return f"DNode({self.value!r})"


class DoublyLinkedList:
    def __init__(self):
        self.head = None
        self.tail = None
        self._size = 0

    def __len__(self):
        return self._size

    def __iter__(self):
        cur = self.head
        while cur:
            yield cur.value
            cur = cur.next

    def __repr__(self):
        return f"DoublyLinkedList({list(self)})"

    def append(self, value):
        node = DNode(value, prev=self.tail)
        if self.tail:
            self.tail.next = node
        else:
            self.head = node
        self.tail = node
        self._size += 1

    def prepend(self, value):
        node = DNode(value, next=self.head)
        if self.head:
            self.head.prev = node
        else:
            self.tail = node
        self.head = node
        self._size += 1

    def insert_after(self, index, value):
        if not (0 <= index < self._size):
            raise IndexError('index out of range')
        cur = self.head
        for _ in range(index):
            cur = cur.next
        node = DNode(value, prev=cur, next=cur.next)
        if cur.next:
            cur.next.prev = node
        else:
            self.tail = node
        cur.next = node
        self._size += 1

    def remove(self, index):
        if not (0 <= index < self._size):
            raise IndexError('index out of range')
        cur = self.head
        for _ in range(index):
            cur = cur.next
        if cur.prev:
            cur.prev.next = cur.next
        else:
            self.head = cur.next
        if cur.next:
            cur.next.prev = cur.prev
        else:
            self.tail = cur.prev
        self._size -= 1
        return cur.value

    def reverse(self):
        """Reverse the list in place by swapping next and prev links."""
        cur = self.head
        self.head, self.tail = self.tail, self.head
        while cur:
            cur.prev, cur.next = cur.next, cur.prev
            cur = cur.prev  # after swap, previous node becomes next

    def to_list(self):
        return list(self)

if __name__ == '__main__':
    dl = DoublyLinkedList()
    for ch in 'abcde':
        dl.append(ch)
    dl.prepend('0')
    dl.insert_after(2, 'X')
    print('Before reverse:', dl)
    dl.reverse()
    print('After reverse :', dl)
    print('Removed element at 3:', dl.remove(3))
    print('Final list    :', dl)

'''linkedlist_merge_sort.py
Implementation of merge sort operating directly on a singly linked list.
Provides Node, LinkedList, and a merge_sort method that returns a new sorted list.
The algorithm runs in O(n log n) time and O(log n) recursion depth.
'''

class Node:
    __slots__ = ('value', 'next')
    def __init__(self, value, nxt=None):
        self.value = value
        self.next = nxt
    def __repr__(self):
        return f"Node({self.value})"

class LinkedList:
    def __init__(self, iterable=None):
        self.head = None
        self._size = 0
        if iterable:
            for item in iterable:
                self.append(item)

    def append(self, value):
        new = Node(value)
        if not self.head:
            self.head = new
        else:
            cur = self.head
            while cur.next:
                cur = cur.next
            cur.next = new
        self._size += 1

    def __len__(self):
        return self._size

    def __iter__(self):
        cur = self.head
        while cur:
            yield cur.value
            cur = cur.next

    def __repr__(self):
        return f"LinkedList({list(self)})"

    # ------- merge‑sort utilities -------
    @staticmethod
    def _split(head):
        """Split the list starting at *head* into two halves.
        Returns (left_head, right_head). Uses the slow/fast pointer technique.
        """
        if not head or not head.next:
            return head, None
        slow, fast = head, head.next
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
        mid = slow.next
        slow.next = None
        return head, mid

    @staticmethod
    def _merge(left, right):
        dummy = Node(None)
        tail = dummy
        while left and right:
            if left.value <= right.value:
                tail.next, left = left, left.next
            else:
                tail.next, right = right, right.next
            tail = tail.next
        tail.next = left if left else right
        return dummy.next

    def _merge_sort(self, head):
        if not head or not head.next:
            return head
        left, right = self._split(head)
        left = self._merge_sort(left)
        right = self._merge_sort(right)
        return self._merge(left, right)

    def merge_sort(self):
        """Return a new LinkedList instance with nodes sorted in ascending order.
        The original list structure is left unchanged.
        """
        sorted_head = self._merge_sort(self.head)
        result = LinkedList()
        cur = sorted_head
        while cur:
            result.append(cur.value)
            cur = cur.next
        return result

if __name__ == '__main__':
    unsorted = LinkedList([7, 3, 5, 2, 9, 1])
    print('Original:', unsorted)
    sorted_ll = unsorted.merge_sort()
    print('Sorted  :', sorted_ll)

'''circular_linked_list.py
Implementation of a circular singly linked list.
Features:
* insert at tail (maintains circularity)
* rotate(k) – moves the head k steps forward
* to_list() – returns a Python list representation (starting at head)
* __iter__ yields values in circular order, stopping after a full loop.
'''

class CNode:
    __slots__ = ('value', 'next')
    def __init__(self, value, nxt=None):
        self.value = value
        self.next = nxt
    def __repr__(self):
        return f"CNode({self.value})"

class CircularLinkedList:
    def __init__(self):
        self.tail = None  # tail.next is the head
        self._size = 0

    def __len__(self):
        return self._size

    def __iter__(self):
        if not self.tail:
            return
        cur = self.tail.next
        for _ in range(self._size):
            yield cur.value
            cur = cur.next

    def __repr__(self):
        return f"CircularLinkedList({self.to_list()})"

    def insert(self, value):
        """Insert *value* at the end (after the current tail)."""
        node = CNode(value)
        if not self.tail:
            node.next = node
            self.tail = node
        else:
            node.next = self.tail.next
            self.tail.next = node
            self.tail = node
        self._size += 1

    def rotate(self, k):
        """Rotate the list forward by *k* nodes.
        After rotation, the node that was k steps after the head becomes the new head.
        """
        if self._size == 0:
            return
        k %= self._size
        for _ in range(k):
            self.tail = self.tail.next  # moving tail forward shifts head forward

    def to_list(self):
        return list(self)

if __name__ == '__main__':
    cl = CircularLinkedList()
    for i in range(1, 6):
        cl.insert(i)
    print('Initial:', cl)
    cl.rotate(2)
    print('After rotate 2:', cl)
    cl.rotate(3)
    print('After rotate 3 (total 5):', cl)

'''repeat_decorator.py
Implements a parameterised decorator @repeat(times=n) that executes the wrapped function
*times* times and returns a list of each call's result.
'''

import functools

def repeat(times: int = 2):
    """Factory that produces a decorator repeating a function *times*.

    The decorated function will be called sequentially *times* and a list of all
    return values is provided to the caller.
    """
    if times < 1:
        raise ValueError("times must be at least 1")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            results = []
            for i in range(times):
                print(f"[repeat] iteration {i+1}/{times} for {func.__name__}")
                results.append(func(*args, **kwargs))
            return results
        return wrapper
    return decorator

# Demo functions -----------------------------------------------------------
@repeat(times=3)
def dice_roll():
    """Simulate a six‑sided dice roll and return the face value."""
    import random
    return random.randint(1, 6)

@repeat(times=4)
def shout(text):
    """Return the uppercase version of *text*."""
    return text.upper()

if __name__ == "__main__":
    print("Dice rolls:", dice_roll())
    print("Shouts:", shout("hello"))

'''memoize_decorator.py
A class‑based decorator that caches function calls based on their arguments.
It works for functions with hashable positional and keyword arguments.
'''

import functools

class memoize:
    """Cache the results of a function call.

    The cache is stored on the instance; each decorated function gets its own
    dictionary keyed by a tuple of args and a frozenset of kw items.
    """
    def __init__(self, func):
        functools.update_wrapper(self, func)
        self.func = func
        self.cache = {}

    def __call__(self, *args, **kwargs):
        # Build a cache key that works for hashable arguments only
        key = args + tuple(sorted(kwargs.items()))
        if key in self.cache:
            print(f"[memoize] cache hit for {self.func.__name__}{key}")
            return self.cache[key]
        print(f"[memoize] compute {self.func.__name__}{key}")
        result = self.func(*args, **kwargs)
        self.cache[key] = result
        return result

    def clear(self):
        """Empty the stored cache."""
        self.cache.clear()

# Example usage -----------------------------------------------------------
@memoize
def fib(n: int) -> int:
    """Return the n‑th Fibonacci number using a naive recursive algorithm."""
    if n <= 1:
        return n
    return fib(n-1) + fib(n-2)

if __name__ == "__main__":
    for i in range(10):
        print(i, fib(i))
    # Demonstrate clearing the cache
    fib.clear()
    print("Cache cleared, recompute fib(5):", fib(5))

'''stacked_decorators.py
Demonstrates two simple decorators – @validate_non_negative and @time_it –
that can be stacked on a function. The order of stacking affects the output.
'''

import functools
import time

def validate_non_negative(func):
    """Raise ValueError if any positional argument is negative."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        for a in args:
            if isinstance(a, (int, float)) and a < 0:
                raise ValueError(f"Negative argument {a} not allowed for {func.__name__}")
        return func(*args, **kwargs)
    return wrapper

def time_it(func):
    """Measure and print the execution time of *func*."""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        result = func(*args, **kwargs)
        elapsed = time.perf_counter() - start
        print(f"[time_it] {func.__name__} took {elapsed:.6f}s")
        return result
    return wrapper

# Stacked usage ------------------------------------------------------------
@time_it
@validate_non_negative
def factorial(n: int) -> int:
    """Iterative factorial that assumes n is a non‑negative integer."""
    prod = 1
    for i in range(2, n+1):
        prod *= i
    return prod

@validate_non_negative
@time_it
def power(base: float, exp: int) -> float:
    """Simple exponentiation using the ** operator."""
    return base ** exp

if __name__ == "__main__":
    print("factorial(5) =", factorial(5))
    try:
        factorial(-3)
    except ValueError as e:
        print("Caught error:", e)
    print("power(2, 10) =", power(2, 10))

'''command_registry.py
A lightweight command‑registry decorator. Functions decorated with @command(name)
are stored in a global dict and can be called later via run_command(name, *args).
'''

import functools

# Global registry mapping command names to callables
_COMMANDS: dict[str, callable] = {}

def command(name: str):
    """Decorator that registers *func* under *name* in the global registry."""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            return func(*args, **kwargs)
        _COMMANDS[name] = wrapper
        print(f"[registry] command '{name}' registered -> {func.__name__}")
        return wrapper
    return decorator

def run_command(name: str, *args, **kwargs):
    """Execute a registered command by *name* passing through arguments."""
    if name not in _COMMANDS:
        raise KeyError(f"Command '{name}' not found")
    return _COMMANDS[name](*args, **kwargs)

# Example commands ----------------------------------------------------------
@command('greet')
def greet_user(username: str, greeting: str = 'Hello'):
    return f"{greeting}, {username}!"

@command('add')
def add_numbers(a: int, b: int) -> int:
    return a + b

@command('repeat')
def repeat_msg(msg: str, times: int = 2) -> str:
    return ' '.join([msg] * times)

if __name__ == "__main__":
    print(run_command('greet', 'Alice'))
    print(run_command('add', 7, 5))
    print(run_command('repeat', 'spam', times=3))
    # Demonstrate error handling
    try:
        run_command('unknown')
    except KeyError as e:
        print('Error:', e)

'''temp_cwd_decorator.py
Provides a @temp_cwd(path) decorator that changes os.getcwd() to *path* while the
wrapped function runs, then restores the original directory even if an error
occurs. Useful for scripts that need to operate on files in a specific folder.
'''

import os
import functools

def temp_cwd(path: str):
    """Decorator that temporarily sets the current working directory.

    The original directory is saved before the call and restored in a finally
    block, guaranteeing cleanup on success or exception.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            original = os.getcwd()
            try:
                os.chdir(path)
                print(f"[temp_cwd] switched to {path}")
                return func(*args, **kwargs)
            finally:
                os.chdir(original)
                print(f"[temp_cwd] restored to {original}")
        return wrapper
    return decorator

# Example usage ------------------------------------------------------------
@temp_cwd(".")  # current directory is already '.' but demonstrates usage
def list_here():
    """Return a list of entries in the temporary cwd."""
    return os.listdir('.')

if __name__ == "__main__":
    print("Files in current directory:", list_here())
    # Demonstrate that the cwd is restored even after an exception
    @temp_cwd("..")
    def raise_error():
        raise RuntimeError("forced error")
    try:
        raise_error()
    except RuntimeError as e:
        print('Caught:', e)
    print("Current directory after error:", os.getcwd())

"""nqueens_one_solution.py

A minimal backtracking solver for the N‑Queens problem.
It stops after finding the first valid configuration and prints the board.
"""

from typing import List

def solve_n_queens(n: int) -> List[int]:
    """Return a list representing column positions of queens for each row.

    The list index is the row number (0‑based) and the value is the column
    where the queen is placed. Raises ValueError if no solution exists.
    """
    board: List[int] = []

    def is_safe(row: int, col: int) -> bool:
        for r, c in enumerate(board):
            if c == col or abs(c - col) == row - r:
                return False
        return True

    def backtrack(row: int) -> bool:
        if row == n:
            return True
        for col in range(n):
            if is_safe(row, col):
                board.append(col)
                if backtrack(row + 1):
                    return True
                board.pop()
        return False

    if not backtrack(0):
        raise ValueError(f"No solution for N={n}")
    return board


def print_board(solution: List[int]) -> None:
    n = len(solution)
    for row in range(n):
        line = ['.'] * n
        line[solution[row]] = 'Q'
        print(' '.join(line))

if __name__ == "__main__":
    N = 8
    sol = solve_n_queens(N)
    print(f"One solution for {N}-Queens:")
    print_board(sol)

'''enumerate_nqueens.py

Generates every distinct solution of the N‑Queens problem using backtracking
and stores each board representation (as strings of '.' and 'Q') in
solutions.txt.
''' 

from typing import List

def solve_all(n: int) -> List[List[int]]:
    """Return a list of all queen column placements for an n×n board."""
    results: List[List[int]] = []
    board: List[int] = []

    def safe(row: int, col: int) -> bool:
        for r, c in enumerate(board):
            if c == col or abs(c - col) == row - r:
                return False
        return True

    def backtrack(row: int) -> None:
        if row == n:
            results.append(board.copy())
            return
        for col in range(n):
            if safe(row, col):
                board.append(col)
                backtrack(row + 1)
                board.pop()

    backtrack(0)
    return results


def board_to_strings(solution: List[int]) -> List[str]:
    n = len(solution)
    lines = []
    for r in range(n):
        line = ['.'] * n
        line[solution[r]] = 'Q'
        lines.append(''.join(line))
    return lines


def main() -> None:
    N = 8
    all_solutions = solve_all(N)
    with open('solutions.txt', 'w') as f:
        for idx, sol in enumerate(all_solutions, 1):
            f.write(f"Solution {idx}\n")
            for line in board_to_strings(sol):
                f.write(line + '\n')
            f.write('\n')
    print(f"Written {len(all_solutions)} solutions to solutions.txt")

if __name__ == '__main__':
    main()

"""visual_nqueens.py

A tiny console visualizer for the 4‑Queens backtracking algorithm.
It prints the board after each queen placement and removal, allowing a step‑by‑step
view of the search tree.
"""

import time
from typing import List

SIZE = 4
DELAY = 0.3  # seconds between steps

board: List[int] = []

def draw() -> None:
    for r in range(SIZE):
        line = ['.'] * SIZE
        if r < len(board):
            line[board[r]] = 'Q'
        print(' '.join(line))
    print('-' * (2 * SIZE - 1))
    time.sleep(DELAY)

def safe(row: int, col: int) -> bool:
    for r, c in enumerate(board):
        if c == col or abs(c - col) == row - r:
            return False
    return True

def backtrack(row: int) -> bool:
    if row == SIZE:
        return True
    for col in range(SIZE):
        if safe(row, col):
            board.append(col)
            draw()
            if backtrack(row + 1):
                return True
            board.pop()
            draw()  # show removal
    return False

if __name__ == '__main__':
    print('Visualizing 4‑Queens backtracking:')
    backtrack(0)
    print('Finished')

