"""bfs_path.py
Utility for shortest‑edge path extraction using BFS.

The graph is given as `dict[int, list[int]]` where keys are vertex ids.
The function `shortest_path` returns a list of vertices from `src` to `dst`.
If `dst` cannot be reached, a `ValueError` is raised.
"""
from collections import deque
from typing import Dict, List

def shortest_path(graph: Dict[int, List[int]], src: int, dst: int) -> List[int]:
    if src not in graph or dst not in graph:
        raise ValueError("Source or destination not present in graph")
    # parent map to reconstruct path
    parent: Dict[int, int] = {src: -1}
    q = deque([src])
    while q:
        v = q.popleft()
        if v == dst:
            break
        for nb in sorted(graph.get(v, [])):
            if nb not in parent:
                parent[nb] = v
                q.append(nb)
    else:
        raise ValueError(f"No path from {src} to {dst}")
    # rebuild path backwards
    path: List[int] = []
    cur = dst
    while cur != -1:
        path.append(cur)
        cur = parent[cur]
    path.reverse()
    return path

if __name__ == "__main__":
    sample = {0: [1, 2], 1: [3], 2: [3], 3: [4], 4: []}
    print("Path 0→4:", shortest_path(sample, 0, 4))

"""bfs_graph.py
A lightweight directed graph class with BFS utilities.

Features
--------
* add_edge(u, v) – insert a directed edge
* bfs(start) – run BFS and store distances internally
* distance(v) – retrieve distance from the last BFS run (‑1 if unreachable)
* reset() – clear stored BFS data
"""
from collections import deque
from typing import Dict, List

class BFSGraph:
    def __init__(self) -> None:
        self.adj: Dict[int, List[int]] = {}
        self._dist: Dict[int, int] = {}

    def add_edge(self, u: int, v: int) -> None:
        self.adj.setdefault(u, []).append(v)
        self.adj.setdefault(v, [])  # ensure v appears in keys for consistency

    def bfs(self, start: int) -> None:
        if start not in self.adj:
            raise ValueError("Start vertex not in graph")
        self._dist = {v: -1 for v in self.adj}
        q = deque([start])
        self._dist[start] = 0
        while q:
            cur = q.popleft()
            for nb in sorted(self.adj[cur]):
                if self._dist[nb] == -1:
                    self._dist[nb] = self._dist[cur] + 1
                    q.append(nb)

    def distance(self, v: int) -> int:
        return self._dist.get(v, -1)

    def reset(self) -> None:
        self._dist.clear()

if __name__ == "__main__":
    g = BFSGraph()
    edges = [(0,1),(0,2),(1,3),(2,3),(3,4)]
    for u, v in edges:
        g.add_edge(u, v)
    g.bfs(0)
    for node in range(5):
        print(f"Distance from 0 to {node}: {g.distance(node)}")

