# memo_fib.py
"""Memoization via closure for a recursive Fibonacci calculator.

`memoize` returns a wrapper that caches results in a dictionary stored in the
enclosing scope. The wrapped `fib` function then runs much faster for larger
inputs because previously computed values are reused.
"""

def memoize(func):
    """Return a memoized version of *func* using a closure.

    The cache dictionary lives in the closure's environment, so each
    memoized function gets its own independent storage.
    """
    cache = {}
    def wrapper(n):
        if n in cache:
            return cache[n]
        result = func(n)
        cache[n] = result
        return result
    return wrapper

@memoize
def fib(n: int) -> int:
    """Return the *n*th Fibonacci number (0‑based)."""
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

if __name__ == "__main__":
    for i in range(12):
        print(f"fib({i}) = {fib(i)}")

