'''typed_descriptor.py
A Typed descriptor that validates the type of assigned values.
Used inside a simple DataRecord class that mimics a dataclass without the @dataclass decorator.
''' 

from typing import Any, Tuple

class Typed:
    """Descriptor that ensures a value matches an expected type.
    The expected type can be a single type or a tuple of allowable types.
    """

    def __init__(self, name: str, expected_type: Any):
        self.name = name
        self.private_name = f'_{name}'
        self.expected_type = expected_type

    def __get__(self, instance, owner):
        if instance is None:
            return self
        return getattr(instance, self.private_name, None)

    def __set__(self, instance, value):
        if not isinstance(value, self.expected_type):
            raise TypeError(
                f"Attribute '{self.name}' expects type {self.expected_type}, got {type(value)}"
            )
        setattr(instance, self.private_name, value)

    def __delete__(self, instance):
        raise AttributeError(f"Cannot delete attribute '{self.name}'")

class DataRecord:
    """A lightweight record class using Typed descriptors.
    Fields: id (int), name (str), tags (list of str), rating (float or int).
    """

    id = Typed('id', int)
    name = Typed('name', str)
    tags = Typed('tags', list)
    rating = Typed('rating', (int, float))

    def __init__(self, id: int, name: str, tags: list, rating: float):
        self.id = id
        self.name = name
        self.tags = tags
        self.rating = rating

    def __repr__(self) -> str:
        return (f"DataRecord(id={self.id!r}, name={self.name!r}, "
                f"tags={self.tags!r}, rating={self.rating!r})")

if __name__ == '__main__':
