'''computed_readonly.py
Shows a hybrid approach: a descriptor that computes a value lazily and a read‑only property exposing it.
''' 

class LazyValue:
    """Descriptor that computes a value the first time it is accessed.
    The owning class must provide a _compute_<name> method.
    """

    def __init__(self, name: str):
        self.name = name
        self.private_name = f'_{name}'

    def __get__(self, instance, owner):
        if instance is None:
            return self
        if not hasattr(instance, self.private_name):
            compute = getattr(instance, f'_compute_{self.name}')
            value = compute()
            setattr(instance, self.private_name, value)
        return getattr(instance, self.private_name)

    def __set__(self, instance, value):
        raise AttributeError(f"'{self.name}' is read‑only")

    def __delete__(self, instance):
        raise AttributeError(f"Cannot delete read‑only attribute '{self.name}'")

class ExpensiveModel:
    """Model with a heavy‑to‑compute 'signature' attribute that is read‑only.
    The signature is generated the first time it is requested.
    """

    signature = LazyValue('signature')

    def __init__(self, data: str):
        self.data = data

    def _compute_signature(self):
        # Simulate heavy computation
        import hashlib, time
        time.sleep(0.1)  # pretend this is costly
        return hashlib.sha256(self.data.encode()).hexdigest()

    def __repr__(self) -> str:
        return f"ExpensiveModel(data={self.data!r})"

if __name__ == '__main__':
    m = ExpensiveModel('sample text')
    print('Model created')
    print('Signature:', m.signature)   # first access, computes
    print('Signature again:', m.signature)  # second access, cached
    try:
        m.signature = 'new value'
    except AttributeError as e:
        print('Attempt to set:', e)

