'''track_copy_decorator.py
Decorator that inspects a function's return value and reports the copy type.
The decorated function must accept a single argument and return a copy of it.
''' 
import copy
import functools
from typing import Callable, Any

def _is_shallow(original: Any, result: Any) -> bool:
    """Return True if *result* appears to be a shallow copy of *original*.
    Heuristic: objects are not the same, but `id(result[0])` equals `id(original[0])`
    for sequence types that support indexing.
    """
    if original is result:
        return False
    try:
        return id(original[0]) == id(result[0])
    except Exception:
        return False

def track_copy(func: Callable[[Any], Any]) -> Callable[[Any], Any]:
    """Decorator that prints whether the returned object is a shallow or deep copy.
    The wrapped function is called normally; after execution the decorator
    determines the copy type using a simple heuristic and prints a message.
    """
    @functools.wraps(func)
    def wrapper(arg):
        result = func(arg)
        if _is_shallow(arg, result):
            print(f'{func.__name__}: returned a shallow copy')
        else:
            print(f'{func.__name__}: returned a deep copy')
        return result
    return wrapper

# Example usage ---------------------------------------------------------------
@track_copy
def make_shallow(x):
    return copy.copy(x)

@track_copy
def make_deep(x):
    return copy.deepcopy(x)

if __name__ == '__main__':
    data = [[1, 2], [3, 4]]
    make_shallow(data)
    make_deep(data)

'''prime_generator.py
An infinite prime number generator using a simple trial‑division test.
''' 

def is_prime(num: int) -> bool:
    """Return ``True`` if *num* is prime, ``False`` otherwise.

    Uses trial division up to ``sqrt(num)``.
    """
    if num < 2:
        return False
    if num == 2:
        return True
    if num % 2 == 0:
        return False
    i = 3
    while i * i <= num:
        if num % i == 0:
            return False
        i += 2
    return True


def primes() -> int:
    """Yield an endless sequence of prime numbers.

    Starts at 2 and increments indefinitely, checking each candidate with ``is_prime``.
    """
    candidate = 2
    while True:
        if is_prime(candidate):
            yield candidate
        candidate += 1 if candidate == 2 else 2  # skip even numbers after 2


def main() -> None:
    import itertools
    # Print the first 20 primes
    for p in itertools.islice(primes(), 20):
        print(p)


if __name__ == "__main__":
    main()

'''paginator.py
Paginate any iterable using a simple generator.
''' 

def paginate(iterable, page_size: int):
    """Yield successive pages (as lists) from *iterable*.

    Parameters
    ----------
    iterable : iterable
        The source collection.
    page_size : int
        Number of items per page; must be > 0.
    """
    if page_size <= 0:
        raise ValueError("page_size must be a positive integer")
    it = iter(iterable)
    while True:
        page = []
        try:
            for _ in range(page_size):
                page.append(next(it))
        except StopIteration:
            if page:
                yield page
            break
        yield page


def main() -> None:
    data = list(range(1, 23))  # 22 items
    print("Pages of size 5:")
    for i, page in enumerate(paginate(data, 5), 1):
        print(f"Page {i}: {page}")


if __name__ == "__main__":
    main()

'''doubly_linked_list.py
Implementation of a doubly linked list.
Supports insertion after a node, removal, forward and reverse iteration.
'''

class DNode:
    """Node for a doubly linked list with value, prev and next pointers."""
    __slots__ = ('value', 'prev', 'next')

    def __init__(self, value, prev=None, nxt=None):
        self.value = value
        self.prev = prev
        self.next = nxt

    def __repr__(self):
        return f'DNode({self.value!r})'

class DoublyLinkedList:
    """Doubly linked list with head and tail references."""

    def __init__(self):
        self.head = None
        self.tail = None

    def append(self, value):
        """Add a node at the end of the list."""
        new = DNode(value, self.tail, None)
        if self.tail:
            self.tail.next = new
        else:
            self.head = new
        self.tail = new

    def insert_after(self, target_node, value):
        """Insert *value* after *target_node* (which must belong to this list)."""
        if target_node is self.tail:
            self.append(value)
            return
        new = DNode(value, target_node, target_node.next)
        target_node.next.prev = new
        target_node.next = new

    def remove(self, node):
        """Remove *node* from the list; does nothing if node is None."""
        if node is None:
            return
        if node.prev:
            node.prev.next = node.next
        else:
            self.head = node.next
        if node.next:
            node.next.prev = node.prev
        else:
            self.tail = node.prev
        node.prev = node.next = None

    def __iter__(self):
        cur = self.head
        while cur:
            yield cur.value
            cur = cur.next

    def __reversed__(self):
        cur = self.tail
        while cur:
            yield cur.value
            cur = cur.prev

    def __repr__(self):
        return f'DoublyLinkedList({list(self)})'

if __name__ == '__main__':
    dll = DoublyLinkedList()
    for i in range(1, 5):
        dll.append(i)  # 1-4
    # Insert 99 after node containing 2
    node = dll.head.next  # node with value 2
    dll.insert_after(node, 99)
    print(dll)  # DoublyLinkedList([1, 2, 99, 3, 4])
    print('Reverse:', list(reversed(dll)))  # Reverse: [4, 3, 99, 2, 1]
    dll.remove(node)
    print('After removing 2:', dll)

'''circular_linked_list.py
Circular singly linked list implementation.
Includes insert_end, make_circular, and has_cycle (Floyd's Tortoise‑Hare).
'''

class CNode:
    __slots__ = ('value', 'next')

    def __init__(self, value, nxt=None):
        self.value = value
        self.next = nxt

    def __repr__(self):
        return f'CNode({self.value!r})'

class CircularSinglyLinkedList:
    """A singly linked list that can be turned into a circular list."""

    def __init__(self):
        self.head = None

    def insert_end(self, value):
        """Insert *value* at the end (non‑circular case)."""
        new = CNode(value)
        if not self.head:
            self.head = new
            return
        cur = self.head
        while cur.next:
            cur = cur.next
        cur.next = new

    def make_circular(self):
        """Connect the last node back to the head, forming a loop."""
        if not self.head:
            return
        cur = self.head
        while cur.next:
            cur = cur.next
        cur.next = self.head

    def has_cycle(self):
        """Detect a cycle using Floyd's algorithm; returns True/False."""
        slow = fast = self.head
        while fast and fast.next:
            slow = slow.next
            fast = fast.next.next
            if slow is fast:
                return True
        return False

    def __iter__(self):
        """Iterate over values; stops if a cycle is detected to avoid infinite loop."""
        cur = self.head
        visited = set()
        while cur and id(cur) not in visited:
            visited.add(id(cur))
            yield cur.value
            cur = cur.next

    def __repr__(self):
        return f'CircularSinglyLinkedList({list(self)})'

if __name__ == '__main__':
    lst = CircularSinglyLinkedList()
    for i in range(5):
        lst.insert_end(i)
    print('Before circular:', lst.has_cycle())  # False
    lst.make_circular()
    print('After circular:', lst.has_cycle())   # True
    # Show first 7 values to demonstrate safe iteration
    print('Iterating safely:', [next(iter(lst)) for _ in range(7)])

'''typed_linked_list.py
Typed linked list using @dataclass.
Provides Node[T] and LinkedList[T] with insert, find, and length.
'''

from __future__ import annotations
from dataclasses import dataclass, field
from typing import Generic, TypeVar, Optional, Iterator

T = TypeVar('T')

@dataclass
class Node(Generic[T]):
    """A node holding a value of type T and a reference to the next node."""
    value: T
    next: Optional[Node[T]] = None

    def __repr__(self) -> str:
        return f'Node({self.value!r})'

class LinkedList(Generic[T]):
    """Singly linked list with type‑checked operations."""

    def __init__(self) -> None:
        self.head: Optional[Node[T]] = None
        self._size: int = 0

    def insert(self, value: T) -> None:
        """Insert *value* at the front of the list (O(1))."""
        self.head = Node(value, self.head)
        self._size += 1

    def find(self, target: T) -> Optional[Node[T]]:
        """Return the first node whose value equals *target*, or None."""
        cur = self.head
        while cur is not None:
            if cur.value == target:
                return cur
            cur = cur.next
        return None

    def __len__(self) -> int:
        return self._size

    def __iter__(self) -> Iterator[T]:
        cur = self.head
        while cur:
            yield cur.value
            cur = cur.next

    def __repr__(self) -> str:
        return f'LinkedList({list(self)})'

if __name__ == '__main__':
    ll = LinkedList[int]()
    for n in (3, 1, 4, 1, 5):
        ll.insert(n)
    print('List:', ll)                # List: LinkedList([5, 1, 4, 1, 3])
    print('Length:', len(ll))          # Length: 5
    node = ll.find(4)
    print('Found node:', node)          # Found node: Node(4)

'''sorted_linked_list.py
Sorted singly linked list implementation.
Insertion keeps the list ordered ascending; to_list returns a regular list.
'''

class SNode:
    __slots__ = ('value', 'next')

    def __init__(self, value, nxt=None):
        self.value = value
        self.next = nxt

    def __repr__(self):
        return f'SNode({self.value!r})'

class SortedLinkedList:
    """Linked list that stays sorted after each insertion."""

    def __init__(self):
        self.head: SNode | None = None

    def insert(self, value):
        """Insert *value* maintaining ascending order."""
        new = SNode(value)
        if not self.head or value < self.head.value:
            new.next = self.head
            self.head = new
            return
        cur = self.head
        while cur.next and cur.next.value < value:
            cur = cur.next
        new.next = cur.next
        cur.next = new

    def to_list(self):
        """Return a Python list containing all node values in order."""
        result = []
        cur = self.head
        while cur:
            result.append(cur.value)
            cur = cur.next
        return result

    def __repr__(self):
        return f'SortedLinkedList({self.to_list()})'

if __name__ == '__main__':
    sll = SortedLinkedList()
    for v in [7, 3, 5, 2, 9, 1]:
        sll.insert(v)
    print(sll)            # SortedLinkedList([1, 2, 3, 5, 7, 9])
    print('Python list:', sll.to_list())

'''linked_queue.py
Queue implementation using a singly linked list.
Supports enqueue (rear insertion), dequeue (front removal), and peek.
'''

class QNode:
    __slots__ = ('value', 'next')

    def __init__(self, value, nxt=None):
        self.value = value
        self.next = nxt

    def __repr__(self):
        return f'QNode({self.value!r})'

class LinkedQueue:
    """FIFO queue backed by a linked list; O(1) enqueue and dequeue."""

    def __init__(self):
        self.head: QNode | None = None  # front
        self.tail: QNode | None = None  # rear

    def enqueue(self, value):
        """Add *value* to the rear of the queue."""
        new = QNode(value)
        if self.tail is None:
            self.head = self.tail = new
        else:
            self.tail.next = new
            self.tail = new

    def dequeue(self):
        """Remove and return the front element; raise IndexError if empty."""
        if self.head is None:
            raise IndexError('dequeue from empty queue')
        val = self.head.value
        self.head = self.head.next
        if self.head is None:
            self.tail = None
        return val

    def peek(self):
        """Return the front element without removing it; return None if empty."""
        return self.head.value if self.head else None

    def __len__(self):
        # Count nodes; not stored to keep implementation simple
        cnt = 0
        cur = self.head
        while cur:
            cnt += 1
            cur = cur.next
        return cnt

    def __repr__(self):
        values = []
        cur = self.head
        while cur:
            values.append(cur.value)
            cur = cur.next
        return f'LinkedQueue({values})'

if __name__ == '__main__':
    q = LinkedQueue()
    for i in range(3):
        q.enqueue(i)
    print('Queue after enqueues:', q)   # [0,1,2]
    print('Peek:', q.peek())           # 0
    print('Dequeue:', q.dequeue())       # 0
    print('Queue now:', q)               # [1,2]
    print('Length:', len(q))

'''package_info.py

Utility to introspect a Python package on the filesystem.
It walks the supplied directory, reports each package (folder with
__init__.py) and each plain module (.py file).  The output is a simple
human‑readable tree.
Usage:
    python package_info.py path/to/package
'''

import sys
import pathlib
from typing import List

def _is_package(dir_path: pathlib.Path) -> bool:
    return (dir_path / "__init__.py").is_file()

def _list_modules(dir_path: pathlib.Path) -> List[pathlib.Path]:
    return [p for p in dir_path.iterdir() if p.is_file() and p.suffix == ".py" and p.name != "__init__.py"]

def _print_tree(root: pathlib.Path, prefix: str = "") -> None:
    if _is_package(root):
        print(f"{prefix}{root.name}/ (package)")
        new_prefix = prefix + "    "
        # list sub‑packages first
        for sub in sorted([d for d in root.iterdir() if d.is_dir()]):
            _print_tree(sub, new_prefix)
        # then modules
        for mod in sorted(_list_modules(root)):
            print(f"{new_prefix}{mod.stem}.py (module)")
    else:
        # Not a package – just list modules directly under root
        for mod in sorted(_list_modules(root)):
            print(f"{prefix}{mod.stem}.py (module)")

def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python package_info.py <package_path>")
        sys.exit(1)
    root_path = pathlib.Path(sys.argv[1]).resolve()
    if not root_path.is_dir():
        print(f"Error: {root_path} is not a directory")
        sys.exit(1)
    _print_tree(root_path)

if __name__ == "__main__":
    main()
